<?php
if (!defined('ABSPATH')) {
    exit;
}

if (!function_exists('wpc_crit_meta_write')) {
    // Mixed-tree belt: the canonical atomic writer lives in defines.php — a partial
    // deploy (FTP truncation, stale defines.php) degrades to a plain write here,
    // never a fatal (law 10). Complete trees never reach this definition.
    function wpc_crit_meta_write($path, $value)
    {
        try {
            $value = (string) $value;
            // v7.21.290 — IDENTICAL BYTES NEVER REWRITE. mtime is the autopurge clock
            // (wpc_autopurge_artifact_mtime): a same-bytes re-land bumped it, the purge
            // fired, and on a kick-looping site the page cache lived shorter than the
            // land interval (staging: stale-mark every 3s, files ABSENT 40s after a
            // 108KB write, every visitor re-rendering = the mint roulette). Size-gate
            // first so the compare is one read only when it can possibly match.
            if (@is_file($path) && (int) @filesize($path) === strlen($value)
                && @file_get_contents($path) === $value) {
                return true;
            }
            return wpc_fs_put($path, $value) !== false;
        } catch (\Throwable $e) {
            return false;
        }
    }
}



if (!function_exists('wpc_mc_up')) {
    // Global MC circuit breaker: an unreachable service must cost ~zero. A
    // timed-out call trips a 5-min skip-all window (staging.wpcompress.com
    // receipt: config-sync blocked ADMIN pages 8s each while the MC was dark).
    function wpc_mc_up()
    {
        return !get_transient('wpc_mc_down');
    }
    function wpc_mc_trip($err = '')
    {
        set_transient('wpc_mc_down', 1, 300);
        if (function_exists('wpc_cache_first_log')) {
            wpc_cache_first_log('mc-breaker-trip', '', '', ['err' => substr((string) $err, 0, 120)]);
        }
    }
}



if (!function_exists('wpc_delay_aggr_rearm')) {
    // A fresh measured gen = a new keep list = a new aggressive-delay attempt:
    // clear the boot-watchdog demote so the site retries interaction-only.
    // DAMPED: each prior trip adds an hour of hold before a land may re-arm
    // (trip-purge oscillation breaker — an unrelated URL's land must not
    // instantly re-arm a site that just demoted). 5 trips = 30d cool-down;
    // any trip older than 30d decays the counter to 0 (no lifetime penalty).
    function wpc_delay_aggr_rearm()
    {
        $tripped_at = (int) get_option('wpc_delay_aggr_off', 0);
        if (!$tripped_at) {
            return;
        }
        $trip_count = (int) get_option('wpc_delay_aggr_fails', 0);
        if (time() - $tripped_at > 30 * DAY_IN_SECONDS) {
            delete_option('wpc_delay_aggr_off');
            delete_option('wpc_delay_v3_bootfails');
            update_option('wpc_delay_aggr_fails', 0, false);
            return;
        }
        if ($trip_count >= 5) {
            return;
        }
        if (time() - $tripped_at < min($trip_count, 5) * HOUR_IN_SECONDS) {
            return;
        }
        delete_option('wpc_delay_aggr_off');
        delete_option('wpc_delay_v3_bootfails');
    }
}



if (!function_exists('wpc_settings_drift_guard')) {
    function wpc_settings_drift_guard($new, $old)
    {
        try {
            if (!is_array($new) || !is_array($old) || !apply_filters('wpc_settings_drift_guard', true)) {
                return $new;
            }
            $protect = apply_filters('wpc_drift_protected_keys', [
                'replace-fonts', 'used-css', 'delay-js-v3', 'preload-crit-fonts',
                'font-display', 'icon-font-display', 'delay-js-v2',


                'static-serve', 'cache', 'critical',
            ]);
            $restored = [];
            foreach ($protect as $k) {
                if (!array_key_exists($k, $new) && array_key_exists($k, $old) && $old[$k] !== '' && $old[$k] !== null) {
                    $new[$k] = $old[$k];
                    $restored[] = (string) $k;
                }
            }
            // Rule: a settings save never drops a protected key. A restore means a writer saved a
            // partial array (the defect this guard hides), so every one is logged with the writer.
            if ($restored && function_exists('wpc_belt_receipt')) {
                $writer = '';
                $frames = debug_backtrace(DEBUG_BACKTRACE_IGNORE_ARGS, 16);
                foreach ($frames as $i => $frame) {
                    if (isset($frame['function']) && $frame['function'] === 'update_option' && isset($frames[$i + 1])) {
                        $caller = $frames[$i + 1];
                        $writer = (isset($caller['class']) ? $caller['class'] . '::' : '') . (isset($caller['function']) ? $caller['function'] : '');
                        break;
                    }
                }
                wpc_belt_receipt('settings-drift-restored', ['keys' => implode(',', $restored), 'n' => count($restored), 'writer' => $writer], false, '');
            }
            return $new;
        } catch (\Throwable $e) {
            return $new;
        }
    }
    if (defined('WPS_IC_SETTINGS')) {
        add_filter('pre_update_option_' . WPS_IC_SETTINGS, 'wpc_settings_drift_guard', 10, 2);
    }
}


if (!function_exists('wpc_cache_first_enabled')) {
    /**
     * Cache-first = pages cache from the very first hit (no pre-crit no-store); crit/LCP landing
     * converges via per-URL HTML purge + warm instead of holding the page uncached. Default ON.
     * Kill-switches: add_filter('wpc_cache_first','__return_false'), define('WPC_CACHE_FIRST', false)
     * or define('WPC_CACHE_FIRST_DISABLE', true), or option wpc_cache_first = '0'.
     */
    function wpc_cache_first_enabled()
    {
        if (defined('WPC_CACHE_FIRST_DISABLE') && WPC_CACHE_FIRST_DISABLE) {
            $on = false;
        } elseif (defined('WPC_CACHE_FIRST')) {
            $on = (bool) WPC_CACHE_FIRST;
        } else {
            $opt = get_option('wpc_cache_first', '1');
            $on  = ($opt === '1' || $opt === 1 || $opt === true);
        }
        return (bool) apply_filters('wpc_cache_first', $on);
    }
}

if (!function_exists('wpc_land_report')) {
    /**
     * Land-report beacon → the joint delivery ledger (service §8, wire-proven both directions).
     * POST crit-push.zapwp.net/land-report, X-WPC-Sig/X-WPC-Ts headers (ms ts, ±600s), HMAC-SHA256
     * over uuid|url_key|ts keyed with the site apikey — the url_key signed IS the url_key sent.
     * Digest = cflog serialization (<=4KB, stored verbatim). Load-gated, blocking=false, throttled
     * once per key|uuid. A pinned box (load-gated out) leaves the row serve-probe-only, not blind.
     */
    function wpc_land_report($key)
    {
        try {
            if (!apply_filters('wpc_land_report_on', true)) { return; }
            if (function_exists('wpc_under_pressure') && wpc_under_pressure()) { return; }
            if (!function_exists('wp_remote_post') || !defined('WPS_IC_CRITICAL')) { return; }
            $key = (string) $key;
            if ($key === '' || (function_exists('wpc_pipeline_key_junk') && wpc_pipeline_key_junk($key))) { return; }
            $dir = rtrim(WPS_IC_CRITICAL, '/') . '/' . $key . '/';
            $rd  = function ($f) { return @is_readable($f) ? trim((string) @file_get_contents($f)) : ''; };
            $uuid = $rd($dir . 'land_uuid.txt');
            if ($uuid === '') { $uuid = $rd($dir . 'uuid.txt'); }
            if (strlen($uuid) < 8) { return; }
            $opt = (function_exists('get_option') && defined('WPS_IC_OPTIONS')) ? get_option(WPS_IC_OPTIONS) : [];
            $apikey = is_array($opt) && !empty($opt['api_key']) ? (string) $opt['api_key'] : '';
            if ($apikey === '') { return; }
            $seen = rtrim(WPS_IC_CRITICAL, '/') . '/.kicklocks/lr_' . md5($key . '|' . $uuid) . '.txt';
            if (@is_readable($seen) && (time() - (int) @filemtime($seen)) < (int) apply_filters('wpc_land_report_ttl', 300)) { return; }
            if (!is_dir(dirname($seen))) { @mkdir(dirname($seen), 0777, true); }
            @touch($seen);
            $tl = [];
            if (function_exists('wpc_cflog_tail')) {
                $tail = wpc_cflog_tail(65536);
                foreach (explode("\n", $tail) as $ln) {
                    if ($ln === '') { continue; }
                    $e = json_decode($ln, true);
                    if (!is_array($e) || !isset($e['event']) || (string) ($e['key'] ?? '') !== $key) { continue; }
                    $tl[] = ['t' => (int) ($e['t'] ?? 0), 'e' => (string) $e['event']];
                }
                $tl = array_slice($tl, -40);
            }
            $load1 = null;
            if (function_exists('sys_getloadavg')) { $la = @sys_getloadavg(); if (is_array($la) && isset($la[0])) { $load1 = round((float) $la[0], 2); } }
            $have = [
                'crit'  => @is_readable($dir . 'critical_desktop.css'),
                'delay' => @is_readable($dir . 'delay.json'),
                'lcp'   => @is_readable($dir . 'lcp.json'),
                'fonts' => (trim($rd($dir . 'fonts_url.txt')) !== '' || @is_readable($dir . 'fonts_none.txt')),
                'used'  => trim($rd($dir . 'used_css_url.txt')) !== '',
            ];
            $rn = count(array_filter($have));
            $digest = ['ve' => defined('WPC_PLUGIN_VERSION') ? WPC_PLUGIN_VERSION : '', 'load1' => $load1,
                'ready_n' => $rn, 'ready_of' => count($have), 'have' => $have, 'timeline' => $tl];
            $dj = wp_json_encode($digest);
            if (is_string($dj) && strlen($dj) > 4096) {
                $digest['timeline'] = array_slice($tl, -10); $digest['clamp'] = 1; $dj = wp_json_encode($digest);
                if (is_string($dj) && strlen($dj) > 4096) { $digest['timeline'] = []; }
            }
            $body = wp_json_encode(['uuid' => $uuid, 'apikey' => $apikey, 'url_key' => $key, 'digest' => $digest]);
            if (!is_string($body)) { return; }
            $ts  = (string) (int) round(microtime(true) * 1000);
            $sig = hash_hmac('sha256', $uuid . '|' . $key . '|' . $ts, $apikey);
            wp_remote_post(apply_filters('wpc_land_report_url', 'https://crit-push.zapwp.net/land-report'), [
                'blocking' => false, 'timeout' => 2, 'redirection' => 0,
                'headers' => ['Content-Type' => 'application/json', 'X-WPC-Sig' => $sig, 'X-WPC-Ts' => $ts],
                'body' => $body,
            ]);
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('land-report-sent', $key, '', ['uuid' => substr($uuid, 0, 8), 'ready' => $rn . '/' . count($have)]);
            }
        } catch (\Throwable $e) {
        }
    }
}

if (!function_exists('wpc_warm_url_variants')) {
    /**
     * The 4 cache-variant request shapes. MUST mirror the writer (cacheHtml.php saveCache:
     * webp = Accept contains image/webp, mobile = is_mobile() UA regex) and the drop-in reader.
     * Order matters: webp forms fire LAST per device so the static mirror bucket (which collapses
     * webp) ends holding the webp render — what real browsers send.
     */
    function wpc_warm_url_variants()
    {
        $desktop = 'Mozilla/5.0 (X11; Linux x86_64; rv:120.0) Gecko/20100101 Firefox/120.0';
        $mobile  = 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1';
        // v7.10.522 — 4 -> 2. The webp variants rendered BYTE-IDENTICAL HTML into a second
        // filename, so half of every fan-out was pure waste: on a 4-worker host, warming two
        // needless variants is half the pool. Kept behind the same single filter as the cache
        // key so the two can never drift apart — a key/fan-out mismatch would warm a file the
        // serve path never looks for.
        $variants = [
            ''            => ['ua' => $desktop, 'accept' => 'text/html'],
            'mobile'      => ['ua' => $mobile,  'accept' => 'text/html'],
        ];
        if (apply_filters('wpc_webp_cache_variant', false)) {
            $variants['webp']        = ['ua' => $desktop, 'accept' => 'text/html,image/webp'];
            $variants['mobile-webp'] = ['ua' => $mobile,  'accept' => 'text/html,image/webp'];
        }
        return $variants;
    }
}

if (!function_exists('wpc_warm_url_queue')) {
    /** The clock the warm queue's windows and the warm run read: the site's UTC timestamp. */
    function wpc_warm_now()
    {
        return function_exists('current_time') ? (int) current_time('timestamp', true) : time();
    }

    /** Fires the queue admits per minute (the bucket every enqueue spends one of). */
    function wpc_warm_bucket_max()
    {
        return max(1, (int) apply_filters('wpc_warm_max_batches_per_minute', 12));
    }

    /**
     * The bucket's current minute: {s: when it opened, n: fires admitted in it}. The window is
     * fixed from its first fire; rewriting the transient with a fresh 60 s on every enqueue would
     * slide it, and a steady feed would then hold the queue shut after twelve.
     */
    function wpc_warm_bucket_state($now)
    {
        $raw = get_transient('wpc_warm_bucket');
        if (is_array($raw) && isset($raw['s'], $raw['n']) && ($now - (int) $raw['s']) < 60) {
            return ['s' => (int) $raw['s'], 'n' => (int) $raw['n']];
        }
        if (is_numeric($raw)) {
            // A bare count (written before the window was kept): it opened no earlier than now.
            return ['s' => (int) $now, 'n' => (int) $raw];
        }
        return ['s' => (int) $now, 'n' => 0];
    }

    function wpc_warm_bucket_store(array $state, $now)
    {
        set_transient('wpc_warm_bucket', $state, max(1, 60 - ((int) $now - (int) $state['s'])));
    }

    /** Seconds between two fires site-wide; one fire sets it and every other fire inside it skips. */
    function wpc_warm_cooldown_seconds()
    {
        return (int) apply_filters('wpc_warm_global_cooldown', 15);
    }

    /** Warm renders the receiver lets run at once; the rest are answered 204 and retried by cron. */
    function wpc_warm_rx_cap()
    {
        return max(1, (int) apply_filters('wpc_warm_rx_cap', 1));
    }

    /** The receiver's in-flight warm renders: slot timestamps younger than 120 s. */
    function wpc_warm_rx_live_slots($now)
    {
        $slots = get_option('wpc_warm_rx_slots');
        return is_array($slots) ? array_values(array_filter($slots, function ($t) use ($now) {
            return ($now - (int) $t) < 120;
        })) : [];
    }

    /**
     * Whether the warm queue runs at all on this site: the kill switch, the per-site switch, the
     * page cache itself (a warm with nowhere to store is a wasted render), and Basic Auth, which a
     * loopback cannot pass.
     */
    function wpc_warm_url_queue_enabled()
    {
        if (defined('WPC_URL_WARM_DISABLE') && WPC_URL_WARM_DISABLE) {
            return false;
        }
        if (!apply_filters('wpc_url_warm_on_purge', (bool) get_option('wpc_url_warm_on_purge', true))) {
            return false;
        }
        if (defined('WPS_IC_SETTINGS')) {
            $wpc_settings = get_option(WPS_IC_SETTINGS);
            if (empty($wpc_settings['cache']['advanced']) || $wpc_settings['cache']['advanced'] == '0') {
                return false;
            }
        }
        if (function_exists('wpc_site_has_basic_auth') && wpc_site_has_basic_auth()) {
            return false;
        }
        return true;
    }

    /**
     * Queue a non-blocking warm of ONE URL (its variants) after its HTML was purged, so even the
     * first visitor after a crit/LCP land gets an optimized cache hit. Fail-safe: any bail-out just
     * leaves the page to warm on first visit, never worse.
     *
     * $fireAt = 0 fires at the end of this request (the purge buttons, a land). A timestamp
     * schedules the fire itself as the queue's cron event at that time instead, so a caller that
     * feeds several URLs at once can space their fires by the site cooldown; false then means
     * the event could not be scheduled and nothing was queued.
     */
    function wpc_warm_url_queue($url, $context = '', $fireAt = 0)
    {
        static $queued = [];
        try {
            if (!empty($_SERVER['HTTP_X_WPC_CACHE_WARM'])) {
                return false;
            }
            if (!wpc_warm_url_queue_enabled()) {
                return false;
            }
            if (class_exists('wps_ic_url_key') && method_exists('wps_ic_url_key', 'sanitizeSameHostUrl')) {
                $url = wps_ic_url_key::sanitizeSameHostUrl($url);
            }
            if (empty($url)) {
                return false;
            }
            if (isset($queued[$url])) {
                return true;
            }


            $wpc_lock = 'wpc_warm_lock_' . md5($url);
            $wpc_debounced = (bool) get_transient($wpc_lock);
            set_transient($wpc_lock, 1, (int) apply_filters('wpc_url_warm_debounce_seconds', 25));
            if ($wpc_debounced) {
                wpc_cache_first_log('warm-coalesced', '', $url, ['context' => $context]);
                return true; // the debounce must actually gate (was log-only — latent bug)
            }


            $wpc_now    = wpc_warm_now();
            $wpc_bucket = wpc_warm_bucket_state($wpc_now);
            if ($wpc_bucket['n'] >= wpc_warm_bucket_max()) {
                if (function_exists('wp_schedule_single_event') && function_exists('wp_next_scheduled')
                    && !wp_next_scheduled('wpc_url_warm', [$url, 1])) {
                    wpc_pl_sched(time() + 90, 'wpc_url_warm', [$url, 1]);
                }
                wpc_cache_first_log('warm-deferred', '', $url, ['context' => $context]);
                return true;
            }
            $wpc_spent = ['s' => $wpc_bucket['s'], 'n' => $wpc_bucket['n'] + 1];
            wpc_warm_bucket_store($wpc_spent, $wpc_now);

            $fireAt = (int) $fireAt;
            if ($fireAt > 0) {
                // The cron handler is the fire: every variant is missing, so it fires them all
                // and schedules its own verification pass.
                if (!wp_next_scheduled('wpc_url_warm', [$url, 1])
                    && !wpc_pl_sched($fireAt, 'wpc_url_warm', [$url, 1])) {
                    wpc_warm_bucket_store($wpc_bucket, $wpc_now);
                    delete_transient($wpc_lock);
                    return false;
                }
                $queued[$url] = true;
                wpc_cache_first_log('warm-fired', '', $url, ['context' => $context, 'at' => $fireAt]);
                return true;
            }

            $queued[$url] = true;
            register_shutdown_function('wpc_warm_url_fire', $url);
            // Cron backstop: verifies all 4 variants actually landed, re-fires the missing ones.
            if (function_exists('wp_schedule_single_event') && function_exists('wp_next_scheduled')
                && !wp_next_scheduled('wpc_url_warm', [$url, 1])) {
                wpc_pl_sched(time() + 60, 'wpc_url_warm', [$url, 1]);
            }
            wpc_cache_first_log('warm-fired', '', $url, ['context' => $context]);
            return true;
        } catch (\Throwable $e) {
            return false;
        }
    }
}

if (!function_exists('wpc_warm_url_queue_capacity')) {
    /**
     * Seconds between two fires the cooldown lets through. A transient set for N seconds is still
     * live at exactly N (it expires strictly after), so a fire N seconds after the last one skips.
     */
    function wpc_warm_fire_spacing()
    {
        return max(0, wpc_warm_cooldown_seconds()) + 1;
    }

    /**
     * How many URLs the warm queue will accept AND fire before $horizon seconds from now, when
     * their fires start at $firstFireAt and are spaced by the cooldown. Every number is the
     * queue's own gate, read where it lives:
     *   - the switches: wpc_warm_url_queue_enabled(), and Safe Mode through wpc_bg_lane_allowed()
     *     (the stand-down wpc_pl_sched applies to the fire's event);
     *   - pressure: wpc_under_pressure(), which wpc_pl_sched sheds on and the fire yields to;
     *   - the cron ceiling: wpc_pipeline_events_ok(), which refuses the fire's event past it;
     *   - the receiver shed: wpc_warm_rx_live_slots() against wpc_warm_rx_cap() — a fire into a
     *     full receiver is answered 204 and only burns a retry;
     *   - the bucket: wpc_warm_bucket_max() minus wpc_warm_bucket_state() — past it the
     *     queue defers the URL to a cron event instead of firing it;
     *   - the cooldown: the transient 'wpc_warm_cooldown' and wpc_warm_fire_spacing() — two fires
     *     closer than that are one fire and one skip.
     * A caller that feeds more than this gets 'warm-deferred' events piling up in cron.
     */
    function wpc_warm_url_queue_capacity($firstFireAt = 0, $horizon = 60)
    {
        try {
            $now = wpc_warm_now();
            if (!wpc_warm_url_queue_enabled()
                || (function_exists('wpc_bg_lane_allowed') && !wpc_bg_lane_allowed('wpc_url_warm'))) {
                return 0;
            }
            if (function_exists('wpc_under_pressure') && wpc_under_pressure()) {
                return 0;
            }
            if (function_exists('wpc_pipeline_events_ok') && !wpc_pipeline_events_ok()) {
                return 0;
            }
            if (count(wpc_warm_rx_live_slots($now)) >= wpc_warm_rx_cap()) {
                return 0;
            }
            $bucketRoom = max(0, wpc_warm_bucket_max() - wpc_warm_bucket_state($now)['n']);
            $start = wpc_warm_first_fire_at($firstFireAt, $now);
            $end = $now + max(1, (int) $horizon);
            $slots = $start >= $end ? 0 : (int) ceil(($end - $start) / wpc_warm_fire_spacing());
            return min($bucketRoom, $slots);
        } catch (\Throwable $e) {
            return 0;
        }
    }

    /**
     * The earliest time the next fire can pass the cooldown, no earlier than $firstFireAt. A
     * caller's own later slot is already spaced from its previous fire; only a fire due now can
     * meet a cooldown someone else just set, and then it waits one spacing.
     */
    function wpc_warm_first_fire_at($firstFireAt, $now)
    {
        $start = max((int) $now, (int) $firstFireAt);
        if ($start <= (int) $now && get_transient('wpc_warm_cooldown')) {
            $start = max($start, (int) $now + wpc_warm_fire_spacing());
        }
        return $start;
    }
}

if (!function_exists('wpc_warm_run_start')) {
    /*
     * THE WARM RUN: Start Optimization puts every uncached page in the page cache.
     *
     * The run's only state is the option 'wpc_warm_run' (not autoloaded, one per blog): the URLs
     * still to warm, the ones handed to the queue and when they fire, the count done, the ones
     * skipped and the failures per URL. It is fed to the one warm primitive, wpc_warm_url_queue(),
     * only as fast as the queue says it will fire (wpc_warm_url_queue_capacity()), with each fire
     * spaced by the site cooldown, so the pacing is the queue's pacing whoever enqueues: at most
     * one fire per cooldown and at most a bucket of fires per minute, two renders per fire.
     *
     * A tick runs from cron every 60 s and from the shutdown of any front-end request once the
     * last tick is 60 s old, so a lost cron event, a PHP restart or a deploy loses nothing: the
     * next tick reads the option. Completion is observed, never assumed: a URL is done when its
     * copy is on disk; one whose fire is 180 s past with no copy and nothing left queued for it
     * is a failure, and two failures skip it. Under pressure a tick feeds nothing and waits
     * 180 s; the list is untouched. The run ends when everything is done or skipped, after
     * WPC_WARM_RUN_MAX_HOURS, when the warm queue is switched off, or on the Stop button.
     *
     * A warm render never asks for critical CSS (P-W5): its crit-less copy is stored local-only
     * and the page's crit is demanded by its first real visit. The run's one generation is the
     * homepage's, asked for once at the start (wpc_warm_home_dispatch_queue). It never forces a
     * generation and never waits for one.
     */

    function wpc_warm_run_max_seconds()
    {
        $hours = defined('WPC_WARM_RUN_MAX_HOURS') ? (float) WPC_WARM_RUN_MAX_HOURS : 24.0;
        return max(60, (int) round($hours * 3600));
    }

    function wpc_warm_run_get()
    {
        $run = get_option('wpc_warm_run');
        return is_array($run) ? $run : [];
    }

    function wpc_warm_run_is_live(array $run)
    {
        return !empty($run['started']) && empty($run['ended']);
    }

    /**
     * Persist the run. The small autoloaded 'wpc_warm_run_live' marker is what the shutdown tick
     * reads, so a request on a site with no run live costs nothing beyond the autoload.
     */
    function wpc_warm_run_save(array $run)
    {
        update_option('wpc_warm_run', $run, false);
        if (wpc_warm_run_is_live($run)) {
            update_option('wpc_warm_run_live', [
                't' => (int) $run['last_tick'],
                'd' => (int) $run['deferred_until'],
            ], true);
        } else {
            delete_option('wpc_warm_run_live');
        }
    }

    /**
     * Start a run over $urls (the uncached pages) unless one is live, and run its first tick.
     * Answers the run's status plus 'started' — false when a run was already live (the click is
     * a no-op that reports it) or the warm queue is switched off.
     */
    function wpc_warm_run_start($src, array $urls)
    {
        $run = wpc_warm_run_get();
        if (wpc_warm_run_is_live($run)) {
            return ['started' => false] + wpc_warm_run_status();
        }
        if (!wpc_warm_url_queue_enabled()) {
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('warm-run-refused', '', '', ['src' => (string) $src, 'why' => 'disabled']);
            }
            return ['started' => false] + wpc_warm_run_status();
        }
        $pending = [];
        foreach ($urls as $url) {
            if (class_exists('wps_ic_url_key') && method_exists('wps_ic_url_key', 'sanitizeSameHostUrl')) {
                $url = wps_ic_url_key::sanitizeSameHostUrl((string) $url);
            }
            if ($url !== '' && !isset($pending[$url])) {
                $pending[$url] = true;
            }
        }
        $now = wpc_warm_now();
        $run = [
            'started'        => $now,
            'src'            => (string) $src,
            'total'          => count($pending),
            'pending'        => array_keys($pending),
            'inflight'       => [],
            'done'           => 0,
            'skipped'        => [],
            'refused'        => [],
            'failures'       => [],
            'last_tick'      => 0,
            'deferred_until' => 0,
            'next_fire_at'   => 0,
        ];
        wpc_warm_run_save($run);
        if (function_exists('wpc_cache_first_log')) {
            wpc_cache_first_log('warm-run-start', '', '', ['src' => (string) $src, 'n' => count($pending)]);
        }
        if (function_exists('wpc_warm_home_dispatch_queue')) {
            wpc_warm_home_dispatch_queue((string) $src);
        }
        wpc_warm_run_tick('start');
        return ['started' => true] + wpc_warm_run_status();
    }

    /** Whether the queue still holds an event that will fire or verify $url. */
    function wpc_warm_run_queued($url)
    {
        return function_exists('wp_next_scheduled')
            && (wp_next_scheduled('wpc_url_warm', [$url, 1]) || wp_next_scheduled('wpc_url_warm', [$url, 2]));
    }

    /** Whether $url has a stored copy for the desktop variant, in either copy family. */
    function wpc_warm_run_copy_present($url)
    {
        if (!defined('WPS_IC_CACHE') || !class_exists('wps_ic_url_key') || !function_exists('wpc_copy_present_gzip')) {
            return false;
        }
        $key = (string) (new wps_ic_url_key())->setup($url);
        if ($key === '') {
            return false;
        }
        return wpc_copy_present_gzip(rtrim(WPS_IC_CACHE, '/') . '/' . $key . '/', '') !== '';
    }

    /**
     * Whether a warm render of $url reached the page cache since $fireAt (its warm-rx), whatever
     * the store then decided. A page rendered and refused a copy is finished for the run; one
     * never reached is a failure.
     */
    function wpc_warm_run_rendered($url, $fireAt)
    {
        if (!class_exists('wps_ic_url_key')) {
            return false;
        }
        $key = (string) (new wps_ic_url_key())->setup($url);
        if ($key === '') {
            return false;
        }
        $seen = (int) get_transient('wpc_warm_rx_seen_' . md5($key));
        return $seen > 0 && $seen >= (int) $fireAt - 5;
    }

    /** One tick: credit what landed, requeue what failed, feed what the queue will fire. */
    function wpc_warm_run_tick($from = '')
    {
        $from = (string) $from === '' ? 'cron' : (string) $from;
        $run = wpc_warm_run_get();
        if (!wpc_warm_run_is_live($run)) {
            return;
        }
        $now = wpc_warm_now();
        // One tick at a time: the cron event and a front-end shutdown can meet.
        if (!add_option('wpc_warm_run_ticking', $now, '', 'no')) {
            if ($now - (int) get_option('wpc_warm_run_ticking') < 60) {
                return;
            }
            update_option('wpc_warm_run_ticking', $now, false);
        }
        try {
            wpc_warm_run_tick_locked($run, $now, $from);
        } catch (\Throwable $e) {
        } finally {
            delete_option('wpc_warm_run_ticking');
        }
    }

    function wpc_warm_run_tick_locked(array $run, $now, $from)
    {
        $before = [(int) $run['done'], count($run['pending']), count($run['inflight']), count($run['skipped'])];
        $run['last_tick'] = $now;
        if (!wpc_warm_url_queue_enabled()) {
            wpc_warm_run_end($run, 'disabled');
            return;
        }
        if ($now - (int) $run['started'] >= wpc_warm_run_max_seconds()) {
            wpc_warm_run_end($run, 'max-hours');
            return;
        }

        foreach ($run['inflight'] as $url => $fireAt) {
            if (wpc_warm_run_copy_present($url)) {
                $run['done']++;
                unset($run['inflight'][$url]);
                continue;
            }
            if ($now - (int) $fireAt <= 180 || wpc_warm_run_queued($url)) {
                continue;
            }
            unset($run['inflight'][$url]);
            if (wpc_warm_run_rendered($url, $fireAt)) {
                // Rendered, and the store refused it a copy: recorded, not retried.
                $run['refused'][] = $url;
                continue;
            }
            $failures = (int) ($run['failures'][$url] ?? 0) + 1;
            $run['failures'][$url] = $failures;
            if ($failures >= 2) {
                $run['skipped'][] = $url;
            } else {
                $run['pending'][] = $url;
            }
        }
        if (empty($run['pending']) && empty($run['inflight'])) {
            // done: every URL rendered (a copy, or a recorded refusal). A URL skipped after its
            // failures was never rendered, and the run says so.
            wpc_warm_run_end($run, empty($run['skipped']) ? 'done' : 'exhausted');
            return;
        }

        // A site without a working cron still warms: a front-end request's tick fires the one
        // due URL the cooldown lets through, as the queue's own cron handler would.
        if ($from === 'shutdown' && function_exists('wpc_url_warm_cron_handler')) {
            foreach ($run['inflight'] as $url => $fireAt) {
                $due = wp_next_scheduled('wpc_url_warm', [$url, 1]);
                if ($due && $due <= $now) {
                    wp_unschedule_event($due, 'wpc_url_warm', [$url, 1]);
                    wpc_url_warm_cron_handler($url, 1);
                    break;
                }
            }
        }

        $deferred = function_exists('wpc_under_pressure') && wpc_under_pressure();
        if ($deferred) {
            $run['deferred_until'] = $now + 180;
        } else {
            $run['deferred_until'] = 0;
            $capacity = wpc_warm_url_queue_capacity((int) $run['next_fire_at']);
            if ($capacity > 0) {
                $fireAt = wpc_warm_first_fire_at((int) $run['next_fire_at'], $now);
                $keep = [];
                $fed = 0;
                $refused = false;
                foreach ($run['pending'] as $url) {
                    if ($refused || $fed >= $capacity || get_transient('wpc_warm_lock_' . md5($url))) {
                        $keep[] = $url;
                        continue;
                    }
                    if (wpc_warm_url_queue($url, 'start-optimization', $fireAt)) {
                        $run['inflight'][$url] = $fireAt;
                        $fireAt += wpc_warm_fire_spacing();
                        $fed++;
                    } else {
                        // The queue could not schedule the fire (ceiling or pressure since the
                        // capacity read): the URL stays first in line for the next tick.
                        $keep[] = $url;
                        $refused = true;
                    }
                }
                $run['pending'] = $keep;
                if ($fed > 0) {
                    $run['next_fire_at'] = $fireAt;
                }
            }
        }
        wpc_warm_run_save($run);

        $after = [(int) $run['done'], count($run['pending']), count($run['inflight']), count($run['skipped'])];
        if (function_exists('wpc_cache_first_log')) {
            if ($after !== $before) {
                wpc_cache_first_log('warm-run-progress', '', '', [
                    'done'      => $after[0],
                    'remaining' => $after[1] + $after[2],
                    'inflight'  => $after[2],
                    'skipped'   => $after[3],
                    'deferred'  => $deferred ? 1 : 0,
                    'from'      => $from,
                ]);
            }
            if ($deferred) {
                wpc_cache_first_log('warm-run-deferred', '', '', ['until' => (int) $run['deferred_until'], 'from' => $from]);
            }
        }
        if (function_exists('wpc_pl_sched') && !wp_next_scheduled('wpc_warm_run_tick')) {
            wpc_pl_sched($deferred ? (int) $run['deferred_until'] : $now + 60, 'wpc_warm_run_tick');
        }
    }

    /** End the run. The option keeps what was left, for the report; the marker goes. */
    function wpc_warm_run_end(array $run, $why)
    {
        $run['ended'] = wpc_warm_now();
        $run['why'] = (string) $why;
        wpc_warm_run_save($run);
        if (function_exists('wp_clear_scheduled_hook')) {
            wp_clear_scheduled_hook('wpc_warm_run_tick');
        }
        if (function_exists('wpc_cache_first_log')) {
            // remaining = the URLs the run never rendered, the skipped ones included.
            wpc_cache_first_log('warm-run-end', '', '', [
                'done'      => (int) $run['done'],
                'refused'   => count((array) ($run['refused'] ?? [])),
                'skipped'   => count($run['skipped']),
                'remaining' => count($run['pending']) + count($run['inflight']) + count($run['skipped']),
                'why'       => (string) $why,
            ]);
        }
    }

    /** The Stop button: end a live run. */
    function wpc_warm_run_stop()
    {
        $run = wpc_warm_run_get();
        if (wpc_warm_run_is_live($run)) {
            wpc_warm_run_end($run, 'stopped');
        }
    }

    /** What the status poll shows. Reads the option; changes nothing. */
    function wpc_warm_run_status()
    {
        $run = wpc_warm_run_get();
        if (empty($run['started'])) {
            return ['live' => false];
        }
        return [
            'live'           => wpc_warm_run_is_live($run),
            'src'            => (string) ($run['src'] ?? ''),
            'started'        => (int) $run['started'],
            'total'          => (int) ($run['total'] ?? 0),
            'done'           => (int) ($run['done'] ?? 0),
            'remaining'      => count((array) ($run['pending'] ?? [])) + count((array) ($run['inflight'] ?? [])),
            'inflight'       => count((array) ($run['inflight'] ?? [])),
            'skipped'        => count((array) ($run['skipped'] ?? [])),
            'deferred_until' => (int) ($run['deferred_until'] ?? 0),
            'ended'          => (int) ($run['ended'] ?? 0),
            'why'            => (string) ($run['why'] ?? ''),
        ];
    }

    /** The front-end half of the ticking: any visitor request once the last tick is 60 s old. */
    function wpc_warm_run_on_shutdown()
    {
        try {
            if (!empty($_SERVER['HTTP_X_WPC_CACHE_WARM'])
                || (defined('DOING_CRON') && DOING_CRON)
                || (function_exists('wp_doing_ajax') && wp_doing_ajax())
                || (function_exists('is_admin') && is_admin())) {
                return;
            }
            // Read from the autoloaded set: a site with no run live pays no query for this.
            if (function_exists('wp_load_alloptions')) {
                $all = wp_load_alloptions();
                $live = isset($all['wpc_warm_run_live']) ? maybe_unserialize($all['wpc_warm_run_live']) : null;
            } else {
                $live = get_option('wpc_warm_run_live');
            }
            if (!is_array($live)) {
                return;
            }
            $now = wpc_warm_now();
            if ($now - (int) ($live['t'] ?? 0) < 60 || $now < (int) ($live['d'] ?? 0)) {
                return;
            }
            wpc_warm_run_tick('shutdown');
        } catch (\Throwable $e) {
        }
    }

    add_action('wpc_warm_run_tick', 'wpc_warm_run_tick');
    add_action('shutdown', 'wpc_warm_run_on_shutdown', 20);
}

if (!function_exists('wpc_warm_home_dispatch_queue')) {
    /*
     * THE WARM LANES' ONE GENERATION: the homepage.
     *
     * A warm render never asks for critical CSS (P-W5): the pages it stores wait for a real
     * visit. The homepage is the exception, because it should always be fast: Start Optimization
     * and Purge & Preload ask for it once, as a step of their own, when it has no crit on disk.
     * The ask is an ordinary automatic dispatch (`gen-dispatch {path:warm-home}`): unforced,
     * under the service hold, the per-page cap and the site spacing. It runs from cron so the
     * click answers at once.
     */

    /** Whether the homepage has a crit file on disk. */
    function wpc_warm_home_has_crit()
    {
        if (!defined('WPS_IC_CRITICAL') || !class_exists('wps_ic_url_key') || !function_exists('home_url')) {
            return true;
        }
        $key = ltrim((string) (new wps_ic_url_key())->setup(home_url('/')), '/');
        if ($key === '') {
            return true;
        }
        $dir = rtrim(WPS_IC_CRITICAL, '/') . '/' . $key . '/';
        return @filesize($dir . 'critical_desktop.css') > 5 || @filesize($dir . 'critical_mobile.css') > 5;
    }

    /** Queue the homepage's one dispatch for $src. True when it was queued. */
    function wpc_warm_home_dispatch_queue($src)
    {
        try {
            $settings = get_option(WPS_IC_SETTINGS);
            if (!is_array($settings) || empty($settings['critical']['css']) || $settings['critical']['css'] != '1'
                || wpc_warm_home_has_crit()) {
                return false;
            }
            // One event for every source: its args are empty, so a second source finds it.
            if (function_exists('wp_next_scheduled') && wp_next_scheduled('wpc_warm_home_dispatch', [])) {
                return true;
            }
            if (!function_exists('wpc_pl_sched') || !wpc_pl_sched(time(), 'wpc_warm_home_dispatch', [])) {
                return false;
            }
            if (function_exists('wpc_spawn_cron')) {
                wpc_spawn_cron();
            }
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('warm-home-queued', '', '', ['src' => (string) $src]);
            }
            return true;
        } catch (\Throwable $e) {
            return false;
        }
    }

    /** The cron half: dispatch the homepage once, if it still has no crit. */
    function wpc_warm_home_dispatch_run()
    {
        try {
            if (wpc_warm_home_has_crit()) {
                return;
            }
            if (!class_exists('wps_criticalCss') && defined('WPS_IC_DIR')) {
                @include_once WPS_IC_DIR . 'addons/criticalCss/criticalCss-v2.php';
            }
            if (class_exists('wps_criticalCss') && function_exists('home_url')) {
                (new wps_criticalCss(home_url('/')))->generateCriticalAjax(false, 'warm-home');
            }
        } catch (\Throwable $e) {
        }
    }

    add_action('wpc_warm_home_dispatch', 'wpc_warm_home_dispatch_run', 10, 0);
}

if (!function_exists('wpc_crit_resync_wave_h')) {
    /** Follow-up waves after a resync click: re-open the one-shot used-css gates and
     *  re-pull, so observe-leg artifacts (geometry/fonts/used amendments) land without
     *  another human action. Bounded: one probe + one kick per wave, pressure-yielding. */
    function wpc_crit_resync_wave_h($urlKey, $wave = 0)
    {
        try {
            if ((string) $urlKey === '' || !defined('WPS_IC_CRITICAL')) {
                return;
            }
            if (function_exists('wpc_under_pressure') && wpc_under_pressure()) {
                if ((int) $wave < 1000 && function_exists('wpc_pl_sched')) {
                    wpc_pl_sched(time() + 120, 'wpc_crit_resync_wave', [(string) $urlKey, (int) $wave + 1000]);
                }
                return;
            }
            $sheet_count = 0;
            foreach ((array) @glob(rtrim(WPS_IC_CRITICAL, '/') . '/used-css/tpl-*.css') as $template_sheet) {
                if (++$sheet_count > 20) {
                    break;
                }
                delete_transient('wpc_ucsr266_' . md5($template_sheet));
                delete_transient('wpc_ucsp_' . md5($template_sheet));
            }
            // Amendments land IN PLACE on the same uuid (geometry bake, observe leg) —
            // the collector dedupes on unchanged uuid, so force the re-pull like
            // refetch=crit does: drop the land stamp (atomic overwrite, never critless).
            @unlink(rtrim(WPS_IC_CRITICAL, '/') . '/' . $urlKey . '/land_uuid.txt');
            delete_transient('wpc_repull_kick_' . md5((string) $urlKey));
            delete_transient('wpc_prescfetch_' . md5((string) $urlKey));
            delete_transient('wpc_prescpoll_' . md5((string) $urlKey));
            if (function_exists('wpc_repull_kick_now')) {
                wpc_repull_kick_now((string) $urlKey, false, 'amendment');
            }
            if (function_exists('wpc_crit_collect_now')) {
                wpc_crit_collect_now((string) $urlKey, 1);
            }
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('resync-wave', (string) $urlKey, '', ['w' => (int) $wave]);
            }
        } catch (\Throwable $e) {
        }
    }
    add_action('wpc_crit_resync_wave', 'wpc_crit_resync_wave_h', 10, 2);
}

if (!function_exists('wpc_warm_url_fire')) {
    /** True while this request's response is still being built (see wpc_warm_url_fire). */
    function wpc_warm_fire_must_wait_for_shutdown()
    {
        if (!empty($GLOBALS['wpc_response_released']) || !empty($GLOBALS['wpc_warm_fire_at_shutdown'])
            || (defined('DOING_CRON') && DOING_CRON)) {
            return false;
        }
        return !function_exists('did_action') || did_action('shutdown') === 0;
    }

    /**
     * Shutdown transport: flush the triggering response, then fire the 4 variant renders as
     * non-blocking local-vhost loopbacks (the proven fireHomepageWarm transport, generalized).
     * The receiver survives the client-close via the X-WPC-Cache-Warm guard in wp-compress.php.
     */
    function wpc_warm_url_fire($url, $only_variants = null)
    {
        // Rule: the fire releases the response (wpc_finish_request) before its loopbacks, so it
        // runs only once the response is complete: at shutdown or in cron. A caller inside a
        // request still being built is moved to shutdown. Observed failure
        // (rig upg, 2026-09-27, staging 2026-09-27 after 7.24.41 to 7.24.45): the upgrade pass on
        // admin_init priority 1 applies the link preset, whose inline fire released the response
        // before admin.php had printed anything, so the first admin page after a plugin update
        // answered 200 with an empty body (no X-Frame-Options, which admin_init priority 10 sends).
        if (wpc_warm_fire_must_wait_for_shutdown()) {
            register_shutdown_function(function () use ($url, $only_variants) {
                $GLOBALS['wpc_warm_fire_at_shutdown'] = true;
                wpc_warm_url_fire($url, $only_variants);
            });
            return true;
        }
        try {
            // v7.10.609 — canonical form BEFORE the fetch. The field log showed two cron
            // loopbacks to /about-us with no trailing slash, 2049ms + 2005ms: WordPress answers
            // a canonical 301, so each warm booted WordPress twice.
            if (function_exists('wpc_canonical_url')) {
                $url = wpc_canonical_url($url);
            }
            // v7.10.520 BELT 1 — PARITY. wpc_warm_url_queue() has refused to run inside a
            // warm request since it was written; fire() never did. A warm loopback could
            // therefore fan out four more, and only a racy 15s global cooldown stood in the
            // way. Measured: 3 hard refreshes produced ~19 concurrent 724KB renders.
            if (!empty($_SERVER['HTTP_X_WPC_CACHE_WARM'])) {
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('warm-refire-blocked', '', (string) $url, []);
                }
                return false;
            }
            // BELT 2 — a request that CANNOT cache must not trigger a warm: its render is not
            // stored, so the "variants missing" signal stays true and would re-fire the whole
            // 4-variant fan-out on every such request. Only a request `no-store` is refused a
            // copy by the store verdict (wpc_store_verdict); a hard refresh's `no-cache` is
            // stored like any visit (dbmwebdesign.de, 2026-09-28), so it may trigger a warm.
            $cache_control = strtolower((string) ($_SERVER['HTTP_CACHE_CONTROL'] ?? ''));
            if ($cache_control !== '' && strpos($cache_control, 'no-store') !== false) {
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('warm-skip-uncacheable', '', (string) $url, ['cc' => substr($cache_control, 0, 24)]);
                }
                return false;
            }
            // BELT 3 — the 15s cooldown was get_transient()-then-set_transient(): a
            // read-then-write race that ~19 simultaneous requests walk straight through.
            // GET_LOCK(name,0) is atomic, so exactly one caller can win.
            if (function_exists('wpc_worker_lock') && !wpc_worker_lock('warm_fire_gate')) {
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('warm-gate-contended', '', (string) $url, []);
                }
                return false;
            }
            // v7.10.531 — the release was a NESTED shutdown function, so it ran last and the gate
            // was held across fastcgi_finish_request() and the whole fan-out: captured holding
            // GET_LOCK for 33s with its MySQL connection in Sleep (blocked on loopback HTTP, not
            // on a query). FPM reports that phase as "Finishing" and request_slowlog_timeout
            // cannot see it, so the most expensive lock in the plugin was structurally invisible.
            // The shutdown release stays as a crash belt only; the real release is explicit, the
            // moment the cooldown transient makes the decision durable.
            if (function_exists('wpc_worker_unlock')) {
                register_shutdown_function(function () { @wpc_worker_unlock('warm_fire_gate'); });
            }
            $holds_fire_gate = true;
            if (function_exists('wpc_bg_slot_take') && !wpc_bg_slot_take('warm')) {
                if (!empty($holds_fire_gate) && function_exists('wpc_worker_unlock')) {
                    @wpc_worker_unlock('warm_fire_gate');
                }
                return;
            }


            $cooldown_seconds = wpc_warm_cooldown_seconds();
            if ($cooldown_seconds > 0 && function_exists('get_transient')) {
                if (get_transient('wpc_warm_cooldown')) {
                    if (function_exists('wpc_cache_first_log')) { wpc_cache_first_log('warm-cooldown-skip', '', $url, []); }
                    if (!empty($holds_fire_gate) && function_exists('wpc_worker_unlock')) {
                        @wpc_worker_unlock('warm_fire_gate');
                    }
                    return false;
                }
                set_transient('wpc_warm_cooldown', 1, $cooldown_seconds);
            }
            // Decision is now durable in the cooldown — the gate has done its whole job. Everything
            // below (jitter + loopback renders) must NOT hold it.
            if (!empty($holds_fire_gate) && function_exists('wpc_worker_unlock')) {
                @wpc_worker_unlock('warm_fire_gate');
                $holds_fire_gate = false;
            }
            if ((function_exists('fastcgi_finish_request') || function_exists('litespeed_finish_request'))) {
                wpc_finish_request();
            }

            $wpc_jitter = (int) apply_filters('wpc_url_warm_jitter_ms', 800);
            if ($wpc_jitter > 0) {
                @usleep(mt_rand(0, $wpc_jitter) * 1000);
            }
            $parts = function_exists('wp_parse_url') ? wp_parse_url($url) : parse_url($url);
            if (empty($parts['host'])) {
                return;
            }
            $https = (!empty($parts['scheme']) && $parts['scheme'] === 'https');
            $port  = !empty($parts['port']) ? (int) $parts['port'] : ($https ? 443 : 80);
            $host  = (string) $parts['host'];
            $path  = !empty($parts['path']) ? $parts['path'] : '/';


            if (substr($path, -1) !== '/' && !preg_match('/\.[a-z0-9]{2,5}$/i', $path)) {
                $path .= '/';
            }

            $wpc_socket_ok = class_exists('wps_ic_ajax') && method_exists('wps_ic_ajax', 'wpc_loopback_open_socket');
            $variants_fired  = 0;
            foreach (wpc_warm_url_variants() as $wpc_variant => $wpc_v) {
                if (is_array($only_variants) && !in_array($wpc_variant, $only_variants, true)) {
                    continue;
                }
                if (++$variants_fired > (int) apply_filters('wpc_warm_batch_cap',
                    (function_exists('wpc_is_constrained_host') && wpc_is_constrained_host()) ? 1 : 2)) {
                    break;
                }


                // ONE transport per variant: the socket loopback when available, wp_remote_get
                // only as its fallback. Double-firing doubled the self-inflicted render load.
                if (!$wpc_socket_ok) {
                    wp_remote_get($url, [
                        'blocking' => false,
                        'timeout'  => 2,
                        'headers'  => [
                            'user-agent'       => $wpc_v['ua'],
                            'accept'           => $wpc_v['accept'],
                            'X-WPC-Cache-Warm' => '1',
                        ],
                    ]);
                }
                if ($wpc_socket_ok) {
                    $req = "GET {$path} HTTP/1.1\r\n"
                         . "Host: {$host}\r\n"
                         . "User-Agent: {$wpc_v['ua']}\r\n"
                         . "Accept: {$wpc_v['accept']}\r\n"
                         . "X-WPC-Cache-Warm: 1\r\n"
                         . "Connection: close\r\n\r\n";
                    $fp = wps_ic_ajax::wpc_loopback_open_socket($host, $port, $https, 0.2);
                    if ($fp) {
                        @stream_set_timeout($fp, 0, 100000);
                        @fwrite($fp, $req);
                        @fclose($fp);
                    }
                }
                // Small gap so the renders queue politely instead of landing simultaneously.
                $wpc_gap_ms = (int) apply_filters('wpc_warm_variant_gap_ms',
                    mt_rand(150, 400) * ((function_exists('wpc_is_constrained_host') && wpc_is_constrained_host()) ? 4 : 1));
                if ($wpc_gap_ms > 0) {
                    @usleep($wpc_gap_ms * 1000);
                }
            }
        } catch (\Throwable $e) {

        }
        return true;
    }
}

if (!function_exists('wpc_warm_rx_gate')) {
    /**
     * Receiver-side shed: our own warm loopbacks may never exhaust the FPM pool. At most
     * wpc_warm_rx_cap warm renders run concurrently; excess loopbacks get an instant 204
     * (the cron backstop re-fires anything that didn't land). Real visitors are never shed.
     */
    function wpc_warm_rx_gate()
    {
        try {
            if (empty($_SERVER['HTTP_X_WPC_CACHE_WARM'])
                || !empty($_SERVER['HTTP_X_WPC_DIAG'])
                || (defined('DOING_CRON') && DOING_CRON)
                || (function_exists('wp_doing_ajax') && wp_doing_ajax())) {
                return;
            }
            $now = time();
            $sl  = wpc_warm_rx_live_slots($now);
            if (function_exists('wpc_under_pressure') && wpc_under_pressure()) {
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('warm-rx-shed', '', '', ['why' => 'pressure']);
                }
                if (function_exists('status_header')) { status_header(204); }
                exit;
            }
            $cap = wpc_warm_rx_cap();
            if (count($sl) >= $cap) {
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('warm-rx-shed', '', '', ['inflight' => count($sl)]);
                }
                if (function_exists('status_header')) { status_header(204); }
                exit;
            }
            $sl[] = $now;
            update_option('wpc_warm_rx_slots', $sl, false);
            register_shutdown_function(function () use ($now) {
                try {
                    $sl = get_option('wpc_warm_rx_slots');
                    if (is_array($sl)) {
                        $k = array_search($now, $sl, true);
                        if ($k !== false) {
                            unset($sl[$k]);
                            update_option('wpc_warm_rx_slots', array_values($sl), false);
                        }
                    }
                } catch (\Throwable $e) {
                }
            });
            // v7.10.691 — warm traffic is the wire's heartbeat. The kick-lane catchup only runs
            // on repull branches, which a HEALTHY site may not enter for hours — the exact state
            // that left c3720e5a's crit serving with 0a0080ce's manifest. Warms are internal and
            // detached (nobody waits on them), fire on every update-window/land wave, and each
            // one heals its own URL. Transient-gated inside (300s): ~3 file reads per warm.
            if (function_exists('wpc_wire_catchup') && class_exists('wps_ic_url_key')) {
                $url_key = ltrim((string) (new wps_ic_url_key())->setup(''), '/');
                if ($url_key !== ''
                    && !(function_exists('wpc_pipeline_key_junk') && wpc_pipeline_key_junk($url_key))) {
                    wpc_wire_catchup($url_key);
                }
            }
        } catch (\Throwable $e) {
        }
    }
    add_action('init', 'wpc_warm_rx_gate', 0);
}

if (!function_exists('wpc_url_warm_cron_handler')) {
    /**
     * Cron backstop: check which of the 4 hashed-cache variant files actually landed; re-fire only
     * the missing ones. Max 2 attempts, then leave the rest to live traffic.
     */
    function wpc_url_warm_cron_handler($url, $attempt = 1)
    {
        // .473: Safe Mode stands the DRAIN down too, not just admission — a cron event already
        // in the row would otherwise run. Returns without rescheduling, so nothing accumulates.
        if (function_exists('wpc_bg_lane_allowed') && !wpc_bg_lane_allowed('wpc_url_warm')) {
            return;
        }
        try {
            if (empty($url) || !defined('WPS_IC_CACHE') || !class_exists('wps_ic_url_key')) {
                return;
            }
            if (method_exists('wps_ic_url_key', 'sanitizeSameHostUrl')) {
                $url = wps_ic_url_key::sanitizeSameHostUrl($url);
                if ($url === '') {
                    return;
                }
            }
            $wpc_key = (new wps_ic_url_key())->setup($url);
            if (empty($wpc_key)) {
                return;
            }
            if (function_exists('wpc_pipeline_key_junk') && wpc_pipeline_key_junk($wpc_key)) {
                return;
            }
            $wpc_dir     = rtrim(WPS_IC_CACHE, '/') . '/' . $wpc_key . '/';
            $wpc_missing = [];
            foreach (array_keys(wpc_warm_url_variants()) as $wpc_variant) {
                $wpc_prefix = $wpc_variant === '' ? '' : $wpc_variant . '_';
                if (wpc_copy_present_gzip($wpc_dir, $wpc_prefix) === '') {
                    $wpc_missing[] = $wpc_variant;
                }
            }
            if (empty($wpc_missing)) {
                return;
            }
            // Sender-side yield: never fire warm renders INTO pressure (the receiver shed
            // just burns a retry), and small boxes rebuild one variant per tick
            if (function_exists('wpc_under_pressure') && wpc_under_pressure()) {
                $pressure_retry_key = 'wpc_warm_resk_' . md5($url);
                $pressure_retry_count = (int) get_transient($pressure_retry_key);
                if ($pressure_retry_count < 6 && function_exists('wp_schedule_single_event') && function_exists('wp_next_scheduled')
                    && !wp_next_scheduled('wpc_url_warm', [$url, (int) $attempt])) {
                    set_transient($pressure_retry_key, $pressure_retry_count + 1, HOUR_IN_SECONDS);
                    wpc_pl_sched(time() + 180, 'wpc_url_warm', [$url, (int) $attempt]);
                }
                return;
            }
            if (function_exists('wpc_box_cores') && wpc_box_cores() <= 2 && count($wpc_missing) > 1) {
                $wpc_missing = array_slice($wpc_missing, 0, 1);
                // Bounded by the same resk counter as the pressure path — never an open loop
                $small_box_retry_key = 'wpc_warm_resk_' . md5($url);
                $small_box_retry_count = (int) get_transient($small_box_retry_key);
                if ($small_box_retry_count < 6 && function_exists('wp_schedule_single_event') && function_exists('wp_next_scheduled')
                    && !wp_next_scheduled('wpc_url_warm', [$url, (int) $attempt])) {
                    set_transient($small_box_retry_key, $small_box_retry_count + 1, HOUR_IN_SECONDS);
                    wpc_pl_sched(time() + 60, 'wpc_url_warm', [$url, (int) $attempt]);
                }
            }
            $fired = wpc_warm_url_fire($url, $wpc_missing);
            wpc_cache_first_log('warm-cron', $wpc_key, $url, ['missing' => $wpc_missing, 'attempt' => (int) $attempt, 'fired' => $fired ? 1 : 0]);
            if ($fired === false) {


                $refused_retry_key = 'wpc_warm_resk_' . md5($url);
                $refused_retry_count = (int) get_transient($refused_retry_key);
                if ($refused_retry_count < 6 && function_exists('wp_schedule_single_event') && function_exists('wp_next_scheduled')
                    && !wp_next_scheduled('wpc_url_warm', [$url, (int) $attempt])) {
                    set_transient($refused_retry_key, $refused_retry_count + 1, HOUR_IN_SECONDS);
                    wpc_pl_sched(time() + 45, 'wpc_url_warm', [$url, (int) $attempt]);
                }
                return;
            }
            if ((int) $attempt < 2 && function_exists('wp_schedule_single_event') && function_exists('wp_next_scheduled')
                && !wp_next_scheduled('wpc_url_warm', [$url, (int) $attempt + 1])) {
                wpc_pl_sched(time() + 90, 'wpc_url_warm', [$url, (int) $attempt + 1]);
            }
        } catch (\Throwable $e) {

        }
    }
    add_action('wpc_url_warm', 'wpc_url_warm_cron_handler', 10, 2);
}


if (!function_exists('wpc_crit_dir')) {
    /**
     * A page's crit folder, 'critical/<key>/' with the trailing slash, or '' when the crit root is
     * not defined or the key is empty. A path only: it never makes the folder. About forty call
     * sites still build this path inline; new code asks here.
     */
    function wpc_crit_dir($urlKey)
    {
        $urlKey = trim((string) $urlKey, '/');
        if (!defined('WPS_IC_CRITICAL') || $urlKey === '' || strpos($urlKey, '..') !== false) {
            return '';
        }
        return rtrim(WPS_IC_CRITICAL, '/') . '/' . $urlKey . '/';
    }
}

if (!function_exists('wpc_crit_cur_uuid')) {
    /** The gen uuid to derive artifact URLs from — land_uuid (what actually
     *  landed) preferred over uuid (overwritten at dispatch). Requires ≥8 HEX
     *  chars so a degenerate value (all-dashes) can't derive a malformed URL. */
    function wpc_crit_cur_uuid($dir)
    {
        $dir = rtrim((string) $dir, '/') . '/';
        foreach (['land_uuid.txt', 'uuid.txt'] as $uf) {
            $uuid = preg_replace('/[^a-f0-9-]/i', '', trim((string) @file_get_contents($dir . $uf)));
            if (preg_match('/[a-f0-9]{8}/i', $uuid)) {
                return $uuid;
            }
        }
        return '';
    }
}
if (!function_exists('wpc_crit_artifact_url')) {
    /** URL of an observation artifact (delay.json / lcp.json), meta-or-DERIVED.
     *  The service returns /status=success (crit done) with NO delay_url/lcp_url
     *  BEFORE the observation artifacts land, and nothing re-polls after success —
     *  so the URL meta is frequently absent while {uuid[:4]}/{uuid}.<artifact> is
     *  already 200 (busyprosai bd175a43, confirmed live: 29KB measured delay.json +
     *  lcp.json with lcp_preload). Prefer the advertised meta; derive from the
     *  on-disk uuid only as the fallback. ?t= busts Bunny's edge so an IN-PLACE
     *  amendment (same uuid, richer body) is seen. Suffixes are the service's
     *  canonical layout (delay/lcp fleet-confirmed 200). */
    function wpc_crit_artifact_url($dir, $which)
    {
        $suf = ['delay' => '.delay.json', 'lcp' => '.lcp.json'];
        if (!isset($suf[$which])) {
            return '';
        }
        $dir  = rtrim((string) $dir, '/') . '/';
        $meta = $dir . ($which === 'delay' ? 'delay_url.txt' : 'lcp_url.txt');
        if (@is_readable($meta)) {
            $u = trim((string) @file_get_contents($meta));
            if ($u !== '' && preg_match('#^https?://#i', $u)) {
                return $u . (strpos($u, '?') !== false ? '&' : '?') . 't=' . time();
            }
        }
        $uuid = wpc_crit_cur_uuid($dir);
        if ($uuid !== '') {
            return 'https://critical-css-mc.b-cdn.net/' . substr($uuid, 0, 4) . '/' . $uuid . $suf[$which] . '?t=' . time();
        }
        return '';
    }
}
if (!function_exists('wpc_delay_manifest_landed')) {
    /** The four effects a freshly landed delay.json owes the rest of the plugin: the two
     *  promotion kill-switches clear, the aggressive-flip re-arms, and the page's stored HTML
     *  is purged so the next render reads the new manifest. Called from the write-once fetch
     *  and from a successful supersede replace, which are the only two writers of that file
     *  on this lane. */
    function wpc_delay_manifest_landed($urlKey)
    {
        delete_option('wpc_delay_v3_manifest_off');
        delete_option('wpc_delay_v3_promoted');
        wpc_delay_aggr_rearm();
        if (class_exists('wps_ic_cache_integrations') && method_exists('wps_ic_cache_integrations', 'purgeUrlHtml')) {
            function_exists('wpc_land_purge_coalesced') ? wpc_land_purge_coalesced($urlKey, '', 'delay-manifest-land') : wps_ic_cache_integrations::purgeUrlHtml($urlKey, '', ['context' => 'delay-manifest-land']);
        }
    }
}
if (!function_exists('wpc_crit_derived_replace')) {
    /** Fetch the fresh artifact first; only a 200 with a JSON body replaces the content and its pointer.
     *  Returns false and leaves both files untouched otherwise, so the measured copy keeps serving.
     *  Both writes are checked: the pointer is only moved once the new content is on disk, and the
     *  landed side effects only fire once both landed — a pointer naming bytes the disk does not
     *  hold is the stale-pointer shape this helper exists to end.
     *  $replaceReason names the staleness the caller found (url-advanced, pointer-purged,
     *  content-missing) and is echoed on the supersede receipt, so a cflog says which signal
     *  moved the artifact. */
    function wpc_crit_derived_replace($dir, $artifact, $freshUrl, $urlKey, $replaceReason = '')
    {
        $pointerFile = $artifact === 'delay' ? 'delay_url.txt' : 'lcp_url.txt';
        $contentFile = $artifact === 'delay' ? 'delay.json' : 'lcp.json';
        $r = wp_remote_get($freshUrl, ['headers' => ['user-agent' => defined('WPS_IC_API_USERAGENT') ? WPS_IC_API_USERAGENT : ''], 'timeout' => 5]);
        $body = (!is_wp_error($r) && (int) wp_remote_retrieve_response_code($r) === 200) ? wp_remote_retrieve_body($r) : '';
        if (!is_string($body) || $body === '' || !is_array(json_decode($body, true))) {
            if (function_exists('wpc_cache_first_log')) { wpc_cache_first_log('derived-supersede-deferred', (string) $urlKey, '', ['artifact' => $artifact, 'code' => is_wp_error($r) ? 0 : (int) wp_remote_retrieve_response_code($r)]); }
            return false;
        }
        $age = (int) @filemtime($dir . $contentFile);
        // A full disk, a read-only mount or a lost lock makes the write falsy. Recording the fresh
        // URL against the old content would pin this page on the old artifact for good: every later
        // check reads pointer == fresh and finds nothing stale to do.
        if (!wpc_crit_meta_write($dir . $contentFile, $body)) {
            if (function_exists('wpc_cache_first_log')) { wpc_cache_first_log('derived-supersede-deferred', (string) $urlKey, '', ['artifact' => $artifact, 'code' => 'write']); }
            return false;
        }
        if (!wpc_crit_meta_write($dir . $pointerFile, $freshUrl)) {
            // Content landed, pointer did not: the new bytes serve, the next check sees the old URL
            // and re-runs this replacement. Nothing downstream is told a manifest landed.
            if (function_exists('wpc_cache_first_log')) { wpc_cache_first_log('derived-supersede-pointer-failed', (string) $urlKey, '', ['artifact' => $artifact, 'bytes' => strlen($body)]); }
            return false;
        }
        @unlink($dir . ($artifact === 'delay' ? 'fonts_none.txt' : 'lcp_none.txt'));
        if ($artifact === 'delay') { wpc_delay_manifest_landed($urlKey); }
        if (function_exists('wpc_cache_first_log')) { wpc_cache_first_log('derived-supersede', (string) $urlKey, '', ['artifact' => $artifact, 'replaced' => 1, 'bytes' => strlen($body), 'age' => $age > 0 ? time() - $age : -1, 'why' => (string) $replaceReason]); }
        return true;
    }
}
if (!function_exists('wpc_lcp_has_usable_facts')) {
    /** USABLE atf facts = an entry carrying stem+css_w in some leg (legged or flat). */
    function wpc_lcp_has_usable_facts($j)
    {
        if (!is_array($j) || !isset($j['atf_images']) || !is_array($j['atf_images'])) { return false; }
        $l = [];
        foreach (['mobile', 'desktop'] as $g) {
            if (isset($j['atf_images'][$g]) && is_array($j['atf_images'][$g])) { $l = array_merge($l, $j['atf_images'][$g]); }
        }
        if (empty($l)) { $l = $j['atf_images']; }
        foreach ((array) $l as $e) {
            if (is_array($e) && !empty($e['stem']) && !empty($e['css_w'])) { return true; }
        }
        return false;
    }
}
if (!function_exists('wpc_write_lcp_preserving_facts')) {
    /** THE ONLY lcp.json WRITER. Census facts live on the gen uuid, so a regen ships a
     *  factless artifact and the pointer follows it — the sizes bake would flap off on
     *  every regen until the next mint (up to a day on a 1/domain budget). Facts already
     *  measured for THIS url survive: grafted onto the incoming body, marked inherited
     *  (never laundered as native), age-bounded, and only ever when the incoming body
     *  carries none of its own. Native facts always win. */
    function wpc_write_lcp_preserving_facts($dir, $body)
    {
        $dir = rtrim((string) $dir, '/') . '/';
        if (!is_string($body) || $body === '') { return false; }
        $incoming = json_decode($body, true);
        if (!is_array($incoming)) { return false; }
        $lcp_file = $dir . 'lcp.json';
        if (apply_filters('wpc_lcp_carry_facts', true)
            && !wpc_lcp_has_usable_facts($incoming) && @is_readable($lcp_file)) {
            $current_mtime = (int) @filemtime($lcp_file);
            $current = json_decode((string) @file_get_contents($lcp_file), true);
            if (is_array($current) && wpc_lcp_has_usable_facts($current) && $current_mtime > 0
                && (time() - $current_mtime) < (int) apply_filters('wpc_lcp_carry_max_age', 7 * DAY_IN_SECONDS)) {
                $incoming['atf_images'] = $current['atf_images'];
                if (empty($incoming['oversized_images']) && !empty($current['oversized_images'])) {
                    $incoming['oversized_images'] = $current['oversized_images'];
                }
                $incoming['wpc_inherited'] = [
                    't' => $current_mtime,
                    'from' => isset($current['census']['method']) ? (string) $current['census']['method']
                        : (!empty($current['wpc_inherited']['from']) ? (string) $current['wpc_inherited']['from'] : 'prev'),
                ];
                $encoded = wp_json_encode($incoming);
                if (is_string($encoded) && $encoded !== '') {
                    $body = $encoded;
                    if (function_exists('wpc_cache_first_log')) {
                        wpc_cache_first_log('lcp-facts-carried', '', '', [
                            'age' => time() - $current_mtime,
                            'from' => (string) $incoming['wpc_inherited']['from'],
                        ]);
                    }
                }
            }
        }
        return wpc_crit_meta_write($lcp_file, $body);
    }
}
if (!function_exists('wpc_is_lcp_taint_pending')) {
    /** On-disk lcp.json is a challenged taint with no census and no usable facts, <7d old
     *  — the shape the in-place amend replaces. Shared by the recovery trigger AND the
     *  traffic carrier's converged-gate: a caller that returns on "measured delay" must
     *  still fall through while this is true. */
    function wpc_is_lcp_taint_pending($dir)
    {
        if (!@is_readable($dir . 'lcp.json')) { return false; }
        $mt = (int) @filemtime($dir . 'lcp.json');
        if ($mt <= 0 || (time() - $mt) >= 7 * DAY_IN_SECONDS) { return false; }
        $j = json_decode((string) @file_get_contents($dir . 'lcp.json'), true);
        if (!is_array($j) || empty($j['nav_debug']['challenged'])) { return false; }
        // A census whose facts were INHERITED (service carry-forward, v3.198.24: method
        // "inherited", or per-leg census.legs{mobile|desktop}) is not this gen's own
        // measurement — same standing as our own wpc_inherited marker, so it must not
        // retire the refetch. Any single inherited leg keeps us converging.
        if (isset($j['census'])) {
            $has_inherited = false;
            if (is_array($j['census'])) {
                $census_legs = (isset($j['census']['legs']) && is_array($j['census']['legs'])) ? $j['census']['legs'] : [];
                foreach (['mobile', 'desktop'] as $device) {
                    if (isset($census_legs[$device]) && (string) $census_legs[$device] === 'inherited') { $has_inherited = true; }
                }
                if (!$has_inherited && isset($j['census']['method'])
                    && (string) $j['census']['method'] === 'inherited') { $has_inherited = true; }
            }
            if (!$has_inherited) { return false; }
        }
        // Inherited facts keep the bake armed but are NOT this gen's measurement — the
        // refetch keeps trying for native ones until the mint (or carry-forward) lands.
        return !wpc_lcp_has_usable_facts($j) || !empty($j['wpc_inherited']);
    }
}
if (!function_exists('wpc_amend_delay_recovery')) {
    /** IN-PLACE AMENDMENT RECOVERY (Artifact Identity Contract 2026-07-22): the
     *  service amends artifacts under a STABLE uuid — ceiling / lcp_preload /
     *  schema_epoch land AFTER the initial crit, so a by-URL cache pins the pre-
     *  amendment copy (busyprosai). While the on-disk delay.json is NOT measured-
     *  shape, re-fetch it (meta-or-DERIVED URL) IGNORING write-once; overwrite ONLY
     *  if the refetch IS measured-shape (never regress). Self-throttled ≤once/5min
     *  per key; retires the instant it's measured. A land also re-pulls the amended
     *  lcp.json (replace-on-200, never blanks a working hero). Extracted so BOTH the
     *  cron/rail repull AND the cron-FREE traffic carrier (wpc_amend_traffic_enqueue,
     *  post-response) run the exact same recovery. Returns true on a measured land. */
    function wpc_amend_delay_recovery($urlKey)
    {
        if ((string) $urlKey === '' || !defined('WPS_IC_CRITICAL') || !class_exists('wps_ic_js_delay_v3')
            || !apply_filters('wpc_delay_amend_refetch', true)
            || (function_exists('wpc_under_pressure') && wpc_under_pressure())) {
            return false; // load gate: the refetch is blocking HTTP — yield to visitors when hot
        }
        $dir = rtrim(WPS_IC_CRITICAL, '/') . '/' . $urlKey . '/';
        // A tainted lcp.json (challenged legs, facts withheld) is amended IN PLACE under the
        // same uuid after gen completes — the write-once law pins the taint, and the delay
        // measured-shape gate below never runs on a converged site. Re-fetch while the taint
