        if ($wpc_ucss_on && function_exists('wpc_used_css_store_sheets') && function_exists('wpc_used_css_sheets_path')
            && @is_readable($dir . 'used_css_sheets_url.txt') && @is_readable($dir . 'used_tpl.txt')) {
