}
if (!function_exists('wpc_wp_cache_record_verdict')) {
    /**
     * The page cache is active only when WP_CACHE is true as WordPress loads: core includes
     * advanced-cache.php only then. The setting, the drop-in on disk or a line written during
     * this request are claims, not the state. greenvalleytint.com (2026-09-22/24) had the setting
     * on and the drop-in installed with WP_CACHE unset (its wp-config.php sits one directory above
     * the web root, where the writer never looked), "only the home URL caches", and the dashboard
     * said nothing.
     */
    function wpc_page_cache_constant_active()
    {
        return defined('WP_CACHE') && WP_CACHE;
    }

    /** The verdicts of wps_ic_htaccess::setWPCache() that leave WP_CACHE for the admin to add. */
    function wpc_wp_cache_verdict_failed($verdict)
    {
        return in_array((string) $verdict, ['not-found', 'not-readable', 'not-writable'], true);
    }

    function wpc_wp_cache_verdict_record()
    {
        $record = get_option('wpc_wp_cache_constant_verdict', []);
        return is_array($record) ? $record : [];
    }

    /**
     * What the admin must add and where. The plugin may not write the file (it is missing where
     * core looks, unreadable or read-only); adding the line by hand is the fix, so the notice says
     * exactly that instead of the plugin failing quietly.
     */
    function wpc_wp_cache_notice_text($verdict, $path)
    {
        $where = ((string) $path !== '') ? (string) $path : __('your wp-config.php', 'wp-compress-image-optimizer');
        $reasons = [
            'not-found'    => __('No wp-config.php was found in the WordPress folder or the folder above it.', 'wp-compress-image-optimizer'),
            'not-readable' => __('The file could not be read.', 'wp-compress-image-optimizer'),
            'not-writable' => __('The file is not writable by the web server.', 'wp-compress-image-optimizer'),
        ];
        $reason = isset($reasons[$verdict]) ? $reasons[$verdict] : '';
        return trim(sprintf(
            /* translators: 1: plugin name, 2: path of wp-config.php, 3: why the plugin could not add the line itself */
            __('%1$s could not enable the page cache: add define(\'WP_CACHE\', true); to %2$s above the line that says /* That\'s all, stop editing! */. %3$s Until then the page cache is not active: cached pages are served only after WordPress and every plugin have loaded.', 'wp-compress-image-optimizer'),
            function_exists('wpc_brand_name') ? wpc_brand_name() : 'WP Compress',
            $where,
            $reason
        ));
    }

    /**
     * Stores the writer's verdict (option wpc_wp_cache_constant_verdict: verdict, path, at),
     * writes the wpcache-verdict receipt only when the verdict or path changes, and raises or
     * clears the notice. $cacheWanted is whether the caller asked for WP_CACHE true.
     */
    function wpc_wp_cache_record_verdict($verdict, $path, $cacheWanted)
    {
        $verdict = (string) $verdict;
        $path = (string) $path;
        $previous = wpc_wp_cache_verdict_record();
        if ((isset($previous['verdict']) ? (string) $previous['verdict'] : '') !== $verdict
            || (isset($previous['path']) ? (string) $previous['path'] : '') !== $path) {
            update_option('wpc_wp_cache_constant_verdict', ['verdict' => $verdict, 'path' => $path, 'at' => time()], true);
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('wpcache-verdict', '', '', ['verdict' => $verdict, 'path' => $path]);
            }
        }
        if ($cacheWanted && wpc_wp_cache_verdict_failed($verdict) && !wpc_page_cache_constant_active()) {
            if (function_exists('wpc_set_state_notice')) {
                wpc_set_state_notice('wp_cache_constant', 'error', wpc_wp_cache_notice_text($verdict, $path));
            }
        } elseif (function_exists('wpc_clear_state_notice')) {
            wpc_clear_state_notice('wp_cache_constant');
        }
    }

    /**
     * Once per admin request: a failed verdict is re-read against the runtime constant, so the
     * notice goes away on the first load after the admin adds the line by hand (or turns the page
     * cache off). Reads only the autoloaded verdict record while nothing has failed.
     */
    function wpc_wp_cache_notice_sync()
    {
        $record = wpc_wp_cache_verdict_record();
        $verdict = isset($record['verdict']) ? (string) $record['verdict'] : '';
        if (!wpc_wp_cache_verdict_failed($verdict)) {
            return;
        }
        $recordedPath = isset($record['path']) ? (string) $record['path'] : '';
        $settings = defined('WPS_IC_SETTINGS') ? get_option(WPS_IC_SETTINGS) : [];
        $cacheWanted = is_array($settings) && !empty($settings['cache']['advanced']) && $settings['cache']['advanced'] == '1';
        if (!$cacheWanted) {
            wpc_wp_cache_record_verdict('disabled', $recordedPath, false);
            return;
        }
        if (wpc_page_cache_constant_active()) {
            $configPath = function_exists('wpc_wp_config_path') ? wpc_wp_config_path() : '';
            wpc_wp_cache_record_verdict($configPath !== '' ? 'found' : 'defined-elsewhere', $configPath, true);
            return;
        }
        wpc_wp_cache_record_verdict($verdict, $recordedPath, true);
    }
    add_action('admin_init', 'wpc_wp_cache_notice_sync', 30);

    /**
     * The page-cache toggle's state line: '' while the page cache is off or active, else why it
     * is not active. Active means WP_CACHE true at runtime and nothing else.
     */
    function wpc_page_cache_inactive_reason()
    {
        $settings = defined('WPS_IC_SETTINGS') ? get_option(WPS_IC_SETTINGS) : [];
        $cacheWanted = is_array($settings) && !empty($settings['cache']['advanced']) && $settings['cache']['advanced'] == '1';
        if (!$cacheWanted || wpc_page_cache_constant_active()) {
            return '';
        }
        $record = wpc_wp_cache_verdict_record();
        $verdict = isset($record['verdict']) ? (string) $record['verdict'] : '';
        $path = isset($record['path']) ? (string) $record['path'] : '';
        // The line reached the file during this or the last minute's requests (a save, or the update
        // path on admin_init just before it): WordPress reads it from the next load. Older than that
        // and still not seen is not "next load".
        if (in_array($verdict, ['written', 'found'], true) && (time() - (isset($record['at']) ? (int) $record['at'] : 0)) < 60) {
            /* translators: %s: path of wp-config.php */
            return sprintf(__('Active from the next page load: WP_CACHE is now set in %s.', 'wp-compress-image-optimizer'), $path);
        }
        if (wpc_wp_cache_verdict_failed($verdict)) {
            return __('Not active: WP_CACHE is not set in wp-config.php (see the notice at the top of this page), so cached pages are served only after WordPress has loaded.', 'wp-compress-image-optimizer');
        }
        return __('Not active: WP_CACHE is not true when WordPress loads, so cached pages are served only after WordPress has loaded.', 'wp-compress-image-optimizer');
    }
}
if (!function_exists('wpc_is_admin_lane_held')) {
    /**
     * v7.22.69 — ONE AUTOLOADED LEDGER FOR THE PER-REQUEST LANE HOLDS. Eight admin-request lanes each
     * read (and periodically wrote) their own transient: two queries per lane per admin page and
     * heartbeat with no object cache. The ledger rides alloptions: zero queries to read, one write
     * when a lane actually fires.
     */
