if (!function_exists('wpc_font_display_effective')) {
    // 'smart' resolves per-site: optional only when the deterministic metrics verdict
    // landed (matched twin proven from the woff2 tables) — zero-CLS is then free; else swap.
    function wpc_font_display_effective($raw, $family = '')
    {
        $raw = strtolower(trim((string) $raw));
        // v7.10.401: 'smart' has always resolved to optional once metrics are validated.
        // Extend that to plain 'swap': a swap with a VALIDATED metrics-matched fallback still
        // swap-reflows on every load for zero benefit (the fallback is metrics-identical), and
        // that reflow is the residual CLS on Divi headings (busy desktop 0.131 -> ~0). Only
        // upgrades when metrics are proven (trustworthy fallback); un-validated swap is left
        // alone (show the real font). Filtered so an explicit swap preference can be restored.
        // v7.21.134 — THE DROPDOWN DOES WHAT IT SAYS. 'smart' is the auto mode and keeps
        // the validated-metrics optional upgrade (.401's measured CLS win, default preset);
        // an EXPLICIT 'swap' selection is a user override and is honored verbatim — the
        // upgrade silently rewriting it to optional was the "choosing Swap changes nothing"
        // report (optica-suiza). Filter restores the old behavior per-site if wanted.
        if ($raw === 'smart' || ($raw === 'swap' && apply_filters('wpc_fd_swap_to_optional_when_validated', false))) {
            // A trustworthy fallback exists when the SERVICE validated it (strict) OR the plugin
            // computed font-metrics for the site and baked size-adjust fallbacks (present). Either
            // makes the fallback metric-matched, so optional is safe and kills the swap-CLS.
            $v = get_option('wpc_font_metrics_validated');
            // v7.10.483 — PER-FAMILY, not site-wide. 'optional' is safe only when THIS family has a
            // metric-matched fallback; the guard read only $v['t'], a site-wide boolean, so one
            // family with metrics promoted EVERY face to optional. zinsenvergleich receipt: two
            // Astra faces, size-adjust=(NONE) and ascent-override=(NONE) on both, one emitted as
            // optional — and Astra is still fetched over the network, so that glyph may simply
            // never paint. That is the .443 trade (invisible icon beats no byte win) arriving by a
            // different route. The per-family list was already being written into $v['fams'] and
            // simply never read.
            // No family supplied => unchanged site-wide behaviour, so no caller regresses.
            $family_name = strtolower(trim((string) $family, " \t\"'"));
            if ($family_name !== '') {
                $validated_families = (is_array($v) && !empty($v['fams']) && is_array($v['fams']))
                    ? array_map('strtolower', $v['fams']) : [];
                if (in_array($family_name, $validated_families, true)) { return 'optional'; }
                // v7.21.03 — A BAKED FALLBACK IS THE PROOF; THE FLAG IS ONLY A DECLARATION.
                // $v['fams'] is populated solely from the artifact's per-face 'validated' key.
                // borderlessmoves: the fonts payload carried Fredoka metrics (we bake
                // "Fredoka Fallback" with size-adjust:101.8%/ascent-override:95.6% from them and
                // splice it into every stack) but no validated flag — so this gate said swap and
                // 10 of 23 late faces kept swapping, which IS the reflow (mobile CLS 0.868).
                // Metrics we actually emitted a fallback from are stronger evidence than a flag
                // that may simply be absent, and they make optional safe by the same argument:
                // text still renders, in a metric-matched face. No metrics => still swap, so
                // icon fonts (never metric-matched) keep today's behaviour and cannot go tofu.
                if (apply_filters('wpc_fd_optional_on_baked_metrics', true)) {
                    $family_metrics = null;
                    $fallback_metrics = apply_filters('wpc_font_fallback_metrics', []);
                    if (is_array($fallback_metrics)) {
                        foreach ($fallback_metrics as $metrics_key => $metrics_row) {
                            if (!is_array($metrics_row) || !is_string($metrics_key)) { continue; }
                            $key_family = strtolower(trim(explode('|', $metrics_key)[0]));
                            if ($key_family === $family_name) { $family_metrics = $metrics_row; break; }
                        }
                    }
                    if (!is_array($family_metrics) && function_exists('wpc_font_catalog_metrics')) {
                        $family_metrics = wpc_font_catalog_metrics($family_name);
                    }
                    // Only a REAL metric override counts — an empty/echoed row proves nothing.
                    if (is_array($family_metrics)
                        && ((!empty($family_metrics['size-adjust']) && preg_match('/^[0-9.]+%$/', (string) $family_metrics['size-adjust']))
                            || (!empty($family_metrics['ascent-override']) && preg_match('/^[0-9.]+%$/', (string) $family_metrics['ascent-override'])))) {
                        return 'optional';
                    }
                }
                // Unknown family => swap. The font renders and may reflow; optional risks never
                // rendering at all. Reflow is recoverable, invisible text is not.
                return 'swap';
            }
            $ok = (is_array($v) && !empty($v['t'])) || (int) get_option('wpc_font_metrics_present', 0) === 1;
            return $ok ? 'optional' : 'swap';
        }
        return $raw;
    }
}

if (!function_exists('wpc_fd_auto_migrate')) {
    function wpc_fd_auto_migrate()
    {
        try {
            if (get_option('wpc_fd_auto_migr') === '1' || !apply_filters('wpc_fd_auto_to_swap', true)) {
                return;
            }
            $set = get_option(WPS_IC_SETTINGS);
            if (!is_array($set) || empty($set['font-display']) || strtolower((string) $set['font-display']) !== 'auto') {
                update_option('wpc_fd_auto_migr', '1', false);
                return;
            }
            $set['font-display'] = 'swap';
            update_option(WPS_IC_SETTINGS, $set);
            update_option('wpc_fd_auto_migr', '1', false);
            delete_option('wpc_fd_rebake_v');
            if (function_exists('wpc_fontdisplay_rebake_once')) {
                wpc_fontdisplay_rebake_once();
            }
            if (function_exists('wpc_r2_purge_html_layers')) {
                wpc_r2_purge_html_layers();
            }
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('fd-auto-migrated', '', '', ['to' => 'swap']);
            }
        } catch (\Throwable $e) {
        }
    }
    add_action('admin_init', 'wpc_fd_auto_migrate', 32);
}


if (!function_exists('wpc_compute_tpl_key')) {

    function wpc_compute_tpl_key()
    {
        try {
            $h = [];
            if (!empty($GLOBALS['wp_styles']) && !empty($GLOBALS['wp_styles']->done)) {
                foreach ((array) $GLOBALS['wp_styles']->done as $handle) {
                    $reg = isset($GLOBALS['wp_styles']->registered[$handle]) ? $GLOBALS['wp_styles']->registered[$handle] : null;
                    $version = ($reg && !empty($reg->ver)) ? (string) $reg->ver : '0';
                    // v7.10.626 — A BUILD STAMP IS NOT A TEMPLATE VERSION. Elementor
                    // enqueues its per-post CSS with ver = the file's mtime
                    // (post-6912.css?ver=1785456828), so every CSS rebuild minted a brand
                    // new tpl_key: the service saw an endless stream of "new" templates,
                    // its 3-template observation budget filled, and 7 of 10 staging
                    // templates could not refresh their used-css since July (their trace,
                    // 2026-07-31: /affiliates/ minted two keys six minutes apart). The key
                    // names WHICH sheets compose this template; a 10-digit unix timestamp
                    // says only WHEN one was written. Real release versions (1.2.3, theme
                    // versions) still participate.
                    if (preg_match('/^\d{9,11}$/', $version)
                        && (int) $version > 946684800 && (int) $version < 4102444800) {
                        $version = 'b';
                    }
                    $h[] = $handle . ':' . $version;
                }
            }
            sort($h);
            $theme = function_exists('wp_get_theme') ? wp_get_theme() : null;
            $sig = (function_exists('get_template') ? get_template() : '') . '|'
                 . ($theme ? $theme->get('Version') : '') . '|'
                 . (!empty($GLOBALS['template']) ? basename((string) $GLOBALS['template']) : '') . '|'
                 . implode(',', $h);
            return 'tpl:' . substr(sha1($sig), 0, 16);
        } catch (\Throwable $e) {
            return '';
        }
    }


    function wpc_dispatch_tpl_key($urlKey)
    {
        if (!defined('WPS_IC_CRITICAL') || empty($urlKey)) {
            return '';
        }
        $tk = trim((string) @file_get_contents(rtrim(WPS_IC_CRITICAL, '/') . '/' . $urlKey . '/tpl.txt'));
        if ($tk === '') {
            // v7.22.11 — crit hand-off: tpl_key missing on 32% of 7.22 gens. tpl.txt is
            // written by the cache SAVE, which runs after a first render's dispatch — so
            // every first-ever URL dispatched without a key and the service had no
            // template-cached observation for it. In a resolved front-end request the key
            // is computable right now; use it, and let the save persist the same value.
            if (function_exists('wpc_compute_tpl_key') && function_exists('did_action') && did_action('template_redirect')
                && !(function_exists('is_admin') && is_admin())) {
                try { $tk = trim((string) wpc_compute_tpl_key()); } catch (\Throwable $e) { $tk = ''; }
            }
            if ($tk === '') {
                return '';
            }
        }
        if (function_exists('wpc_used_css_key_valid')) {
            return wpc_used_css_key_valid($tk) ? $tk : '';
        }
        return preg_match('/^tpl:[a-f0-9]{6,}$/', $tk) ? $tk : '';
    }


    function wpc_dispatch_post_mtime($postID, $url)
    {
        if (!function_exists('get_post_modified_time')) {
            return '';
        }
        // Homepage / front page → dynamic ATF, no reliable content-version → omit.
        if (function_exists('home_url') && rtrim((string) $url, '/') === rtrim((string) home_url('/'), '/')) {
            return '';
        }
        $pid = (is_numeric($postID) && (int) $postID > 0) ? (int) $postID : 0;
        if ($pid === 0 && function_exists('url_to_postid')) {
            $pid = (int) url_to_postid((string) $url); // 0 for archives / taxonomies / search → omit
        }
        if ($pid <= 0) {
            return '';
        }
        $mt = get_post_modified_time('U', true, $pid); // GMT unix
        return ($mt && function_exists('get_post_status') && get_post_status($pid) === 'publish') ? (string) $mt : '';
    }
}


if (!function_exists('wpc_browser_accept')) {
    /**
     * The Accept header a current browser sends when it fetches a subresource of this kind:
     * 'image', 'style' or 'font'. A warm request to the zone sends the same, so the copy it stores
     * is the one a browser's request reads.
     */
    function wpc_browser_accept($kind)
    {
        if ($kind === 'image') {
            return 'image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8';
        }
        if ($kind === 'style') {
            return 'text/css,*/*;q=0.1';
        }
        return '*/*';
    }
}

if (!function_exists('wpc_site_cdn_hosts')) {
    /**
     * The hosts this site's CDN serves its files from: the Cloudflare CNAME, the custom CNAME and
     * the zone, lower-case, port and trailing dot dropped, as a set (host => 1).
     */
    function wpc_site_cdn_hosts()
    {
        $hosts = [];
        if (!function_exists('get_option')) {
            return $hosts;
        }
        foreach ([defined('WPS_IC_CF_CNAME') ? WPS_IC_CF_CNAME : 'wps-ic-cf-cname', 'ic_custom_cname', 'ic_cdn_zone_name'] as $option) {
            $host = strtolower(trim((string) get_option($option)));
            if (strpos($host, '://') !== false) {
                $host = strtolower((string) parse_url($host, PHP_URL_HOST));
            }
            $host = rtrim((string) preg_replace('/:\d+$/', '', $host), '.');
            if ($host !== '') {
                $hosts[$host] = 1;
            }
        }
        return $hosts;
    }
}

if (!function_exists('wpc_land_second_wave')) {
    function wpc_land_second_wave($url)
    {
        try {
            if (!class_exists('wps_ic_url_key') || !method_exists('wps_ic_url_key', 'sanitizeSameHostUrl')) {
                return;
            }
            $clean = wps_ic_url_key::sanitizeSameHostUrl((string) $url);
            if ($clean === '') {
                return;
            }

            // 1. External re-purge (same primitives purgeUrlHtml uses; each self-gates/no-ops).
            if (class_exists('wps_ic_cache_integrations')) {
                try {
                    if (method_exists('wps_ic_cache_integrations', 'purgeVarnish')) {
                        wps_ic_cache_integrations::purgeVarnish(0, false, $clean);
                    }
                } catch (\Throwable $e) {
                }
            }
            if (class_exists('wps_ic_cache') && method_exists('wps_ic_cache', 'purgeEdgeHtmlUrls')) {
                try {
                    $forms   = [$clean];
                    $forms[] = (substr($clean, -1) === '/') ? rtrim($clean, '/') : $clean . '/';
                    wps_ic_cache::purgeEdgeHtmlUrls(array_filter($forms));
                } catch (\Throwable $e) {
                }
            }


            $key = (new wps_ic_url_key())->setup($clean);
            if (empty($key) || !defined('WPS_IC_CACHE')) {
                return;
            }
            $dir = rtrim(WPS_IC_CACHE, '/') . '/' . $key . '/';
            if (apply_filters('wpc_bypass_freeze_fallback', true)) {
                $newest = 0;
                foreach (['index.html_gzip', 'webp_index.html_gzip', 'mobile_index.html_gzip', 'mobile-webp_index.html_gzip', 'localonly_index.html_gzip', 'mobile_localonly_index.html_gzip'] as $vf) {
                    $mt = @filemtime($dir . $vf);
                    if ($mt && $mt > $newest) {
                        $newest = $mt;
                    }
                }
                if ($newest > 0 && (time() - $newest) > 600) {
                    if (class_exists('wps_ic_cache_integrations') && method_exists('wps_ic_cache_integrations', 'purgeCacheFiles')) {
                        wps_ic_cache_integrations::purgeCacheFiles($key);
                    }
                    if (class_exists('wps_cacheHtml') && method_exists('wps_cacheHtml', 'removeStaticMirror')) {
                        wps_cacheHtml::removeStaticMirror($clean);
                    }
                    if (function_exists('wpc_cache_first_log')) {
                        wpc_cache_first_log('bypass-failed-fallback', $key, $clean, ['age' => time() - $newest]);
                    }
                    return;
                }
            }

            // 2. Edge pre-warm from the ARMED page (our own cache file — no origin request needed).
            if (!apply_filters('wpc_land_asset_prewarm', true) || !function_exists('wp_remote_get')) {
                return;
            }
            $html = '';
            foreach (['webp_index.html_gzip', 'index.html_gzip'] as $f) {
                if (@is_readable($dir . $f) && function_exists('gzdecode')) {
                    $raw = @file_get_contents($dir . $f);
                    if ($raw !== false) {
                        $html = (string) @gzdecode($raw);
                    }
                    break;
                }
            }
            if ($html === '') {
                return;
            }
            $targets = [];
            $kinds = [];

            if (preg_match('/<link[^>]*id="wpc-lcp-bg-preload"[^>]*href="([^"]+)"/i', $html, $m)
                || preg_match('/<link[^>]*href="([^"]+)"[^>]*id="wpc-lcp-bg-preload"/i', $html, $m)) {
                $targets[] = $m[1];
                $kinds[$m[1]] = 'image';
            }

            if (preg_match_all('/<link[^>]*rel="preload"[^>]*as="font"[^>]*href="([^"]+)"/i', $html, $mm)) {
                $targets = array_merge($targets, array_slice($mm[1], 0, 4));
            }
            // v7.10.689 — font preloads are post-paint injected now (data-wpc-fpb script,
            // JSON [[url,mime],...]); warm those URLs exactly like the old static tags.
            if (preg_match('/<script[^>]*data-wpc-fpb="1"[^>]*>\(function\(\)\{var u=(\[\[.*?\]\]);/s', $html, $fpb_match)) {
                $font_preloads = json_decode(str_replace('<\/', '</', (string) $fpb_match[1]), true);
                if (is_array($font_preloads)) {
                    foreach (array_slice($font_preloads, 0, 4) as $font_preload) {
                        if (is_array($font_preload) && !empty($font_preload[0])) {
                            $targets[] = (string) $font_preload[0];
                        }
                    }
                }
            }
            if (preg_match('/<link[^>]*id="wpc-used-css"[^>]*href="([^"]+)"/i', $html, $m)) {
                $targets[] = $m[1];
                $kinds[$m[1]] = 'style';
            }

            if (preg_match_all('/<link[^>]*type=["\'](?:wpc-stylesheet|wpc-mobile-stylesheet)["\'][^>]*href="([^"]+)"/i', $html, $mm)) {
                foreach (array_slice($mm[1], 0, 3) as $sheet) {
                    $targets[] = $sheet;
                    $kinds[$sheet] = 'style';
                }
            }

            $home_host = (string) parse_url(home_url(), PHP_URL_HOST);
            $cdn_hosts = wpc_site_cdn_hosts();
            $fired     = 0;
            foreach (array_unique($targets) as $t) {
                if ($fired >= 8) {
                    break;
                }
                $kind = isset($kinds[$t]) ? $kinds[$t] : 'font';
                $t = html_entity_decode((string) $t);
                $h = (string) parse_url($t, PHP_URL_HOST);
                if ($h === '' || ($h !== $home_host && stripos($h, 'zapwp.com') === false && !isset($cdn_hosts[strtolower($h)])
                    && !apply_filters('wpc_land_prewarm_host_ok', false, $h))) {
                    continue;
                }
                wp_remote_get($t, ['blocking' => false, 'timeout' => 3, 'redirection' => 2, 'headers' => ['Accept' => wpc_browser_accept($kind)]]);
                $fired++;
            }
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('second-wave', $key, $clean, ['prewarmed' => $fired]);
            }
        } catch (\Throwable $e) {
        }
    }
    add_action('wpc_land_second_wave', 'wpc_land_second_wave', 10, 1);
}


if (!function_exists('wpc_crit_page_dirs')) {
    /**
     * Every page folder under the critical root, as full paths. The root also holds stores that
     * are not pages — used-css, sidecar, the lazy-CSS lane's combined/ — and the dot folders
     * (.kicklocks); none of them is a page, so no page state is ever written into one. inv2/ is a
     * folder the deleted inv2 engine left behind (its reset created it on every manual purge,
     * engine on or off), so it is still skipped by name.
     */
    function wpc_crit_page_dirs()
    {
        if (!defined('WPS_IC_CRITICAL')) {
            return [];
        }
        $root = rtrim(WPS_IC_CRITICAL, '/');
        $out = [];
        foreach ((array) @scandir($root) as $entry) {
            if ($entry === '' || $entry === false || $entry[0] === '.'
                || in_array($entry, ['used-css', 'inv2', 'sidecar', 'combined'], true)
                || !@is_dir($root . '/' . $entry)) {
                continue;
            }
            $out[] = $root . '/' . $entry;
        }
        return $out;
    }

    /** Delete transients for $keys and, for 'all', every row with $prefix in the options table. */
    function wpc_crit_forget_transients($scope, array $keys, array $names)
    {
        foreach ($keys as $key) {
            foreach ($names as $name) {
                delete_transient($name($key));
            }
        }
        if ((string) $scope !== 'all' || !isset($GLOBALS['wpdb']) || !is_object($GLOBALS['wpdb'])
            || !method_exists($GLOBALS['wpdb'], 'query') || !isset($GLOBALS['wpdb']->options)) {
            return;
        }
        global $wpdb;
        foreach (array_keys($names) as $prefix) {
            foreach (['_transient_', '_transient_timeout_'] as $kind) {
                $wpdb->query($wpdb->prepare("DELETE FROM {$wpdb->options} WHERE option_name LIKE %s",
                    $wpdb->esc_like($kind . $prefix) . '%'));
            }
        }
    }

    /** Forget the service's served holds for the scope ('all' or one key). */
    function wpc_crit_forget_served_holds($scope, array $keys)
    {
        wpc_crit_forget_transients($scope, $keys, [
            WPC_GEN_SERVED_HOLD_PREFIX => function ($key) { return WPC_GEN_SERVED_HOLD_PREFIX . md5((string) $key); },
        ]);
    }

    /** Forget the generation each page of the scope holds as the one it waits for. */
    function wpc_crit_forget_held_uuids($scope, array $keys)
    {
        wpc_crit_forget_transients($scope, $keys, [
            'wpc_critical_uuid_' => function ($key) { return 'wpc_critical_uuid_' . $key; },
        ]);
    }
}

if (!function_exists('wpc_crit_invalidate')) {
    /**
     * The one way crit is invalidated. Every caller names its reason; the reason is the
     * measurement key of the receipt `crit-invalidate {scope, reason, mode, dirs}`.
     *
     * $scope: 'all', or one url key.
     * $mode:
     *   'wipe'  — the old crit is known to be wrong for the page and a person or a theme change
     *             said so (Remove Critical CSS, switch_theme, a per-page removal, the integration
     *             API's purge calls). The removal epoch at the same scope goes up first, so the
     *             service cannot hand the removed generation back, then the files go: for 'all'
     *             the crit and its identity files, for one key that page's files. The page is
     *             crit-less until a new generation lands. A site-wide wipe keeps the measured
     *             state (delay.json, lcp.json) unless the reason says the site itself changed
     *             (wpc_crit_wipe_drops_measured): a measurement of the old theme is a wrong
     *             answer for the new one, not a stale one.
     *   'stale' — everything else that can change the CSS surface. stale.txt in every page dir
     *             of the scope and the park reset: the old crit keeps serving and the page stays
     *             cached, the regeneration is owed on the page's next visit (the render's stale
     *             kick). stale.txt is cleared by a land and by nothing else. Nothing is deleted
     *             and no epoch moves.
     * A trigger that cannot change the CSS surface does not call this at all.
     *
     * One invalidation per scope and mode per request: a second call that an earlier one already
     * covers ('all' covers every key, 'wipe' covers 'stale') does nothing and returns 0.
     *
     * Returns the number of page dirs touched.
     */
    function wpc_crit_invalidate($scope, $reason, $mode)
    {
        $scope = (string) $scope === 'all' ? 'all' : ltrim((string) $scope, '/');
        $reason = (string) $reason;
        $mode = (string) apply_filters('wpc_crit_invalidate_mode', $mode === 'wipe' ? 'wipe' : 'stale', $reason);
        $mode = $mode === 'wipe' ? 'wipe' : 'stale';
        if ($scope === '' || strpos($scope, '..') !== false || !defined('WPS_IC_CRITICAL')) {
            return 0;
        }
        $done = isset($GLOBALS['wpc_crit_invalidated']) && is_array($GLOBALS['wpc_crit_invalidated'])
            ? $GLOBALS['wpc_crit_invalidated'] : [];
        $coveredBy = $mode === 'wipe' ? ['wipe'] : ['wipe', 'stale'];
        foreach ($coveredBy as $coveringMode) {
            if (isset($done[$coveringMode . '|all']) || isset($done[$coveringMode . '|' . $scope])) {
                return 0;
            }
        }
        $GLOBALS['wpc_crit_invalidated'] = $done + [$mode . '|' . $scope => $reason];

        $root = rtrim(WPS_IC_CRITICAL, '/');
        $dirs = 0;
        $measuredDropped = null;
        try {
            $scopeKeys = $scope === 'all' ? array_map('basename', wpc_crit_page_dirs()) : [$scope];
            // An invalidation asks for a regeneration: a served hold (the service's "nothing new
            // for an hour") is about the crit that was just invalidated and must not refuse it. For
            // 'all' that is one more walk of the crit root and an options-table sweep; on an
            // object-cache site only the keys that have a page folder are reached.
            wpc_crit_forget_served_holds($scope, $scopeKeys);
            if ($mode === 'wipe') {
                if (function_exists('wpc_crit_epoch_bump')) {
                    wpc_crit_epoch_bump($scope === 'all' ? 'site' : 'page', $scope === 'all' ? '' : $scope, $reason);
                }
                // Before any file goes: nothing may still name a removed generation. The held
                // uuid is what the collect lanes pull straight from the CDN by, with no service
                // call that could refuse it.
                wpc_crit_forget_held_uuids($scope, $scopeKeys);
                // The per-page cap counts dispatches for the crit that was just removed.
                if (function_exists('wpc_gen_rate_reset')) {
                    wpc_gen_rate_reset($scope);
                }
                // A removal asks for new crit, so no page it touches may stay refused by a dead mark:
                // one such mark kept two pages of a test site crit-less through Remove Critical.
                if (function_exists('wpc_kick_dead_clear')) {
                    wpc_kick_dead_clear($scope, $reason);
                }
                // Nor by the service's demand deferral: a pacing hold, not a verdict on the page.
                if (function_exists('wpc_gen_hold_forget_deferred')) {
                    wpc_gen_hold_forget_deferred($scope, $scopeKeys, $reason);
                }
                if ($scope === 'all') {
                    $dirs = count($scopeKeys);
                    if (function_exists('wpc_delete_crit_artifacts')) {
                        wpc_delete_crit_artifacts();
                    }
                    if (wpc_crit_wipe_drops_measured($reason)) {
                        $delayReset = function_exists('wpc_delay_manifest_reset') ? wpc_delay_manifest_reset($reason) : ['files' => 0];
                        $measuredDropped = (int) $delayReset['files'] + (int) wpc_lcp_observation_reset($reason);
                    }
                } else {
                    $dirs = is_dir($root . '/' . $scope) ? 1 : 0;
                    if (class_exists('wps_ic_cache_integrations')) {
                        wps_ic_cache_integrations::purgeCriticalFiles($scope);
                    }
                }
            } else {
                $pageDirs = [];
                if ($scope === 'all') {
                    // The used-CSS drop list trusts only crit written after the last site-wide mark.
                    set_transient('wpc_crit_stale_' . md5('all'), time(), 6 * HOUR_IN_SECONDS);
                    $pageDirs = wpc_crit_page_dirs();
                } elseif (@is_file($root . '/' . $scope . '/critical_desktop.css') || @is_file($root . '/' . $scope . '/critical_mobile.css')) {
                    // A page with no crit has nothing to keep serving: its next visit dispatches anyway.
                    $pageDirs[] = $root . '/' . $scope;
                }
                foreach ($pageDirs as $dir) {
                    if (wpc_crit_meta_write($dir . '/stale.txt', (string) time()) !== false) {
                        $dirs++;
                    }
                    // A stale mark is a request for a regeneration, so the park that would refuse
                    // one is forgotten; it re-arms after fresh landless dispatches if the landing
                    // path is genuinely broken.
                    if (function_exists('wpc_crit_park_reset')) {
                        wpc_crit_park_reset($dir);
                    }
                }
            }
        } catch (\Throwable $e) {
        }
        if (function_exists('wpc_cache_first_log')) {
            $layers = ['scope' => $scope, 'reason' => $reason, 'mode' => $mode, 'dirs' => $dirs];
            if ($measuredDropped !== null) {
                $layers['measured'] = $measuredDropped;
            }
            wpc_cache_first_log('crit-invalidate', $scope, '', $layers);
        }
        return $dirs;
    }
}

if (!function_exists('wpc_crit_wipe_drops_measured')) {
    /**
     * The site-wide wipes whose cause also invalidates what the service measured on the pages:
     * a theme switch and the integration API's purge_site both say the site's markup changed, so
     * the LCP facts and the delay manifest describe a page that no longer exists. Remove Critical
     * and the nuclear path are not listed: Remove says the crit is wrong, not the measurement,
     * and the nuclear path deletes every crit file itself.
     */
    function wpc_crit_wipe_drops_measured($reason)
    {
        return in_array((string) $reason, ['switch_theme', 'integration-purge-site'], true);
    }
}

if (!function_exists('wpc_crit_settings_keys')) {
    /** The settings whose change can change the critical CSS; wps_ic_options' purgeList owns the list. */
    function wpc_crit_settings_keys()
    {
        return class_exists('wps_ic_options') ? (new wps_ic_options())->criticalPurgeKeys() : [];
    }
}

if (!function_exists('wpc_crit_invalidate_on_settings_save')) {
    /**
     * A settings save, from whichever side it came: the site's own settings screen or the agency
     * portal's relay. One function, so the same change does the same thing from both.
     * Returns the dirs marked, or 0 when no changed key can change the critical CSS.
     */
    function wpc_crit_invalidate_on_settings_save(array $changedKeys)
    {
        if (empty(array_intersect(array_map('strval', $changedKeys), wpc_crit_settings_keys()))) {
            return 0;
        }
        global $wpdb;
        if (is_object($wpdb) && method_exists($wpdb, 'query')) {
            $wpdb->query($wpdb->prepare("DELETE FROM {$wpdb->options} WHERE option_name LIKE %s OR option_name LIKE %s",
                $wpdb->esc_like('_transient_wpc_critical_key_') . '%', $wpdb->esc_like('_transient_timeout_wpc_critical_key_') . '%'));
        }
        return wpc_crit_invalidate('all', 'settings-save', 'stale');
    }
}

if (!function_exists('wpc_delay_manifest_reset')) {
    /**
     * Delete the JS delay manifest and its sticky option state (v7.10.519).
     *
     * Reported by Denis and confirmed: NOTHING deleted delay.json. The only unlink in the
     * tree is delay_url.txt (the POINTER), dropped on every crit land while the body was
     * kept — so a fresh generation got a fresh pointer and the old manifest. And because
     * an overwrite requires the replacement to already be measured-shape ("never regress"),
     * a wrong manifest was immortal: no button could clear it.
     *
     * Worse, two of the option lanes had writers and ZERO deleters — wpc_presc_pins (2
     * writers) and wpc_delay_v3_jqneed (1 writer). A stale pin can hold one script eager
     * while its dependency stays delayed, which tears the chain and breaks JS with no way
     * out. Same class as every other bug this release: state with a writer and no deleter.
     *
     * Deleting the manifest does NOT regress behaviour — it drops to the unmeasured lane
     * until a new one lands, and since .512 the unmeasured defer path is order-safe.
     */
    function wpc_delay_manifest_reset($ctx = '')
    {
        $files_removed = 0;
        $options_removed = 0;
        try {
            if (defined('WPS_IC_CRITICAL')) {
                $crit_root = rtrim(WPS_IC_CRITICAL, '/');
                $entries = @scandir($crit_root);
                if (is_array($entries)) {
                    foreach ($entries as $entry) {
                        if ($entry === '.' || $entry === '..' || $entry === 'used-css') {
                            continue;
                        }
                        $page_dir = $crit_root . '/' . $entry;
                        if (!@is_dir($page_dir)) {
                            continue;
                        }
                        // Pointer AND body together — dropping only one is what created the
                        // fresh-pointer/stale-body split in the first place.
                        foreach (['delay.json', 'delay_url.txt'] as $file_name) {
                            if (@is_file($page_dir . '/' . $file_name) && @unlink($page_dir . '/' . $file_name)) {
                                $files_removed++;
                            }
                        }
                    }
                }
            }
            // Global (not per-key) lanes that outlived every file purge.
            foreach ([
                'wpc_delay_v3_manifest_off', 'wpc_delay_aggr_off', 'wpc_delay_v3_promoted',
                'wpc_presc_pins', 'wpc_delay_v3_jqneed',
            ] as $option_name) {
                if (get_option($option_name) !== false) {
                    delete_option($option_name);
                    $options_removed++;
                }
            }
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('delay-manifest-reset', '', '', [
                    'ctx' => (string) $ctx, 'files' => $files_removed, 'options' => $options_removed,
                ]);
            }
        } catch (\Throwable $e) {
        }
        return ['files' => $files_removed, 'options' => $options_removed];
    }
}

if (!function_exists('wpc_lcp_observation_reset')) {
    /**
     * Delete every page's LCP observation: lcp.json, its pointer (lcp_url.txt, lcp_src.txt), the
     * heal record and the measured-none mark. Body and pointer go together for the reason
     * wpc_delay_manifest_reset gives: a pointer that outlives its body re-fetches the old answer.
     * Until a generation lands the page renders with no LCP hints, which is the unmeasured state,
     * not a wrong one. Returns the number of files deleted.
     */
    function wpc_lcp_observation_reset($ctx = '')
    {
        $deleted = 0;
        try {
            if (!defined('WPS_IC_CRITICAL')) {
                return 0;
            }
            foreach (wpc_crit_page_dirs() as $pageDir) {
                foreach (['lcp.json', 'lcp_url.txt', 'lcp_src.txt', 'lcp_heal.json', 'lcp_none.txt'] as $name) {
                    $file = $pageDir . '/' . $name;
                    if (@is_file($file) && @unlink($file)) {
                        $deleted++;
                    }
                }
            }
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('lcp-observation-reset', '', '', ['ctx' => (string) $ctx, 'files' => $deleted]);
            }
        } catch (\Throwable $e) {
        }
        return $deleted;
    }
}

if (!function_exists('wpc_crit_bypass_active')) {
    /**
     * v7.10.391 zero-dark purge. Hard purge writes bypass.txt instead of deleting artifacts:
     * while active, STALE artifacts resolve as absent (pages render critless but CACHEABLE —
     * no layer is ever cold + forbidden to cache at once, the exact interaction behind the
     * post-purge 60s outages). An artifact fresher than the window start lifts the bypass
     * for its URL the moment it lands. File-based (stale.txt idiom): zero DB cost per render.
     */
    function wpc_crit_bypass_start()
    {
        if (!defined('WPS_IC_CRITICAL') || !function_exists('wpc_crit_meta_write')) { return false; }
        return wpc_crit_meta_write(rtrim(WPS_IC_CRITICAL, '/') . '/bypass.txt', (string) time()) !== false;
    }
    /**
     * v7.10.825 — per-URL window for Rebuild This Page: the clicked page stops serving its
     * suspect crit IMMEDIATELY (renders with full theme CSS, cacheable) instead of serving it
     * for the whole gen window. Same laws as the global window: land lifts it, orphan lifts it,
     * the 1800s ceiling bounds it.
     */
    function wpc_crit_bypass_page_start($key)
    {
        if (!defined('WPS_IC_CRITICAL') || !function_exists('wpc_crit_meta_write')) { return false; }
        $key = basename((string) $key);
        if ($key === '') { return false; }
        return wpc_crit_meta_write(rtrim(WPS_IC_CRITICAL, '/') . '/' . $key . '/bypass.txt', (string) time()) !== false;
    }
    /**
     * The bypass window that applies to $key, read without touching it: the site-wide window
     * first, else the key's own (Rebuild This Page). ['file', 'scope' => 'site'|'page'|'',
     * 'armed_at', 'state'] where state is 'none' (no window), 'expired' (past the ceiling),
     * 'no-key', 'orphan' (nothing dispatched since it armed and the land budget is spent),
     * 'no-crit' (no crit on disk), 'landed' (a crit newer than the window is on disk) or
     * 'active'. wpc_crit_bypass_active() acts on it (it removes an expired or orphaned window);
     * the doctor only reads it.
     */
    function wpc_crit_bypass_read($key, $now = null)
    {
        $window = ['file' => '', 'scope' => '', 'armed_at' => 0, 'state' => 'none'];
        if (!defined('WPS_IC_CRITICAL')) { return $window; }
        $now = $now === null ? time() : (int) $now;
        $key = basename((string) $key);
        $crit_root = rtrim(WPS_IC_CRITICAL, '/');
        $bf = $crit_root . '/bypass.txt';
        $scope = 'site';
        $t = (int) @file_get_contents($bf);
        // .825: no global window -> consult this key's own window (Rebuild This Page).
        if ($t <= 0 && $key !== '') {
            $bf = $crit_root . '/' . $key . '/bypass.txt';
            $scope = 'page';
            $t = (int) @file_get_contents($bf);
        }
        $window['file'] = $bf;
        if ($t <= 0) { return $window; }
        $window['scope'] = $scope;
        $window['armed_at'] = $t;
        if (($now - $t) > (int) apply_filters('wpc_crit_bypass_max_s', 1800)) {
            $window['state'] = 'expired';
            return $window;
        }
        if ($key === '') {
            $window['state'] = 'no-key';
            return $window;
        }
        // v7.10.690 — A DEFERRAL IS A PROMISE SOMETHING WILL UNDO IT. The window's undo is a
        // fresh land; its trigger is the purge-side redispatch. If NOTHING has dispatched for
        // this key since the window armed and the ≤60s land contract's budget is long spent,
        // the promise is broken: lift and serve the existing crit (soft-purge semantics)
        // instead of riding the 1800s ceiling critless. Keys whose regen DID dispatch keep the
        // window (dispatch_ts >= arm) and lift per-URL the moment their land arrives.
        if (($now - $t) > (int) apply_filters('wpc_crit_bypass_orphan_s', 240)) {
            $dispatch_ts = (int) @file_get_contents(rtrim(WPS_IC_CRITICAL, '/') . '/' . $key . '/dispatch_ts.txt');
            if ($dispatch_ts < $t) {
                $window['state'] = 'orphan';
                return $window;
            }
        }
        $m = (int) @filemtime(rtrim(WPS_IC_CRITICAL, '/') . '/' . $key . '/critical_desktop.css');
        // missing artifact = the ordinary critless path owns it; fresher-than-window = landed, lift
        $window['state'] = $m <= 0 ? 'no-crit' : ($m <= $t ? 'active' : 'landed');
        return $window;
    }

    function wpc_crit_bypass_active($key)
    {
        $window = wpc_crit_bypass_read($key);
        if ($window['state'] === 'expired') {
            @unlink($window['file']);
            return false;
        }
        if ($window['state'] === 'orphan') {
            @unlink($window['file']);
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('bypass-orphan-lift', basename((string) $key), '', ['open_s' => time() - $window['armed_at']]);
            }
            return false;
        }
        return $window['state'] === 'active';
    }
    /**
     * A page's bypass window waits for a crit newer than the one on disk. An answer that reused a
     * generation (debounced, unchanged, converged) and names the very generation on disk
     * (land_uuid.txt) says that crit is the current one: no newer crit is coming, and the window
     * ends. An answer naming any other generation leaves the window to its own laws (a land
     * lifts it). Only the page's own window is ended; the site-wide one is not a page's. Nothing
     * is purged here: renders inside the window are refused a copy while crit is on disk.
     */
    function wpc_crit_bypass_lift_reused($key, $served, $critUuid)
    {
        if (!defined('WPS_IC_CRITICAL')) { return false; }
        $key = basename((string) $key);
        $critUuid = (string) $critUuid;
        if ($key === '' || $critUuid === '') { return false; }
        $dir = rtrim(WPS_IC_CRITICAL, '/') . '/' . $key . '/';
        if (trim((string) @file_get_contents($dir . 'land_uuid.txt')) !== $critUuid) { return false; }
        if (!@is_file($dir . 'bypass.txt') || !@unlink($dir . 'bypass.txt')) { return false; }
        if (function_exists('wpc_cache_first_log')) {
            wpc_cache_first_log('bypass-lift', $key, '', ['why' => 'served-' . (string) $served,
                'crit_uuid' => substr($critUuid, 0, 8)]);
        }
        return true;
    }
}
if (!function_exists('wpc_crit_park_reset')) {
    /**
     * Forget a page's landless park: gen_fails.json goes, except the page's own removal epoch, what
     * the service acknowledged of it, and the order our generations were dispatched in — the
     * values in that file that are not about the park. The epochs must outlive every purge so each
     * later dispatch keeps carrying them and the static lanes keep waiting for the acknowledgement.
     * The dispatch order must outlive a stale mark, because the land that answers the mark is
     * judged by it: when a stale mark dropped it, the re-poll and sync lanes landed an older
     * generation over a newer one on two test sites, after every other lane had refused it.
     * TRUE when the park record was dropped.
     */
    function wpc_crit_park_reset($dir)
    {
        $file = rtrim((string) $dir, '/') . '/gen_fails.json';
        if (!@is_file($file)) {
            return false;
        }
        $stored = json_decode((string) @file_get_contents($file), true);
        $kept = [];
        if (is_array($stored)) {
            if (isset($stored['page_epoch']) && (int) $stored['page_epoch'] > 0) {
                $kept['page_epoch'] = (int) $stored['page_epoch'];
                if (isset($stored['page_epoch_acked'])) {
                    $kept['page_epoch_acked'] = (int) $stored['page_epoch_acked'];
                }
            }
            if (!empty($stored['dispatched']) && is_array($stored['dispatched'])) {
                $kept['dispatched'] = $stored['dispatched'];
            }
        }
        if ($kept !== []) {
            wpc_crit_meta_write($file, json_encode($kept));
            return true;
        }
        return @unlink($file);
    }
}

if (!function_exists('wpc_delete_crit_artifacts')) {
    // v7.21.196 — REMOVE MEANS DELETE. The .391 bypass window kept artifacts on disk and
    // auto-lifted (240s orphan / fresh land), so a BROKEN artifact survived Remove and
    // resurrected (rosario, twice in one day). The dangerous half of the old hard purge was
    // never the delete — it was forbidding pages to cache while cold. So: unlink the CRIT
    // artifacts (css + combined + land/uuid identity + stale/bypass marks) while renders stay
    // critless-but-CACHEABLE, and deliberately KEEP the measured state (delay.json, lcp.json,
    // fonts, subsets, used-css, metrics) — deleting those is the .56 unmeasured-lane class.
    function wpc_delete_crit_artifacts()
    {
        $n = 0;
        try {
            if (!defined('WPS_IC_CRITICAL')) {
                return 0;
            }
            $root = rtrim(WPS_IC_CRITICAL, '/');
            @unlink($root . '/bypass.txt');
            // v7.24.11 — corpus.txt / land_corpus.txt go with the artifact they describe. A
            // land_corpus.txt that outlives its crit would make the next render compare this
            // page's CSS against a corpus nothing is serving, and answer 'drift' forever.
            // forfeit_state_*.json is the retired size verdict's hysteresis file (7.21.147);
            // nothing reads it any more, so the first crit delete after the upgrade clears it.
            $artifact_files = ['critical_desktop.css', 'critical_mobile.css', 'critical_combined.css',
                'land_uuid.txt', 'land_rev.txt', 'land_ts.txt', 'uuid.txt', 'stale.txt',
                'corpus.txt', 'land_corpus.txt', 'bypass.txt',
                'forfeit_state_desktop.json', 'forfeit_state_mobile.json'];
            $dirs = wpc_crit_page_dirs();
            $cap = (int) apply_filters('wpc_crit_delete_dir_cap', 3000);
            foreach ($dirs as $dir_index => $d) {
                if ($dir_index >= $cap) {
                    break;
                }
                foreach ($artifact_files as $f) {
                    if (@is_file($d . '/' . $f) && @unlink($d . '/' . $f)) {
                        $n++;
                    }
                }
                if (wpc_crit_park_reset($d)) {
                    $n++;
                }
            }
            // The other delete path (purgeCriticalFiles) has always cleared the land cooldown;
            // this one never did, so click 2 of Remove Critical hit land-cooldown-deferred in
            // initCritical and dispatched nothing at all. A delete IS the end of the cooldown:
            // there is no landed artifact left for it to protect.
            if (function_exists('wpc_land_cooldown_clear')) {
                wpc_land_cooldown_clear('all');
            }
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('crit-files-deleted', '', '', ['files' => $n, 'dirs' => count($dirs)]);
            }
        } catch (\Throwable $e) {
        }
        return $n;
    }
}

if (!function_exists('wpc_delay_report_stamp')) {
    /**
     * The stamp a page's Delay JS report carries, verified by wpc_delay_v3_report_handler().
     * Rule: a report may speak only for a page this site actually served, and whatever it moves
     * is scoped to that page. The render mints the stamp over the page's path and puts it in the
     * page (wpcDelayV3Cfg.rs, and the LCP tracer's own script); the report sends it back as `s`
     * beside the path `u`. Observed failure it closes: the handler's only trust check was the
     * request's Origin/Referer host, which any client sets at will, so a forged header could
     * switch the delay manifest off site-wide, append scripts to the operator's Delay JS excludes
     * and wipe every cached page.
     * No time bucket: a cached copy outlives any bucket, and binding the stamp to the path is the
     * point. The secret is the kick admission token's (wp_salt('nonce'), the api key when there is
     * no salt, and ABSPATH), under its own label so neither token answers for the other.
     */
    function wpc_delay_report_stamp($path)
    {
        $secret = function_exists('wp_salt') ? (string) wp_salt('nonce') : '';
        if ($secret === '' && function_exists('get_option') && defined('WPS_IC_OPTIONS')) {
            $opts = get_option(WPS_IC_OPTIONS);
            $secret = is_array($opts) && !empty($opts['api_key']) ? (string) $opts['api_key'] : '';
        }
        return substr(hash_hmac('sha256', 'delay-report|' . (string) $path, $secret . '|' . ABSPATH), 0, 20);
    }

    /**
     * The path this page's reports name as `u`: the senders send location.pathname cut to 120
     * characters, so the render mints over the request path cut the same way. A stamp minted over
     * any other spelling of the path would refuse every report the page sends.
     */
    function wpc_delay_report_page_path()
    {
        $uri = isset($_SERVER['REQUEST_URI']) ? (string) $_SERVER['REQUEST_URI'] : '';
        $path = explode('?', $uri, 2)[0];
        return substr($path === '' ? '/' : $path, 0, 120);
    }
}

if (!function_exists('wpc_repull_kick_now')) {


    function wpc_kick_lockfile($urlKey, $scope = 'recv')
    {
        if (!defined('WPS_IC_CRITICAL') || (string) $urlKey === '') { return ''; }
        $sc = ($scope === 'fire') ? 'f_' : 'r_';
        return rtrim(WPS_IC_CRITICAL, '/') . '/.kicklocks/' . $sc . md5((string) $urlKey) . '.lock';
    }
    function wpc_kick_recent($urlKey, $ttl, $scope = 'recv')
    {
        $f = wpc_kick_lockfile($urlKey, $scope);
        return $f !== '' && @is_file($f) && (time() - (int) @filemtime($f)) < (int) $ttl;
    }
    function wpc_kick_stamp($urlKey, $scope = 'recv')
    {
        $f = wpc_kick_lockfile($urlKey, $scope);
        if ($f === '') { return; }
        $d = dirname($f);
        if (!is_dir($d)) { @mkdir($d, 0777, true); }
        @touch($f);
    }


    /*
     * THE TRANSPORT THROTTLE: one admission point for every kick.
     *
     * A kick costs PHP work before any /generate POST: a loopback (two transports), then a
     * receiver run that collects (/status + pointer) or generates. The service's budget bounds
     * fresh renders, not that work, so the site bounds it here. Every kick source — the render
     * sentinel, the JS beacon, stale and watchdog kicks, warm-render kicks — passes through
     * wpc_kick_admit(): on the fire side at the top of wpc_repull_kick_now(), on the receive side
     * at the top of wpc_repull_kick_receiver(). A loopback admitted at the fire side carries a
     * signed admission token and is not counted again when it arrives; a beacon, which never
     * passes the fire side, is counted when it arrives.
     *
     * One counter: at most WPC_KICK_ADMIT_PER_MINUTE (default 12, 0 = unthrottled) admissions in any rolling
     * 60 s per blog, kept in a file so it survives an object-cache flush. When the counter
     * cannot be read or written — lock contention, an unwritable directory — the kick is dropped:
     * an unbounded burst is the thing this exists to prevent. The per-key dedupes (60 s fire, 120 s
     * receive), the 6 h dead-key mark and the pressure back-off run first, so a duplicate never
     * spends an admission. A dropped kick costs nothing: the next render or beacon asks again.
     */
    function wpc_kick_admit_ceiling()
    {
        return defined('WPC_KICK_ADMIT_PER_MINUTE') ? max(0, (int) WPC_KICK_ADMIT_PER_MINUTE) : 12;
    }

    /** $create false: the path only, no directory made (a reader that must not write, the doctor). */
    function wpc_kick_admit_counter_file($create = true)
    {
        if (!defined('WPS_IC_CRITICAL')) { return ''; }
        $dir = rtrim(WPS_IC_CRITICAL, '/') . '/.kicklocks/';
        if ($create && !is_dir($dir)) { @mkdir($dir, 0777, true); }
        return (is_dir($dir) && is_writable($dir)) ? $dir . 'admit' : '';
    }

    /** The admission token a loopback carries, bound to its key and the current minute. */
    function wpc_kick_admit_token($urlKey, $minutesAgo = 0)
    {
        $secret = function_exists('wp_salt') ? (string) wp_salt('nonce') : '';
        if ($secret === '' && function_exists('get_option') && defined('WPS_IC_OPTIONS')) {
            $opts = get_option(WPS_IC_OPTIONS);
            $secret = is_array($opts) && !empty($opts['api_key']) ? (string) $opts['api_key'] : '';
        }
        $minute = (int) floor(time() / 60) - (int) $minutesAgo;
        return substr(hash_hmac('sha256', 'kick|' . (string) $urlKey . '|' . $minute, $secret . '|' . ABSPATH), 0, 20);
    }

    function wpc_kick_admit_token_valid($urlKey, $token)
    {
        $token = (string) $token;
        if ($token === '') { return false; }
        foreach ([0, 1] as $minutesAgo) {
            if (hash_equals(wpc_kick_admit_token($urlKey, $minutesAgo), $token)) { return true; }
        }
        return false;
    }

    /**
     * The admissions still inside the rolling 60 s window, oldest first, read from the counter
     * file's timestamp list. A counter in the older fixed-window shape ({s, c}) reads as empty.
     */
    function wpc_kick_admit_window($stored)
    {
        $state = json_decode((string) $stored, true);
        $now = time();
        $times = (is_array($state) && isset($state['t']) && is_array($state['t'])) ? $state['t'] : [];
        return array_values(array_filter(array_map('intval', $times), function ($at) use ($now) {
            return ($now - $at) < 60;
        }));
    }

    /**
     * Take one admission from the site's rolling-minute counter: at most the ceiling in any 60 s,
     * counted back from now, not from the window's first admission. Fails closed.
     */
    function wpc_kick_admit_take()
    {
        $ceiling = wpc_kick_admit_ceiling();
        if ($ceiling === 0) { return true; }
        $file = wpc_kick_admit_counter_file();
        if ($file === '' || !function_exists('wpc_fs_update')) { return false; }
        list($written, $admitted) = wpc_fs_update($file, function ($current) use ($ceiling) {
            $times = wpc_kick_admit_window($current);
            if (count($times) >= $ceiling) { return [null, false]; }
            $times[] = time();
            return [json_encode(['t' => $times]), true];
        }, true);
        return $written && $admitted === true;
    }

    /** How many admissions the rolling window has left now (diagnostics; takes nothing). */
    function wpc_kick_admit_room()
    {
        $ceiling = wpc_kick_admit_ceiling();
        if ($ceiling === 0) { return -1; }
        $file = wpc_kick_admit_counter_file();
        $times = wpc_kick_admit_window($file !== '' ? @file_get_contents($file) : '');
        return max(0, $ceiling - count($times));
    }

    /**
     * A kick wpc_kick_admit() refused: kick-refused {why, src, …}, once per page, reason and source
     * per $sampleSeconds (30 s; the service hold samples per 120 s, the hit kick's own window, so
     * a held page writes one line per source per window and never one per hit). The throttle
     * keeps its own receipt (kick-throttled).
     */
    function wpc_kick_refused_note($urlKey, $why, $source, array $layers = [], $sampleSeconds = 30)
    {
        if (!function_exists('wpc_cache_first_log')) {
            return;
        }
        $sample = 'wpc_kick_refused_' . md5((string) $urlKey . '|' . $why . '|' . $source);
        if (get_transient($sample)) {
            return;
        }
        set_transient($sample, 1, max(1, (int) $sampleSeconds));
        wpc_cache_first_log('kick-refused', (string) $urlKey, '', ['why' => (string) $why, 'src' => substr((string) $source, 0, 20)] + $layers);
    }

    /** A kick source as it travels in a query string and a receipt: lower-case letters and '-'. */
    function wpc_kick_source_name($source)
    {
        return substr((string) preg_replace('/[^a-z-]/', '', strtolower((string) $source)), 0, 20);
    }

    /**
     * Who sent the kick this request carries. A loopback this site signed was counted on the fire
     * side and is named by its src ('render', 'stale', 'hit' …); an unsigned request is the
     * drop-in's hit kick when it says src=hit, a browser beacon otherwise. The receiver counts
     * both unsigned kinds; the name is for receipts only and decides nothing else.
     */
    function wpc_kick_received_source($urlKey)
    {
        $named = isset($_GET['src']) ? wpc_kick_source_name($_GET['src']) : '';
        if (wpc_kick_admit_token_valid($urlKey, isset($_GET['wpc_admit']) ? (string) $_GET['wpc_admit'] : '')) {
            return ['signed' => true, 'name' => $named !== '' ? $named : 'loopback'];
        }
        return ['signed' => false, 'name' => $named === 'hit' ? 'hit' : 'beacon'];
    }

    /**
     * The kick sources that fetch a generation the service has already made: an amendment landed
     * in place on the same uuid, a backend refetch, the poll of a pending uuid. The service hold
     * bounds new generations, not collection, so these still pass while it stands; every other
     * source is refused by it in wpc_kick_admit().
     */
    function wpc_kick_collect_only_sources()
    {
        return ['amendment', 'refetch', 'pending-poll'];
    }

    /**
     * Admit one kick. $source names the caller on the fire side ('render', 'stale', 'watchdog',
     * 'kick' …) or 'receiver' on the receive side, where the request's own token decides whether
     * it is a loopback already counted or a beacon counted now. A request reached through a host
     * that is not the site's own (wpc_request_host_is_home) sends and receives no kick. True = go
     * ahead.
     */
    function wpc_kick_admit($urlKey, $source = 'kick')
    {
        try {
            $urlKey = (string) $urlKey;
            if ($urlKey === '') { return false; }
            if (function_exists('wpc_request_host_is_home') && !wpc_request_host_is_home()) {
                wpc_kick_refused_note($urlKey, 'foreign-host', $source,
                    ['host' => substr(strtolower((string) (isset($_SERVER['HTTP_HOST']) ? $_SERVER['HTTP_HOST'] : '')), 0, 80)], 3600);
                return false;
            }
            $receiving = ($source === 'receiver');
            // Every refusal leaves a receipt: a dead mark once refused every kick of two pages for
            // a whole evening with nothing in the log but the renders that asked.
            if (function_exists('wpc_kick_is_dead') && wpc_kick_is_dead($urlKey)) {
                wpc_kick_refused_note($urlKey, 'dead', $source, ['until' => function_exists('wpc_kick_dead_until') ? wpc_kick_dead_until($urlKey) : 0]);
                return false;
            }
            if ($receiving) {
                if (get_transient('wpc_repull_kick_' . md5($urlKey)) || wpc_kick_recent($urlKey, 120)) {
                    wpc_kick_refused_note($urlKey, 'recent', $source);
                    return false;
                }
                if (get_transient(WPC_KICK_PRESSURE_BACKOFF_PREFIX . md5($urlKey))) {
                    wpc_kick_refused_note($urlKey, 'pressure', $source);
                    return false;
                }
                $received = wpc_kick_received_source($urlKey);
                $source = $received['signed'] ? 'loopback' : $received['name'];
                // A signed kick whose fire side passed a hold on a visitor's evidence carries it
                // here, so the receiver's gates and the dispatch's visitor field agree with the
                // fire side (wpc_repull_kick_now appends human=1 only then).
                if ($received['signed'] && isset($_GET['human']) && (string) $_GET['human'] === '1') {
                    $GLOBALS['wpc_gen_human_evidence'][ltrim($urlKey, '/')] = 1;
                }
            } elseif (get_transient('wpc_kick_fire_' . md5($urlKey)) || wpc_kick_recent($urlKey, 60, 'fire')) {
                wpc_kick_refused_note($urlKey, 'recent', $source);
                return false;
            }
            // THE SERVICE HOLD, for every kick source, decided here and nowhere else. While the
            // service has asked the site to wait, a kick cannot dispatch: the receiver skips
            // collection for a stale-marked page and the dispatch door refuses the POST. Only the
            // render kick used to check the hold (at its own call site); the stale and hit kicks
            // did not, so a held site spent one loopback and one receiver run per page per 120 s
            // for nothing. A signed loopback was held or admitted here on the fire side; on the
            // receive side the hold applies to what never passed the fire side — the browser
            // beacon and the drop-in's unsigned hit kick, which cannot read the option before
            // WordPress loads. The homepage keeps its exemption (wpc_gen_service_hold_until).
            // Collection-only sources pass: the hold bounds generation, not fetching what exists.
            if ($source !== 'loopback' && !in_array((string) $source, wpc_kick_collect_only_sources(), true)
                && function_exists('wpc_gen_service_hold_until')) {
                $holdUntil = wpc_gen_service_hold_until($urlKey);
                // A hold the service lifts on a human view (demand_deferred) does not hold the
                // kick a visitor's browser asked for: the beacon from the page itself, or any kick
                // fired inside the visitor's own request (a render, a hit, the first interaction),
                // judged by the classifier whose answer the dispatch sends as `visitor`. The
                // drop-in's hit kick reaches the receiver as a server loopback and reads as a bot.
                // webdesign4u.com.au, 2026-09-28: 18+ kicks from real visits refused service-hold
                // for 24 h, so the dispatch that would have lifted the deferral never left.
                if ($holdUntil > 0 && function_exists('wpc_visitor_kind') && wpc_visitor_kind() === 'human'
                    && function_exists('wpc_gen_human_evidence')) {
                    $GLOBALS['wpc_gen_human_evidence'][ltrim($urlKey, '/')] = 1;
                    $holdUntil = wpc_gen_service_hold_until($urlKey);
                    if ($holdUntil > 0) {
                        unset($GLOBALS['wpc_gen_human_evidence'][ltrim($urlKey, '/')]);
                    } elseif (function_exists('wpc_cache_first_log')) {
                        wpc_cache_first_log('kick-hold-passed', $urlKey, '', ['why' => 'human', 'src' => substr((string) $source, 0, 20)]);
                    }
                }
                if ($holdUntil > 0) {
                    wpc_kick_refused_note($urlKey, 'service-hold', $source, ['until' => $holdUntil], 120);
                    return false;
                }
            }
            if ($source !== 'loopback' && !wpc_kick_admit_take()) {
                if (!get_transient('wpc_kick_throttled_' . md5($source)) && function_exists('wpc_cache_first_log')) {
                    set_transient('wpc_kick_throttled_' . md5($source), 1, 60);
                    wpc_cache_first_log('kick-throttled', $urlKey, '', ['src' => substr((string) $source, 0, 20)]);
                }
                return false;
            }
            if ($receiving) {
                set_transient('wpc_repull_kick_' . md5($urlKey), 1, 120);
                wpc_kick_stamp($urlKey);
            } else {
                set_transient('wpc_kick_fire_' . md5($urlKey), 1, 60);
                wpc_kick_stamp($urlKey, 'fire');
            }
            return true;
        } catch (\Throwable $e) {
            return false;
        }
    }


    // A client that re-dispatches crit generation every ~45s to a FAILING backend (502 / no-response
    // / land-fail) amplifies the outage — it holds an overloaded pod flat instead of letting it drain


    /** $create false: the path only, no directory made (a reader that must not write, the doctor). */
    function wpc_gen_backoff_file($create = true)
    {
        if (!defined('WPS_IC_CRITICAL')) { return ''; }
        $d = rtrim(WPS_IC_CRITICAL, '/') . '/.kicklocks/';
        if ($create && !is_dir($d)) { @mkdir($d, 0777, true); }
        return $d . 'genfail.json';
    }

    /** TRUE ⇒ the gen dispatch should be DEFERRED (we're inside a failure-backoff window). */
    function wpc_gen_backoff_active()
    {
        try {
            if (!apply_filters('wpc_gen_failure_backoff', true)) { return false; }
            $f = wpc_gen_backoff_file();
            if ($f === '' || !@is_file($f)) { return false; }
            $j = json_decode((string) @file_get_contents($f), true);
            return is_array($j) && !empty($j['until']) && time() < (int) $j['until'];
        } catch (\Throwable $e) {
            return false;
        }
    }

    /** Record a gen/land FAILURE → widen the backoff window (exponential, capped). */
    function wpc_gen_note_failure($why = '')
    {
        try {
            if (!apply_filters('wpc_gen_failure_backoff', true)) { return; }
            $f = wpc_gen_backoff_file();
            if ($f === '') { return; }
            $j     = json_decode((string) @file_get_contents($f), true);
            $fails = (is_array($j) && !empty($j['fails'])) ? (int) $j['fails'] + 1 : 1;
            $base  = (int) apply_filters('wpc_gen_backoff_base', 45);
            $max   = (int) apply_filters('wpc_gen_backoff_max', 900);
            $wait  = min($base * (1 << min($fails - 1, 6)), $max);       // 45,90,180,360,720,900,900…
            wpc_crit_meta_write($f, json_encode(['fails' => $fails, 'until' => time() + $wait, 't' => time(), 'why' => substr((string) $why, 0, 40)]));
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('gen-backoff', '', '', ['fails' => $fails, 'wait' => $wait, 'why' => substr((string) $why, 0, 24)]);
            }
        } catch (\Throwable $e) {
        }
    }

    /** Record a land SUCCESS → clear the backoff (the backend is healthy again). */
    function wpc_gen_note_success()
    {
        try {
            $f = wpc_gen_backoff_file();
            if ($f !== '' && @is_file($f)) { @unlink($f); }
        } catch (\Throwable $e) {
        }
    }


    /**
     * The key's gen_fails.json. $create false never makes the key's crit folder: a reader that must
     * not write (the doctor) gets '' for a page that has no folder, which reads as no record.
     */
    function wpc_gen_landless_file($urlKey, $create = true)
    {
        if (!defined('WPS_IC_CRITICAL') || !is_string($urlKey) || $urlKey === '') { return ''; }
        $d = rtrim(WPS_IC_CRITICAL, '/') . '/' . $urlKey . '/';
        if ($create && !is_dir($d) && function_exists('wp_mkdir_p')) { @wp_mkdir_p($d); }
        return is_dir($d) ? $d . 'gen_fails.json' : '';
    }

    /*
     * THE LANDLESS PARK, COUNTED PER GENERATION.
     *
     * The question the park answers is the one the service cannot: did a generation of ours ever
     * land here? A backend that accepts dispatches and never delivers would otherwise be asked
     * again every couple of minutes forever. gen_fails.json keeps {n, until, t} and a set of our
     * own generations still owed a land, pending {uuid: dispatched_at}, plus terminal {uuid: 1}
     * for those the service reported not_found / failed. A generation counts as failed once it
     * is terminal or older than 300 s without landing; five failed → park for
     * min(1 h · 2^(n−5), 24 h). An answer that reused an existing generation (debounced,
     * unchanged, converged) adds nothing: nothing of ours was produced, so nothing failed.
     * A land removes its uuid and every older entry and lifts the park; newer entries stay, so a
     * late land does not erase newer failures. Entries older than 1800 s are dropped (the
     * service's own terminal window), and the set never holds more than 50.
     *
     * Kill switch: define WPC_GEN_PENDING_SET false → n counts every dispatch, as it did before
     * generations were told apart.
     */
    function wpc_gen_pending_set_enabled()
    {
        return !defined('WPC_GEN_PENDING_SET') || WPC_GEN_PENDING_SET;
    }

    /**
     * The key's record, normalised; an older {n, until, t} reads as is with an empty set.
     * $create false reads without making the key's crit folder (wpc_gen_landless_file).
     */
    function wpc_gen_landless_read($urlKey, $create = true)
    {
        $state = ['n' => 0, 'until' => 0, 't' => 0, 'pending' => [], 'terminal' => [], 'kept' => []];
        $file = wpc_gen_landless_file((string) $urlKey, $create);
        $stored = ($file !== '' && @is_file($file)) ? json_decode((string) @file_get_contents($file), true) : null;
        if (is_array($stored)) {
            // Fields this record does not own (a page's own values) ride through every rewrite.
            $state['kept'] = array_diff_key($stored, array_flip(['n', 'until', 't', 'pending', 'terminal']));
            foreach (['n', 'until', 't'] as $field) {
                $state[$field] = isset($stored[$field]) ? (int) $stored[$field] : 0;
            }
            foreach (['pending', 'terminal'] as $field) {
                $state[$field] = isset($stored[$field]) && is_array($stored[$field]) ? $stored[$field] : [];
            }
        }
        // Drop what the service has long since forgotten, then keep the newest 50.
        $now = time();
        foreach ($state['pending'] as $uuid => $at) {
            if ($now - (int) $at > 1800) {
                unset($state['pending'][$uuid]);
            }
        }
        if (count($state['pending']) > 50) {
            asort($state['pending']);
            $state['pending'] = array_slice($state['pending'], -50, null, true);
        }
        $state['terminal'] = array_intersect_key($state['terminal'], $state['pending']);
        return $state;
    }

    function wpc_gen_landless_write($urlKey, array $state)
    {
        $file = wpc_gen_landless_file((string) $urlKey);
        if ($file === '') { return; }
        $record = (isset($state['kept']) ? (array) $state['kept'] : []) + ['n' => (int) $state['n'], 'until' => (int) $state['until'], 't' => time()];
        if (!empty($state['pending'])) {
            asort($state['pending']);
            $record['pending'] = array_slice($state['pending'], -50, null, true);
        }
        if (!empty($state['terminal'])) { $record['terminal'] = $state['terminal']; }
        wpc_crit_meta_write($file, json_encode($record));
    }

    /** How many of this key's generations failed to land: terminal, or pending for over 300 s. */
    function wpc_gen_landless_count(array $state, $now = null)
    {
        $failed = 0;
        $now = $now === null ? time() : (int) $now;
        foreach ($state['pending'] as $uuid => $at) {
            if (!empty($state['terminal'][$uuid]) || $now - (int) $at > 300) {
                $failed++;
            }
        }
        return $failed;
    }

    function wpc_gen_landless_park_seconds($failed)
    {
        return (int) min(3600 * pow(2, max(0, (int) $failed - 5)), 86400); // 1h, 2h, 4h … 24h cap
    }

    /**
     * The park verdict of one record at $now, without writing: the time the page is parked until,
     * or 0 when it is not. A park already on record answers its own until; otherwise five failed
     * generations answer the park they start now. wpc_gen_landless_parked() records that park;
     * the doctor only reads it.
     */
    function wpc_gen_landless_is_parked(array $state, $now)
    {
        $now = (int) $now;
        if ((int) $state['until'] > $now) { return (int) $state['until']; }
        if (!wpc_gen_pending_set_enabled()) { return 0; }
        $failed = wpc_gen_landless_count($state, $now);
        if ($failed < 5) { return 0; }
        return $now + wpc_gen_landless_park_seconds($failed);
    }

    /** TRUE ⇒ this URL is parked (too many landless generations) — skip generation for now. */
    function wpc_gen_landless_parked($urlKey)
    {
        try {
            if (!apply_filters('wpc_gen_landless_giveup', true)) { return false; }
            $state = wpc_gen_landless_read($urlKey);
            $now = time();
            $until = wpc_gen_landless_is_parked($state, $now);
            if ($until === 0) { return false; }
            if ($until === (int) $state['until']) { return true; }
            $failed = wpc_gen_landless_count($state, $now);
            $state['n'] = $failed;
            $state['until'] = $until;
            wpc_gen_landless_write($urlKey, $state);
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('gen-parked', (string) $urlKey, '', ['n' => $failed, 'until' => $state['until']]);
            }
            return true;
        } catch (\Throwable $e) {
            return false;
        }
    }

    /** Switched off (WPC_GEN_PENDING_SET false): every dispatch counts, whatever it was answered. */
    function wpc_gen_landless_count_dispatch($urlKey)
    {
        try {
            if (!apply_filters('wpc_gen_landless_giveup', true)) { return; }
            $state = wpc_gen_landless_read($urlKey);
            $state['n']++;
            if ($state['n'] >= 5) {
                $state['until'] = time() + wpc_gen_landless_park_seconds($state['n']);
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('gen-parked', (string) $urlKey, '', ['n' => $state['n'], 'until' => $state['until']]);
                }
            }
            wpc_gen_landless_write($urlKey, $state);
        } catch (\Throwable $e) {
        }
    }

    /**
     * The order this site dispatched its generations in, per page: uuid => milliseconds, the ten
     * newest, kept in gen_fails.json beside the pending set. Unlike the pending set it keeps a
     * generation after it lands, because a land is judged against the one on disk
     * (wps_criticalCss::saveCriticalCss: a land never replaces a newer generation of ours with an
     * older one). A park reset (a stale mark, a removal) keeps it (wpc_crit_park_reset); a
     * generation with no record lands as it always has.
     */
    function wpc_gen_dispatch_order_note($urlKey, $uuid)
    {
        try {
            $uuid = preg_replace('/[^A-Za-z0-9-]/', '', (string) $uuid);
            if ((string) $urlKey === '' || $uuid === '') { return; }
            $state = wpc_gen_landless_read($urlKey);
            $order = isset($state['kept']['dispatched']) && is_array($state['kept']['dispatched']) ? $state['kept']['dispatched'] : [];
            $order[$uuid] = (int) round(microtime(true) * 1000);
            asort($order);
            $state['kept']['dispatched'] = array_slice($order, -10, null, true);
            wpc_gen_landless_write($urlKey, $state);
        } catch (\Throwable $e) {
        }
    }

    /** When this site dispatched $uuid for $urlKey (milliseconds), or 0 when it has no record. */
    function wpc_gen_dispatch_order_of($urlKey, $uuid)
    {
        $order = wpc_gen_landless_read((string) $urlKey)['kept']['dispatched'] ?? [];
        return is_array($order) && isset($order[(string) $uuid]) ? (int) $order[(string) $uuid] : 0;
    }

    /**
     * TRUE when this site dispatched $uuid before $thanUuid for $urlKey, both on record: the one
     * test every landing route and the announce re-poll share, so no route can land an older
     * generation of ours over a newer one. A uuid with no record is never older.
     */
    function wpc_gen_dispatched_before($urlKey, $uuid, $thanUuid)
    {
        $uuid = preg_replace('/[^A-Za-z0-9-]/', '', (string) $uuid);
        $thanUuid = preg_replace('/[^A-Za-z0-9-]/', '', (string) $thanUuid);
        if ($uuid === '' || $thanUuid === '' || $uuid === $thanUuid) {
            return false;
        }
        $order = wpc_gen_landless_read((string) $urlKey)['kept']['dispatched'] ?? [];
        if (!is_array($order) || empty($order[$uuid]) || empty($order[$thanUuid])) {
            return false;
        }
        return (int) $order[$uuid] < (int) $order[$thanUuid];
    }

    /** Record one generation of ours that is owed a land. */
    function wpc_gen_pending_add($urlKey, $uuid)
    {
        try {
            if (!apply_filters('wpc_gen_landless_giveup', true) || !wpc_gen_pending_set_enabled()) { return; }
            $state = wpc_gen_landless_read($urlKey);
            $uuid = preg_replace('/[^A-Za-z0-9-]/', '', (string) $uuid);
            if ($uuid === '') { return; }
            $state['pending'][$uuid] = time();
            $state['n'] = wpc_gen_landless_count($state);
            wpc_gen_landless_write($urlKey, $state);
        } catch (\Throwable $e) {
        }
    }

    /**
     * The service removed our generation (its epoch fell below the minimum): it will never land,
     * and that is not a failure of the backend. It leaves the set without counting.
     */
    function wpc_gen_pending_forget($urlKey, $uuid)
    {
        try {
            $uuid = preg_replace('/[^A-Za-z0-9-]/', '', (string) $uuid);
            if ($uuid === '') { return; }
            $state = wpc_gen_landless_read($urlKey);
            if (!isset($state['pending'][$uuid])) { return; }
            unset($state['pending'][$uuid], $state['terminal'][$uuid]);
            $state['n'] = wpc_gen_landless_count($state);
            wpc_gen_landless_write($urlKey, $state);
        } catch (\Throwable $e) {
        }
    }

    /** The service reported our generation not_found / failed: it will never land. */
    function wpc_gen_pending_terminal($urlKey, $uuid)
    {
        try {
            $uuid = preg_replace('/[^A-Za-z0-9-]/', '', (string) $uuid);
            if ($uuid === '' || !wpc_gen_pending_set_enabled()) { return; }
            $state = wpc_gen_landless_read($urlKey);
            if (!isset($state['pending'][$uuid])) { return; }
            $state['terminal'][$uuid] = 1;
            $state['n'] = wpc_gen_landless_count($state);
            wpc_gen_landless_write($urlKey, $state);
        } catch (\Throwable $e) {
        }
    }

    /**
     * What a /status answer says about the generation it was asked about ($uuid, dispatched for
     * $urlKey), in the service's own words since crit-push 3.198.293 (server.js /status):
     *   'superseded' a generation removed below the page's or the site's minimum epoch
     *                (`failed` + `epoch_superseded` / `below_epoch_min`); only a generation gets this;
     *   'refused'    the dispatch was refused at admission (`blocked` + its refusal type, e.g.
     *                domain_capped, demand_deferred): it never made a generation;
     *   'not-found'  no row, no stamp, no files (`not_found`, reason `unknown_uuid` or `expired`);
     *   'failed'     the generation failed (`failed` + any other type, `abandoned` among them);
     *   ''           still rendering, landed, an answer that says none of these, or a gone answer
     *                about a dispatch of ours younger than a minute (below).
     * Before 3.198.293 a refused or never-seen uuid read as `epoch_superseded`; staging 2026-09-27
     * polled eight such uuids as superseded and dispatched again each time.
     *
     * A uuid is minted and written here before its POST leaves (wpc_gen_dispatch_stamp), and the
     * service writes its row only once it admits the POST, so a poll racing the POST is answered
     * `not_found` (and `epoch_superseded` with the service's STATUS_EPOCH_SCOPE_OFF kill switch)
     * for a generation that is about to exist. The page's dispatch record names the uuid and when
     * it was stamped; for its first minute a not-found or superseded answer says nothing. The
     * repull held that minute for 'superseded' alone; since 3.198.293 the in-flight answer is
     * `not_found`, which the repull and initCritical would have counted as a failed generation.
     */
    function wpc_gen_status_gone($statusJson, $urlKey = '', $uuid = '')
    {
        if (!is_array($statusJson)) {
            return '';
        }
        $status = (string) ($statusJson['status'] ?? '');
        if (($statusJson['error_type'] ?? '') === 'epoch_superseded' || $status === 'epoch_superseded'
            || ($status === 'failed' && ($statusJson['reason'] ?? '') === 'below_epoch_min')) {
            $gone = 'superseded';
        } elseif ($status === 'blocked') {
            $gone = 'refused';
        } elseif ($status === 'not_found') {
            $gone = 'not-found';
        } elseif ($status === 'failed') {
            $gone = 'failed';
        } else {
            return '';
        }
        if (($gone === 'not-found' || $gone === 'superseded') && (string) $urlKey !== '' && (string) $uuid !== ''
            && defined('WPS_IC_CRITICAL') && function_exists('wpc_crit_dispatch_record_read')) {
            $record = wpc_crit_dispatch_record_read(WPS_IC_CRITICAL . ltrim((string) $urlKey, '/') . '/');
            if (isset($record['uuid'], $record['at']) && $record['uuid'] === (string) $uuid && time() - (int) $record['at'] < 60) {
                return '';
            }
        }
        return $gone;
    }

    /**
     * Forget a generation of ours the service answered as gone ($gone from wpc_gen_status_gone),
     * everywhere this site holds it: the pending set (superseded and refused leave it uncounted:
     * neither is a generation that failed to land; not-found and failed count toward the park),
     * the uuid transient and uuid.txt when they still name it. Nothing
     * polls it again and nothing is sent for it here: the page's next real visit asks afresh.
     * True when this call dropped it, so the caller writes its receipt once. uuid.txt left in
     * place made every repull run, the pending-poll kick and every background initCritical ask
     * /status about the same never-made uuid for as long as the page was visited (staging,
     * 2026-09-27: 106 /status calls and 203 failed CDN pulls in 46 minutes for two pages).
     */
    function wpc_gen_forget_gone($urlKey, $uuid, $gone)
    {
        $urlKey = ltrim((string) $urlKey, '/');
        $uuid = preg_replace('/[^A-Za-z0-9-]/', '', (string) $uuid);
        if ($urlKey === '' || $uuid === '' || $gone === '') {
            return false;
        }
        $dropped = false;
        if ((string) get_transient('wpc_critical_uuid_' . $urlKey) === $uuid) {
            delete_transient('wpc_critical_uuid_' . $urlKey);
            $dropped = true;
        }
        if (defined('WPS_IC_CRITICAL')) {
            $uuidFile = rtrim(WPS_IC_CRITICAL, '/') . '/' . $urlKey . '/uuid.txt';
            if (preg_replace('/[^A-Za-z0-9-]/', '', trim((string) @file_get_contents($uuidFile))) === $uuid) {
                @unlink($uuidFile);
                $dropped = true;
            }
        }
        if ($gone === 'superseded' || $gone === 'refused') {
            wpc_gen_pending_forget($urlKey, $uuid);
        } else {
            wpc_gen_pending_terminal($urlKey, $uuid);
        }
        return $dropped;
    }

    /**
     * A generation landed for this key: the park lifts. The landed uuid and every older entry
     * leave the set; newer entries stay. A uuid the set does not hold (pruned, or a generation
     * the service reused) still proves delivery, so every entry already counted as failed goes.
     */
    function wpc_gen_landed($urlKey, $uuid)
    {
        try {
            $state = wpc_gen_landless_read($urlKey);
            $uuid = preg_replace('/[^A-Za-z0-9-]/', '', (string) $uuid);
            if (!wpc_gen_pending_set_enabled()) {
                $state['pending'] = [];
                $state['terminal'] = [];
            } elseif ($uuid !== '' && isset($state['pending'][$uuid])) {
                $landedAt = (int) $state['pending'][$uuid];
                foreach ($state['pending'] as $entry => $at) {
                    if ((int) $at <= $landedAt) {
                        unset($state['pending'][$entry], $state['terminal'][$entry]);
                    }
                }
            } else {
                $now = time();
                foreach ($state['pending'] as $entry => $at) {
                    if (!empty($state['terminal'][$entry]) || $now - (int) $at > 300) {
                        unset($state['pending'][$entry], $state['terminal'][$entry]);
                    }
                }
            }
            $state['until'] = 0;
            $state['n'] = wpc_gen_landless_count($state);
            if (empty($state['pending']) && empty($state['kept'])) {
                $file = wpc_gen_landless_file((string) $urlKey);
                if ($file !== '' && @is_file($file)) { @unlink($file); }
                return;
            }
            wpc_gen_landless_write($urlKey, $state);
        } catch (\Throwable $e) {
        }
    }


    /** $create false: the path only, no directory made (a reader that must not write, the doctor). */
    function wpc_land_cooldown_file($urlKey, $create = true)
    {
        if (!defined('WPS_IC_CRITICAL') || $urlKey === '') { return ''; }
        $d = rtrim(WPS_IC_CRITICAL, '/') . '/.kicklocks/';
        if ($create && !is_dir($d)) { @mkdir($d, 0777, true); }
        return $d . 'land_' . md5($urlKey) . '.txt';
    }

    /** TRUE ⇒ this URL landed successfully within the cooldown window — defer any new dispatch. */
    function wpc_land_cooldown_active($urlKey)
    {
        try {
            if (!apply_filters('wpc_land_cooldown', true) || $urlKey === '') { return false; }
            $f = wpc_land_cooldown_file($urlKey);
            if ($f === '' || !@is_file($f)) { return false; }
            $t = (int) @file_get_contents($f);
            return $t > 0 && (time() - $t) < (int) apply_filters('wpc_land_cooldown_seconds', 100);
        } catch (\Throwable $e) {
            return false;
        }
    }

    /** Stamp a successful land — starts this URL's cooldown window. */
    function wpc_land_cooldown_stamp($urlKey)
    {
        try {
            $f = wpc_land_cooldown_file($urlKey);
            if ($f !== '') { wpc_crit_meta_write($f, (string) time()); }
        } catch (\Throwable $e) {
        }
    }


    function wpc_land_cooldown_clear($urlKey)
    {
        try {
            if (!defined('WPS_IC_CRITICAL')) { return; }
            if ($urlKey === 'all') {
                foreach ((array) @glob(rtrim(WPS_IC_CRITICAL, '/') . '/.kicklocks/land_*.txt') as $f) { @unlink($f); }
                return;
            }
            $f = wpc_land_cooldown_file((string) $urlKey);
            if ($f !== '' && @is_file($f)) { @unlink($f); }
        } catch (\Throwable $e) {
        }
    }

    /**
     * The receipt for a kick a self-started render did not fire: `render-kick-skipped {why}`,
     * once per key per 120 s. 'warm' covers every render the warm lanes start.
     */
    function wpc_render_kick_skipped_note($urlKey, $marker)
    {
        if (!function_exists('wpc_cache_first_log')) {
            return;
        }
        $sample = 'wpc_render_kick_skipped_' . md5((string) $urlKey);
        if (get_transient($sample)) {
            return;
        }
        set_transient($sample, 1, 120);
        wpc_cache_first_log('render-kick-skipped', (string) $urlKey, '', ['why' => (string) $marker]);
    }

    /**
     * Fire one kick for $urlKey: a loopback to the receiver, or with $inline and a crit on disk
     * the collect in-process. $source names the caller for the throttle's receipt. True when the
     * kick left (or was deferred past the response), false when nothing was sent.
     */
    function wpc_repull_kick_now($urlKey = '', $inline = false, $source = 'kick')
    {
        try {
            if ($urlKey !== '' && function_exists('wpc_saved_page_keep')) {
                wpc_saved_page_keep((string) $urlKey);
            }
            // A render the plugin started itself never kicks (P-W5): crit is demanded by real
            // visits. The stored copy still carries the arm sentinel, so a browser that later
            // opens it asks from its own beacon.
            $selfStarted = function_exists('wpc_render_self_started') ? wpc_render_self_started() : '';
            if ($selfStarted !== '') {
                wpc_render_kick_skipped_note((string) $urlKey, $selfStarted);
                return false;
            }
            if (!$inline && function_exists('wpc_render_guard_active') && wpc_render_guard_active() && function_exists('wpc_net_defer')) {
                wpc_net_defer('kick:' . md5((string) $urlKey), function () use ($urlKey, $source) { wpc_repull_kick_now($urlKey, false, $source); });
                return true;
            }
            if ($urlKey === '' && class_exists('wps_ic_url_key')) {
                $urlKey = (new wps_ic_url_key())->setup(home_url('/'));
            }
            if (empty($urlKey)) {
                return false;
            }
            // Any other source asking for the page takes a watchdog kick's claim on its next land,
            // admitted or not: that source would have asked anyway (wpc_watchdog_rescue_note).
            if ((string) $source !== 'watchdog') {
                wpc_watchdog_claim_drop($urlKey);
            }

            // The landless park gates GENERATION only (in the dispatch helper): a kick is also the
            // COLLECTION lane and the artifact may be on the shelf. The service hold is decided in
            // the admission, for every source but the collection-only ones.
            if (!wpc_kick_admit($urlKey, (string) $source)) {
                return false;
            }
            // A render's kick is receipted here, once admitted, and never where it is only queued
            // behind the render guard: a queued kick that the admission then refused read in the
            // log as fourteen kicks that never reached the receiver. The refusal is its receipt.
            if (function_exists('wpc_cache_first_log') && ($source === 'render' || $source === 'stale')) {
                wpc_cache_first_log($source === 'render' ? 'render-kick' : 'render-kick-stale', (string) $urlKey, '', []);
            }
            $critDir   = defined('WPS_IC_CRITICAL') ? rtrim(WPS_IC_CRITICAL, '/') . '/' . $urlKey . '/' : '';
            $critOnDisk  = $critDir && @filesize($critDir . 'critical_desktop.css') > 5;
            if ($inline && $critOnDisk && function_exists('wpc_lcp_repull_handler')) {

                wpc_lcp_repull_handler($urlKey, 1);
            } else {
                // src names the caller in the receiver's kick-rx receipt; the token alone decides
                // whether the receiver counts the kick again.
                $kickQuery = '?action=wpc_repull_kick&k=' . rawurlencode($urlKey) . '&wpc_admit=' . wpc_kick_admit_token($urlKey)
                    . '&src=' . wpc_kick_source_name($source)
                    . (function_exists('wpc_gen_human_evidence') && wpc_gen_human_evidence($urlKey) ? '&human=1' : '');
                if (function_exists('wp_remote_get') && function_exists('admin_url')) {
                    wp_remote_get(admin_url('admin-ajax.php') . $kickQuery,
                        ['blocking' => false, 'timeout' => 2, 'headers' => ['X-WPC-Cache-Warm' => '1']]);
                }
                if (class_exists('wps_ic_ajax') && method_exists('wps_ic_ajax', 'wpc_loopback_open_socket')
                    && function_exists('admin_url')) {
                    $ajaxUrlParts = parse_url(admin_url('admin-ajax.php'));
                    if (!empty($ajaxUrlParts['host'])) {
                        $ajaxHttps = (isset($ajaxUrlParts['scheme']) && $ajaxUrlParts['scheme'] === 'https');
                        $fp = wps_ic_ajax::wpc_loopback_open_socket($ajaxUrlParts['host'], $ajaxHttps ? 443 : 80, $ajaxHttps, 0.3);
                        if ($fp) {
                            $ajaxPath = (isset($ajaxUrlParts['path']) ? $ajaxUrlParts['path'] : '/wp-admin/admin-ajax.php') . $kickQuery;
                            fwrite($fp, "GET " . $ajaxPath . " HTTP/1.1\r\nHost: " . $ajaxUrlParts['host']
                                . "\r\nX-WPC-Cache-Warm: 1\r\nConnection: Close\r\n\r\n");
                            fclose($fp);
                        }
                    }
                }
            }

            // The backstop repull collects what the kick asked for. A page whose last dispatch the
            // door refused for want of a saved copy gets none: its kick will be refused the same
            // way, and the repull would only hold the site's 45 s repull mutex (staging,
            // 2026-09-26: three repull-mutex-skip of a real page behind such repulls).
            if (function_exists('wp_schedule_single_event') && function_exists('wp_next_scheduled')
                && !(function_exists('wpc_saved_page_missing') && wpc_saved_page_missing($urlKey))
                && !wp_next_scheduled('wpc_lcp_repull', [$urlKey, 1])) {
                wpc_pl_sched(time() + 45, 'wpc_lcp_repull', [$urlKey, 1]);
            }
            return true;
        } catch (\Throwable $e) {
            return false;
        }
    }

    /**
     * THE RENDER'S ONE ASK PER PAGE. A render may reach several askers for the same page: the
     * corpus drift check, the stale mark, the arm sentinel, the pending-uuid poll
     * and the copy admission's refusal. They go through here, and only the first one asks: its
     * source is the kick's src in every receipt. The rest return false with one sampled
     * `kick-collapsed {src, first}` line. Before this, `corpus-drift` was followed by `stale` and
     * `admission` by `render` in one render; the second was refused as recent only when the first
     * had been admitted, and asked a second time when it had not.
     * A new render-path asker calls this, not wpc_repull_kick_now().
     */
    function wpc_kick_once_per_request($urlKey, $source)
    {
        $askedKey = ltrim((string) $urlKey, '/');
        if ($askedKey === '') {
            return false;
        }
        if (!isset($GLOBALS['wpc_kick_asked_in_request']) || !is_array($GLOBALS['wpc_kick_asked_in_request'])) {
            $GLOBALS['wpc_kick_asked_in_request'] = [];
        }
        if (wpc_kick_asked_in_request($askedKey)) {
            if (function_exists('wpc_belt_receipt')) {
                wpc_belt_receipt('kick-collapsed', ['src' => wpc_kick_source_name($source),
                    'first' => wpc_kick_source_name($GLOBALS['wpc_kick_asked_in_request'][$askedKey])], true, $askedKey);
            }
            return false;
        }
        $GLOBALS['wpc_kick_asked_in_request'][$askedKey] = (string) $source;
        return wpc_repull_kick_now($urlKey, false, $source);
    }

    /**
     * False only when this request names a public host (Host or X-Forwarded-Host) and none of the
     * hosts it names is the site's own: the home host or the WordPress host, www-insensitive, port
     * ignored, or a subdomain of either that is not one of the site's CDN hosts (Cloudflare CNAME,
     * custom CNAME, zone). A request that names internal hosts only (wpc_host_is_internal: a
     * reverse proxy that rewrote Host) is the site's own.
     */
    function wpc_request_host_is_home()
    {
        if (!function_exists('home_url') || !function_exists('wpc_canon_is_same_host')) {
            return true;
        }
        $named = [];
        foreach (['HTTP_HOST', 'HTTP_X_FORWARDED_HOST'] as $header) {
            if (empty($_SERVER[$header])) { continue; }
            foreach (explode(',', (string) $_SERVER[$header]) as $host) {
                $host = strtolower(trim($host));
                if ($host !== '') { $named[] = $host; }
            }
        }
        if (!$named) {
            return true;
        }
        $own = [(string) home_url('/')];
        if (function_exists('site_url')) {
            $own[] = (string) site_url('/');
        }
        $apexes = [];
        foreach ($own as $ownUrl) {
            $ownHost = strtolower((string) parse_url($ownUrl, PHP_URL_HOST));
            if (strpos($ownHost, 'www.') === 0) {
                $ownHost = substr($ownHost, 4);
            }
            if ($ownHost !== '') {
                $apexes[$ownHost] = 1;
            }
        }
        $cdnHosts = function_exists('wpc_site_cdn_hosts') ? wpc_site_cdn_hosts() : [];
        $public = false;
        foreach ($named as $host) {
            foreach ($own as $ownUrl) {
                if (wpc_canon_is_same_host('https://' . $host . '/', $ownUrl)) {
                    return true;
                }
            }
            $name = rtrim((string) preg_replace('/:\d+$/', '', $host), '.');
            $bare = strpos($name, 'www.') === 0 ? substr($name, 4) : $name;
            if ($name !== '' && !isset($cdnHosts[$name]) && !isset($cdnHosts[$bare]) && !isset($cdnHosts['www.' . $bare])) {
                foreach (array_keys($apexes) as $apex) {
                    $tail = '.' . $apex;
                    if (strlen($name) > strlen($tail) && substr($name, -strlen($tail)) === $tail) {
                        return true;
                    }
                }
            }
            if (!wpc_host_is_internal($host)) {
                $public = true;
            }
        }
        return !$public;
    }

    /**
     * Whether a Host value names a machine rather than a public site: an IP literal, a single-label
     * name (localhost, backend), or a name under .internal, .local, .lan, .localhost or
     * .localdomain. A port is ignored.
     */
    function wpc_host_is_internal($host)
    {
        $host = strtolower(trim((string) $host));
        if ($host === '') {
            return false;
        }
        if ($host[0] === '[') {
            return true;
        }
        $name = rtrim((string) preg_replace('/:\d+$/', '', $host), '.');
        if ($name === '' || filter_var($name, FILTER_VALIDATE_IP) !== false || strpos($name, '.') === false) {
            return true;
        }
        return preg_match('/\.(?:internal|local|lan|localhost|localdomain)$/', $name) === 1;
    }

    /** Whether a render-path asker of this request already asked for $urlKey. */
    function wpc_kick_asked_in_request($urlKey)
    {
        return isset($GLOBALS['wpc_kick_asked_in_request'][ltrim((string) $urlKey, '/')]);
    }

    /*
     * THE WATCHDOG'S CLAIM. When the init watchdog's kick is the last ask a page had before its
     * generation lands, and nothing else asked for the page in the 120 s before that kick, the land
     * writes `watchdog-rescue {since_dispatch_s}`: the one generation that nothing but the
     * watchdog would have collected. The claim is a file per page under .kicklocks/ (wd_<md5>),
     * written by the watchdog's admitted kick, dropped by any other source's ask and read once
     * by the land. A release series with no watchdog-rescue line is the signal to delete the
     * watchdog.
     */
    function wpc_watchdog_claim_file($urlKey)
    {
        if (!defined('WPS_IC_CRITICAL') || ltrim((string) $urlKey, '/') === '') {
            return '';
        }
        return rtrim(WPS_IC_CRITICAL, '/') . '/.kicklocks/wd_' . md5(ltrim((string) $urlKey, '/'));
    }

    function wpc_watchdog_claim_drop($urlKey)
    {
        $file = wpc_watchdog_claim_file($urlKey);
        if ($file !== '' && @is_file($file)) {
            @unlink($file);
        }
    }

    /** A generation landed on $urlKey: write watchdog-rescue when the watchdog's claim stands. */
    function wpc_watchdog_rescue_note($urlKey, $dispatchedAt)
    {
        $file = wpc_watchdog_claim_file($urlKey);
        if ($file === '' || !@is_file($file)) {
            return false;
        }
        $claimedAt = (int) @filemtime($file);
        @unlink($file);
        // The watchdog only kicks a dispatch younger than 6 h; an older claim collected nothing.
        if ($claimedAt <= 0 || time() - $claimedAt > 6 * 3600 || !function_exists('wpc_cache_first_log')) {
            return false;
        }
        wpc_cache_first_log('watchdog-rescue', ltrim((string) $urlKey, '/'), '',
            ['since_dispatch_s' => (int) $dispatchedAt > 0 ? max(0, time() - (int) $dispatchedAt) : -1]);
        return true;
    }


    /**
     * A kick the receiver could not run: another background job held the budget ('busy'), both
     * generate slots were taken ('slots'), or the site's 45 s dispatch spacing refused its POST
     * ('spacing'). It is dropped, with `kick-dropped {why}` (`kick-deferred {why:spacing}` for
     * the spacing, which is a wait, not a failure), and the page's dedupes are released so its
     * next visit kicks again. There is no queue and no timer: crit is asked for by real visits.
     */
    function wpc_kick_dropped($urlKey, $why)
    {
        $urlKey = (string) $urlKey;
        if ($urlKey === '') {
            return;
        }
        delete_transient('wpc_kick_fire_' . md5($urlKey));
        $fireLock = wpc_kick_lockfile($urlKey, 'fire');
        if ($fireLock !== '') {
            @unlink($fireLock);
        }
        if ($why === 'slots' || $why === 'spacing') {
            // Past the receive-side admission: its 120 s dedupe would refuse the next visit too.
            delete_transient('wpc_repull_kick_' . md5($urlKey));
            $receiveLock = wpc_kick_lockfile($urlKey);
            if ($receiveLock !== '') {
                @unlink($receiveLock);
            }
        }
        if (function_exists('wpc_cache_first_log')) {
            wpc_cache_first_log($why === 'spacing' ? 'kick-deferred' : 'kick-dropped', $urlKey, '', ['why' => (string) $why]);
        }
    }

    function wpc_repull_kick_receiver()
    {
        try {
            // v7.21.360 — REGENERATION IS NEVER WORTH A SLOW SITE. This lane holds a PHP
            // worker while it self-fetches ?criticalCombine= renders (rosariospadaro
            // receipt: one kick ran 15,185ms with 14,066ms of it in outbound HTTP, on a
            // box where a plain uncached homepage already costs 4.6s with zero external
            // calls). The pressure governor guards 39 other background lanes but never
            // guarded this one, so crit work piled onto an already-saturated host and the
            // visitors — and PageSpeed — paid for it. Shed here, before the slot is taken
            // and before any work: kicks are re-issued by the next render, so a deferral
            // costs nothing but a little latency on the regeneration itself.
            if (function_exists('wpc_under_pressure') && wpc_under_pressure()
                && apply_filters('wpc_kick_pressure_gate', true)) {
                $pressureKey = isset($_GET['k']) ? sanitize_text_field((string) $_GET['k']) : '';
                // brief backoff so a hot box is not re-probed by every render, then the
                // next kick through once it is quiet
                if (function_exists('set_transient') && $pressureKey !== '') {
                    set_transient(WPC_KICK_PRESSURE_BACKOFF_PREFIX . md5($pressureKey), 1,
                        (int) apply_filters('wpc_kick_pressure_backoff', 90));
                }
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('kick-pressure-deferred', $pressureKey, '', []);
                }
                wp_die('', '', ['response' => 200]);
            }
            if (function_exists('wpc_bg_slot_take') && !wpc_bg_slot_take('kick')) {
                // Only a loopback this site fired (its admission token) re-arms the page and is
                // receipted: an anonymous request cannot clear a key's dedupe or write a log line.
                $droppedKey = isset($_GET['k']) ? sanitize_text_field((string) $_GET['k']) : '';
                if ($droppedKey !== '' && wpc_kick_admit_token_valid($droppedKey, isset($_GET['wpc_admit']) ? (string) $_GET['wpc_admit'] : '')) {
                    wpc_kick_dropped($droppedKey, 'busy');
                }
                wp_die('', '', ['response' => 200]);
            }


            if (function_exists('ignore_user_abort')) { @ignore_user_abort(true); }
            if (function_exists('set_time_limit')) { @set_time_limit(120); }
            $k = isset($_GET['k']) ? sanitize_text_field((string) $_GET['k']) : '';
            // A browser beacon or the drop-in's hit kick asks without passing the fire side: it
            // too takes a watchdog kick's claim on the page's next land.
            if ($k !== '') {
                $askedBy = wpc_kick_received_source($k);
                if (!$askedBy['signed']) {
                    wpc_watchdog_claim_drop($k);
                }
            }
            if ($k === '' || !wpc_kick_admit($k, 'receiver')) {
                wp_die('', '', ['response' => 200]);
            }
            $dir  = defined('WPS_IC_CRITICAL') ? rtrim(WPS_IC_CRITICAL, '/') . '/' . $k . '/' : '';
            $have = $dir && @filesize($dir . 'critical_desktop.css') > 5;

            // A stale mark stands until a land clears it, however old: the service paces a large
            // stale set over hours, and a mark dropped by age left the obsolete crit serving for
            // good on a quiet page. A looping page is stopped by the per-page cap and the park.
            $staleMarked = $have && $dir && @is_file($dir . 'stale.txt');
            if ($staleMarked) {
                $have = false;
            }
            // v7.10.685 — PRESENCE IS NOT SERVICE. $have decided COLLECT-vs-GENERATE purely on a
            // crit FILE existing, but a crit the render refuses to paint — the zero-dark bypass
            // window — serves nobody. While that file sat on
            // disk every kick took the collect branch, so the ONE page that needed a fresh gen was
            // the one page that never dispatched. Receipt (wpcompress, 2026-08-02): pages with no
            // crit file reached the service all afternoon while the homepage sent ZERO requests for
            // hours and rendered critless. stale.txt was already honoured above; this is its
            // untreated twin.
            $unservableWhy = false;
            if ($have && $dir && apply_filters('wpc_kick_gen_on_unservable', true)) {
                if (function_exists('wpc_crit_bypass_active') && wpc_crit_bypass_active($k)) {
                    $unservableWhy = 'bypass';
                }
                if ($unservableWhy !== false) {
                    $have = false; // regenerate: a crit nobody paints is not a crit we hold
                }
            }
            if (function_exists('wpc_cache_first_log')) {
                $receivedSource = wpc_kick_received_source($k);
                wpc_cache_first_log('kick-rx', $k, '', ['have' => $have ? 1 : 0,
                    'stale' => $staleMarked ? 1 : 0, 'unservable' => $unservableWhy === false ? '' : $unservableWhy,
                    'src' => $receivedSource['name']]);
            }
            if ($have && function_exists('wpc_lcp_repull_handler')) {


                $wpc_ck   = defined('WPS_IC_CACHE') ? rtrim(WPS_IC_CACHE, '/') . '/' . $k . '/' : '';
                $wpc_cm   = (int) @filemtime($dir . 'critical_desktop.css');
                $wpc_newv = 0;
                foreach (['index.html_gzip', 'webp_index.html_gzip', 'mobile_index.html_gzip', 'mobile-webp_index.html_gzip', 'localonly_index.html_gzip', 'mobile_localonly_index.html_gzip'] as $wpc_vf) {
                    $wpc_vm = (int) @filemtime($wpc_ck . $wpc_vf);
                    if ($wpc_vm > $wpc_newv) {
                        $wpc_newv = $wpc_vm;
                    }
                }
                if ($wpc_cm > 0 && $wpc_newv > 0 && $wpc_cm > $wpc_newv
                    && apply_filters('wpc_stale_public_heal', true)) {
                    if (class_exists('wps_ic_cache_integrations') && method_exists('wps_ic_cache_integrations', 'purgeCacheFiles')) {
                        wps_ic_cache_integrations::purgeCacheFiles($k);
                    }
                    $wpc_su = (class_exists('wps_ic_url_key') && method_exists('wps_ic_url_key', 'getUrlFromKey'))
                        ? (string) wps_ic_url_key::getUrlFromKey($k) : '';
                    if ($wpc_su !== '' && class_exists('wps_cacheHtml') && method_exists('wps_cacheHtml', 'removeStaticMirror')) {
                        wps_cacheHtml::removeStaticMirror($wpc_su);
                    }
                    if (function_exists('wpc_cache_first_log')) {
                        wpc_cache_first_log('stale-purge', $k, $wpc_su, ['crit_m' => $wpc_cm, 'cache_m' => $wpc_newv]);
                    }
                }
                if (function_exists('wpc_wire_catchup')) {
                    wpc_wire_catchup($k); // v7.10.684 — heal a declared-but-not-held wire on the kick lane
                }
                wpc_lcp_repull_handler($k, 1);
            } elseif (class_exists('wps_criticalCss')
                // v7.10.686 — AN UNSERVABLE CRIT MUST NOT BE VETOED BY COLLECTION. .685 correctly
                // routed a bypassed crit to this branch, and then collection
                // answered "already landed" from the same file-presence test the branch exists to
                // escape (pullDerivedArtifacts returns true when both blobs are >64B) — so the
                // generate below never ran. Receipt (wpcompress 2026-08-02): kick-rx
                // {have:0, unservable:"bypass"} immediately followed by kick-collect-landed, and
                // still no dispatch. Re-collecting cannot help: the bypass rejects THESE
                // bytes by mtime, so the same bytes stay unservable however many times we fetch them. Only a new
                // generation changes the answer — short-circuit straight to it.
                && ($unservableWhy !== false || $staleMarked
                    || !(function_exists('wpc_crit_kick_collect') && wpc_crit_kick_collect($k)))) {
                // B3 (≤60s contract): collection ran first and found nothing on the shelf —
                // only now is generation the right move.

                $u = '';
                if (class_exists('wps_ic_url_key') && method_exists('wps_ic_url_key', 'getUrlFromKey')) {
                    $u = (string) wps_ic_url_key::getUrlFromKey($k);
                }
                // A8 (incident report 2026-07-20): an unresolvable key must be a NO-OP, not a
                // home_url fallback — the fallback redirected five different pages' kicks at
                // the one page already parked and failing (and stamped home's key over their
                // logs, A7). Home itself still resolves: its key matches setup(home_url()).
                if ($u === '' && function_exists('home_url') && class_exists('wps_ic_url_key')
                    && ltrim((string) (new wps_ic_url_key())->setup(home_url('/')), '/') === ltrim((string) $k, '/')) {
                    $u = home_url('/');
                }
                if ($u === '') {
                    // v7.10.530 — record the proof so the render path stops minting chains for it.
                    if (function_exists('wpc_kick_dead_mark')) {
                        wpc_kick_dead_mark($k);
                    }
                    if (function_exists('wpc_cache_first_log')) {
                        wpc_cache_first_log('kick-unresolvable', $k, '', []);
                    }
                }
                if ($u !== '' && function_exists('wpc_gen_service_hold_until') && wpc_gen_service_hold_until($k) > 0) {
                    // The service asked the site to wait: no generate slot is taken.
                    wpc_gen_service_hold_note($k, 'kick');
                    $u = '';
                }
                if ($u !== '') {


                    global $wpdb;


                    $generateLockPrefix = 'wpc_gen_' . substr(md5((defined('DB_NAME') ? DB_NAME : '') . $wpdb->prefix), 0, 12) . '_';
                    $generateSlot = 0;
                    foreach ([1, 2] as $slotNumber) {
                        if ((int) $wpdb->get_var($wpdb->prepare("SELECT GET_LOCK(%s, %d)", $generateLockPrefix . $slotNumber, 0))) {
                            $generateSlot = $slotNumber;
                            break;
                        }
                    }
                    if (!$generateSlot) {
                        if (function_exists('wpc_cache_first_log')) {
                            wpc_cache_first_log('kick-slots-busy', $k, '', []);
                        }
                        wpc_kick_dropped($k, 'slots');
                    } else {
                        try {
                            if (function_exists('set_time_limit')) {
                                @set_time_limit(150);
                            }
                            $c = new wps_criticalCss($u);
                            if (method_exists($c, 'generateCriticalAjax')) {
                                $c->generateCriticalAjax();
                            }
                            if (function_exists('wpc_cache_first_log')) {
                                wpc_cache_first_log('kick-generate', $k, $u, []);
                            }
                        } finally {
                            $wpdb->query($wpdb->prepare("SELECT RELEASE_LOCK(%s)", $generateLockPrefix . $generateSlot));
                        }
                    }
                }
            }
        } catch (\Throwable $e) {
        }
        wp_die('', '', ['response' => 200]);
    }
    add_action('wp_ajax_wpc_repull_kick', 'wpc_repull_kick_receiver');
    add_action('wp_ajax_nopriv_wpc_repull_kick', 'wpc_repull_kick_receiver');
}


if (!function_exists('wpc_gen_dispatch')) {
    /*
     * THE ONE DOOR TO /generate.
     *
     * Every generation this site asks the crit service for leaves through wpc_gen_dispatch():
     * initCritical, generateCriticalAjax and, through them, the kick receiver, the cron
     * redispatch, the heal lanes, the first-run lane, ?apiPreload and every button. The door
     * owns what must be the same on every path:
     *
     *   the switch   nothing leaves while critical CSS is off for the page (wpc_crit_generation_off),
     *                whoever asks, a person's click included.
     *   the class    'human' when a person's click (or the backend acting for one) declared it,
     *                'automatic' for everything else. Humans pass straight through, keep the
     *                force flag their path has always sent and are bounded only by the service.
     *   the page     a body without the page's html is never sent, whoever asks.
     *   the gates    automatic only, in order: the service's holds (wpc_gen_service_hold_until;
     *                a needs_corpus hold is judged on the built body, wpc_gen_hold_on_body), at
     *                most 4 POSTs per URL key per 2 h, and 45 s between POSTs site-wide. Each
     *                protects something the others do not: the service's budget, one looping
     *                page spending it, the origin's PHP workers.
     *   the identity a client uuid the service adopts as the generation id, stamped on disk
     *                before the POST so a held connection that outlives our timeout still lands
     *                and still measures; the envelope, so the answer says whether it was a fresh
     *                generation or a reused one.
     *   the answer   wpc_gen_answer(): what the per-generation park records, the service's
     *                refusal contract (site-wide hold, per-key retry, the 5xx back-off).
     *
     * The caller keeps what is specific to it: its own guards before the door (single-flight,
     * park, cooldown, served hold), the request body (built only after the gates pass, because a
     * corpus fetch is expensive) and what it does with a landed answer.
     */

    /**
     * TRUE when critical CSS is off for $urlKey: the site setting is off and no page's own setting
     * turns it on for that key. With no key, TRUE only when no page turns it on either.
     * The dispatch door asks this for every caller, a click included: with the setting off, Remove
     * Critical on a test site still sent two forced generations and landed crit on disk, because
     * the consume check before the door stands aside for forced and admin requests.
     */
    function wpc_crit_generation_off($urlKey = '')
    {
        $settings = get_option(WPS_IC_SETTINGS);
        if (is_array($settings) && isset($settings['critical']['css']) && (string) $settings['critical']['css'] === '1') {
            return false;
        }
        $excludes = get_option('wpc-excludes');
        $pagesOn = [];
        if (is_array($excludes) && !empty($excludes['page_excludes']) && is_array($excludes['page_excludes'])) {
            foreach ($excludes['page_excludes'] as $pageId => $pageExcludes) {
                if (is_array($pageExcludes) && isset($pageExcludes['critical_css']) && (string) $pageExcludes['critical_css'] === '1') {
                    $pagesOn[] = $pageId;
                }
            }
        }
        if ($pagesOn === []) {
            return true;
        }
        $urlKey = ltrim((string) $urlKey, '/');
        if ($urlKey === '') {
            return false;
        }
        if (!class_exists('wps_ic_url_key')) {
            return false;
        }
        foreach ($pagesOn as $pageId) {
            $pageUrl = ((string) $pageId === 'home') ? home_url('/') : (function_exists('get_permalink') ? (string) get_permalink((int) $pageId) : '');
            if ($pageUrl !== '' && ltrim((string) (new wps_ic_url_key())->setup($pageUrl), '/') === $urlKey) {
                return false;
            }
        }
        return true;
    }

    /** 'human' when this request declared a person's intent; 'automatic' otherwise. */
    function wpc_gen_dispatch_class()
    {
        return (!empty($GLOBALS['wpc_gen_human_via']) || !empty($GLOBALS['wpc_critical_generate_forced']))
            ? 'human' : 'automatic';
    }

    /**
     * Which lane asked for a generation, for the gen-dispatch receipt only; it decides nothing.
     * A human path names itself; otherwise a cron hook, the kick receiver (loopback or beacon),
     * a warm render, another ajax action, or 'render' for a visitor's own request.
     */
    function wpc_gen_dispatch_lane()
    {
        if (!empty($GLOBALS['wpc_gen_human_via'])) {
            return (string) $GLOBALS['wpc_gen_human_via'];
        }
        if (!empty($GLOBALS['wpc_critical_generate_forced'])) {
            return 'forced';
        }
        if (function_exists('wp_doing_cron') && wp_doing_cron()) {
            $hook = function_exists('current_action') ? (string) current_action() : '';
            return $hook !== '' ? 'cron:' . substr($hook, 0, 40) : 'cron';
        }
        $action = isset($_REQUEST['action']) ? preg_replace('/[^a-z0-9_]/', '', strtolower((string) $_REQUEST['action'])) : '';
        if ($action === 'wpc_repull_kick') {
            return 'kick';
        }
        if (!empty($_SERVER['HTTP_X_WPC_CACHE_WARM'])) {
            return 'warm';
        }
        if (function_exists('wp_doing_ajax') && wp_doing_ajax()) {
            return 'ajax:' . substr((string) $action, 0, 40);
        }
        return 'render';
    }

    /**
     * Run $dispatch as a human-initiated generation: class human, which forces
     * (wpc_gen_force_for_class). For the paths a person starts that leave the kick-path guards
     * as they are (Run critical, the Remove click's detached regeneration); the paths that also
     * stand those guards down declare themselves through $GLOBALS['wpc_critical_generate_forced'].
     */
    function wpc_gen_as_human($via, callable $dispatch)
    {
        $previous = isset($GLOBALS['wpc_gen_human_via']) ? $GLOBALS['wpc_gen_human_via'] : null;
        $GLOBALS['wpc_gen_human_via'] = (string) $via;
        try {
            return $dispatch();
        } finally {
            if ($previous === null) {
                unset($GLOBALS['wpc_gen_human_via']);
            } else {
                $GLOBALS['wpc_gen_human_via'] = $previous;
            }
        }
    }

    /**
     * The force value a dispatch sends, decided by who asked and by nothing else. Every human
     * dispatch sends '1' (policy P-G6, amended 2026-09-23: a click always generates), so the
     * service renders it past its demand filter and its debounce while its hourly caps still
     * apply; that covers Generate, Rebuild This Page, Run critical, the Remove/Purge Critical
     * regeneration and ?apiGenerateCritical. An automatic dispatch never forces: the service's
     * debounce is its only protection against generation storms. The service compares the
     * string '1'.
     */
    function wpc_gen_force_for_class($class)
    {
        return $class === 'human' ? '1' : '';
    }

    /**
     * The fields a dispatch carries about removal. Removal is the service's: it keeps a minimum
     * epoch per site and per page and never answers with a generation below it. The plugin only
     * mints the values (a Remove raises the site's, a per-page removal that page's) and carries
     * them: `epoch` from the option wpc_crit_site_epoch, `page_epoch` from the page's
     * gen_fails.json. The service stores max(stored, sent), so every dispatch is also the
     * durable carrier of a raise the prompt endpoint missed. Absent means 0 and is not sent.
     * Kill switch: define WPC_CRIT_SITE_EPOCH false.
     */
    function wpc_gen_dispatch_epoch_fields(array $args, $urlKey)
    {
        unset($args['epoch'], $args['page_epoch']);
        if (defined('WPC_CRIT_SITE_EPOCH') && !WPC_CRIT_SITE_EPOCH) {
            return $args;
        }
        $siteEpoch = (int) get_option('wpc_crit_site_epoch', 0);
        if ($siteEpoch > 0) {
            $args['epoch'] = $siteEpoch;
        }
        if ((string) $urlKey !== '') {
            $record = wpc_gen_landless_read((string) $urlKey);
            $pageEpoch = isset($record['kept']['page_epoch']) ? (int) $record['kept']['page_epoch'] : 0;
            if ($pageEpoch > 0) {
                $args['page_epoch'] = $pageEpoch;
            }
        }
        return $args;
    }

    /**
     * The URL of one of the service's read routes for $urlKey ('/status', '/v2/latest'), carrying
     * the same removal epochs a dispatch carries (wpc_gen_dispatch_epoch_fields: present only
     * when above 0), and the site's apikey: the service stores a carried epoch only from a read
     * that names the matching apikey (a uuid alone rides the served page). A read that names the
     * epoch lets the service withhold a generation below it on the plugin's own pulls.
     */
    function wpc_crit_service_read_url($route, array $query, $urlKey)
    {
        if (!isset($query['apikey'])) {
            $options = get_option(defined('WPS_IC_OPTIONS') ? WPS_IC_OPTIONS : 'wps_ic');
            if (is_array($options) && !empty($options['api_key'])) {
                $query['apikey'] = (string) $options['api_key'];
            }
        }
        $query = wpc_gen_dispatch_epoch_fields($query, (string) $urlKey);
        return str_replace('/generate', (string) $route, WPS_IC_CRITICAL_API_URL) . '?' . http_build_query($query);
    }

    /**
     * Raise a removal epoch: 'site' when every page's crit was removed (Remove Critical CSS, a
     * theme switch, purge_site, the nuclear purge), 'page' when one page's was (the per-page
     * Critical CSS purge, the page settings, the meta box, purge_url / purge_id, a generation the
     * service withdrew). Nothing that only marks crit stale raises anything: a stale crit keeps
     * serving until a new one lands.
     *
     * The value is minted here and stored where every dispatch reads it (the option for the
     * site, the page's gen_fails.json for a page), then sent once to the service's prompt
     * endpoint. The plugin never compares an epoch itself; the service does. Until the service
     * has acknowledged the value (wpc_crit_removal_unacked), no land from a static object is
     * taken: the storage pointer and the CDN shelf keep naming the removed generation until the
     * service holds the number that withdraws it.
     *
     * The click's POST is non-blocking, so it never confirms anything: whether WordPress refused it
     * (posted:0) or handed it over (posted:1), the value is sent again, twice and no more: by the
     * next /generate, which carries it, and by one blocking cron event 60 s later
     * (wpc_crit_removal_retry), whose answer is the acknowledgement. Without that event a removal
     * the service did hear of would stay unacknowledged until a blocking /generate answer, and
     * every land from a static object would wait for it.
     *
     * Returns the epoch raised, or 0 when switched off or the page cannot be named.
     */
    function wpc_crit_epoch_bump($scope, $urlKey = '', $reason = '', $pageUrl = '')
    {
        if (defined('WPC_CRIT_SITE_EPOCH') && !WPC_CRIT_SITE_EPOCH) {
            return 0;
        }
        $scope = $scope === 'page' ? 'page' : 'site';
        $urlKey = ltrim((string) $urlKey, '/');
        if ($scope === 'page' && $urlKey === '') {
            return 0;
        }
        try {
            // Strictly rising: two removals in one second must still separate the generations
            // admitted between them. A site with no acknowledgement record yet (a build that kept
            // none) counts everything raised before this removal as acknowledged.
            if ($scope === 'site') {
                $previousEpoch = (int) get_option('wpc_crit_site_epoch', 0);
                if (get_option('wpc_crit_site_epoch_acked', null) === null) {
                    update_option('wpc_crit_site_epoch_acked', $previousEpoch, false);
                }
                $epoch = max(time(), $previousEpoch + 1);
                update_option('wpc_crit_site_epoch', $epoch, false);
            } else {
                $state = wpc_gen_landless_read($urlKey);
                $previousEpoch = (int) ($state['kept']['page_epoch'] ?? 0);
                if (!isset($state['kept']['page_epoch_acked'])) {
                    $state['kept']['page_epoch_acked'] = $previousEpoch;
                }
                $epoch = max(time(), $previousEpoch + 1);
                $state['kept']['page_epoch'] = $epoch;
                wpc_gen_landless_write($urlKey, $state);
                if ($pageUrl === '') {
                    $pageUrl = wpc_crit_epoch_page_url($urlKey);
                }
            }
            $post = wpc_crit_epoch_post($scope, $epoch, $urlKey, (string) $pageUrl, false);
            if (function_exists('wpc_cache_first_log')) {
                $layers = ['scope' => $scope, 'epoch' => $epoch, 'reason' => (string) $reason, 'posted' => $post['posted']];
                if ($post['err'] !== '') {
                    $layers['err'] = $post['err'];
                }
                // With critical CSS off the removal still raises the epoch, so switching it on later
                // cannot land the removed generation, but no regeneration follows it.
                if (function_exists('wpc_crit_generation_off') && wpc_crit_generation_off($urlKey)) {
                    $layers['dispatch'] = 0;
                    $layers['why'] = 'crit-off';
                }
                wpc_cache_first_log('crit-removal', $urlKey, (string) $pageUrl, $layers);
            }
            if (!$post['acked'] && ($post['posted'] || $post['err'] !== '') && function_exists('wp_schedule_single_event')
                && !wp_next_scheduled('wpc_crit_removal_retry', [$scope, $urlKey])) {
                // Plain cron, not the pipeline scheduler: a removal the service may never have
                // heard of must not be shed by load or queued behind warm work.
                wp_schedule_single_event(time() + 60, 'wpc_crit_removal_retry', [$scope, $urlKey]);
            }
            return $epoch;
        } catch (\Throwable $e) {
            return 0;
        }
    }

    /** The page URL a page-scope removal names to the service: url.txt, then the key map. */
    function wpc_crit_epoch_page_url($urlKey)
    {
        $pageUrl = '';
        if (defined('WPS_IC_CRITICAL')) {
            $pageUrl = trim((string) @file_get_contents(rtrim(WPS_IC_CRITICAL, '/') . '/' . $urlKey . '/url.txt'));
        }
        if ($pageUrl === '' && class_exists('wps_ic_url_key') && method_exists('wps_ic_url_key', 'getUrlFromKey')) {
            $pageUrl = (string) wps_ic_url_key::getUrlFromKey($urlKey);
        }
        return $pageUrl;
    }

    /**
     * POST one removal epoch to the service's /v2/site-epoch. Returns ['posted', 'err', 'code',
     * 'acked'].
     *
     * Non-blocking (the click): posted:1 = the POST was handed to the transport; it says nothing
     * about the answer (a refused connection or a timeout still looks handed over). posted:0 with
     * err = WordPress refused it before the transport (a blocked host, a pre_http_request filter,
     * a bad URL). Blocking (the retry): posted:1 = an HTTP answer came back, code is its status,
     * and a 200 is the service's acknowledgement of the value, recorded here.
     */
    function wpc_crit_epoch_post($scope, $epoch, $urlKey, $pageUrl, $blocking)
    {
        $result = ['posted' => 0, 'err' => '', 'code' => 0, 'acked' => 0];
        $options = get_option(defined('WPS_IC_OPTIONS') ? WPS_IC_OPTIONS : 'wps_ic');
        $apikey = is_array($options) && !empty($options['api_key']) ? (string) $options['api_key'] : '';
        if ($apikey === '' || !defined('WPS_IC_CRITICAL_API_URL') || ($scope === 'page' && $pageUrl === '')) {
            return $result;
        }
        $body = $scope === 'site'
            ? ['apikey' => $apikey, 'epoch' => (int) $epoch]
            : ['apikey' => $apikey, 'page_epoch' => (int) $epoch, 'url' => (string) $pageUrl];
        $ts = sprintf('%.0f', microtime(true) * 1000);
        $signed = (int) $epoch . '|' . ($scope === 'site' ? '' : (string) $pageUrl) . '|' . $ts;
        $transportAnswer = wp_remote_post(str_replace('/generate', '/v2/site-epoch', WPS_IC_CRITICAL_API_URL), [
            'timeout'  => $blocking ? 5 : 2,
            'blocking' => (bool) $blocking,
            'headers'  => [
                'Content-Type' => 'application/json',
                'X-WPC-Ts'     => $ts,
                'X-WPC-Sig'    => hash_hmac('sha256', $signed, $apikey),
            ],
            'body'     => json_encode($body),
        ]);
        if (is_wp_error($transportAnswer)) {
            $result['err'] = substr((string) $transportAnswer->get_error_message(), 0, 80);
            return $result;
        }
        $result['posted'] = 1;
        if ($blocking) {
            $result['code'] = (int) wp_remote_retrieve_response_code($transportAnswer);
            $answer = json_decode((string) wp_remote_retrieve_body($transportAnswer), true);
            // ok with applied:false means the service holds no generation of this site to remove,
            // which acknowledges the value as fully as a raise does.
            if ($result['code'] === 200 && is_array($answer) && !empty($answer['ok'])) {
                wpc_crit_epoch_acked($scope === 'site' ? (int) $epoch : 0, $urlKey, $scope === 'page' ? (int) $epoch : 0);
                $result['acked'] = 1;
            }
        }
        return $result;
    }

    /**
     * The one retry of a removal POST: the value raised last for that scope, sent blocking so its
     * answer is read. Skipped when the service has acknowledged that value meanwhile (a /generate
     * answer). Nothing is scheduled after it: the next /generate carries the value anyway.
     */
    function wpc_crit_removal_retry($scope, $urlKey = '')
    {
        try {
            if (defined('WPC_CRIT_SITE_EPOCH') && !WPC_CRIT_SITE_EPOCH) {
                return;
            }
            $scope = $scope === 'page' ? 'page' : 'site';
            $urlKey = ltrim((string) $urlKey, '/');
            $pageUrl = '';
            if ($scope === 'site') {
                $epoch = (int) get_option('wpc_crit_site_epoch', 0);
                $ackedEpoch = (int) get_option('wpc_crit_site_epoch_acked', 0);
            } else {
                $kept = wpc_gen_landless_read($urlKey)['kept'];
                $epoch = (int) ($kept['page_epoch'] ?? 0);
                $ackedEpoch = (int) ($kept['page_epoch_acked'] ?? 0);
                $pageUrl = wpc_crit_epoch_page_url($urlKey);
            }
            if ($epoch <= 0) {
                return;
            }
            if ($ackedEpoch >= $epoch) {
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('crit-removal-retry', $urlKey, $pageUrl, ['scope' => $scope, 'epoch' => $epoch, 'posted' => 0, 'skipped' => 'acked']);
                }
                return;
            }
            $post = wpc_crit_epoch_post($scope, $epoch, $urlKey, $pageUrl, true);
            if (function_exists('wpc_cache_first_log')) {
                $layers = ['scope' => $scope, 'epoch' => $epoch, 'posted' => $post['posted'], 'code' => $post['code'], 'acked' => $post['acked']];
                if ($post['err'] !== '') {
                    $layers['err'] = $post['err'];
                }
                wpc_cache_first_log('crit-removal-retry', $urlKey, $pageUrl, $layers);
            }
        } catch (\Throwable $e) {
        }
    }
    add_action('wpc_crit_removal_retry', 'wpc_crit_removal_retry', 10, 2);

    /**
     * Record what the service confirmed it holds: its site minimum and, for $urlKey, its page
     * minimum. Only ever rises. Written from a /v2/site-epoch 200 and from a /generate answer
     * that names the minimums it stored (wpc_gen_answer).
     */
    function wpc_crit_epoch_acked($siteEpochMin, $urlKey = '', $pageEpochMin = 0)
    {
        if ((int) $siteEpochMin > (int) get_option('wpc_crit_site_epoch_acked', 0)) {
            update_option('wpc_crit_site_epoch_acked', (int) $siteEpochMin, false);
        }
        $urlKey = ltrim((string) $urlKey, '/');
        if ($urlKey !== '' && (int) $pageEpochMin > 0) {
            $state = wpc_gen_landless_read($urlKey);
            if ((int) $pageEpochMin > (int) ($state['kept']['page_epoch_acked'] ?? 0)) {
                $state['kept']['page_epoch_acked'] = (int) $pageEpochMin;
                wpc_gen_landless_write($urlKey, $state);
            }
        }
    }

    /**
     * True while this site holds a removal epoch (the site's, or $urlKey's page epoch) the
     * service has not acknowledged. A value with no acknowledgement record at all was raised by
     * a build that kept none and counts as acknowledged.
     */
    function wpc_crit_removal_unacked($urlKey = '')
    {
        if (defined('WPC_CRIT_SITE_EPOCH') && !WPC_CRIT_SITE_EPOCH) {
            return false;
        }
        $siteAcked = get_option('wpc_crit_site_epoch_acked', null);
        if ($siteAcked !== null && (int) get_option('wpc_crit_site_epoch', 0) > (int) $siteAcked) {
            return true;
        }
        $urlKey = ltrim((string) $urlKey, '/');
        if ($urlKey === '') {
            return false;
        }
        $kept = wpc_gen_landless_read($urlKey)['kept'];
        return isset($kept['page_epoch_acked']) && (int) ($kept['page_epoch'] ?? 0) > (int) $kept['page_epoch_acked'];
    }

    /**
     * The per-page cap's window (P-G4): the times, inside the last 7200 s, of the automatic
     * dispatches for $urlKey that the service accepted as a generation.
     */
    function wpc_gen_rate_window($urlKey)
    {
        $rate = (array) get_option('wpc_gen_rate', []);
        return array_values(array_filter((array) ($rate[(string) $urlKey] ?? []), function ($t) {
            return (time() - (int) $t) < 7200;
        }));
    }

    /**
     * Count one accepted automatic dispatch against its page's cap: a POST the service took as a
     * generation (answered fresh or still rendering) or may have (fire-and-forget, or timed out
     * with no answer: a render under way). A refusal and a reused generation count nothing.
     */
    function wpc_gen_rate_count($urlKey)
    {
        if ((string) $urlKey === '' || !apply_filters('wpc_gen_rate_cap', true)) {
            return;
        }
        $rate = (array) get_option('wpc_gen_rate', []);
        $times = wpc_gen_rate_window($urlKey);
        $times[] = time();
        $rate[(string) $urlKey] = $times;
        if (count($rate) > 200) {
            $rate = array_slice($rate, -100, null, true);
        }
        update_option('wpc_gen_rate', $rate, false);
    }

    /** A wipe starts the page's cap afresh: 'all' or one url key. */
    function wpc_gen_rate_reset($scope)
    {
        $rate = get_option('wpc_gen_rate', []);
        if (!is_array($rate) || $rate === []) {
            return;
        }
        if ((string) $scope === 'all') {
            delete_option('wpc_gen_rate');
            return;
        }
        if (isset($rate[(string) $scope])) {
            unset($rate[(string) $scope]);
            update_option('wpc_gen_rate', $rate, false);
        }
    }

    /**
     * The automatic gates, in order. '' = pass; otherwise the reason, already receipted.
     *
     * The 45 s site spacing applies only to a page that already serves crit (a crit file on
     * disk, stale-marked or not), as in 7.24.04: it paces the refresh of pages that are styled,
     * and a crit-less page is the one that must not wait. Applied to every page, it deferred
     * the first kick of every other page after a Remove Critical (staging, 2026-09-27: a fixed
     * 13 s visit cadence let one page in two through), and a deferred kick is owed only the
     * page's next visit. $spacing is filled with what the dispatch door needs to give the
     * gap back when this dispatch is refused: ['taken' => 'serves-crit'|'crit-less'|'off',
     * 'before' => the mark it replaced, 'mark' => the mark it wrote].
     */
    function wpc_gen_automatic_gate($urlKey, $via, &$spacing = null)
    {
        $spacing = ['taken' => 'off', 'before' => null, 'mark' => 0];
        if (function_exists('wpc_gen_service_hold_until') && wpc_gen_service_hold_until($urlKey) > 0) {
            wpc_gen_service_hold_note($urlKey, $via);
            return 'service-hold';
        }
        if ($urlKey !== '' && apply_filters('wpc_gen_rate_cap', true)) {
            $perKeyTimes = wpc_gen_rate_window($urlKey);
            if (count($perKeyTimes) >= 4) {
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('gen-dispatch-capped', $urlKey, '', ['n2h' => count($perKeyTimes), 'via' => $via]);
                }
                return 'capped';
            }
        }
        $spacingSeconds = (int) apply_filters('wpc_gen_global_spacing', 45);
        if ($spacingSeconds <= 0) {
            return '';
        }
        $critDir = ($urlKey !== '' && defined('WPS_IC_CRITICAL')) ? rtrim(WPS_IC_CRITICAL, '/') . '/' . ltrim($urlKey, '/') . '/' : '';
        if ($critDir === '' || !(@filesize($critDir . 'critical_desktop.css') > 5 || @filesize($critDir . 'critical_mobile.css') > 5)) {
            $spacing['taken'] = 'crit-less';
            return '';
        }
        $spacing['taken'] = 'serves-crit';
        $now = time();
        if (!add_option('wpc_gen_sf_global', $now, '', 'no')) {
            $last = (int) get_option('wpc_gen_sf_global');
            if ($last && ($now - $last) < $spacingSeconds) {
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('gen-deferred-global', $urlKey, '', ['age' => $now - $last, 'via' => $via]);
                }
                return 'spaced';
            }
            $spacing['before'] = $last;
            update_option('wpc_gen_sf_global', $now);
        }
        $spacing['mark'] = $now;
        return '';
    }

    /**
     * Give the site spacing back after a dispatch that produced no generation: refused before
     * the POST (no page, a service hold on the body) or refused by the service's answer. The
     * mark goes back to what it was, unless a later dispatch has taken it since. The purge's own
     * redispatch was refused `no-page` on staging (2026-09-27) and still held the mark, so the
     * homepage's first two visit kicks after it were deferred 38 s and 40 s.
     * Receipt: `gen-gap-returned {why, via}`.
     */
    function wpc_gen_spacing_give_back(array $spacing, $urlKey, $why, $via)
    {
        if (empty($spacing['mark']) || (int) get_option('wpc_gen_sf_global') !== (int) $spacing['mark']) {
            return;
        }
        if ($spacing['before'] === null) {
            delete_option('wpc_gen_sf_global');
        } else {
            update_option('wpc_gen_sf_global', (int) $spacing['before']);
        }
        if (function_exists('wpc_cache_first_log')) {
            wpc_cache_first_log('gen-gap-returned', (string) $urlKey, '', ['why' => substr((string) $why, 0, 32), 'via' => (string) $via]);
        }
    }

    /** The page's URL as a dispatch names it: without the parameters of a push render (wpc_crit_push_params). */
    function wpc_gen_dispatch_url($url)
    {
        $parts = explode('?', (string) $url, 2);
        if (!isset($parts[1]) || !function_exists('wpc_crit_push_params')) {
            return (string) $url;
        }
        $kept = [];
        foreach (explode('&', $parts[1]) as $pair) {
            $name = strtolower(urldecode((string) explode('=', $pair, 2)[0]));
            if ($pair !== '' && !in_array($name, wpc_crit_push_params(), true)) {
                $kept[] = $pair;
            }
        }
        return $parts[0] . ($kept !== [] ? '?' . implode('&', $kept) : '');
    }

    /**
     * POST one body to /generate: gzip JSON when it carries a corpus (html or css), shedding
     * html_mobile and then css until it is under 10 MB; else JSON or form.
     */
    function wpc_gen_post(array $args, array $request)
    {
        $transport = array_merge(['timeout' => 5], isset($request['transport']) ? (array) $request['transport'] : []);
        if ((!empty($args['css']) || !empty($args['html'])) && function_exists('gzencode')) {
            foreach (['', 'html_mobile', 'css'] as $shed) {
                if ($shed !== '') {
                    if (!isset($args[$shed])) {
                        continue;
                    }
                    unset($args[$shed]);
                }
                $gzipped = gzencode(wp_json_encode($args));
                if ($gzipped !== false && strlen($gzipped) < 10 * 1024 * 1024) {
                    return wp_remote_post(WPS_IC_CRITICAL_API_URL, $transport + [
                        'body'    => $gzipped,
                        'headers' => ['Content-Type' => 'application/json', 'Content-Encoding' => 'gzip'],
                    ]);
                }
            }
        }
        if (!empty($request['form'])) {
            return wp_remote_post(WPS_IC_CRITICAL_API_URL, $transport + ['body' => $args]);
        }
        return wp_remote_post(WPS_IC_CRITICAL_API_URL, $transport + [
            'body'    => wp_json_encode($args),
            'headers' => ['Content-Type' => 'application/json'],
        ]);
    }

    /**
     * Dispatch one generation for $urlKey.
     *
     * $buildRequest(string $uuid): array — called only after the gates pass. Returns
     *   'args'      the body (url, apikey, version, corpus …)
     *   'transport' wp_remote_post options (timeout, blocking, sslverify, user-agent)
     *   'form'      true to send the body form-encoded when it carries no corpus
     *   'receipt'   extra fields for the gen-dispatch receipt
     *
     * A body without the page ('html') is never sent, whoever asks: 'no-page'; nor one for a URL
     * that is not a front-end page (wpc_url_is_low_value): 'not-a-page'. The URL goes
     * without the push parameters, and 'via' names the path that asked.
     *
     * Returns ['sent', 'refused', 'uuid', 'class', 'response', 'body', 'answer']; 'built' is true
     * when the body was built and then refused.
     */
    function wpc_gen_dispatch($urlKey, $via, callable $buildRequest)
    {
        $urlKey = (string) $urlKey;
        $via = (string) $via;
        $result = ['sent' => false, 'refused' => '', 'uuid' => '', 'class' => wpc_gen_dispatch_class(),
                   'response' => null, 'body' => '', 'answer' => []];
        if (wpc_crit_generation_off($urlKey)) {
            if ($urlKey !== '') {
                delete_option('wpc_gen_sf_' . $urlKey);
            }
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('gen-dispatch-refused', $urlKey, '', ['why' => 'crit-off', 'path' => $via, 'class' => $result['class']]);
            }
            $result['refused'] = 'crit-off';
            return $result;
        }
        $spacing = ['taken' => 'off', 'before' => null, 'mark' => 0];
        if ($result['class'] === 'automatic') {
            $refused = wpc_gen_automatic_gate($urlKey, $via, $spacing);
            if ($refused !== '') {
                // Nothing left: the caller's single-flight must not hold the key for a POST
                // that never happened.
                if ($urlKey !== '') {
                    delete_option('wpc_gen_sf_' . $urlKey);
                }
                // A kick the 45 s spacing refused is owed its page's next visit, exactly as a kick
                // the receiver was too busy to run: the page's kick dedupes are released.
                if ($refused === 'spaced' && $urlKey !== '' && wpc_gen_dispatch_lane() === 'kick' && function_exists('wpc_kick_dropped')) {
                    wpc_kick_dropped($urlKey, 'spacing');
                }
                $result['refused'] = $refused;
                return $result;
            }
        } else {
            // A click holds the site spacing too, so the automatic lanes stand back from it.
            $spacingBefore = get_option('wpc_gen_sf_global', null);
            $spacing = ['taken' => 'human', 'before' => $spacingBefore === null || $spacingBefore === false ? null : (int) $spacingBefore,
                        'mark' => time()];
            update_option('wpc_gen_sf_global', $spacing['mark']);
        }

        $uuid = wp_generate_uuid4();
        $result['uuid'] = $uuid;
        $stampSnapshot = wpc_gen_dispatch_stamp($urlKey, $uuid);

        $request = (array) $buildRequest($uuid);
        // An automatic POST always waits for its answer; only a click may send and not wait. A
        // fire-and-forget automatic POST read nothing: its refusal was never learned as a hold,
        // it was counted as a live generation against the page's 4 per 2 h, and its never-made
        // uuid was polled until the service called it superseded and the page dispatched again
        // (staging, 2026-09-27: /features/ capped after four unread POSTs, no crit for 2 h).
        if ($result['class'] === 'automatic' && isset($request['transport']['blocking']) && !$request['transport']['blocking']) {
            $request['transport']['blocking'] = true;
            $request['transport']['timeout'] = (int) apply_filters('wpc_gen_dispatch_timeout', 5);
        }
        $args = isset($request['args']) ? (array) $request['args'] : [];
        $held = null;
        // Critical CSS describes a front-end document; a REST route, feed, sitemap, admin or
        // static-file URL has none, whoever asks for it (the interaction handler takes its URL
        // from the browser). The same URL test initCritical asks before it builds.
        if (!empty($args['url']) && function_exists('wpc_url_is_low_value') && wpc_url_is_low_value((string) $args['url'])) {
            $unbuilt = 'not-a-page';
        } elseif (empty($args['html'])) {
            $unbuilt = 'no-page';
        } elseif ($result['class'] === 'automatic' && ($held = wpc_gen_hold_on_body($urlKey, $args)) !== null) {
            $unbuilt = 'service-hold';
        } else {
            $unbuilt = '';
        }
        if ($unbuilt !== '') {
            wpc_gen_dispatch_unstamp($urlKey, $uuid, $stampSnapshot, $unbuilt);
            wpc_gen_spacing_give_back($spacing, $urlKey, $unbuilt, $via);
            if ($urlKey !== '') {
                delete_option('wpc_gen_sf_' . $urlKey);
            }
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('gen-dispatch-refused', $urlKey, '', ['why' => $unbuilt, 'path' => $via, 'class' => $result['class'],
                    'css' => empty($args['css']) ? 0 : 1, 'scope' => is_array($held) ? $held['scope'] : '', 'type' => is_array($held) ? $held['type'] : '']);
            }
            if ($unbuilt === 'no-page' && function_exists('wpc_saved_page_wanted')) {
                wpc_saved_page_wanted($urlKey);
                wpc_saved_page_missing_mark($urlKey);
            }
            $result['refused'] = $unbuilt;
            $result['built'] = true;
            return $result;
        }
        if (isset($args['url'])) {
            $args['url'] = wpc_gen_dispatch_url((string) $args['url']);
        }
        $args['via'] = substr($via, 0, 40);
        $args['uuid'] = $uuid;
        $args['envelope'] = '1';
        unset($args['force']);
        $force = wpc_gen_force_for_class($result['class']);
        if ($force !== '') {
            $args['force'] = $force;
        }
        $args = wpc_gen_dispatch_epoch_fields($args, $urlKey);

        $response = wpc_gen_post($args, $request);
        $body = (string) wp_remote_retrieve_body($response);
        $blocking = !isset($request['transport']['blocking']) || $request['transport']['blocking'];
        if (function_exists('wpc_cache_first_log')) {
            wpc_cache_first_log('gen-dispatch', $urlKey, '', array_merge([
                'path'  => $via,
                'lane'  => wpc_gen_dispatch_lane(),
                'uuid'  => substr($uuid, 0, 8),
                'class' => $result['class'],
                'force' => $force !== '' ? 1 : 0,
                'epoch' => isset($args['epoch']) ? (int) $args['epoch'] : 0,
                'page_epoch' => isset($args['page_epoch']) ? (int) $args['page_epoch'] : 0,
                'code'  => is_wp_error($response) ? 0 : (int) wp_remote_retrieve_response_code($response),
                'len'   => strlen($body),
                'head'  => substr($body, 0, 60),
                'gap'   => $spacing['taken'],
                // What the service's demand gate reads (human|bot): without it a demand_deferred
                // answer could not be told from a bot-classified dispatch (webdesign4u.com.au).
                'visitor' => isset($args['visitor']) ? substr((string) $args['visitor'], 0, 8) : '',
            ], isset($request['receipt']) ? (array) $request['receipt'] : []));
        }

        $result['sent'] = true;
        $result['response'] = $response;
        $result['body'] = $body;
        $result['answer'] = wpc_gen_answer($urlKey, $uuid, $response, $body, $result['class'], $blocking);
        // An answer that names another generation (the pointer's, on a reused answer) is noted in
        // the same dispatch record; the record's uuid and time stay what the stamp wrote.
        if ($urlKey !== '' && !empty($result['answer']['crit_uuid']) && defined('WPS_IC_CRITICAL')
            && function_exists('wpc_crit_dispatch_record_served')) {
            wpc_crit_dispatch_record_served(WPS_IC_CRITICAL . $urlKey . '/', $uuid, $result['answer']['crit_uuid']);
        }
        if (!empty($result['answer']['refused'])) {
            $refusedAs = $result['answer']['error_type'] !== '' ? $result['answer']['error_type'] : 'http-' . (int) $result['answer']['code'];
            wpc_gen_dispatch_unstamp($urlKey, $uuid, $stampSnapshot, $refusedAs);
            wpc_gen_spacing_give_back($spacing, $urlKey, $refusedAs, $via);
        }
        if ($result['class'] === 'automatic' && !empty($result['answer']['accepted'])) {
            wpc_gen_rate_count($urlKey);
        }
        return $result;
    }

    /**
     * Name the generation on disk before the POST leaves: the uuid transient, uuid.txt,
     * dispatch_ts.txt (a held connection that outlives our timeout still lands and measures) and
     * the page's dispatch record, which the corpus pushed with this dispatch is stamped with and
     * which the land pairs by uuid (wpc_crit_corpus_land). This is the one place the record and
     * dispatch_ts.txt are written for a dispatch; nothing rewrites them when the answer arrives.
     *
     * The stamp has to come first: the request builder stamps corpus.txt with the record's uuid,
     * and a webhook land can arrive before a blocking POST returns. So it cannot wait for the
     * answer; instead it keeps what it overwrites, and a refusal puts that back
     * (wpc_gen_dispatch_unstamp). Returns that snapshot: ['uuid', 'at', 'dir_created', 'files'
     * => name => ['bytes', 'mtime'], or null for a file that did not exist].
     */
    function wpc_gen_dispatch_stamp($urlKey, $uuid)
    {
        $snapshot = ['uuid' => '', 'at' => 0, 'dir_created' => false, 'files' => []];
        if ($urlKey === '') { return $snapshot; }
        // The service's async proof-trim overwrites over-cap artifacts minutes after a
        // generation; 30 min keeps the poll open across it (uuid.txt, 6 h, is the net).
        set_transient('wpc_critical_uuid_' . $urlKey, $uuid, 60 * 30);
        if (defined('WPS_IC_CRITICAL') && function_exists('wpc_crit_meta_write')) {
            $dir = WPS_IC_CRITICAL . $urlKey . '/';
            if (!is_dir($dir)) {
                @mkdir($dir, 0777, true);
                $snapshot['dir_created'] = true;
            }
            // corpus.txt is written by the request builder, not here, but under this stamp's uuid.
            foreach (['uuid.txt', 'dispatch_ts.txt', 'dispatch_record.json', 'corpus.txt'] as $name) {
                $snapshot['files'][$name] = @is_file($dir . $name)
                    ? ['bytes' => (string) @file_get_contents($dir . $name), 'mtime' => (int) @filemtime($dir . $name)] : null;
            }
            $mintedUuid = preg_replace('/[^A-Za-z0-9-]/', '', (string) $uuid);
            $stampedAt = time();
            $snapshot['uuid'] = $mintedUuid;
            $snapshot['at'] = $stampedAt;
            wpc_crit_meta_write($dir . 'uuid.txt', $mintedUuid);
            wpc_crit_meta_write($dir . 'dispatch_ts.txt', (string) $stampedAt);
            wpc_crit_meta_write($dir . 'dispatch_record.json', json_encode(['uuid' => $mintedUuid, 'at' => $stampedAt]));
        }
        wpc_gen_dispatch_order_note($urlKey, $uuid);
        return $snapshot;
    }

    /**
     * A refused dispatch produced no generation: put the page's folder back exactly as the stamp
     * found it, bytes and mtimes. Only a file that still carries this dispatch's stamp is put
     * back; one a land or an answer rewrote since is theirs and stays.
     *
     * Restoring uuid.txt by rewriting it, and leaving dispatch_ts.txt and dispatch_record.json
     * naming the refused uuid, made every refusal read as a dispatch younger than 6 h to the
     * watchdog, the repull, the store verdict and the support panel: on staging /features/ stayed
     * a watchdog candidate forever, refused no-page on every kick (2026-09-27, lane l1-kick-askers).
     */
    function wpc_gen_dispatch_unstamp($urlKey, $uuid, array $snapshot, $why)
    {
        if ($urlKey === '') { return; }
        if ((string) get_transient('wpc_critical_uuid_' . $urlKey) === (string) $uuid) {
            delete_transient('wpc_critical_uuid_' . $urlKey);
        }
        $restored = [];
        if (defined('WPS_IC_CRITICAL') && !empty($snapshot['files'])) {
            $dir = WPS_IC_CRITICAL . $urlKey . '/';
            $mintedUuid = (string) $snapshot['uuid'];
            $record = function_exists('wpc_crit_dispatch_record_read') ? wpc_crit_dispatch_record_read($dir) : [];
            $corpus = function_exists('wpc_crit_corpus_stamp_parts')
                ? wpc_crit_corpus_stamp_parts((string) @file_get_contents($dir . 'corpus.txt')) : [];
            $stillOurs = [
                'uuid.txt'             => trim((string) @file_get_contents($dir . 'uuid.txt')) === $mintedUuid,
                'dispatch_ts.txt'      => trim((string) @file_get_contents($dir . 'dispatch_ts.txt')) === (string) $snapshot['at'],
                'dispatch_record.json' => isset($record['uuid']) && $record['uuid'] === $mintedUuid,
                'corpus.txt'           => isset($corpus['uuid']) && $corpus['uuid'] === $mintedUuid,
            ];
            foreach ($snapshot['files'] as $name => $before) {
                if (empty($stillOurs[$name])) { continue; }
                $file = $dir . $name;
                if ($before === null) {
                    @unlink($file);
                } else {
                    if ((string) @file_get_contents($file) !== $before['bytes']) {
                        wpc_crit_meta_write($file, $before['bytes']);
                    }
                    @touch($file, (int) $before['mtime']);
                }
                $restored[] = $name;
            }
            if (!empty($snapshot['dir_created']) && is_dir($dir) && count((array) @scandir($dir)) === 2) {
                @rmdir($dir);
                $restored[] = 'dir';
            }
        }
        if (function_exists('wpc_cache_first_log')) {
            wpc_cache_first_log('dispatch-unstamped', $urlKey, '', ['why' => substr((string) $why, 0, 32), 'restored' => $restored]);
        }
    }

    /**
     * Read the service's answer to one dispatch. Records what the per-generation park needs,
     * applies the refusal contract and returns ['code', 'served', 'crit_uuid', 'error_type',
     * 'retry_after', 'refused', 'accepted', 'epoch', 'epoch_min', 'retry_at']. accepted = the POST counts
     * against the page's cap: the service took it, or it may have (no answer yet). retry_at = when
     * this site's own retry of the page (redispatch, or the collect for a queued one) is scheduled,
     * 0 when none is (a click's ajax answer carries it).
     *
     *   no answer (fire-and-forget, or a timeout)     → the generation is owed a land
     *   200, served fresh or no envelope             → owed a land
     *   200, debounced / unchanged / converged       → nothing of ours; the per-key served hold
     *   429 render_pending                           → ours, still rendering: owed a land
     *   4xx / 5xx naming an error_type               → the hold its hold_scope names, any class
     *   429 / 5xx                                    → today's per-key retry, collect, back-off
     */
    function wpc_gen_answer($urlKey, $uuid, $response, $body, $class, $blocking)
    {
        $answer = ['code' => 0, 'served' => '', 'crit_uuid' => '', 'error_type' => '', 'retry_after' => 0, 'refused' => false,
                   'accepted' => false, 'epoch' => 0, 'epoch_min' => 0, 'retry_at' => 0];
        if (!wpc_gen_pending_set_enabled()) {
            wpc_gen_landless_count_dispatch($urlKey);
        }
        if (!$blocking) {
            wpc_gen_pending_add($urlKey, $uuid);
            $answer['served'] = 'unread';
            $answer['accepted'] = true;
            return $answer;
        }
        $isTimeout = false;
        if (is_wp_error($response)) {
            $message = strtolower((string) $response->get_error_message());
            $isTimeout = (strpos($message, 'timed out') !== false || strpos($message, 'timeout') !== false
                || strpos($message, 'too slow') !== false);
        }
        $code = is_wp_error($response) ? 0 : (int) wp_remote_retrieve_response_code($response);
        $json = is_wp_error($response) ? null : json_decode((string) $body, true);
        $json = is_array($json) ? $json : null;
        $answer['code'] = $code;
        $answer['served'] = $json && !empty($json['served']) ? strtolower((string) $json['served']) : '';
        $answer['crit_uuid'] = $json && !empty($json['crit_uuid']) ? (string) $json['crit_uuid'] : '';
        $answer['error_type'] = $json && !empty($json['error_type']) ? (string) $json['error_type'] : '';
        $retryAfter = is_wp_error($response) ? 0 : (int) wp_remote_retrieve_header($response, 'retry-after');
        if ($retryAfter <= 0 && $json && !empty($json['retry_after'])) {
            $retryAfter = (int) $json['retry_after'];
        }
        $answer['retry_after'] = $retryAfter;
        // The generation's epoch and the effective minimum ride the answer (headers on the bare
        // path). They are recorded, never evaluated: the service applies its own minimum.
        $answer['epoch'] = $json && isset($json['epoch']) ? (int) $json['epoch']
            : (is_wp_error($response) ? 0 : (int) wp_remote_retrieve_header($response, 'x-wpc-epoch'));
        $answer['epoch_min'] = $json && isset($json['epoch_min']) ? (int) $json['epoch_min']
            : (is_wp_error($response) ? 0 : (int) wp_remote_retrieve_header($response, 'x-wpc-epoch-min'));
        // The envelope names the minimums the service stored for this dispatch: that is its
        // acknowledgement of the removal epochs the POST carried. A raise its hourly budget
        // refused was not stored and acknowledges nothing.
        if ($json && isset($json['site_epoch_min']) && empty($json['epoch_raise_throttled']) && function_exists('wpc_crit_epoch_acked')) {
            wpc_crit_epoch_acked((int) $json['site_epoch_min'], $urlKey, (int) ($json['page_epoch_min'] ?? 0));
        }

        // A removal landed while this render was running: the service will deliver it nowhere.
        // That is no generation and no failure — nothing is owed a land, nothing retries, no
        // breaker arms. The next visit asks again and gets a current one.
        if ($answer['error_type'] === 'epoch_superseded') {
            $answer['refused'] = true;
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('crit-epoch-superseded', $urlKey, '', ['uuid' => substr((string) $uuid, 0, 8),
                    'via' => 'generate', 'code' => $code, 'epoch_min' => $answer['epoch_min']]);
            }
            return $answer;
        }

        $reused = in_array($answer['served'], ['debounced', 'unchanged', 'converged'], true);
        // A timeout is a generation under way: the service decides a refusal before it renders.
        // It is owed a land (a land removes it; one that never lands counts toward the park) and
        // it counts against the page's cap.
        if (($code === 0 && $isTimeout) || ($code >= 200 && $code < 300 && !$reused)
            || ($code === 429 && $answer['error_type'] === 'render_pending')) {
            wpc_gen_pending_add($urlKey, $uuid);
            $answer['accepted'] = true;
        } elseif ($code >= 400 || $code === 0) {
            $answer['refused'] = true;
        }
        if ($reused && function_exists('wpc_crit_bypass_lift_reused')) {
            wpc_crit_bypass_lift_reused($urlKey, $answer['served'], $answer['crit_uuid']);
        }
        if ($code >= 200 && $code < 300) {
            wpc_gen_hold_forget_url($urlKey);
            if (function_exists('wpc_gen_apply_served_hold')) {
                wpc_gen_apply_served_hold($urlKey, $response, (string) $body);
            }
        }
        $holdScope = $code >= 400 ? wpc_gen_hold_learn($urlKey, $answer['error_type'], $retryAfter, (array) $json) : '';
        if (function_exists('wpc_cache_first_log')) {
            wpc_cache_first_log('gen-answer', $urlKey, '', ['uuid' => substr((string) $uuid, 0, 8),
                'served' => $answer['served'], 'crit_uuid' => substr($answer['crit_uuid'], 0, 8), 'code' => $code,
                'epoch' => $answer['epoch'], 'epoch_min' => $answer['epoch_min']]);
        }

        // UNREACHABLE backend (connect/DNS/SSL WP_Error — NOT a timeout) or a real 5xx backs off
        // now; the async timeout rides the status-poll / kick / repull recovery instead.
        if ($code >= 500 || (is_wp_error($response) && !$isTimeout)) {
            // A per-URL generation failure comes back as HTTP 500 with a JSON body naming
            // error_type (css_stub / fetch_blocked), and a saturated edge can answer with a
            // contract-less HTML 5xx. Neither is backend death. The SITE-WIDE breaker arms only
            // when the body affirms it: JSON that says arm_backoff truthy or carries no contract.
            $armBackoff = true;
            if (!is_wp_error($response)) {
                if ($json === null) {
                    $armBackoff = false;
                } elseif (array_key_exists('arm_backoff', $json)) {
                    $armBackoff = !empty($json['arm_backoff']);
                } elseif (in_array($answer['error_type'], ['css_stub', 'fetch_blocked', 'server_busy'], true)) {
                    $armBackoff = false;
                }
            }
            if ($armBackoff && function_exists('wpc_gen_note_failure')) {
                wpc_gen_note_failure('dispatch-' . ($code ?: 'wperr'));
            } elseif (!$armBackoff && function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('dispatch-noarm', $urlKey, '', ['code' => $code,
                    'type' => $json !== null ? substr($answer['error_type'], 0, 20) : 'non-json']);
            }
        }
        // REFUSAL CONTRACTS. Every refusal body carries error_type / retryable / arm_backoff /
        // retry_after, and how far it reaches (hold_scope, wpc_gen_hold_learn above):
        //   retryable:false — this page is not re-dispatched; its hold still ends when the
        //     service said.
        //   fleet_queued (429, retry_after 45) — do NOT re-dispatch; re-check the pointer (the
        //     collect lane) after Retry-After.
        //   anything else retryable — this key re-dispatches itself after retry_after (bounded
        //     60..3600, 500 → 300; demand_deferred and refusal_storm up to 2 days), and never
        //     before a hold on it ends.
        $unretryable = ($json !== null && array_key_exists('retryable', $json) && !$json['retryable']) || $holdScope === 'version';
        if (!$unretryable && ($code >= 500 || $code === 429 || (is_wp_error($response) && !$isTimeout))
            && $urlKey !== '' && function_exists('wpc_pl_sched') && !wp_next_scheduled('wpc_crit_redispatch', [$urlKey])) {
            if ($answer['error_type'] === 'fleet_queued') {
                // queued, not refused: the artifact will land on its own — poll, never re-POST
                if (!wp_next_scheduled('wpc_crit_collect', [$urlKey, 9])) {
                    wpc_pl_sched(time() + min(600, max(45, $retryAfter ?: 45)), 'wpc_crit_collect', [$urlKey, 9]);
                    wpc_spawn_cron();
                }
            } else {
                $ceiling = ($answer['error_type'] === 'demand_deferred' || $answer['error_type'] === 'refusal_storm') ? 2 * DAY_IN_SECONDS : 3600;
                $redispatchAt = time() + min($ceiling, max(60, $retryAfter ?: 300));
                $heldUntil = wpc_gen_service_hold_until($urlKey, true);
                if ($heldUntil >= $redispatchAt && $heldUntil < PHP_INT_MAX) {
                    $redispatchAt = $heldUntil + 1;
                }
                wpc_pl_sched($redispatchAt, 'wpc_crit_redispatch', [$urlKey]);
                wpc_spawn_cron();
            }
            if ($answer['error_type'] !== '' && function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('dispatch-refusal', $urlKey, '', ['code' => $code, 'type' => substr($answer['error_type'], 0, 32), 'ra' => $retryAfter]);
            }
        }
        // The page's retry is whatever the scheduler holds: the one just scheduled, or one
        // scheduled before this answer (the scheduler refuses a duplicate, so that one runs).
        if ($answer['refused'] && $urlKey !== '' && !$unretryable && function_exists('wp_next_scheduled')) {
            $answer['retry_at'] = (int) (wp_next_scheduled('wpc_crit_redispatch', [$urlKey]) ?: wp_next_scheduled('wpc_crit_collect', [$urlKey, 9]));
        }
        return $answer;
    }
}


if (!function_exists('wpc_crit_self_arm_watchdog')) {
    /*
     * THE INIT WATCHDOG: ONE JOB. Collect a generation this site dispatched that never landed: a
     * page (the homepage included) whose dispatch is younger than 6 h (uuid.txt) and that has no
     * servable crit (none, stale-marked, or refused by its bypass window). Every other ask belongs
     * to its owner: a visit kicks from the render or the arm sentinel's beacon, the warm lanes and
     * an update ask for the homepage through wpc_warm_home_dispatch_queue() or the update resync,
     * and a dispatch arms its own collector.
     *
     * Where it runs: a front-end or admin page view, at most once per 10 minutes per site (a file
     * stamp in critical/.kicklocks/, beside the kick admission counter). Never on admin-ajax, REST
     * or cron requests (the site's own background lanes and the kick receiver itself), never
     * during the update window. It skips a page whose kicks are refused anyway: a dead-marked key,
     * and a page whose last dispatch the door refused for want of a saved copy, until a render
     * saves the page again (staging, 2026-09-26/27: such a page was re-kicked every 2-4 minutes,
     * each kick refused no-page, each backstop repull holding the mutex a real page then missed).
     * Receipts: `watchdog-skip {why: throttled|window|dead|no-page}` (once per page and reason per
     * hour; throttled and window are site-wide), `watchdog-arm` for the homepage's kick, and
     * `watchdog-rescue` when a land is owed to this lane alone (wpc_watchdog_rescue_note).
     */

    /** The watchdog's 10-minute stamp, beside the kick admission counter. '' when there is none. */
    function wpc_watchdog_stamp_file()
    {
        if (!defined('WPS_IC_CRITICAL')) {
            return '';
        }
        $dir = rtrim(WPS_IC_CRITICAL, '/') . '/.kicklocks/';
        if (!is_dir($dir)) {
            @mkdir($dir, 0777, true);
        }
        return is_dir($dir) ? $dir . 'watchdog' : '';
    }

    /** `watchdog-skip {why}`, once per page ('' = the site) and reason per hour. */
    function wpc_watchdog_skip_note($urlKey, $why)
    {
        if (!function_exists('wpc_cache_first_log')) {
            return;
        }
        $fields = ['why' => (string) $why];
        if (function_exists('wpc_belt_rx_admit')) {
            $sampleName = 'watchdog-skip-' . $why;
            $gate = wpc_belt_rx_admit([$sampleName], (string) $urlKey, (string) $urlKey === '' ? '/wpc-watchdog' : '');
            if (!in_array($sampleName, $gate['admit'], true)) {
                return;
            }
            if (!empty($gate['sampled'])) {
                $fields['sampled'] = 1;
            }
        }
        wpc_cache_first_log('watchdog-skip', (string) $urlKey, '', $fields);
    }

    /** Whether this request is one the watchdog never runs on: admin-ajax, REST or cron. */
    function wpc_watchdog_request_excluded()
    {
        if ((function_exists('wp_doing_ajax') && wp_doing_ajax()) || (defined('DOING_AJAX') && DOING_AJAX)) {
            return true;
        }
        if ((function_exists('wp_doing_cron') && wp_doing_cron()) || (defined('DOING_CRON') && DOING_CRON)) {
            return true;
        }
        // REST_REQUEST is defined at parse_request, after init: read the request itself.
        if (defined('REST_REQUEST') && REST_REQUEST) {
            return true;
        }
        $uri = isset($_SERVER['REQUEST_URI']) ? (string) $_SERVER['REQUEST_URI'] : '';
        $restPrefix = function_exists('rest_get_url_prefix') ? '/' . trim((string) rest_get_url_prefix(), '/') . '/' : '/wp-json/';
        return strpos($uri, $restPrefix) !== false || isset($_GET['rest_route']);
    }

    /**
     * Whether the watchdog may kick $urlKey (folder $dir): a dispatch younger than 6 h and no
     * servable crit. A skip that carries a receipt comes back as its reason ('dead', 'no-page');
     * a page that is not a candidate, or that another lane is already collecting, is false.
     */
    function wpc_watchdog_candidate($urlKey, $dir)
    {
        if ((time() - (int) @filemtime($dir . 'uuid.txt')) > 6 * 3600) {
            return false;
        }
        $servable = @filesize($dir . 'critical_desktop.css') > 5 && !@is_file($dir . 'stale.txt')
            && !(apply_filters('wpc_kick_gen_on_unservable', true)
                && function_exists('wpc_crit_bypass_active') && wpc_crit_bypass_active($urlKey));
        if ($servable) {
            return false;
        }
        if (function_exists('wpc_pipeline_key_junk') && wpc_pipeline_key_junk($urlKey)) {
            return false;
        }
        if (get_transient('wpc_kick_fire_' . md5($urlKey)) || get_transient('wpc_collect_' . md5($urlKey))
            || get_transient('criticalRunning' . $urlKey) || get_transient('wpc_repull_kick_' . md5($urlKey))) {
            return false;
        }
        if (function_exists('wpc_kick_is_dead') && wpc_kick_is_dead($urlKey)) {
            return 'dead';
        }
        if (function_exists('wpc_saved_page_missing') && wpc_saved_page_missing($urlKey)) {
            return 'no-page';
        }
        return true;
    }

    /** Kick $urlKey for collection; the kick claims the land when nothing else asked in 120 s. */
    function wpc_watchdog_kick($urlKey)
    {
        if (!function_exists('wpc_repull_kick_now')) {
            return false;
        }
        $askedRecently = function_exists('wpc_kick_recent') && (wpc_kick_recent($urlKey, 120, 'fire') || wpc_kick_recent($urlKey, 120));
        if (!wpc_repull_kick_now($urlKey, false, 'watchdog')) {
            return false;
        }
        $claim = function_exists('wpc_watchdog_claim_file') ? wpc_watchdog_claim_file($urlKey) : '';
        if ($claim !== '') {
            if ($askedRecently) {
                @unlink($claim);
            } else {
                @touch($claim);
            }
        }
        return true;
    }

    function wpc_crit_self_arm_watchdog()
    {
        try {
            if (!apply_filters('wpc_crit_self_arm', true) || !function_exists('get_option')) {
                return;
            }
            if (wpc_watchdog_request_excluded()) {
                return;
            }
            if (!is_admin() && function_exists('wpc_pipeline_admission_ok') && !wpc_pipeline_admission_ok()) {
                return; // query-string URLs never self-arm the pipeline
            }
            $set = get_option(WPS_IC_SETTINGS);
            if (!is_array($set) || empty($set['critical']['css']) || $set['critical']['css'] != '1') {
                return;
            }
            $opt = get_option(WPS_IC_OPTIONS);
            if (!is_array($opt) || empty($opt['api_key'])) {
                return;
            }
            if (!class_exists('wps_ic_url_key') || !defined('WPS_IC_CRITICAL')) {
                return;
            }
            if (function_exists('wpc_update_window_active') && wpc_update_window_active()) {
                wpc_watchdog_skip_note('', 'window');
                return;
            }
            $stamp = wpc_watchdog_stamp_file();
            if ($stamp === '') {
                return;
            }
            if (@is_file($stamp) && (time() - (int) @filemtime($stamp)) < 600) {
                wpc_watchdog_skip_note('', 'throttled');
                return;
            }
            @touch($stamp);
            $k = ltrim((string) (new wps_ic_url_key())->setup(home_url('/')), '/');
            if ($k === '') {
                return;
            }
            // Interior pages, at most three kicks or sweeps per run; the homepage below.
            $crit_root = rtrim(WPS_IC_CRITICAL, '/') . '/';
            $swept_or_kicked = 0;
            foreach (['*/uuid.txt', '*/*/uuid.txt', '*/*/*/uuid.txt'] as $uuid_glob) {
                foreach ((array) @glob($crit_root . $uuid_glob, GLOB_NOSORT) as $uuid_file) {
                    if ($swept_or_kicked >= 3) {
                        break 2;
                    }
                    $page_dir = dirname($uuid_file) . '/';
                    $page_key = trim(substr($page_dir, strlen($crit_root)), '/');
                    if ($page_key === '' || $page_key === $k) {
                        continue; // homepage rides the dedicated lane below
                    }
                    // A SEPARATE JOB that only shares this loop, kept as it was: the contamination
                    // sweep. AUTO-QUARANTINE (out-of-the-box recovery): land_uuid WITHOUT
                    // dispatch_ts = landed-but-never-dispatched = storm-borrowed foreign crit. Wipe
                    // the dir; the sentinel/kick regenerate it legitimately. Pre-.320 dirs have
                    // NEITHER stamp and are untouched.
                    // manifest.held_gen belt (v7.10.697): a manifest flip is a legitimate land
                    // whether or not a dispatch stamp survives — never quarantine that dir.
                    if (@is_readable($page_dir . 'land_uuid.txt') && !@is_readable($page_dir . 'dispatch_ts.txt')
                        && !@is_readable($page_dir . 'manifest.held_gen')) {
                        foreach ((array) @glob($page_dir . '*') as $contaminated_file) {
                            @unlink($contaminated_file);
                        }
                        if (function_exists('wpc_cache_first_log')) {
                            wpc_cache_first_log('contamination-swept', $page_key, '', []);
                        }
                        $swept_or_kicked++;
                        continue;
                    }
                    $candidate = wpc_watchdog_candidate($page_key, $page_dir);
                    if (is_string($candidate)) {
                        wpc_watchdog_skip_note($page_key, $candidate);
                        continue;
                    }
                    if ($candidate !== true) {
                        continue;
                    }
                    $swept_or_kicked++;
                    wpc_watchdog_kick($page_key);
                }
            }
            $candidate = wpc_watchdog_candidate($k, rtrim(WPS_IC_CRITICAL, '/') . '/' . $k . '/');
            if (is_string($candidate)) {
                wpc_watchdog_skip_note($k, $candidate);
                return;
            }
            if ($candidate === true && wpc_watchdog_kick($k) && function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('watchdog-arm', $k, '', []);
            }
        } catch (\Throwable $e) {
        }
    }
    add_action('init', 'wpc_crit_self_arm_watchdog', 99);
}


// ─── Crit ≤60s land contract (v7.10.320): dispatch-owned collector + publish webhook ───
if (!function_exists('wpc_crit_collect_now')) {
    /**
     * ZERO-HELD-WORKER collector (v7.10.324, James's contention law): ONE probe —
     * HEAD by uuid / pointer fallback, land through the validated save path — and exit.
     * No sleep, no loop, no held FPM child. The cadence comes from pre-scheduled probe
     * events, fired by whatever PHP runs next (spawn-nudge, webhook, sentinel beacon,
     * admin heartbeat). $budget > 0 ⇒ on a miss, one follow-up probe is scheduled.
     */
    function wpc_crit_collect_now($urlKey, $budget = 0, $interval = 12)
    {
        try {
            if (empty($urlKey) || !defined('WPS_IC_CRITICAL') || !class_exists('wps_criticalCss')) {
                return false;
            }
            if (function_exists('wpc_pipeline_key_junk') && wpc_pipeline_key_junk($urlKey)) {
                return false;
            }
            if (function_exists('wpc_under_pressure') && wpc_under_pressure()) {
                return false; // scheduled probes keep trying; never add load to a hot box
            }
            $lk = 'wpc_collect_' . md5((string) $urlKey);
            if (get_transient($lk)) {
                return false; // collapse simultaneous probes
            }
            set_transient($lk, 1, 8);
            $dir = rtrim(WPS_IC_CRITICAL, '/') . '/' . $urlKey . '/';
            // A dispatch newer than the land (uuid.txt ≠ land_uuid.txt) must overwrite —
            // organic regens and serve-stale copies are otherwise stranded by "already landed".
            $du = trim((string) @file_get_contents($dir . 'uuid.txt'));
            $lu = trim((string) @file_get_contents($dir . 'land_uuid.txt'));
            $force = ($du !== '' && $du !== $lu);
            // stale + same-uuid is decided INSIDE pullDerivedArtifacts via the pointer
            // (a fresh publish collects even when the dispatch timeout ate the ack).
            $landed = false;
            try {
                $cc = new wps_criticalCss();
                $landed = $cc->pullDerivedArtifacts($urlKey, '', $force);
            } catch (\Throwable $e) {
            }
            delete_transient($lk);
            if ($landed) {
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('collector-landed', (string) $urlKey, '', ['forced' => $force ? 1 : 0]);
                }
                return true;
            }
            if ((int) $budget > 0 && function_exists('wp_next_scheduled')
                && !wp_next_scheduled('wpc_crit_collect', [$urlKey, 9])) {
                wpc_pl_sched(time() + max(8, (int) $interval), 'wpc_crit_collect', [$urlKey, 9]);
            }
            // NO spawn_cron on a miss — a probe miss re-spawning cron chains cron passes
            // continuously across many armed URLs (staging TTFB storm receipt); the arm's
            // single nudge + organic PHP + the webhook carry the cadence.
            return false;
        } catch (\Throwable $e) {
            return false;
        }
    }
}

if (!function_exists('wpc_crit_collector_arm')) {
    /**
     * B2 as probe BURSTS (law 9 + zero-held-workers): dispatch mints its own pickup
     * appointments — staggered single events, each a sub-second probe — plus the repull
     * backstop and a spawn nudge. No shutdown worker, no sleeping FPM child, ever.
     */
    function wpc_crit_collector_arm($urlKey)
    {
        try {
            if (empty($urlKey)) {
                return;
            }
            if (get_transient('wpc_collarm_' . md5((string) $urlKey))) {
                return;
            }
            set_transient('wpc_collarm_' . md5((string) $urlKey), 1, 60);
            foreach ([12 => 1, 30 => 2, 60 => 3, 120 => 4] as $delay_seconds => $attempt) {
                if (function_exists('wp_next_scheduled') && !wp_next_scheduled('wpc_crit_collect', [$urlKey, $attempt])) {
                    wpc_pl_sched(time() + $delay_seconds, 'wpc_crit_collect', [$urlKey, $attempt]);
                }
            }
            if (function_exists('wp_next_scheduled') && !wp_next_scheduled('wpc_lcp_repull', [$urlKey, 1])) {
                wpc_pl_sched(time() + 90, 'wpc_lcp_repull', [$urlKey, 1]);
            }
            if (function_exists('spawn_cron')) {
                wpc_spawn_cron();
            }
        } catch (\Throwable $e) {
        }
    }
    add_action('wpc_crit_collect', function ($urlKey, $n = 1) {
        wpc_crit_collect_now((string) $urlKey, ((int) $n === 4 || (int) $n === 9) ? 1 : 0);
    }, 10, 2);
    // B5: a failed dispatch re-dispatches itself (retry_after-scheduled by the dispatcher).
    add_action('wpc_crit_redispatch', function ($urlKey, $sync = 0) {
        try {
            // v7.21.167 — the class loads lazily at frontend call sites, so in an admin-ajax
            // context (Refresh's .166 in-process dispatch) it was absent and this bailed with
            // NO receipt — the homepage kick vanished silently while /video (frontend kicks)
            // dispatched fine. Self-include like every other call site; a bail leaves a row.
            if (!class_exists('wps_criticalCss') && defined('WPS_IC_DIR')) {
                @include_once WPS_IC_DIR . 'addons/criticalCss/criticalCss-v2.php';
            }
            if (empty($urlKey) || !class_exists('wps_criticalCss') || !class_exists('wps_ic_url_key')) {
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('redispatch-bail', (string) $urlKey, '', ['cls' => class_exists('wps_criticalCss') ? 1 : 0]);
                }
                return;
            }
            $u = method_exists('wps_ic_url_key', 'getUrlFromKey')
                ? (string) wps_ic_url_key::getUrlFromKey((string) $urlKey) : '';
            if ($u === '' && function_exists('home_url')
                && ltrim((string) (new wps_ic_url_key())->setup(home_url('/')), '/') === ltrim((string) $urlKey, '/')) {
                $u = home_url('/');
            }
            if ($u === '') {
                return;
            }
            $c = new wps_criticalCss($u);
            if (method_exists($c, 'generateCriticalAjax')) {
                $c->generateCriticalAjax((bool) $sync); // sync=1 = operator Pull Latest (bust tpl cache)
            }
        } catch (\Throwable $e) {
        }
    }, 10, 2);
}

if (!function_exists('wpc_near_expiry_regen')) {
    /** §6 near_expiry (>13d of 14d retention): arm a fresh gen instead of relying on
     *  about-to-expire shelf URLs. FAIL-OPEN: with no served crit on disk the caller's
     *  pull proceeds untouched (an expiring artifact beats none). Herd-gated: the expiry
     *  horizon is fleet-synchronized by construction — long per-key transient, global
     *  backoff + pressure yields, jittered dispatch. */
    function wpc_near_expiry_regen($urlKey)
    {
        try {
            if ((string) $urlKey === '' || !defined('WPS_IC_CRITICAL')
                || !apply_filters('wpc_near_expiry_regen', true)) {
                return false;
            }
            if (function_exists('wpc_pipeline_key_junk') && wpc_pipeline_key_junk($urlKey)) {
                return false;
            }
            $dir = rtrim(WPS_IC_CRITICAL, '/') . '/' . $urlKey . '/';
            if (!((int) @filesize($dir . 'critical_desktop.css') > 64)) {
                return false;
            }
            if (get_transient('wpc_nexp_' . md5((string) $urlKey))) {
                return false;
            }
            if (function_exists('wpc_gen_backoff_active') && wpc_gen_backoff_active()) {
                return false;
            }
            // While the service holds the site, the redispatch would be refused and the 12 h
            // suppression below would burn the one regeneration this artifact gets.
            if (function_exists('wpc_gen_service_hold_active') && wpc_gen_service_hold_active($urlKey)) {
                return false;
            }
            if (function_exists('wpc_under_pressure') && wpc_under_pressure()) {
                return false;
            }
            // Schedule FIRST, suppress only on a committed dispatch — the pipeline
            // ceiling can eat the schedule, and a burned shot with a 2-day suppression
            // would outlive the ≤1-day retention runway. 12h suppression = a second
            // attempt still fits inside the window.
            $scheduled = false;
            if (function_exists('wpc_pl_sched') && function_exists('wp_next_scheduled')) {
                $scheduled = wp_next_scheduled('wpc_crit_redispatch', [(string) $urlKey]) !== false
                    || wpc_pl_sched(time() + rand(30, 900), 'wpc_crit_redispatch', [(string) $urlKey]) !== false;
            }
            if (!$scheduled) {
                return false;
            }
            set_transient('wpc_nexp_' . md5((string) $urlKey), 1, 12 * HOUR_IN_SECONDS);
            wpc_crit_meta_write($dir . 'stale.txt', (string) time());
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('near-expiry-regen', (string) $urlKey, '', []);
            }
            return true;
        } catch (\Throwable $e) {
            return false;
        }
    }
}

// ─── §10 TTFB actuation — the slow-ttfb lever (v7.10.357) ───
// The service MEASURES a recoverable origin-TTFB cap (ceiling.caps[factor:ttfb,scope:origin].
// fixable_ms); the plugin ACTUATES by arming the zero-PHP static serve (Lane A), whose OWN
// self-test + auto-rollback lives in htaccess.class.php — so the rollback safety is local to
// the actuator (contract §10 v1.2.1). Never touches Lane B (cache.advanced / R9) or the manual
// toggle; a host it cannot serve on rolls back to PHP serve, unchanged, and backs off.
if (!function_exists('wpc_ttfb_read_ceiling_cap')) {
    /** Recoverable origin-TTFB think-time (ms) from a delay.json ceiling{}; 0 if none. */
    function wpc_ttfb_read_ceiling_cap($dir)
    {
        try {
            $f = rtrim((string) $dir, '/') . '/delay.json';
            if (!@is_readable($f)) {
                return 0;
            }
            $j = json_decode((string) @file_get_contents($f), true);
            if (!is_array($j) || empty($j['ceiling']) || !is_array($j['ceiling'])) {
                return 0;
            }
            $lists = [];
            foreach (['mobile', 'desktop'] as $device) {
                if (isset($j['ceiling'][$device]['caps']) && is_array($j['ceiling'][$device]['caps'])) {
                    $lists[] = $j['ceiling'][$device]['caps'];
                }
            }
            if (isset($j['ceiling']['caps']) && is_array($j['ceiling']['caps'])) {
                $lists[] = $j['ceiling']['caps'];
            }
            $best = 0;
            foreach ($lists as $caps) {
                foreach ($caps as $c) {
                    // caps[].basis (service 3.77.1/.81.0): ONLY actuate on measured origin
                    // think-time. 'coarse_upper_bound' (server_ms absent → ttfb−floor) over-
                    // claims; 'cpu_share_proxy' is the TBT cap, never TTFB. Skip a degenerate
                    // cross-device read (3.81.0) or an unmeasured leg — a slow origin can't tell
                    // which viewport asked (staging: 28s "measured" TTFB, real 260ms → bogus
                    // 45-point cap). Absent basis (pre-3.77 gens) is NOT trusted → no actuation.
                    if (is_array($c) && (string) ($c['factor'] ?? '') === 'ttfb' && (string) ($c['scope'] ?? '') === 'origin'
                        && (string) ($c['basis'] ?? '') === 'measured_server_ms'
                        && empty($c['ttfb_read_degenerate']) && empty($c['ttfb_unmeasured'])
                        && isset($c['fixable_ms']) && is_numeric($c['fixable_ms']) && (int) $c['fixable_ms'] > $best) {
                        $best = (int) $c['fixable_ms'];
                    }
                }
            }
            return $best;
        } catch (\Throwable $e) {
            return 0;
        }
    }

    /** Exponential-capped retry window after a host can't serve statically (mirrors the
     *  gen-backoff): base 1h, cap 7d — never re-probe a non-serving host every land. */
    function wpc_ttfb_ss_backoff_bump()
    {
        $n = max(0, (int) get_option('wpc_ttfb_ss_fails'));
        $base = (int) apply_filters('wpc_ttfb_ss_backoff_base', 3600);
        $cap  = (int) apply_filters('wpc_ttfb_ss_backoff_cap', 7 * DAY_IN_SECONDS);
        update_option('wpc_ttfb_ss_fails', $n + 1, false);
        update_option('wpc_ttfb_ss_next', time() + min($cap, $base * (1 << min($n, 12))), false);
    }
    function wpc_ttfb_ss_backoff_clear()
    {
        delete_option('wpc_ttfb_ss_fails');
        delete_option('wpc_ttfb_ss_next');
    }

    function wpc_ttfb_maybe_arm_static_serve($urlKey)
    {
        try {
            if (!apply_filters('wpc_ttfb_static_serve_auto', true) || get_option('wpc_ttfb_ss_optout')) {
                return false;
            }
            // Only evaluate in an HTTP context (loopback cron / admin-ajax kick): a WP-CLI
            // system-cron run has no SERVER_SOFTWARE, so isApache() would false-negative and
            // POISON the backoff on a genuinely Apache host. Skip cleanly — no state touched
            // — and let the next HTTP-context kick decide.
            if (empty($_SERVER['SERVER_SOFTWARE'])) {
                return false;
            }
            // Already serving statically (auto OR user OR live block) → nothing to do.
            if (get_option('wpc_static_serve_active') == 1 || get_option('wpc_ttfb_ss_auto') === '1') {
                return false;
            }
            $set = get_option(WPS_IC_SETTINGS);
            if (is_array($set) && !empty($set['static-serve']) && $set['static-serve'] == '1') {
                return false; // user already armed it manually
            }
            // Nothing to statically serve unless the plugin's own HTML cache is on.
            if (function_exists('wpc_cache_first_enabled') && !wpc_cache_first_enabled()) {
                return false;
            }
            // Evaluate at most hourly; honor the failure backoff; yield under pressure.
            if (get_transient('wpc_ttfb_ss_eval') || time() < (int) get_option('wpc_ttfb_ss_next')) {
                return false;
            }
            if (function_exists('wpc_under_pressure') && wpc_under_pressure()) {
                return false;
            }
            // Never stomp a competing full-page cache (WP Rocket / LiteSpeed / foreign drop-in).
            if (function_exists('wpc_detect_foreign_page_cache') && wpc_detect_foreign_page_cache() !== false) {
                return false;
            }
            set_transient('wpc_ttfb_ss_eval', 1, HOUR_IN_SECONDS);

            $dir = defined('WPS_IC_CRITICAL') ? rtrim(WPS_IC_CRITICAL, '/') . '/' . $urlKey . '/' : '';
            $fixable = $dir !== '' ? wpc_ttfb_read_ceiling_cap($dir) : 0;
            $min = (int) apply_filters('wpc_ttfb_static_serve_min_ms', 300);
            if ($fixable < $min) {
                return false; // no meaningful recoverable TTFB — leave the host alone
            }

            if (!class_exists('wps_ic_htaccess') && defined('WPS_IC_DIR')) {
                @include_once WPS_IC_DIR . 'classes/htaccess.class.php';
            }
            if (!class_exists('wps_ic_htaccess')) {
                return false;
            }
            $h = new wps_ic_htaccess();
            // The constructor only detects Apache under is_admin(); this lane is a background
            // kick/cron worker, so force detection now (needs SERVER_SOFTWARE — absent only
            // under WP-CLI, where there is no request to serve and skipping is correct).
            if (method_exists($h, 'isApache')) {
                $h->isApache();
            }
            // Arm the serve-decision flag BEFORE apply so the enable's warm writes real mirror
            // files (the wpc_static_serve filter below honors it); rolled back on any failure.
            update_option('wpc_ttfb_ss_auto', '1', false);
            $res = method_exists($h, 'applyStaticServe') ? $h->applyStaticServe() : ['ok' => false, 'reason' => 'no-method'];
            if (!empty($res['ok'])) {
                wpc_ttfb_ss_backoff_clear();
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('ttfb-static-serve-armed', (string) $urlKey, '', ['fixable_ms' => $fixable]);
                }
                if (function_exists('wpc_auto_journal')) {
                    wpc_auto_journal('ttfb-static-serve', ['armed' => 1, 'fixable_ms' => $fixable]);
                }
                return true;
            }
            // not-apache / not-writeable / self-test-failed (already rolled the htaccess block
            // back to PHP serve, nothing broken) → clear our flag + back off hard.
            delete_option('wpc_ttfb_ss_auto');
            wpc_ttfb_ss_backoff_bump();
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('ttfb-static-serve-unavailable', (string) $urlKey, '',
                    ['reason' => (string) ($res['reason'] ?? '?'), 'fixable_ms' => $fixable]);
            }
            return false;
        } catch (\Throwable $e) {
            return false;
        }
    }

    if (function_exists('add_filter')) {
        // Serve-decision: honor the auto-armed TTFB static serve so cacheHtml writes the
        // mirror files. The constant / user setting still win first (the core filter runs
        // and returns early when either is set); this only ORs in the auto flag.
        add_filter('wpc_static_serve', function ($v) {
            return $v ? $v : (get_option('wpc_ttfb_ss_auto') === '1');
        });
    }
}

if (!function_exists('wpc_crit_kick_collect')) {
    /** B3: the kick lane COLLECTS before it generates — the shelf outranks the brakes. */
    function wpc_crit_kick_collect($urlKey)
    {
        try {
            if (empty($urlKey) || !class_exists('wps_criticalCss') || !defined('WPS_IC_CRITICAL')) {
                return false;
            }
            // stale + same-uuid is decided inside pullDerivedArtifacts via the pointer —
            // it refuses only when nothing newer than the landed artifact is published.
            $cc = new wps_criticalCss();
            if ($cc->pullDerivedArtifacts((string) $urlKey)) {
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('kick-collect-landed', (string) $urlKey, '', []);
                }
                return true;
            }
        } catch (\Throwable $e) {
        }
        return false;
    }
}

if (!function_exists('wpc_crit_purge_redispatch')) {
    /** B1: the crit purge itself owns the homepage regen — detached, ungated on cache mode. */
    function wpc_crit_purge_redispatch($sync = false)
    {
        try {
            if (!class_exists('wps_criticalCss') || !class_exists('wps_ic_url_key') || !function_exists('home_url')) {
                return;
            }
            $k = ltrim((string) (new wps_ic_url_key())->setup(home_url('/')), '/');
            if ($k === '') {
                return;
            }
            // With critical CSS off a purge regenerates nothing: no cron backstop, no collector,
            // no forced dispatch (Remove Critical on a crit-off test site sent two and landed crit).
            if (function_exists('wpc_crit_generation_off') && wpc_crit_generation_off($k)) {
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('purge-redispatch', $k, '', ['dispatch' => 0, 'why' => 'crit-off']);
                }
                return;
            }
            // Operator Pull Latest passes $sync=true → the cron backstop carries sync=1 so a
            // fresh (tpl-cache-busting) gen happens even if the detach below dies. The NON-sync
            // path keeps the 1-arg [$k] shape so it still dedups with near_expiry / B5 redispatch
            // (which schedule [$urlKey]); a sync resync uses [$k,1] and is INTENDED to fire even
            // if a non-sync gen is pending (only sync busts the cache).
            $redispatch_args = $sync ? [$k, 1] : [$k];
            if (function_exists('wp_next_scheduled') && !wp_next_scheduled('wpc_crit_redispatch', $redispatch_args)) {
                wpc_pl_sched(time() + 20, 'wpc_crit_redispatch', $redispatch_args); // backstop if the detach dies
            }
            if (function_exists('spawn_cron')) {
                wpc_spawn_cron();
            }
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('purge-redispatch', $k, '', []);
            }
            // Probe bursts own the pickup (zero-held-workers) — armed regardless of SAPI.
            if (function_exists('wpc_crit_collector_arm')) {
                wpc_crit_collector_arm($k);
            }
            if (!function_exists('fastcgi_finish_request') && !function_exists('litespeed_finish_request')) {
                return;
            }
            register_shutdown_function(function () use ($k, $sync) {
                try {
                    if ((function_exists('fastcgi_finish_request') || function_exists('litespeed_finish_request'))) {
                        wpc_finish_request();
                    } elseif (function_exists('litespeed_finish_request')) {
                        @litespeed_finish_request();
                    }
                    // Bounded ≤ ~15s total (8s dispatch + one probe) — ONE ordinary-request-
                    // sized burst per human purge click, never a sleeping worker (James's
                    // contention law; the probe bursts + webhook carry the tail).
                    if (function_exists('set_time_limit')) { @set_time_limit(30); }
                    if (function_exists('ignore_user_abort')) { @ignore_user_abort(true); }
                    add_filter('wpc_gen_dispatch_timeout', function () use ($sync) { return $sync ? 20 : 8; });
                    $_GET['forceCritical'] = '1'; // human-initiated: the kick-path guards stand down
                    $c = new wps_criticalCss(home_url('/'));
                    if (method_exists($c, 'generateCriticalAjax')) {
                        wpc_gen_as_human('purge-redispatch', function () use ($c, $sync) {
                            $c->generateCriticalAjax((bool) $sync); // Pull Latest → fresh, tpl-cache-busting gen
                        });
                    }
                    if (function_exists('wpc_crit_collect_now')) {
                        wpc_crit_collect_now($k, 1);
                    }
                } catch (\Throwable $e) {
                }
            });
        } catch (\Throwable $e) {
        }
    }
}

if (!function_exists('wpc_delay_inline_fresher')) {
    /**
     * Delay-inline landing gate (v7.10.381, service-flagged): land when the on-disk delay.json is
     * ABSENT, or when the incoming measured manifest is NEWER by generated_at (the service amends
     * in place under a stable uuid, so a stale first-land must not pin us forever). Forward-only —
     * an incoming with no/older/unparseable stamp keeps the on-disk copy, so it can never regress.
     * The measured-shape gate still applies separately, so a non-measured body never lands here.
     */
    function wpc_delay_inline_fresher($file, $incoming)
    {
        if (!@is_readable($file)) { return true; }
        if (!is_array($incoming) || empty($incoming['generated_at'])) { return false; }
        $in = @strtotime((string) $incoming['generated_at']);
        if (!$in) { return false; }
        $od   = json_decode((string) @file_get_contents($file), true);
        $odGA = (is_array($od) && !empty($od['generated_at'])) ? @strtotime((string) $od['generated_at']) : 0;
        return $in > (int) $odGA;
    }
}

if (!function_exists('wpc_lcp_first_auth')) {
    /** First lcp_preload's url_is_authoritative: true (or absent => true) emits a BARE hero
     *  preload; false = responsive skip; null = no preload entry. Decides the bare<->skip flip. */
    function wpc_lcp_first_auth($lcpArr)
    {
        if (!is_array($lcpArr) || empty($lcpArr['hints']['lcp_preload'][0]) || !is_array($lcpArr['hints']['lcp_preload'][0])) {
            return null;
        }
        $e = $lcpArr['hints']['lcp_preload'][0];
        return array_key_exists('url_is_authoritative', $e) ? (bool) $e['url_is_authoritative'] : true;
    }

    /** v7.10.383 — synchronous CF edge purge for the bare->skip lcp flip ONLY. The served page
     *  still carries the old bare preload; the batched CF purge (purgeEdgeHtmlUrls default queue)
     *  pressure-defers on a pinned box (queued becomes never), so evict this one URL inline, past
     *  the queue. Batched path untouched for everything else. Best-effort; never blocks. */
    function wpc_lcp_edge_flip_purge($url)
    {
        try {
            if ((string) $url === '' || !class_exists('wps_ic_cache') || !method_exists('wps_ic_cache', 'purgeEdgeHtmlUrls')) {
                return;
            }
            $clean = (string) strtok((string) $url, '?');
            if ($clean === '') { return; }
            $forms = array_values(array_filter([$clean, (substr($clean, -1) === '/') ? rtrim($clean, '/') : $clean . '/']));
            wps_ic_cache::purgeEdgeHtmlUrls($forms, true); // inline=true => synchronous, past the batch queue
            if (function_exists('wpc_cache_first_log')) { wpc_cache_first_log('cf-purge-flip-sync', '', $clean, []); }
        } catch (\Throwable $e) {
        }
    }
}

if (!function_exists('wpc_crit_webhook_rx')) {
    /**
     * The crit_published webhook receiver.
     * POST /wp-admin/admin-ajax.php?action=wpc_crit_published, and the body the service sends is
     * exactly {event:'crit_published', uuid, url, url_key, ts, sig, gen_dispatch_received_ts,
     * artifacts{mobile,desktop,combined}} (crit-push server.js:17147-17156) — no artifact bodies,
     * no rev. sig = HMAC-SHA256("uuid|url_key|ts", apikey); on this webhook the service puts it
     * in the body, on the consolidated callback in the headers, and this receiver accepts either
     * transport. url_key is the service's canonicalizeForKey form and is used for the signature
     * ONLY; our own key derivation stays wps_ic_url_key::setup.
     *
     * The webhook is a SIGNAL, not a data carrier: artifacts{} is advisory — the pull derives
     * every URL from the signed uuid through the validated save path, so a tampered body can
     * never point this site at foreign CSS. The callback that DOES carry delay.json and lcp.json
     * inline is the consolidated one, at wp-compress-core.php:3741.
     */
    function wpc_crit_webhook_rx()
    {
        try {
            if (!apply_filters('wpc_crit_webhook', true) || !defined('WPS_IC_CRITICAL') || !class_exists('wps_ic_url_key')) {
                status_header(200);
                echo 'off';
                exit;
            }
            // v3.82.0+ consolidated callback carries artifacts INLINE (delay.json ~29KB), so
            // the old 16KB cap truncated the body → json_decode failed → 403 → the plugin fell
            // back to polling. Read the full signed body up to a bounded cap (the sig is verified
            // before any of it is trusted; an unsigned POST just pays one bounded read, then 403).
            $raw  = (string) @file_get_contents('php://input', false, null, 0, (int) apply_filters('wpc_crit_webhook_max_body', 262144));
            $j    = json_decode($raw, true);
            $uuid = is_array($j) ? preg_replace('/[^A-Za-z0-9-]/', '', (string) ($j['uuid'] ?? '')) : '';
            $url  = is_array($j) ? (string) ($j['url'] ?? '') : '';
            $ukey = is_array($j) ? (string) ($j['url_key'] ?? '') : '';
            // Signature transport: X-WPC-Sig / X-WPC-Ts headers (service 3.83.0 consolidated
            // callback), falling back to body sig/ts (legacy crit_published). Same HMAC recipe
            // over uuid|url_key|ts either way — url_key/uuid always ride the body.
            $ts   = (string) (!empty($_SERVER['HTTP_X_WPC_TS']) ? $_SERVER['HTTP_X_WPC_TS'] : (is_array($j) ? ($j['ts'] ?? '') : ''));
            $sig  = strtolower((string) (!empty($_SERVER['HTTP_X_WPC_SIG']) ? $_SERVER['HTTP_X_WPC_SIG'] : (is_array($j) ? ($j['sig'] ?? '') : '')));
            $evt  = is_array($j) ? (string) ($j['event'] ?? '') : '';
            // Q2: 'prescriptions_updated' rides this receiver with the identical field
            // set + signature recipe; everything below the event check stays shared.
            $ok   = is_array($j) && in_array($evt, ['crit_published', 'prescriptions_updated'], true)
                && strlen($uuid) >= 8 && $url !== '' && strlen($url) <= 2048
                && $ukey !== '' && strlen($ukey) <= 1024
                && ctype_digit($ts) && (bool) preg_match('/^[a-f0-9]{64}$/', $sig);
            // ts is milliseconds in the contract — accept s or ms, 10min skew.
            $tsn = $ok ? (float) $ts : 0;
            if ($tsn > 20000000000) {
                $tsn = $tsn / 1000;
            }
            $ok = $ok && abs(time() - $tsn) <= 600;
            $opt = ($ok && function_exists('get_option') && defined('WPS_IC_OPTIONS')) ? get_option(WPS_IC_OPTIONS) : [];
            $key = is_array($opt) && !empty($opt['api_key']) ? (string) $opt['api_key'] : '';
            $ok  = $ok && $key !== '' && hash_equals(hash_hmac('sha256', $uuid . '|' . $ukey . '|' . $ts, $key), $sig);
            if ($ok) {
                $wh = strtolower((string) parse_url($url, PHP_URL_HOST));
                $oh = strtolower((string) parse_url(home_url('/'), PHP_URL_HOST));
                if (strpos($wh, 'www.') === 0) { $wh = substr($wh, 4); }
                if (strpos($oh, 'www.') === 0) { $oh = substr($oh, 4); }
                $ok = $wh !== '' && $wh === $oh;
            }
            if (!$ok) {
                status_header(403);
                echo 'x';
                exit;
            }
            if ($evt === 'prescriptions_updated') {
                // SIGNAL-ONLY (body URLs untrusted): schedule the pull; it re-derives
                // through the validated /v2/latest + prescriptions_url.txt path. Own
                // dedupe key — the crit event shares this uuid and must not eat it.
                if (get_transient('wpc_whkp_' . md5($uuid . '|' . $ts))) {
                    status_header(200);
                    echo 'dup';
                    exit;
                }
                set_transient('wpc_whkp_' . md5($uuid . '|' . $ts), 1, 600);
                $presc_key = ltrim((string) (new wps_ic_url_key())->setup((string) strtok($url, '?')), '/');
                if ($presc_key === '' || (function_exists('wpc_pipeline_key_junk') && wpc_pipeline_key_junk($presc_key))) {
                    status_header(200);
                    echo 'nokey';
                    exit;
                }
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('whk-presc-rx', $presc_key, (string) strtok($url, '?'), ['uuid' => substr($uuid, 0, 8)]);
                }
                // The webhook is the POSITIVE SIGNAL that prescriptions exist. Write the
                // want-marker (opens the /v2/latest prescriptions gate for ≤1h so the URL
                // meta lands even on sites that already hold every other artifact) AND, if
                // the URL is already on disk, a due-NOW marker so the next traffic kick
                // pulls immediately even with cron dead.
                $presc_dir = rtrim(WPS_IC_CRITICAL, '/') . '/' . $presc_key . '/';
                if (is_dir($presc_dir)) {
                    wpc_crit_meta_write($presc_dir . 'presc_want.txt', (string) time());
                    if (@is_readable($presc_dir . 'prescriptions_url.txt')) {
                        wpc_crit_meta_write($presc_dir . 'presc_due.txt', (string) time());
                    }
                }
                if (function_exists('wp_next_scheduled') && !wp_next_scheduled('wpc_presc_poll', [$presc_key])) {
                    wpc_pl_sched(time() + 1, 'wpc_presc_poll', [$presc_key]);
                }
                status_header(200);
                echo 'ok';
                if (function_exists('spawn_cron')) {
                    register_shutdown_function('spawn_cron');
                }
                exit;
            }
            // Dedupe per DELIVERY (uuid|ts), not per uuid — the service sends a SECOND signed
            // crit_published for the same uuid when a late observation reannounces it, with a
            // fresh ts and the same field list. That delivery carries no new body, but it does
            // mean a fresh pull is wanted, and keying on uuid alone would 'dup' it out. A retry
            // re-sends the same signed ts and is still deduped; the pull is idempotent anyway.
            if (get_transient('wpc_whk_' . md5($uuid . '|' . $ts))) {
                status_header(200);
                echo 'dup';
                exit;
            }
            set_transient('wpc_whk_' . md5($uuid . '|' . $ts), 1, 600);
            $wpc_klk = rtrim(WPS_IC_CRITICAL, '/') . '/.kicklocks/';
            if (!is_dir($wpc_klk)) { @mkdir($wpc_klk, 0777, true); }
            wpc_crit_meta_write($wpc_klk . 'whk_last.txt', (string) time());
            $k = ltrim((string) (new wps_ic_url_key())->setup((string) strtok($url, '?')), '/');
            if ($k === '' || (function_exists('wpc_pipeline_key_junk') && wpc_pipeline_key_junk($k))) {
                status_header(200);
                echo 'nokey';
                exit;
            }
            $dir = rtrim(WPS_IC_CRITICAL, '/') . '/' . $k . '/';
            if (!is_dir($dir) && function_exists('wp_mkdir_p')) { @wp_mkdir_p($dir); }
            wpc_crit_meta_write($dir . 'uuid.txt', $uuid);
            // crit_published carries exactly {event, uuid, url, url_key, ts, sig,
            // gen_dispatch_received_ts, artifacts{mobile,desktop,combined}} (crit-push
            // server.js:17147-17156). There are no inline artifact bodies on this webhook and
            // never were; the callback that does carry delay.json and lcp.json inline is the
            // consolidated one, handled in wp-compress-core.php:3741.
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('whk-rx', $k, (string) strtok($url, '?'), ['uuid' => substr($uuid, 0, 8)]);
            }
            // v7.21.173 — ACK-AFTER-SAVE (crit-team closed-loop spec, pairs with their .151
            // landing verifier): the old tail answered 'ok' BEFORE consuming, then leaned on
            // the SAPI detach or a +1s cron nudge — on a host without the detach, or
            // with wp-cron masked (beucomply masks unauthenticated admin-ajax AND cron),
            // delivered:true never became a land: reannounce e5517f28 acked 200, old 89KB
            // crit still serving 5+ minutes later. The ack now MEANS landed: pull + save +
            // purge run synchronously, then the response says {landed, uuid, rev} — their
            // verifier reads it, and a false carries the reason. The pull is two CDN blob
            // fetches (<2s typical); their side owns the webhook timeout and asked for this.
            if (function_exists('set_time_limit')) { @set_time_limit(60); }
            if (function_exists('ignore_user_abort')) { @ignore_user_abort(true); }
            $landed = false;
            // No rev rides crit_published: its body is the field list named above
            // (server.js:17147-17156), so the pull is asked for rev 0 and the ack echoes 0.
            // The wire rev reaches this site through wire.json, landed by the pull itself.
            if (class_exists('wps_criticalCss')) {
                $cc = new wps_criticalCss();
                $landed = (bool) $cc->pullDerivedArtifacts($k, $uuid, true, 0,
                    ['via' => 'webhook', 'epoch' => (is_array($j) && isset($j['epoch'])) ? $j['epoch'] : null]);
                if ($landed && function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('whk-landed', $k, '', ['uuid' => substr($uuid, 0, 8)]);
                }
            } else {
                // belt: no class in this context — keep the old cron nudge so the land
                // still has a path, and say so in the ack.
                if (function_exists('wp_next_scheduled') && !wp_next_scheduled('wpc_crit_collect', [$k])) {
                    wpc_pl_sched(time() + 1, 'wpc_crit_collect', [$k]);
                }
                if (function_exists('spawn_cron')) {
                    wpc_spawn_cron();
                }
            }
            status_header(200);
            header('Content-Type: application/json; charset=utf-8');
            echo wp_json_encode(['landed' => $landed, 'uuid' => (string) $uuid, 'rev' => 0,
                'reason' => $landed ? '' : (class_exists('wps_criticalCss') ? 'pull-refused' : 'no-class-cron-nudged')]);
            exit;
        } catch (\Throwable $e) {
            // fail OPEN: a webhook fault answers 200 and leaves the B2 backstop to land it
        }
        status_header(200);
        echo '';
        exit;
    }
    add_action('wp_ajax_wpc_crit_published', 'wpc_crit_webhook_rx');
    add_action('wp_ajax_nopriv_wpc_crit_published', 'wpc_crit_webhook_rx');
}


// v7.21.174 — PENDING-AWARE PULL (crit-team final spec: zero-touch on WAF'd sites).
// Inbound announces can die on a WAF'd origin and nothing plugin-side noticed until a
// human Refresh or the slow reconcile. Site->service OUTBOUND is never WAF-blocked, so
// after any dispatch the rendered URL polls the shelf until landed: every frontend
// render's shutdown, at most once per 30s per key, only while a dispatch is pending
// (dispatch_ts newer than the land, and younger than the 15-minute window). Rides
// RENDER shutdowns and never cron — masked-cron hosts are the exact class this serves
// (.173's lesson). Collection is the existing lane; its receipts already ledger.
if (!function_exists('wpc_pull_pending_dispatch')) {
    function wpc_pull_pending_dispatch()
    {
        try {
            if ((function_exists('is_admin') && is_admin()) || !defined('WPS_IC_CRITICAL') || !class_exists('wps_ic_url_key')) {
                return;
            }
            if (!apply_filters('wpc_pending_pull', true)) {
                return;
            }
            // A REST route, feed, sitemap or other non-page answer has no crit to collect.
            if (function_exists('wpc_request_is_not_page') && wpc_request_is_not_page()) {
                return;
            }
            $k = ltrim((string) (new wps_ic_url_key())->setup(), '/');
            if ($k === '') {
                return;
            }
            $d = rtrim(WPS_IC_CRITICAL, '/') . '/' . $k . '/';
            $dispatch_ts = (int) @file_get_contents($d . 'dispatch_ts.txt');
            if ($dispatch_ts < 1 || (time() - $dispatch_ts) > (int) apply_filters('wpc_pending_pull_window', 900)) {
                return;
            }
            if ((int) @filemtime($d . 'land_uuid.txt') >= $dispatch_ts) {
                return;
            }
            if (get_transient('wpc_ppull_' . md5($k))) {
                return;
            }
            set_transient('wpc_ppull_' . md5($k), 1, (int) apply_filters('wpc_pending_pull_every', 30));
            if (!wpc_detach_request_or_schedule_cron($k)) {
                return;
            }
            if (function_exists('ignore_user_abort')) { @ignore_user_abort(true); }
            if (function_exists('set_time_limit')) { @set_time_limit(30); }
            if (function_exists('wpc_crit_kick_collect') && wpc_crit_kick_collect($k)
                && (int) @filemtime($d . 'land_uuid.txt') >= $dispatch_ts
                && function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('pending-pull-landed', $k, '', ['age' => time() - $dispatch_ts]);
            }
        } catch (\Throwable $e) {
        }
    }
    add_action('shutdown', 'wpc_pull_pending_dispatch', 99);
}
if (!function_exists('wpc_detach_request_or_schedule_cron')) {
    /**
     * v7.22.66 — a visitor never waits on a CDN pull. The two artifact lanes on shutdown
     * (pending pull, pointer tick) ran their remote HTTP with no detach; on FPM/LSAPI the
     * response is released first, and where no detach exists the pull moves to cron.
     */
    function wpc_detach_request_or_schedule_cron($k)
    {
        $finished = function_exists('wpc_finish_request') ? wpc_finish_request() : false;
        if ($finished) {
            return true;
        }
        if ($k !== '' && function_exists('wpc_pl_sched') && function_exists('wp_next_scheduled')
            && !wp_next_scheduled('wpc_lcp_repull', [$k, 1])) {
            wpc_pl_sched(time() + 60, 'wpc_lcp_repull', [$k, 1]);
        }
        return false;
    }
    // v7.21.188 — POINTER TICK (crit-team Q1: five fresh pointers, zero autonomous lands).
    // The .174 lane only polls inside 15 min of OUR dispatch; a service-side publish
    // (observer mint, reannounce) writes no dispatch stamp here and pullDerivedArtifacts'
    // already-landed fast path never consults the pointer — so a newer shelf gen over a
    // healthy landed page was invisible. This lane compares the storage pointer to
    // land_uuid on render shutdowns, 60s/key, and force-pulls on mismatch: landing is
    // <=60s + one render after anyone's publish, WAF-irrelevant (CDN GETs only).
    function wpc_pull_on_storage_pointer_mismatch()
    {
        try {
            if ((function_exists('is_admin') && is_admin()) || !defined('WPS_IC_CRITICAL')
                || !class_exists('wps_ic_url_key')) {
                return;
            }
            if (!apply_filters('wpc_pointer_tick', true)) {
                return;
            }
            // A REST route, feed, sitemap or other non-page answer has no crit to collect.
            if (function_exists('wpc_request_is_not_page') && wpc_request_is_not_page()) {
                return;
            }
            if (!class_exists('wps_criticalCss') && defined('WPS_IC_DIR')) {
                @include_once WPS_IC_DIR . 'addons/criticalCss/criticalCss-v2.php';
            }
            if (!class_exists('wps_criticalCss')) {
                return;
            }
            if (function_exists('wpc_under_pressure') && wpc_under_pressure()) {
                return;
            }
            $k = ltrim((string) (new wps_ic_url_key())->setup(), '/');
            if ($k === '' || (function_exists('wpc_pipeline_key_junk') && wpc_pipeline_key_junk($k))) {
                return;
            }
            $d = rtrim(WPS_IC_CRITICAL, '/') . '/' . $k . '/';
            $lu = trim((string) @file_get_contents($d . 'land_uuid.txt'));
            if ($lu === '') {
                return;
            }
            if (get_transient('wpc_ptick_' . md5($k))) {
                return;
            }
            set_transient('wpc_ptick_' . md5($k), 1, (int) apply_filters('wpc_pointer_tick_every', 60));
            if (!wpc_detach_request_or_schedule_cron($k)) {
                return;
            }
            $cc = new wps_criticalCss();
            if (!method_exists($cc, 'fetchLatestPointerUuid') || !method_exists($cc, 'pullDerivedArtifacts')) {
                return;
            }
            $p = preg_replace('/[^a-f0-9-]/i', '', (string) $cc->fetchLatestPointerUuid($k));
            if (strlen($p) < 8 || $p === $lu) {
                return;
            }
            if (function_exists('ignore_user_abort')) {
                @ignore_user_abort(true);
            }
            if (function_exists('set_time_limit')) {
                @set_time_limit(30);
            }
            if ($cc->pullDerivedArtifacts($k, $p, true, 0, ['via' => 'pointer'])
                && trim((string) @file_get_contents($d . 'land_uuid.txt')) === $p
                && function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('pointer-tick-landed', $k, '', ['uuid' => substr($p, 0, 8), 'was' => substr($lu, 0, 8)]);
            }
        } catch (\Throwable $e) {
        }
    }
    add_action('shutdown', 'wpc_pull_on_storage_pointer_mismatch', 98);
}

// ─── AUTO-100 prescriptions consumption (contract v1.1.1 §4, Phase A) ───
// Land-time only: validate → store → apply-route → journal. Render reads the stored
// file with fail-open parse guards; no HTTP ever leaves the render path.
if (!function_exists('wpc_presc_known_classes')) {
    /** Complete 12-class enum (contract delta 1) — a short list rejects every real file. */
    function wpc_presc_known_classes()
    {
        return ['font-metric-swap', 'icon-pop', 'crit-removal', 'used-swap', 'unsized-media',
            'band-restyle', 'js-init-reflow', 'paint-fouc', 'site-native', 'unclassified',
            'third-party-lane', 'delay-created-conceal'];
    }

    /** Envelope + per-item structural validation. Law 12: unknown keys pass through,
     *  unknown classes stay in (apply skips + journals them) — only structurally broken
     *  items are dropped, never the whole file. Returns the sanitized envelope or false. */
    function wpc_prescriptions_valid($j)
    {
        if (!is_array($j) || !isset($j['v']) || !isset($j['prescriptions']) || !is_array($j['prescriptions'])) {
            return false;
        }
        $out = $j;
        $items = [];
        foreach ($j['prescriptions'] as $p) {
            if (count($items) >= 64) {
                break;
            }
            if (!is_array($p) || empty($p['id']) || empty($p['class'])) {
                continue;
            }
            $id = strtolower((string) $p['id']);
            $cl = strtolower((string) $p['class']);
            if (!preg_match('/^[a-f0-9]{6,40}$/', $id) || !preg_match('/^[a-z0-9][a-z0-9-]{1,39}$/', $cl)) {
                continue;
            }
            $p['id'] = $id;
            $p['class'] = $cl;
            $items[] = $p;
        }
        $out['prescriptions'] = $items;
        return $out;
    }

    /** Replace-by-id receipts, single non-autoload option, hard-capped, only-on-change:
     *  an identical row is a no-op (original applied_at receipt preserved — the verdict
     *  loop keys on it); a changed row keeps first_at. Cflog mirror per change (law 7). */
    function wpc_presc_journal_merge($rows)
    {
        if (!is_array($rows) || empty($rows)) {
            return;
        }
        $j = get_option('wpc_presc_journal');
        if (!is_array($j)) {
            $j = [];
        }
        $dirty = false;
        foreach ($rows as $id => $row) {
            $id = (string) $id;
            $row = (array) $row;
            $prev = isset($j[$id]) && is_array($j[$id]) ? $j[$id] : null;
            if ($prev !== null
                && (string) ($prev['status'] ?? '') === (string) ($row['status'] ?? '')
                && (string) ($prev['skipped'] ?? '') === (string) ($row['skipped'] ?? '')
                && (string) ($prev['class'] ?? '') === (string) ($row['class'] ?? '')
                && (string) ($prev['fix'] ?? '') === (string) ($row['fix'] ?? '')) {
                continue; // identical receipt — keep the original timestamps
            }
            $row['applied_at'] = time();
            $row['first_at'] = $prev !== null ? (int) ($prev['first_at'] ?? $prev['applied_at'] ?? time()) : time();
            $j[$id] = $row;
            $dirty = true;
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('presc-' . (string) ($row['status'] ?? 'journal'), '', '',
                    ['id' => $id, 'class' => (string) ($row['class'] ?? ''), 'fix' => (string) ($row['fix'] ?? ''), 'skipped' => (string) ($row['skipped'] ?? '')]);
            }
        }
        if (!$dirty) {
            return;
        }
        // Evict junk (skips/reports) before LIVE receipts — stable armed/applied rows
        // keep their original applied_at by design, so age alone would evict exactly
        // the receipts the verdict loop needs most (multi-page sites, 48 ids/URL).
        if (count($j) > 160) {
            uasort($j, function ($a, $b) {
                $w = function ($r) {
                    return in_array((string) ($r['status'] ?? ''), ['armed', 'applied', 'pending-verdict', 'service-applied'], true) ? 1 : 0;
                };
                return ($w($a) - $w($b)) ?: ((int) ($a['applied_at'] ?? 0) - (int) ($b['applied_at'] ?? 0));
            });
            $j = array_slice($j, -160, null, true);
        }
        update_option('wpc_presc_journal', $j, false);
    }

    function wpc_presc_journal_put($id, $row)
    {
        wpc_presc_journal_merge([(string) $id => $row]);
    }

    /** A3 gate-2 STICKY store: ids the inline guard refuted on the served DOM (the re-count
     *  found them non-unique, or the plausibility pass found the reserve implausible).
     *  Kept OUT of the churny journal so a forced re-apply cannot re-arm them and
     *  eviction cannot drop the gate state. Each mark is STAMPED with the 12-hex artifact
     *  tag (av = md5(prescriptions body)[:12]) it was computed against, so a mark is
     *  honored only while that exact artifact is live — a republish, a purge-and-refetch,
     *  or a stale in-flight beacon all self-invalidate on av mismatch. id => av. Bounded. */
    function wpc_presc_av_tag($body)
    {
        return substr(md5((string) $body), 0, 12);
    }
    function wpc_presc_notuniq_get()
    {
        $s = get_option('wpc_presc_notuniq');
        return is_array($s) ? $s : [];
    }
    /** Is this id currently refuted FOR the live artifact av? */
    function wpc_presc_notuniq_hit($store, $id, $av)
    {
        $id = strtolower((string) $id);
        return $av !== '' && isset($store[$id]) && (string) $store[$id] === (string) $av;
    }
    function wpc_presc_notuniq_mark($map)
    {
        $s = wpc_presc_notuniq_get();
        $orig = $s;
        foreach ((array) $map as $id => $av) {
            $id = strtolower((string) $id);
            $av = (string) $av;
            if (!preg_match('/^[a-f0-9]{6,40}$/', $id) || !preg_match('/^[a-f0-9]{6,32}$/', $av)) {
                continue;
            }
            // Move to the TAIL on every confirm (unconditional per-id, not gated on a
            // batch change-flag) — eviction is LRU-by-mark, so a repeatedly-refuted id is
            // the LAST to evict, not the first (the insertion-order slice dropped exactly
            // those). The consume lane is ≤1/60s, so the write below is not churn.
            unset($s[$id]);
            $s[$id] = $av;
        }
        if ($s !== $orig) { // value change OR reorder
            if (count($s) > 512) {
                $s = array_slice($s, -512, null, true);
            }
            update_option('wpc_presc_notuniq', $s, false);
        }
    }
    function wpc_presc_notuniq_clear($ids)
    {
        $s = wpc_presc_notuniq_get();
        if (empty($s)) {
            return;
        }
        $d = false;
        foreach ((array) $ids as $id) {
            $id = strtolower((string) $id);
            if (isset($s[$id])) {
                unset($s[$id]);
                $d = true;
            }
        }
        if ($d) {
            update_option('wpc_presc_notuniq', $s, false);
        }
    }

    /** Route each entry per the §4 fix.type→action map; journal every id (law 7) in ONE
     *  batched option write. $av = the artifact tag this envelope was applied from
     *  (a runtime not-unique mark is honored only while its av is the live one). */
    function wpc_presc_apply($urlKey, $env, $av = '')
    {
        $known = wpc_presc_known_classes();
        $armed = 0;
        $pins = [];
        $rows = [];
        $storedPins = get_option('wpc_presc_pins');
        if (!is_array($storedPins)) {
            $storedPins = [];
        }
        // A3 gate-2: ids the served-DOM re-count already refuted stay demoted across
        // every re-apply — a forced refetch of an unchanged file must not re-arm them
        // (the oscillation class). A genuine service rewrite clears them (see fetch).
        $notUniq = function_exists('wpc_presc_notuniq_get') ? wpc_presc_notuniq_get() : [];
        $journalBefore = get_option('wpc_presc_journal');
        // Same selector alphabet the render leg enforces — land and render must agree,
        // or 'armed' receipts describe rules that never emit.
        $selRx = '/^[A-Za-z0-9 _\-#.:\[\]=>+~()]+$/';
        foreach ((array) ($env['prescriptions'] ?? []) as $p) {
            $id = (string) $p['id'];
            $cl = (string) $p['class'];
            $fx = isset($p['fix']['type']) ? strtolower((string) $p['fix']['type']) : '';
            $base = ['class' => $cl, 'fix' => $fx];
            if (!empty($p['applied_by_service'])) {
                $rows[$id] = $base + ['status' => 'service-applied'];
                continue;
            }
            if (!in_array($cl, $known, true)) {
                $rows[$id] = $base + ['status' => 'skipped', 'skipped' => 'unknown-class'];
                continue;
            }
            if ($fx === 'reserve-rect') {
                // A3 gate 1: only the verdict probe's verified_unique:true stamp arms an
                // emission (the runtime re-count is check #2). Unstamped = pre-verdict file
                // — the poll-#2 rewrite carries the stamps; false = service-demoted.
                if (isset($p['verified_unique']) && $p['verified_unique'] === false) {
                    $rows[$id] = $base + ['status' => 'report', 'skipped' => 'not-unique-verdict'];
                    continue;
                }
                $sel = isset($p['fix']['payload']['sel']) ? trim((string) $p['fix']['payload']['sel']) : '';
                // Same rounding the render leg applies — (int) truncation would journal
                // 'armed' for 2000.5 (render drops it) and 'bad-payload' for 23.7 (render
                // emits it): receipts must describe what actually ships.
                $px  = isset($p['fix']['payload']['min_height_px']) && is_numeric($p['fix']['payload']['min_height_px'])
                    ? (int) round((float) $p['fix']['payload']['min_height_px']) : 0;
                if ($sel === '' || strlen($sel) > 400 || !preg_match($selRx, $sel) || $px < 24 || $px > 2000) {
                    $rows[$id] = $base + ['status' => 'skipped', 'skipped' => 'bad-payload'];
                    continue;
                }
                if (!isset($p['verified_unique']) || $p['verified_unique'] !== true) {
                    $rows[$id] = $base + ['status' => 'pending-verdict'];
                    continue;
                }
                if (wpc_presc_notuniq_hit($notUniq, $id, $av)) {
                    // runtime re-count refuted this id FOR THIS artifact version — do not
                    // re-arm (render suppresses it too). A different av (republish) is not
                    // a hit, so a genuinely re-published/fixed id arms again.
                    $rows[$id] = $base + ['status' => 'skipped',
                        'skipped' => (is_array($journalBefore) && (string) ($journalBefore[$id]['skipped'] ?? '') === 'implausible') ? 'implausible' : 'not-unique'];
                    continue;
                }
                $armed++;
                $rows[$id] = $base + ['status' => 'armed'];
            } elseif ($fx === 'lane-demote') {
                $host = isset($p['fix']['payload']['host']) ? strtolower(trim((string) $p['fix']['payload']['host'])) : '';
                $mode = isset($p['fix']['payload']['mode']) ? strtolower(trim((string) $p['fix']['payload']['mode'])) : '';
                // Contract §2 lane names → internal lanes (service-confirmed emitted set:
                // delay-interaction-only, keep-eager, facade). keep-eager = consent pin —
                // surfaced via the eager lane, NEVER wired into excludes (dm law: the
                // built-in consent keeps do the actual eager-keeping); facade = Phase C,
                // report lane. Unknown modes journal as skips.
                $modeMap = ['delay-interaction-only' => 'io', 'io' => 'io', 'delay' => 'delay',
                    'keep-eager' => 'eager', 'facade' => 'report', 'report' => 'report', 'review' => 'report'];
                if ($host === '' || $mode === '' || !function_exists('wpc_auto_3p_lane_set')) {
                    $rows[$id] = $base + ['status' => 'skipped', 'skipped' => ($host === '' || $mode === '') ? 'bad-payload' : 'no-lane-engine'];
                    continue;
                }
                if (!isset($modeMap[$mode])) {
                    $rows[$id] = $base + ['status' => 'skipped', 'skipped' => 'unknown-mode'];
                    continue;
                }
                $m = (isset($p['match']) && is_array($p['match'])) ? $p['match'] : [];
                $lr = wpc_auto_3p_lane_set($host, $modeMap[$mode], $m, 'presc:' . $id);
                // A false receipt blinds the verdict loop — journal what actually happened.
                $rows[$id] = $lr !== false
                    ? $base + ['status' => 'applied']
                    : $base + ['status' => 'skipped', 'skipped' => 'lane-rejected'];
            } elseif ($fx === 'lane-pin') {
                // A2: the chain walk needs wp_scripts, which only exists on a front-end
                // render — store the intent; the delay-v3 pass resolves or degrades there.
                $cand = (isset($p['evidence']['candidates']) && is_array($p['evidence']['candidates']))
                    ? array_slice(array_map('strval', $p['evidence']['candidates']), 0, 6) : [];
                if (empty($cand)) {
                    $rows[$id] = $base + ['status' => 'skipped', 'skipped' => 'no-candidates'];
                    continue;
                }
                // A render-decided pin keeps BOTH its state and its journal receipt —
                // re-journaling 'armed' here would erase the 'applied'/'report' truth.
                $stored_state = (string) ($storedPins[$id]['state'] ?? '');
                if ($stored_state === 'resolved' || $stored_state === 'degraded') {
                    $pins[$id] = $storedPins[$id];
                    continue;
                }
                $pins[$id] = ['cand' => $cand, 'sel' => (string) ($p['selector'] ?? ''), 'state' => 'pending',
                    't' => time(), 'k' => (string) $urlKey, 'cl' => $cl];
                $rows[$id] = $base + ['status' => 'armed'];
            } elseif ($fx === 'bake-geometry' || $fx === 'size-adjust') {
                $rows[$id] = $base + ['status' => 'service-applied'];
            } elseif ($fx === 'report-customer' || $fx === 'surface-review') {
                $rows[$id] = $base + ['status' => 'report'];
            } else {
                $rows[$id] = $base + ['status' => 'skipped', 'skipped' => 'unknown-fix'];
            }
        }
        wpc_presc_journal_merge($rows);
        {
            $cur = $storedPins;
            // pending intents refresh; resolved/degraded verdicts stick (render decided)
            foreach ($pins as $wpc_pid => $wpc_pin) {
                if (!isset($cur[$wpc_pid]) || (($cur[$wpc_pid]['state'] ?? '') === 'pending')) {
                    $cur[$wpc_pid] = $wpc_pin;
                }
            }
            // WITHDRAWAL: this key's stored pins absent from the current envelope (or
            // re-typed away from lane-pin) un-pin — a chain must not stay promoted
            // after the service retreats from the prescription.
            foreach (array_keys($cur) as $pin_id) {
                if ((string) ($cur[$pin_id]['k'] ?? '') === (string) $urlKey && !isset($pins[$pin_id])) {
                    unset($cur[$pin_id]);
                }
            }
            if (count($cur) > 12) {
                uasort($cur, function ($a, $b) {
                    return (int) ($a['t'] ?? 0) - (int) ($b['t'] ?? 0);
                });
                $cur = array_slice($cur, -12, null, true);
            }
            if ($cur !== $storedPins) {
                update_option('wpc_presc_pins', $cur, false);
            }
        }
        return $armed;
    }

    /** Fetch → validate → store → apply. Buster-always (§1 fetch law: the file is amended
     *  in place post-verdict); ETag is a change marker ONLY — never If-None-Match (delta 3). */
    function wpc_prescriptions_fetch($urlKey, $force = false)
    {
        try {
            if (empty($urlKey) || !defined('WPS_IC_CRITICAL') || !apply_filters('wpc_prescriptions_consume', true)) {
                return false;
            }
            if (function_exists('wpc_pipeline_key_junk') && wpc_pipeline_key_junk($urlKey)) {
                return false;
            }
            // A FORCED fetch (poll #2 / webhook / due-tick) bypasses the 30s land-side
            // single-flight (a heated land fetch must not swallow the post-verdict pull)
            // but takes a SHARED 15s force-mutex — the cron poll and the traffic tick
            // have disjoint lane throttles and would otherwise double-fetch concurrently.
            if (!$force && get_transient('wpc_prescfetch_' . md5((string) $urlKey))) {
                return false;
            }
            if ($force && get_transient('wpc_prescff_' . md5((string) $urlKey))) {
                return false;
            }
            set_transient('wpc_prescfetch_' . md5((string) $urlKey), 1, 30);
            if ($force) {
                set_transient('wpc_prescff_' . md5((string) $urlKey), 1, 15);
            }
            $dir = rtrim(WPS_IC_CRITICAL, '/') . '/' . $urlKey . '/';
            $u = trim((string) @file_get_contents($dir . 'prescriptions_url.txt'));
            if ($u === '' || !preg_match('#^https://#i', $u)) {
                return false;
            }
            $u .= (strpos($u, '?') === false ? '?' : '&') . 't=' . time();
            $r = wp_remote_get($u, ['timeout' => 5, 'user-agent' => defined('WPS_IC_API_USERAGENT') ? WPS_IC_API_USERAGENT : '']);
            if (is_wp_error($r) || (int) wp_remote_retrieve_response_code($r) !== 200) {
                return false;
            }
            $body = (string) wp_remote_retrieve_body($r);
            if ($body === '' || strlen($body) > 262144) {
                return false;
            }
            $etag = wp_remote_retrieve_header($r, 'etag');
            $etag = is_string($etag) ? trim($etag) : '';
            if (!$force && $etag !== '' && @is_readable($dir . 'prescriptions.json')
                && $etag === trim((string) @file_get_contents($dir . 'prescriptions_etag.txt'))) {
                return true; // unchanged shelf copy — already applied
            }
            $env = wpc_prescriptions_valid(json_decode($body, true));
            if ($env === false) {
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('presc-invalid', (string) $urlKey, '', ['len' => strlen($body)]);
                }
                return false;
            }
            // CHANGE DETECTION keys on a PERSISTED per-URL body md5 (option, survives the
            // prescriptions.json unlink that our own purge/refetch does) — NOT the on-disk
            // json, whose absence would false-positive "changed" on a byte-identical
            // refetch and spuriously clear the sticky store / fire a purge.
            $body_md5 = md5($body);
            $av_tag  = wpc_presc_av_tag($body);
            $body_md5_store = get_option('wpc_presc_bodymd5');
            if (!is_array($body_md5_store)) {
                $body_md5_store = [];
            }
            $changed = ((string) ($body_md5_store[(string) $urlKey] ?? '')) !== $body_md5;
            wpc_crit_meta_write($dir . 'prescriptions.json', $body);
            if ($etag !== '') {
                wpc_crit_meta_write($dir . 'prescriptions_etag.txt', $etag);
            }
            if ($changed) {
                // Re-insert at the tail (LRU): the change-detection baseline for an
                // actively-refetched URL must outlive eviction, else a >cap multi-page
                // site false-positives 'changed' on a byte-identical refetch and fires an
                // avoidable purge. 256 URLs is far beyond any real per-install footprint.
                unset($body_md5_store[(string) $urlKey]);
                $body_md5_store[(string) $urlKey] = $body_md5;
                if (count($body_md5_store) > 256) {
                    $body_md5_store = array_slice($body_md5_store, -256, null, true);
                }
                update_option('wpc_presc_bodymd5', $body_md5_store, false);
            }
            // The av stamp makes marks self-invalidate across versions, so an explicit
            // clear is no longer load-bearing — but prune this envelope's stale-av marks
            // on a genuine republish to keep the store tight.
            if ($changed && function_exists('wpc_presc_notuniq_clear')) {
                $stale_ids = [];
                $not_unique = wpc_presc_notuniq_get();
                foreach ((array) ($env['prescriptions'] ?? []) as $prescription) {
                    $prescription_id = strtolower((string) ($prescription['id'] ?? ''));
                    if ($prescription_id !== '' && isset($not_unique[$prescription_id]) && (string) $not_unique[$prescription_id] !== $av_tag) {
                        $stale_ids[] = $prescription_id;
                    }
                }
                if (!empty($stale_ids)) {
                    wpc_presc_notuniq_clear($stale_ids);
                }
            }
            $armed = wpc_presc_apply($urlKey, $env, $av_tag);
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('presc-landed', (string) $urlKey, '', ['n' => count((array) $env['prescriptions']), 'armed' => (int) $armed, 'changed' => (int) $changed]);
            }
            // Purge on ANY content change (coalescer bounds the cost): a rewrite that
            // only DEMOTES must also rotate cached HTML, or stale reserve rules persist.
            if ($changed && function_exists('wpc_land_purge_coalesced')) {
                wpc_land_purge_coalesced($urlKey, '', 'presc-land');
            }
            return true;
        } catch (\Throwable $e) {
            return false;
        }
    }

    /** Land ride: try now if the URL meta is here, and arm poll #2 (+300s) for the
     *  post-verdict rewrite (§1: prescriptions.json is amended after verdict).
     *  CRON-INDEPENDENCE: the due-marker file makes the traffic-driven kick lane a
     *  co-equal executor of poll #2 (wpc_presc_due_tick below) — WP-Cron is an
     *  optimization here, never a dependency (DISABLE_WP_CRON + dead crontab sites). */
    function wpc_presc_on_land($urlKey)
    {
        try {
            if (empty($urlKey) || !apply_filters('wpc_prescriptions_consume', true)) {
                return;
            }
            $dir = defined('WPS_IC_CRITICAL') ? rtrim(WPS_IC_CRITICAL, '/') . '/' . $urlKey . '/' : '';
            if ($dir !== '' && @is_readable($dir . 'prescriptions_url.txt')) {
                wpc_prescriptions_fetch($urlKey);
            }
            // Arm the +300s post-verdict poll ONLY when prescriptions are known for this
            // site (url meta present). A prescriptions-less site gets no marker — else the
            // due-tick drips a 120s transient write per trafficked kick forever.
            if ($dir !== '' && is_dir($dir) && @is_readable($dir . 'prescriptions_url.txt')) {
                // Keep the EARLIER due time: a webhook's due-NOW marker must never be
                // pushed out by a land re-arm (cron-dead sites: the marker is the only
                // carrier of the post-verdict pull).
                $current_due = (int) trim((string) @file_get_contents($dir . 'presc_due.txt'));
                $new_due = time() + 300;
                if ($current_due <= 0 || $current_due > $new_due) {
                    wpc_crit_meta_write($dir . 'presc_due.txt', (string) $new_due);
                }
            }
            if ($dir !== '' && @is_readable($dir . 'prescriptions_url.txt')
                && function_exists('wpc_pl_sched') && function_exists('wp_next_scheduled')
                && !wp_next_scheduled('wpc_presc_poll', [(string) $urlKey])) {
                wpc_pl_sched(time() + 300, 'wpc_presc_poll', [(string) $urlKey]);
            }
        } catch (\Throwable $e) {
        }
    }

    /** Traffic-driven poll executor: any kick/repull after the due time runs poll #2
     *  inline on a BACKGROUND worker (the kick lane is loopback-driven, cron-free).
     *  Also folds the beacon queue opportunistically — same cron-independence. Bounded:
     *  120s throttle + the fetch's own single-flight; marker clears only on success. */
    function wpc_presc_due_tick($urlKey)
    {
        try {
            if ((string) $urlKey === '' || !defined('WPS_IC_CRITICAL')) {
                return false;
            }
            if (function_exists('wpc_presc_seen_consume_h')) {
                $q = get_option('wpc_presc_seen_queue');
                if (is_array($q) && !empty($q)) {
                    wpc_presc_seen_consume_h();
                }
            }
            $dir = rtrim(WPS_IC_CRITICAL, '/') . '/' . $urlKey . '/';
            $due = (int) trim((string) @file_get_contents($dir . 'presc_due.txt'));
            if ($due <= 0 || time() < $due) {
                return false;
            }
            if (get_transient('wpc_prescdt_' . md5((string) $urlKey))) {
                return false;
            }
            set_transient('wpc_prescdt_' . md5((string) $urlKey), 1, 120);
            if (!@is_readable($dir . 'prescriptions_url.txt')) {
                // No URL to fetch — retire this marker (the /v2/latest + presc_want lane
                // lands the URL and re-arms). Never drip a per-kick transient forever.
                @unlink($dir . 'presc_due.txt');
                return false;
            }
            if (wpc_prescriptions_fetch($urlKey, true)) {
                @unlink($dir . 'presc_due.txt');
                delete_transient('wpc_prescpw_' . md5((string) $urlKey));
                delete_transient('wpc_prescdf_' . md5((string) $urlKey));
                return true;
            }
            // Duration cap: a marker whose fetch NEVER succeeds (withdrawn shelf URL)
            // retires after 12 consecutive failures — the next land re-arms it. Without
            // this the 120s-throttled retry drips forever on trafficked sites.
            $fail_count = (int) get_transient('wpc_prescdf_' . md5((string) $urlKey)) + 1;
            set_transient('wpc_prescdf_' . md5((string) $urlKey), $fail_count, DAY_IN_SECONDS);
            if ($fail_count >= 12) {
                @unlink($dir . 'presc_due.txt');
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('presc-due-retired', (string) $urlKey, '', ['fails' => $fail_count]);
                }
            }
            return false;
        } catch (\Throwable $e) {
            return false;
        }
    }

    /** Poll #2 handler: force-refetch the post-verdict rewrite. Every blocked path
     *  DEFERS instead of dropping (bounded by a wave counter) — a swallowed poll loses
     *  the verified_unique stamps until the next full generation. */
    function wpc_presc_poll_h($urlKey)
    {
        try {
            if ((string) $urlKey === '' || !defined('WPS_IC_CRITICAL')) {
                return;
            }
            if (function_exists('wpc_pipeline_key_junk') && wpc_pipeline_key_junk($urlKey)) {
                return;
            }
            $ctr = 'wpc_prescpw_' . md5((string) $urlKey);
            $defer = function ($secs) use ($urlKey, $ctr) {
                $n = (int) get_transient($ctr);
                if ($n >= 8) {
                    return; // wave cap — stop chaining, the next land re-arms
                }
                set_transient($ctr, $n + 1, HOUR_IN_SECONDS);
                if (function_exists('wpc_pl_sched') && function_exists('wp_next_scheduled')
                    && !wp_next_scheduled('wpc_presc_poll', [(string) $urlKey])) {
                    wpc_pl_sched(time() + $secs, 'wpc_presc_poll', [(string) $urlKey]);
                }
            };
            if (function_exists('wpc_under_pressure') && wpc_under_pressure()) {
                $defer(120);
                return;
            }
            if (get_transient('wpc_prescpoll_' . md5((string) $urlKey))) {
                $defer(90);
                return;
            }
            set_transient('wpc_prescpoll_' . md5((string) $urlKey), 1, 60);
            $dir = rtrim(WPS_IC_CRITICAL, '/') . '/' . $urlKey . '/';
            if (!@is_readable($dir . 'prescriptions_url.txt')) {
                // Positive-signal path only (webhook wrote presc_want): clear the /v2/latest
                // throttle so the repull lands the URL meta now, not up to 60s later.
                delete_transient('wpc_v2l_' . md5((string) $urlKey));
                if (function_exists('wpc_pl_sched') && function_exists('wp_next_scheduled')
                    && !wp_next_scheduled('wpc_lcp_repull', [(string) $urlKey, 1])) {
                    wpc_pl_sched(time() + 1, 'wpc_lcp_repull', [(string) $urlKey, 1]);
                }
                $defer(120); // re-poll after the repull lands the URL meta
                return;
            }
            if (wpc_prescriptions_fetch($urlKey, true)) {
                @unlink($dir . 'presc_due.txt');
                delete_transient($ctr);
            } else {
                $defer(90);
            }
        } catch (\Throwable $e) {
        }
    }
    add_action('wpc_presc_poll', 'wpc_presc_poll_h', 10, 1);
}


if (!function_exists('wpc_presc_seen_handler')) {
    /** A3 runtime beacon from the inline guard: `not-unique` (the re-count found the
     *  selector on more than one element) or `implausible` (the reserve is far taller than
     *  the element it holds, measured in the browser). font_seen shape: accept filter, a
     *  lock per verdict, strict input caps, bounded queue, deferred consume — zero blocking
     *  work on the beacon request. */
    function wpc_presc_seen_handler()
    {
        try {
            if (!apply_filters('wpc_presc_seen_accept', true)) {
                wp_die('', '', 204);
            }
            $sk  = isset($_POST['skipped']) ? trim((string) wp_unslash($_POST['skipped'])) : '';
            if (!in_array($sk, ['not-unique', 'implausible'], true)) {
                wp_die('', '', 204);
            }
            // One beacon per verdict per pageload carries up to 4 comma-joined ids (the 30s
            // lock would drop a second beacon of the same verdict).
            $lock = $sk === 'not-unique' ? 'wpc_presc_seen_lock' : 'wpc_presc_seen_lock_' . $sk;
            if (get_transient($lock)) {
                wp_die('', '', 204);
            }
            set_transient($lock, 1, 30);
            $idr = isset($_POST['id']) ? strtolower(trim((string) wp_unslash($_POST['id']))) : '';
            // av = the artifact tag the verdict was computed against; a mark is honored
            // only while that av is live, so a stale in-flight beacon can't suppress a
            // freshly re-published id.
            $av  = isset($_POST['av']) ? strtolower(trim((string) wp_unslash($_POST['av']))) : '';
            if ($idr === '' || strlen($idr) > 180 || !preg_match('/^[a-f0-9]{6,32}$/', $av)) {
                wp_die('', '', 204);
            }
            $ids = array_slice(array_filter(array_map('trim', explode(',', $idr))), 0, 4);
            $q = get_option('wpc_presc_seen_queue');
            if (!is_array($q)) {
                $q = [];
            }
            $qd = false;
            foreach ($ids as $id) {
                if (!preg_match('/^[a-f0-9]{6,40}$/', $id)) {
                    continue;
                }
                if (!isset($q[$id]) && count($q) < 10) {
                    $q[$id] = $sk === 'not-unique' ? $av : ['av' => $av, 'skipped' => $sk];
                    $qd = true;
                }
            }
            if ($qd) {
                update_option('wpc_presc_seen_queue', $q, false);
                if (function_exists('wp_schedule_single_event') && !wp_next_scheduled('wpc_presc_seen_consume')) {
                    wp_schedule_single_event(time() + 60, 'wpc_presc_seen_consume');
                }
            }
        } catch (\Throwable $e) {
        }
        wp_die('', '', 204);
    }
    add_action('wp_ajax_wpc_presc_seen', 'wpc_presc_seen_handler');
    add_action('wp_ajax_nopriv_wpc_presc_seen', 'wpc_presc_seen_handler');

    function wpc_presc_seen_consume_h()
    {
        try {
            $q = get_option('wpc_presc_seen_queue');
            delete_option('wpc_presc_seen_queue');
            if (!is_array($q) || empty($q) || !function_exists('wpc_presc_journal_put')) {
                return;
            }
            $mark = [];
            $votes = get_option('wpc_presc_implausible_votes', []);
            $votes = is_array($votes) ? $votes : [];
            $need = max(1, (int) apply_filters('wpc_presc_implausible_votes', 3));
            foreach ($q as $id => $queued) {
                $av = is_array($queued) ? (string) ($queued['av'] ?? '') : (string) $queued;
                $skipped = (is_array($queued) && ($queued['skipped'] ?? '') === 'implausible') ? 'implausible' : 'not-unique';
                if ($skipped === 'implausible') {
                    $prior = isset($votes[$id]) && is_array($votes[$id]) && (string) ($votes[$id]['av'] ?? '') === $av ? (int) ($votes[$id]['n'] ?? 0) : 0;
                    $votes[$id] = ['av' => $av, 'n' => $prior + 1, 't' => time()];
                    if ($prior + 1 < $need) {
                        continue;
                    }
                    unset($votes[$id]);
                }
                wpc_presc_journal_put((string) $id, ['status' => 'skipped', 'skipped' => $skipped,
                    'via' => $skipped === 'implausible' ? 'runtime-plausibility' : 'runtime-recount']);
                if (preg_match('/^[a-f0-9]{6,32}$/', $av)) {
                    $mark[(string) $id] = $av; // id => artifact tag
                }
            }
            if (count($votes) > 200) {
                uasort($votes, function ($a, $b) { return (int) ($b['t'] ?? 0) - (int) ($a['t'] ?? 0); });
                $votes = array_slice($votes, 0, 200, true);
            }
            update_option('wpc_presc_implausible_votes', $votes, false);
            // Sticky gate: survives journal eviction AND forced re-applies; the av stamp
            // makes a stale-artifact verdict self-invalidate.
            if (!empty($mark) && function_exists('wpc_presc_notuniq_mark')) {
                wpc_presc_notuniq_mark($mark);
            }
        } catch (\Throwable $e) {
        }
    }
    add_action('wpc_presc_seen_consume', 'wpc_presc_seen_consume_h');
}


// ─── used-css scoped purge (v7.10.325, hit-rate law): a used.css artifact is TEMPLATE-
// keyed — purging ALL local HTML for it wiped every page's cache on every used-css land.
// Purge only the pages whose crit dir carries the same tpl (bounded); fall back to the
// old full wipe only when the template family is too large to enumerate. ───
if (!function_exists('wpc_used_css_scoped_purge')) {
    function wpc_used_css_scoped_purge($tplKey)
    {
        try {
            $cap = (int) apply_filters('wpc_used_css_purge_cap', 12);
            if (!is_string($tplKey) || $tplKey === '' || !defined('WPS_IC_CRITICAL')
                || !class_exists('wps_ic_cache_integrations') || !method_exists('wps_ic_cache_integrations', 'purgeUrlHtml')) {
                return false;
            }
            $root = rtrim(WPS_IC_CRITICAL, '/') . '/';
            $keys = [];
            foreach (['*/tpl.txt', '*/*/tpl.txt', '*/*/*/tpl.txt'] as $gp) {
                foreach ((array) @glob($root . $gp, GLOB_NOSORT) as $tf) {
                    if (trim((string) @file_get_contents($tf)) !== trim($tplKey)) {
                        continue;
                    }
                    $keys[] = trim(substr(dirname($tf) . '/', strlen($root)), '/');
                    if (count($keys) > $cap) {
                        return false; // family too large — caller falls back to the full wipe
                    }
                }
            }
            if (empty($keys)) {
                return false;
            }
            foreach ($keys as $k) {
                wps_ic_cache_integrations::purgeUrlHtml($k, '', ['context' => 'used-css-tpl', 'warm' => false]);
            }
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('used-css-scoped-purge', substr($tplKey, 0, 24), '', ['n' => count($keys)]);
            }
            return true;
        } catch (\Throwable $e) {
            return false;
        }
    }
}


// ─── LiteSpeed purge-ping (v7.10.324, hawkeye receipt): background lands cannot emit
// response headers, and LiteSpeed purges ONLY via response headers — so the clean URL
// keeps serving a stale LS HIT that never runs PHP. The ping is one non-blocking
// cache-miss loopback (?wpc_lsp) whose own response carries the purge directive. ───
if (!function_exists('wpc_ls_purge_ping')) {
    function wpc_ls_purge_ping($url)
    {
        try {
            if (empty($url) || !function_exists('wp_remote_get')) {
                return false;
            }
            $is_litespeed = defined('LSCWP_V') || class_exists('\LiteSpeed\Purge')
                || (!empty($_SERVER['SERVER_SOFTWARE']) && stripos((string) $_SERVER['SERVER_SOFTWARE'], 'litespeed') !== false);
            if (!$is_litespeed) {
                return false;
            }
            if (get_transient('wpc_lsp_' . md5((string) $url))) {
                return true; // one ping per URL per window
            }
            set_transient('wpc_lsp_' . md5((string) $url), 1, 20);
            wp_remote_get(add_query_arg('wpc_lsp', (string) time(), (string) $url),
                ['blocking' => false, 'timeout' => 2, 'sslverify' => false]);
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('ls-ping-fired', '', (string) $url, []);
            }
            return true;
        } catch (\Throwable $e) {
            return false;
        }
    }

    function wpc_ls_purge_ping_rx()
    {
        try {
            if (empty($_GET['wpc_lsp'])) {
                return;
            }
            // Purges only THIS request's own clean path — the same power any visitor already
            // has via a random query param; rate-limited so probe floods mint nothing.
            $path = (string) strtok((string) ($_SERVER['REQUEST_URI'] ?? '/'), '?');
            if ($path === '') {
                $path = '/';
            }
            if (get_transient('wpc_lsprx_' . md5($path))) {
                status_header(200);
                echo 'dup';
                exit;
            }
            set_transient('wpc_lsprx_' . md5($path), 1, 10);
            if (function_exists('do_action') && (defined('LSCWP_V') || class_exists('\LiteSpeed\Purge'))
                && function_exists('home_url')) {
                do_action('litespeed_purge_url', home_url($path));
            }
            if (!headers_sent()) {
                header('X-LiteSpeed-Purge: ' . $path, false);
                header('X-LiteSpeed-Cache-Control: no-cache', false);
            }
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('ls-ping-rx', '', $path, []);
            }
            status_header(200);
            echo 'ok';
            exit;
        } catch (\Throwable $e) {
            // fail OPEN: never break the render this rode in on
        }
    }
    add_action('init', 'wpc_ls_purge_ping_rx', 0);
}


// ─── Crit pipeline SELF-TEST (v7.10.323): the acceptance drill, productized ───
// Preflight = read-only hop checks. Drill (&drill=1) = windowless: stale-mark the
// homepage (old crit keeps serving), regenerate through the real lanes, measure
// dispatch→land from the B7 stamps, verify the marker cleared; on timeout the marker
// is removed so serving state is exactly as before. One budgeted worker, bounded.
if (!function_exists('wpc_crit_selftest_run')) {
    function wpc_crit_selftest_report_file()
    {
        if (!defined('WPS_IC_CRITICAL')) {
            return '';
        }
        $d = rtrim(WPS_IC_CRITICAL, '/') . '/.kicklocks/';
        if (!is_dir($d)) {
            @mkdir($d, 0777, true);
        }
        return $d . 'selftest.json';
    }

    function wpc_crit_selftest_run($drill = false)
    {
        $t0 = time();
        $r  = ['t' => $t0, 'mode' => $drill ? 'drill' : 'preflight', 'verdict' => 'FAIL', 'hops' => [], 'latency_s' => null, 'notes' => []];
        try {
            $set = get_option(WPS_IC_SETTINGS);
            $opt = get_option(WPS_IC_OPTIONS);
            $r['hops']['crit_enabled'] = is_array($set) && !empty($set['critical']['css']) && $set['critical']['css'] == '1';
            $r['hops']['api_key'] = is_array($opt) && !empty($opt['api_key']);
            $hd = rtrim(WPS_IC_CRITICAL, '/') . '/.selftest-' . getmypid();
            @mkdir($hd, 0777, true);
            $r['hops']['store_writable'] = function_exists('wpc_crit_meta_write')
                && wpc_crit_meta_write($hd . '/x.txt', 'ok') && trim((string) @file_get_contents($hd . '/x.txt')) === 'ok';
            foreach ((array) @glob($hd . '/*') as $hf) {
                @unlink($hf);
            }
            @rmdir($hd);
            $k    = ltrim((string) (new wps_ic_url_key())->setup(home_url('/')), '/');
            $dir  = rtrim(WPS_IC_CRITICAL, '/') . '/' . $k . '/';
            $apikey = is_array($opt) && !empty($opt['api_key']) ? (string) $opt['api_key'] : '';
            $ptr = $apikey !== '' ? wpc_crit_pointer_url($apikey, home_url('/')) : '';
            if ($ptr !== '') {
                $pr  = wp_remote_get($ptr, ['timeout' => 4]);
                $r['hops']['pointer_http'] = is_wp_error($pr) ? 0 : (int) wp_remote_retrieve_response_code($pr);
            }
            if (defined('WPS_IC_CRITICAL_API_URL')) {
                $sr = wp_remote_get(str_replace('/generate', '/status', WPS_IC_CRITICAL_API_URL) . '?uuid=selftest', ['timeout' => 4]);
                $r['hops']['service_http'] = is_wp_error($sr) ? 0 : (int) wp_remote_retrieve_response_code($sr);
            }
            $whk = (int) @file_get_contents(rtrim(WPS_IC_CRITICAL, '/') . '/.kicklocks/whk_last.txt');
            $r['hops']['webhook_seen_s'] = $whk > 0 ? (time() - $whk) : -1;
            $r['hops']['backoff']      = function_exists('wpc_gen_backoff_active') && wpc_gen_backoff_active();
            $r['hops']['parked_home']  = function_exists('wpc_gen_landless_parked') && wpc_gen_landless_parked($k);
            $r['hops']['detach']       = function_exists('fastcgi_finish_request') || function_exists('litespeed_finish_request');
            $r['hops']['crit_on_disk'] = @filesize($dir . 'critical_desktop.css') > 64;
            $r['hops']['last_land_age_s'] = ($wpc_ll = (int) @file_get_contents($dir . 'land_ts.txt')) > 0 ? (time() - $wpc_ll) : -1;

            $preOk = $r['hops']['crit_enabled'] && $r['hops']['api_key'] && $r['hops']['store_writable'];
            if (!$drill) {
                $r['verdict'] = $preOk ? 'PASS-PREFLIGHT' : 'FAIL';
                return $r;
            }
            // DRILL START (zero-held-workers): stale-mark + the real purge-regen lane +
            // probe bursts; the verdict materializes in the stamps and the POLL endpoint
            // computes it. No sleeping worker, works on every SAPI.
            if (!$preOk || !class_exists('wps_criticalCss')) {
                $r['notes'][] = 'preflight-failed';
                return $r;
            }
            wpc_crit_meta_write($dir . 'stale.txt', (string) $t0);
            if (function_exists('wpc_crit_purge_redispatch')) {
                wpc_crit_purge_redispatch();
            }
            $r['verdict'] = 'RUNNING';
            $r['deadline'] = $t0 + (int) apply_filters('wpc_selftest_budget', 150);
            $r['key'] = $k;
            return $r;
        } catch (\Throwable $e) {
            $r['notes'][] = 'exception: ' . substr($e->getMessage(), 0, 120);
            return $r;
        }
    }

    /** Poll-side finalize: PASS/FAIL computed from the on-disk stamps; FAIL restores serving state. */
    function wpc_crit_selftest_finalize($rep)
    {
        try {
            if (!is_array($rep) || ($rep['verdict'] ?? '') !== 'RUNNING' || empty($rep['key'])) {
                return $rep;
            }
            $dir = rtrim(WPS_IC_CRITICAL, '/') . '/' . $rep['key'] . '/';
            $t0  = (int) ($rep['t'] ?? 0);
            $lts = (int) @file_get_contents($dir . 'land_ts.txt');
            if ($lts >= $t0 && !@is_file($dir . 'stale.txt')) {
                $dts = (int) @file_get_contents($dir . 'dispatch_ts.txt');
                $rep['latency_s'] = ($dts >= $t0) ? max(0, $lts - $dts) : null;
                $rep['hops']['landed'] = true;
                $rep['verdict'] = 'PASS';
            } elseif (time() > (int) ($rep['deadline'] ?? 0)) {
                @unlink($dir . 'stale.txt'); // restore serving state exactly as before
                // The landed artifact may BE the latest published (service debounced the
                // regen — nothing newer exists to land). That is freshness, not failure.
                $pointer_uuid = '';
                try {
                    $options = get_option(WPS_IC_OPTIONS);
                    $api_key = is_array($options) && !empty($options['api_key']) ? (string) $options['api_key'] : '';
                    $pointer_url = wpc_crit_pointer_url($api_key, home_url('/'));
                    if ($pointer_url !== '') {
                        $pointer_response = wp_remote_get($pointer_url, ['timeout' => 4]);
                        if (!is_wp_error($pointer_response) && (int) wp_remote_retrieve_response_code($pointer_response) === 200) {
                            $pointer_json = json_decode((string) wp_remote_retrieve_body($pointer_response), true);
                            $pointer_uuid = is_array($pointer_json) ? preg_replace('/[^a-f0-9-]/i', '', (string) ($pointer_json['crit_uuid'] ?? '')) : '';
                        }
                    }
                } catch (\Throwable $e) {
                }
                if ($pointer_uuid !== '' && $pointer_uuid === trim((string) @file_get_contents($dir . 'land_uuid.txt'))) {
                    $rep['verdict'] = 'PASS-FRESH';
                    $rep['notes'][] = 'landed artifact IS the latest published (service debounced the regen)';
                } else {
                    $rep['verdict'] = 'FAIL';
                    $rep['notes'][] = 'no-land-within-budget; pointer_http=' . (int) ($rep['hops']['pointer_http'] ?? 0)
                        . ' (200 = service published → plugin pickup at fault; else service generate side)';
                }
            }
            if (($rep['verdict'] ?? '') !== 'RUNNING') {
                $f = wpc_crit_selftest_report_file();
                if ($f !== '') {
                    wpc_crit_meta_write($f, (string) wp_json_encode($rep));
                }
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('selftest', (string) $rep['verdict'], '', ['s' => $rep['latency_s'] ?? null, 'drill' => 1]);
                }
            }
            return $rep;
        } catch (\Throwable $e) {
            return $rep;
        }
    }

    function wpc_crit_selftest_rx()
    {
        try {
            $tok = isset($_GET['t']) && defined('WPC_PERF_DEBUG_TOKEN') && hash_equals((string) WPC_PERF_DEBUG_TOKEN, (string) $_GET['t']);
            if (!(function_exists('current_user_can') && current_user_can('manage_options')) && !$tok) {
                status_header(403);
                echo 'x';
                exit;
            }
            // v7.10.379 TRACE (read-only cross-team debug, &trace=1): this key's landing lifecycle
            // — gen uuid (the service's join key), artifact inventory + quality flags, and the cflog
            // hop timeline with per-hop deltas. Pure disk reads, bounded; no side effects. &k= a
            // non-home URL, &all=1 unfiltered stream, &tail=N rows.
            if (isset($_GET['trace'])) {
                $tk = isset($_GET['k']) && (string) $_GET['k'] !== ''
                    ? ltrim((string) (new wps_ic_url_key())->setup((string) strtok((string) $_GET['k'], '?')), '/')
                    : ltrim((string) (new wps_ic_url_key())->setup(home_url('/')), '/');
                if ($tk === '' || (function_exists('wpc_pipeline_key_junk') && wpc_pipeline_key_junk($tk))) {
                    $tk = ltrim((string) (new wps_ic_url_key())->setup(home_url('/')), '/');
                }
                $tdir = rtrim(WPS_IC_CRITICAL, '/') . '/' . $tk . '/';
                $tnow = time();
                $trd  = function ($f) { return @is_readable($f) ? (string) @file_get_contents($f) : ''; };
                $tart = function ($file) use ($tdir, $tnow) {
                    $p = $tdir . $file; $ex = @is_readable($p);
                    return ['exists' => (bool) $ex, 'bytes' => $ex ? (int) @filesize($p) : 0, 'age_s' => $ex ? max(0, $tnow - (int) @filemtime($p)) : -1];
                };
                $tdelay = $tart('delay.json');
                if ($tdelay['exists'] && class_exists('wps_ic_js_delay_v3')) {
                    $tdj = json_decode($trd($tdir . 'delay.json'), true);
                    $tdelay['measured'] = is_array($tdj) && wps_ic_js_delay_v3::wpc_delay_measured_shape($tdj);
                }
                $tlcp = $tart('lcp.json'); $tlcp['none'] = @is_readable($tdir . 'lcp_none.txt'); $tlcp['preload'] = [];
                if ($tlcp['exists']) {
                    $tlj = json_decode($trd($tdir . 'lcp.json'), true);
                    if (is_array($tlj) && !empty($tlj['hints']['lcp_preload']) && is_array($tlj['hints']['lcp_preload'])) {
                        foreach ($tlj['hints']['lcp_preload'] as $tlp) {
                            if (!is_array($tlp)) { continue; }
                            $tlcp['preload'][] = ['device' => (string) ($tlp['device'] ?? 'both'),
                                'url_is_authoritative' => array_key_exists('url_is_authoritative', $tlp) ? (bool) $tlp['url_is_authoritative'] : true];
                        }
                    }
                }
                $ttl = [];
                if (function_exists('wpc_cflog_tail')) {
                    $ttail = wpc_cflog_tail(131072);
                    $tall = isset($_GET['all']); $tprev = null;
                    foreach (explode("\n", $ttail) as $tln) {
                        if ($tln === '') { continue; }
                        $te = json_decode($tln, true);
                        if (!is_array($te) || !isset($te['event'])) { continue; }
                        if (!$tall && (string) ($te['key'] ?? '') !== $tk) { continue; }
                        $trow = ['t' => (int) ($te['t'] ?? 0), 'event' => (string) $te['event'], 'layers' => $te['layers'] ?? []];
                        $trow['dt_s'] = $tprev === null ? 0 : ((int) $trow['t'] - $tprev);
                        $tprev = (int) $trow['t']; $ttl[] = $trow;
                    }
                    $ttl = array_slice($ttl, -(int) (isset($_GET['tail']) ? max(1, min(300, (int) $_GET['tail'])) : 80));
                }
                $twhk = (int) $trd(rtrim(WPS_IC_CRITICAL, '/') . '/.kicklocks/whk_last.txt');
                $tdts = (int) $trd($tdir . 'dispatch_ts.txt'); $tlts = (int) $trd($tdir . 'land_ts.txt');
                // v7.10.688 — the wire block. §8(c)/§8.1 read wire.json at render and no endpoint
                // surfaced it, so "is the manifest carrying the instruction?" was answerable on
                // neither side of the fence (the .687 Roboto/hero standstill). held_url vs
                // declared_url is the §2 dedupe key — a mismatch means declared-but-not-held
                // (wpc_wire_catchup's case). Per-device counts + the drop families + lcp verdict
                // are the two consumers' entire decision surface. Pure disk reads.
                $twp = function_exists('wpc_wire_provenance') ? wpc_wire_provenance($tk)
                    : ['rev' => 0, 'sig' => '', 'url' => '', 'scope' => 'url', 'material_rev' => 0, 'epoch' => 0];
                $twire = [
                    'declared_rev' => (int) $twp['rev'], 'declared_url' => (string) $twp['url'],
                    'held_url' => trim($trd($tdir . 'wire.held_url')),
                    'material_rev' => (int) $twp['material_rev'], 'epoch' => (int) $twp['epoch'],
                    'scope' => (string) $twp['scope'], 'file' => $tart('wire.json'),
                ];
                $twj = $twire['file']['exists'] ? json_decode($trd($tdir . 'wire.json'), true) : null;
                if (is_array($twj) && !empty($twj['wire']) && is_array($twj['wire'])) {
                    foreach (['mobile', 'desktop'] as $twd) {
                        $twn = (isset($twj['wire'][$twd]) && is_array($twj['wire'][$twd])) ? $twj['wire'][$twd] : [];
                        $twdrops = (isset($twn['drop']) && is_array($twn['drop'])) ? $twn['drop'] : [];
                        $twfams = [];
                        foreach ($twdrops as $twdr) {
                            if (is_array($twdr) && ($twdr['class'] ?? '') === 'font-family' && !empty($twdr['family'])) {
                                $twfams[] = strtolower((string) $twdr['family']);
                            }
                        }
                        $twire[$twd] = [
                            'allow' => isset($twn['allow']) && is_array($twn['allow']) ? count($twn['allow']) : 0,
                            'defer' => isset($twn['defer']) && is_array($twn['defer']) ? count($twn['defer']) : 0,
                            'drop'  => count($twdrops), 'drop_families' => $twfams,
                            'lcp_verdict' => (isset($twn['lcp']['verdict']) && is_string($twn['lcp']['verdict']))
                                ? $twn['lcp']['verdict'] : null,
                        ];
                    }
                }
                status_header(200);
                @header('Content-Type: application/json');
                echo wp_json_encode([
                    'site' => (string) parse_url(home_url('/'), PHP_URL_HOST),
                    'ver'  => defined('WPC_PLUGIN_VERSION') ? WPC_PLUGIN_VERSION : '',
                    'now'  => $tnow, 'key' => $tk,
                    'uuid' => ['on_disk' => trim($trd($tdir . 'uuid.txt')), 'land_uuid' => trim($trd($tdir . 'land_uuid.txt'))],
                    // Atomic Contract canary surface (v7.10.697): which path owns this key and
                    // which generation the manifest hold names — diff against the service's
                    // pointer read; a mismatch names the owning side in one look.
                    'manifest' => [
                        'held_gen' => trim($trd($tdir . 'manifest.held_gen')),
                        'present'  => @is_readable($tdir . 'manifest.json'),
                        'mode'     => function_exists('wpc_manifest_mode') ? (wpc_manifest_mode($tk) !== '') : false,
                    ],
                    // Verified Copy Contract surface (v7.10.700): last refusal + storm state —
                    // one look answers "why is the edge not filling?" / "did a bad copy sneak in?"
                    'admission' => (array) get_option('wpc_admission_state700', []),
                    'wire' => $twire,
                    'artifacts' => [
                        'crit_desktop'  => $tart('critical_desktop.css'),
                        'crit_mobile'   => $tart('critical_mobile.css'),
                        'crit_combined' => $tart('critical_combined.css'),
                        'delay' => $tdelay, 'lcp' => $tlcp, 'prescriptions' => $tart('prescriptions.json'),
                    ],
                    'locators' => [
                        'delay_url'    => trim($trd($tdir . 'delay_url.txt')) !== '',
                        'lcp_url'      => trim($trd($tdir . 'lcp_url.txt')) !== '',
                        'fonts_url'    => trim($trd($tdir . 'fonts_url.txt')) !== '',
                        'fonts_none'   => @is_readable($tdir . 'fonts_none.txt'),
                        'used_css_url' => trim($trd($tdir . 'used_css_url.txt')) !== '',
                    ],
                    'stamps' => [
                        // raw last-write stamps — NOT gen-scoped (dispatch_ts/land_ts can be
                        // different gens, so a derived delta lies). Authoritative per-gen
                        // dispatch->serve latency is the ledger's (uuid-joined + serve-probe);
                        // honest hop spacing is the timeline dt_s below.
                        'dispatch_ts' => $tdts ?: null, 'land_ts' => $tlts ?: null,
                        'note' => 'last-write, not gen-scoped',
                    ],
                    'webhook' => ['last_seen_s' => $twhk > 0 ? ($tnow - $twhk) : -1, 'dedupe_key' => 'uuid|ts'],
                    'timeline' => $ttl,
                ]);
                exit;
            }
            // REFETCH (v7.10.327): re-consume held/amended shelf artifacts without FTP.
            // &refetch=fonts → drop the local subset+metrics so the fonts leg refetches
            //   the (possibly re-amended) fonts_url on the next kick — crit embeds keep
            //   carrying first paint meanwhile.
            // &refetch=crit → drop land_uuid.txt only; the collector force-pulls the held
            //   uuid and OVERWRITES in place (atomic rename — never a critless window).
            // &refetch=used → clear the one-shot fetch gates and re-pull the stored
            //   used-css bundles inline (amended shelf bytes can differ at identical
            //   length), then rotate page copies exactly like a land would.
            // Optional &k= targets a non-home key (junk-gated); default homepage.
            // &refetch=resync → the one-click full close: stale-mark everything (pages
            //   keep serving), clear every gate/backoff, force a fresh dispatch, pull all
            //   lanes now, and self-schedule follow-up waves for the observe-leg artifacts.
            $refetchWhat = isset($_GET['refetch']) ? sanitize_key((string) $_GET['refetch']) : '';
            $isResync = ($refetchWhat === 'resync');
            if ($isResync) {
                $refetchWhat = 'all';
            }
            if ($refetchWhat !== '' && in_array($refetchWhat, ['fonts', 'crit', 'used', 'all'], true)) {
                $refetchUrlKey = isset($_GET['k']) ? sanitize_text_field((string) $_GET['k'])
                    : ltrim((string) (new wps_ic_url_key())->setup(home_url('/')), '/');
                if ($refetchUrlKey === '' || (function_exists('wpc_pipeline_key_junk') && wpc_pipeline_key_junk($refetchUrlKey))) {
                    status_header(200);
                    echo '{"error":"bad-key"}';
                    exit;
                }
                $refetchDir = rtrim(WPS_IC_CRITICAL, '/') . '/' . $refetchUrlKey . '/';
                $refetchDone = [];
                // Captured BEFORE the crit branch unlinks land_uuid.txt (all-mode ordering);
                // identity law: a bare uuid without its dispatch stamp is borrowed state.
                $stampUuid = trim((string) @file_get_contents($refetchDir . 'land_uuid.txt'));
                if ($stampUuid === '' && @is_readable($refetchDir . 'dispatch_ts.txt')) {
                    $stampUuid = trim((string) @file_get_contents($refetchDir . 'uuid.txt'));
                }
                if ($isResync) {
                    if (function_exists('wpc_crit_invalidate')) {
                        wpc_crit_invalidate('all', 'pull-latest', 'stale');
                    }
                    delete_option('wpc_gen_sf_global');
                    delete_option('wpc_gen_sf_' . $refetchUrlKey);
                    delete_transient('wpc_collarm_' . md5((string) $refetchUrlKey));
                    delete_transient('wpc_kick_fire_' . md5((string) $refetchUrlKey));
                    if (function_exists('wpc_kick_lockfile')) {
                        @unlink(wpc_kick_lockfile($refetchUrlKey, 'recv'));
                        @unlink(wpc_kick_lockfile($refetchUrlKey, 'fire'));
                    }
                    // Pull Latest force-gens with sync=1 (v7.10.357) — threaded through the
                    // redispatch cron arg + detached runner (NOT a shared transient, which
                    // leaked the blocking full-sync onto visitor kicks). sync=1 makes the
                    // service SKIP its template cache and grind a genuinely fresh, current-
                    // schema gen (ceiling / hints / verified-unique prescriptions) — without
                    // it, resync re-pulls the SAME stale tpl-cached artifact (staging receipt:
                    // 48's morning gen had no ceiling until a sync=1 gen busted the cache).
                    if (function_exists('wpc_crit_purge_redispatch')) {
                        wpc_crit_purge_redispatch(true); // operator force-sync, detached runner
                    }
                    foreach ([150, 330] as $waveDelay) {
                        wpc_pl_sched(time() + $waveDelay, 'wpc_crit_resync_wave', [$refetchUrlKey, (int) $waveDelay]);
                    }
                    $refetchDone[] = 'resync-armed';
                }
                if ($refetchWhat === 'fonts' || $refetchWhat === 'all') {
                    @unlink($refetchDir . 'font-subsets.css');
                    @unlink($refetchDir . 'font-metrics.json');
                    $refetchDone[] = 'fonts';
                }
                if ($refetchWhat === 'used' || $refetchWhat === 'all') {
                    // prescriptions re-consume rides the used refetch: drop the stored file
                    // + gates so the next kick pulls the (possibly re-amended) shelf copy.
                    @unlink($refetchDir . 'prescriptions.json');
                    @unlink($refetchDir . 'prescriptions_etag.txt');
                    delete_transient('wpc_prescfetch_' . md5((string) $refetchUrlKey));
                    delete_transient('wpc_prescpoll_' . md5((string) $refetchUrlKey));
                    if (function_exists('wpc_presc_on_land')) {
                        wpc_presc_on_land($refetchUrlKey);
                    }
                    $refetchDone[] = 'presc';
                }
                $critLanded = null;
                if ($refetchWhat === 'crit' || $refetchWhat === 'all') {
                    @unlink($refetchDir . 'land_uuid.txt');
                    // Manifest-path escape hatch (v7.10.697): the crit drill also drops the
                    // manifest hold, reverting the key to the legacy flow until the next
                    // generation_complete webhook re-establishes it.
                    @unlink($refetchDir . 'manifest.held_gen');
                    @unlink($refetchDir . 'manifest.json');
                    if (function_exists('wpc_crit_collector_arm')) {
                        wpc_crit_collector_arm($refetchUrlKey);
                    }
                    if (function_exists('wpc_crit_collect_now')) {
                        $critLanded = (bool) wpc_crit_collect_now($refetchUrlKey, 1); // one bounded inline probe
                    }
                    $refetchDone[] = 'crit';
                }
                if ($refetchWhat === 'used' || $refetchWhat === 'all') {
                    // URL metas are ARTIFACTS (purges delete them; identity survives) — when
                    // absent, derive the shelf URLs. POINTER FIRST: a refetch means "give me
                    // what the service currently publishes", and staged corrections can live
                    // on a held uuid the local stamps have already moved past (hawkeye
                    // receipt: stamps → morning gen, corrected used.css → pointer's uuid).
                    // Local stamps are the fallback when the pointer is unreachable.
                    // NOTE: stamps were captured early ($wpc_uid333) — the crit branch above
                    // unlinks land_uuid.txt in 'all' mode.
                    $usedBaseUrl = '';
                    $pointerUsedBase = '';
                    $usedBaseSource = '';
                    {
                        $options = get_option(WPS_IC_OPTIONS);
                        $apiKey = is_array($options) && !empty($options['api_key']) ? (string) $options['api_key'] : '';
                        $pageUrl = trim((string) @file_get_contents($refetchDir . 'url.txt'));
                        if ($pageUrl === '' && ltrim((string) (new wps_ic_url_key())->setup(home_url('/')), '/') === ltrim((string) $refetchUrlKey, '/')) {
                            $pageUrl = home_url('/'); // A8 law: home fallback only for the home key
                        }
                        if ($apiKey !== '' && $pageUrl !== '') {
                            $pointerUrl = wpc_crit_pointer_url($apiKey, $pageUrl);
                            if ($pointerUrl !== '') {
                                $pointerResponse = wp_remote_get($pointerUrl, ['timeout' => 4, 'user-agent' => defined('WPS_IC_API_USERAGENT') ? WPS_IC_API_USERAGENT : '']);
                                if (!is_wp_error($pointerResponse) && (int) wp_remote_retrieve_response_code($pointerResponse) === 200) {
                                    $pointerJson = json_decode((string) wp_remote_retrieve_body($pointerResponse), true);
                                    $pointerUuid = is_array($pointerJson) ? preg_replace('/[^a-f0-9-]/i', '', (string) ($pointerJson['crit_uuid'] ?? '')) : '';
                                    if (strlen($pointerUuid) >= 8) {
                                        $usedBaseUrl = 'https://critical-css-mc.b-cdn.net/' . substr($pointerUuid, 0, 4) . '/' . $pointerUuid;
                                        $usedBaseSource = 'ptr';
                                        if (is_array($pointerJson) && (int) ($pointerJson['has_used_css'] ?? 0) === 1) {
                                            $pointerUsedBase = $usedBaseUrl;
                                            $usedBaseSource = 'ptr-used';
                                        }
                                    }
                                }
                            }
                        }
                    }
                    if ($usedBaseUrl === '' && preg_match('/^[0-9a-f-]{8,}$/i', (string) $stampUuid)) {
                        $usedBaseUrl = 'https://critical-css-mc.b-cdn.net/' . substr($stampUuid, 0, 4) . '/' . $stampUuid;
                        $usedBaseSource = 'stamp';
                    }
                    // Crit lands are ASYNC — during the click land_uuid.txt still holds the
                    // PREVIOUS gen, so a pointer that advertises used files (has_used_css:1,
                    // truthful since the kick carries the capability) outranks the live stamp.
                    // The stamp still wins when the pointer lacks used files or timed out.
                    $liveUuid = trim((string) @file_get_contents($refetchDir . 'land_uuid.txt'));
                    if ($pointerUsedBase === '' && preg_match('/^[0-9a-f-]{8,}$/i', $liveUuid)) {
                        $usedBaseUrl = 'https://critical-css-mc.b-cdn.net/' . substr($liveUuid, 0, 4) . '/' . $liveUuid;
                        $usedBaseSource = 'land';
                    }
                    // Operator override (temporary until the service advertises used_css=1 on
                    // the kick so every gen mints its own bundle): &used_uuid=<uuid> pulls the
                    // known-good used bundle by uuid — a fresh gen with real used files later
                    // supersedes it organically. One-shot, no persistence, no FTP.
                    $overrideUuid = isset($_GET['used_uuid']) ? preg_replace('/[^0-9a-f-]/i', '', (string) $_GET['used_uuid']) : '';
                    if (strlen($overrideUuid) >= 8) {
                        $usedBaseUrl = 'https://critical-css-mc.b-cdn.net/' . substr($overrideUuid, 0, 4) . '/' . $overrideUuid;
                        $usedBaseSource = 'override';
                    }
                    $tplKey = '';
                    foreach (['tpl.txt', 'used_tpl.txt'] as $tplFile) {
                        $tplValue = trim((string) @file_get_contents($refetchDir . $tplFile));
                        if (function_exists('wpc_used_css_key_valid') && wpc_used_css_key_valid($tplValue)) {
                            $tplKey = $tplValue;
                            break;
                        }
                    }
                    if ($tplKey === '') {
                        // Page-dir identity missing (pre-.327 installs / service rows with
                        // tpl_key=None): recover the key from the newest store file itself.
                        $newestMtime = 0;
                        foreach ((array) @glob(rtrim(WPS_IC_CRITICAL, '/') . '/used-css/tpl-*.css') as $storeFile) {
                            $storeName = basename($storeFile);
                            if (!preg_match('/^tpl-([0-9a-f]{16})\.css$/', $storeName, $storeMatch)) {
                                continue;
                            }
                            $storeMtime = (int) @filemtime($storeFile);
                            if ($storeMtime > $newestMtime) {
                                $newestMtime = $storeMtime;
                                $tplKey = 'tpl:' . $storeMatch[1];
                            }
                        }
                    }
                    $usedPulled = [];
                    $usedDebug = ['tpl' => $tplKey, 'base' => substr((string) $usedBaseUrl, 0, 90), 'base_src' => $usedBaseSource];
                    if ($tplKey !== '' && function_exists('wpc_used_css_fetch') && function_exists('wpc_used_css_path')) {
                        $shelfSuffixes = ['union' => '.used.css', 'mobile' => '.used-mobile.css', 'desktop' => '.used-desktop.css'];
                        foreach (['union' => ['', 'used_css_url.txt'], 'mobile' => ['mobile', 'used_css_mobile_url.txt'], 'desktop' => ['desktop', 'used_css_desktop_url.txt']] as $lane => $laneSpec) {
                            $metaRaw = trim((string) @file_get_contents($refetchDir . $laneSpec[1]));
                            $usedUrl = $metaRaw;
                            if ($usedUrl !== '' && !preg_match('#^https?://#i', $usedUrl)) {
                                $usedUrl = ''; // 'None'/junk meta (service-side null serialization) — derive instead
                            }
                            $usedUrlSource = $usedUrl !== '' ? 'meta' : 'none';
                            if ($usedUrl !== '' && $usedBaseUrl !== '' && strpos($usedUrl, basename($usedBaseUrl)) === false) {
                                $usedUrl = ''; // meta uuid ≠ the generation that just landed — stale by definition
                                $usedUrlSource = 'meta-stale';
                            }
                            if ($usedUrl === '' && $usedBaseUrl !== '') {
                                $usedUrl = $usedBaseUrl . $shelfSuffixes[$lane] . '?t=' . time(); // ?t= — Bunny negative-caches premature 404s
                                $usedUrlSource = ($usedUrlSource === 'meta-stale') ? 'derived-over-stale-meta' : 'derived';
                            }
                            $storePath = $usedUrl !== '' ? wpc_used_css_path($tplKey, $laneSpec[0]) : '';
                            if ($storePath === '') {
                                continue;
                            }
                            delete_transient('wpc_ucsr266_' . md5($storePath));
                            delete_transient('wpc_ucsp_' . md5($storePath));
                            $mtimeBefore = (int) @filemtime($storePath);
                            $fetchWhy = '';
                            $usedPulled[$lane] = (bool) wpc_used_css_fetch($usedUrl, $tplKey, $laneSpec[0], $fetchWhy);
                            $usedDebug[$lane] = [
                                'src' => $usedUrlSource, 'meta_raw' => substr($metaRaw, 0, 70),
                                'url' => substr((string) $usedUrl, 0, 110), 'why' => (string) $fetchWhy,
                                'ok' => $usedPulled[$lane],
                                'mtime_before' => $mtimeBefore, 'mtime_after' => (int) @filemtime($storePath),
                            ];
                            // Unconditional on success — a pointer-first pull that leaves the
                            // OLD uuid in the meta gets reverted by the next meta-driven
                            // re-pull (waves/kick legs fetch the stale address and overwrite).
                            if ($usedPulled[$lane] && $usedBaseSource !== 'override' && function_exists('wpc_crit_meta_write')) {
                                // override stays one-shot — persisting it would let repull
                                // waves re-fetch a hand-pasted uuid forever.
                                wpc_crit_meta_write($refetchDir . $laneSpec[1], (string) strtok($usedUrl, '?'));
                            }
                        }
                    }
                    if (!empty(array_filter($usedPulled))) {
                        if (!function_exists('wpc_used_css_scoped_purge') || !wpc_used_css_scoped_purge($tplKey)) {
                            try { wps_ic_cache::removeHtmlCacheFiles('all', '', '', 'soft'); } catch (\Throwable $e) {}
                        }
                    }
                    $refetchDone[] = 'used:' . ($tplKey === '' ? 'no-tpl-key' : (empty($usedPulled) ? 'no-urls' : implode(',', array_keys(array_filter($usedPulled)))));
                }
                delete_transient('wpc_repull_kick_' . md5($refetchUrlKey));
                if (function_exists('wpc_repull_kick_now')) {
                    wpc_repull_kick_now($refetchUrlKey, false, 'refetch'); // fonts leg refetches on the kicked repull
                }
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('refetch', $refetchUrlKey, '', ['what' => implode(',', $refetchDone), 'landed' => $critLanded]);
                }
                status_header(200);
                header('Content-Type: application/json');
                echo wp_json_encode(['refetch' => $refetchDone, 'key' => $refetchUrlKey, 'crit_repulled' => $critLanded,
                    'used_dbg' => isset($usedDebug) ? $usedDebug : null,
                    'note' => 'fonts re-land async within ~60s of the kick; poll perf-debug fonts/land lines']);
                exit;
            }

            $f = wpc_crit_selftest_report_file();
            if (empty($_GET['run'])) {
                // POLL: finalizes a RUNNING drill from the stamps (and self-restores on timeout).
                $rep = json_decode(($f !== '' && @is_readable($f)) ? (string) @file_get_contents($f) : '', true);
                if (is_array($rep) && ($rep['verdict'] ?? '') === 'RUNNING' && function_exists('wpc_crit_selftest_finalize')) {
                    $rep = wpc_crit_selftest_finalize($rep);
                }
                status_header(200);
                header('Content-Type: application/json');
                echo is_array($rep) ? wp_json_encode($rep) : '{"verdict":"NEVER-RUN"}';
                exit;
            }
            $prev = json_decode(($f !== '' && @is_readable($f)) ? (string) @file_get_contents($f) : '', true);
            if (is_array($prev) && ($prev['verdict'] ?? '') === 'RUNNING' && time() <= (int) ($prev['deadline'] ?? 0)) {
                status_header(200);
                echo '{"verdict":"ALREADY-RUNNING"}';
                exit;
            }
            // Start (preflight or drill) is a sub-second request — no worker held, any SAPI.
            $rep = wpc_crit_selftest_run(!empty($_GET['drill']));
            if ($f !== '') {
                wpc_crit_meta_write($f, (string) wp_json_encode($rep));
            }
            if (function_exists('wpc_cache_first_log')) {
                wpc_cache_first_log('selftest', (string) $rep['verdict'], '', ['drill' => empty($_GET['drill']) ? 0 : 1]);
            }
            status_header(200);
            header('Content-Type: application/json');
            echo wp_json_encode($rep);
            exit;
        } catch (\Throwable $e) {
            exit;
        }
    }
    add_action('wp_ajax_wpc_crit_selftest', 'wpc_crit_selftest_rx');
    add_action('wp_ajax_nopriv_wpc_crit_selftest', 'wpc_crit_selftest_rx');
}


if (!function_exists('wpc_cflog_read')) {
    function wpc_cflog_read($n = 40)
    {
        $out = function_exists('wpc_cflog_entries') ? wpc_cflog_entries(32768) : [];
        if (!empty($out)) {
            return array_slice($out, -$n);
        }
        return array_slice((array) get_option('wpc_cache_first_log', []), -$n);
    }
}


if (!function_exists('wpc_cflog_viewer')) {
    function wpc_cflog_viewer()
    {
        if (!current_user_can('manage_options') && !current_user_can('manage_wpc_settings')) {
            wp_send_json_error('forbidden', 403);
        }
        $log = function_exists('wpc_cflog_read') ? wpc_cflog_read(40) : (array) get_option('wpc_cache_first_log', []);
        foreach ($log as &$e) {
            if (isset($e['t'])) {
                $e['time'] = gmdate('H:i:s', (int) $e['t']) . 'Z';
            }
        }
        wp_send_json_success(array_reverse($log));
    }
    add_action('wp_ajax_wpc_cflog', 'wpc_cflog_viewer');

    /**
     * GET admin-ajax.php?action=wpc_cflog_tail&wps_ic_nonce=…&lines=N&since=<unix time>: the raw
     * log lines (JSONL, oldest first) for an admin. The log stopped being readable over HTTP when
     * it became wpc-cflog.php (it carried crit uuids and key prefixes, world-readable on
     * webdesign4u.com.au); staging A/B and customer reads fetched that URL. A read: no receipt.
     */
    function wpc_cflog_tail_ajax()
    {
        $nonce = isset($_REQUEST['wps_ic_nonce']) ? (string) $_REQUEST['wps_ic_nonce'] : '';
        if (!current_user_can('manage_wpc_settings') || !wp_verify_nonce($nonce, 'wps_ic_nonce_action')) {
            wp_send_json_error('forbidden', 403);
        }
        $lines = isset($_GET['lines']) ? (int) $_GET['lines'] : 500;
        $since = isset($_GET['since']) ? (int) $_GET['since'] : 0;
        $body = function_exists('wpc_cflog_lines') ? wpc_cflog_lines($lines, $since) : [];
        nocache_headers();
        header('Content-Type: application/x-ndjson; charset=utf-8');
        echo $body ? implode("\n", $body) . "\n" : '';
        wp_die('', '', ['response' => 200]);
    }
    add_action('wp_ajax_wpc_cflog_tail', 'wpc_cflog_tail_ajax');

}


if (!function_exists('wpc_normalize_font_face_fallback')) {
    // v7.21.148 — "Fonts, settled" §2A + Tier 0 unblock. The v3.198.129 fonts.json nests the
    // verdict under a per-face fallback{} object (validated, fallback_stack, size_adjust...)
    // while the consume read face-level keys only — so 'smart' never saw validated (measured
    // optional count = 0) and metric rows starved. Normalize: lift nested validated; map the
    // underscore metric names to the hyphen names every consumer checks; carry fallback_stack
    // (whitelisted, max 5) and default 'local' to the stack head.
    function wpc_normalize_font_face_fallback($fe)
    {
        try {
            if (!is_array($fe)) {
                return $fe;
            }
            $fb = (!empty($fe['fallback']) && is_array($fe['fallback'])) ? $fe['fallback'] : null;
            if ($fb === null) {
                return $fe;
            }
            if (empty($fe['validated']) && !empty($fb['validated'])) {
                $fe['validated'] = true;
            }
            $row = (!empty($fe['metrics']) && is_array($fe['metrics'])) ? $fe['metrics'] : [];
            foreach (['size_adjust' => 'size-adjust', 'size-adjust' => 'size-adjust',
                      'ascent_override' => 'ascent-override', 'ascent-override' => 'ascent-override',
                      'descent_override' => 'descent-override', 'descent-override' => 'descent-override',
                      'line_gap_override' => 'line-gap-override', 'line-gap-override' => 'line-gap-override'] as $k => $h) {
                if (empty($row[$h]) && !empty($fb[$k]) && preg_match('/^[0-9.]+%$/', (string) $fb[$k])) {
                    $row[$h] = (string) $fb[$k];
                }
            }
            if (empty($row['fallback_stack']) && !empty($fb['fallback_stack']) && is_array($fb['fallback_stack'])) {
                $stack = [];
                foreach ($fb['fallback_stack'] as $n) {
                    if (is_string($n) && preg_match('/^[A-Za-z0-9 -]{2,32}$/', trim($n))) {
                        $stack[] = trim($n);
                    }
                    if (count($stack) >= 5) {
                        break;
                    }
                }
                if ($stack) {
                    $row['fallback_stack'] = $stack;
                    if (empty($row['local'])) {
                        $row['local'] = $stack[0];
                    }
                }
            }
            if (empty($row['local']) && !empty($fb['local']) && is_string($fb['local'])) {
                $row['local'] = $fb['local'];
            }
            if (!empty($row)) {
                $fe['metrics'] = $row;
            }
            return $fe;
        } catch (\Throwable $e) {
            return $fe;
        }
    }
}


if (!function_exists('wpc_font_metrics_from_evidence')) {
    function wpc_font_metrics_from_evidence($table)
    {
        try {
            if (!is_array($table) || !class_exists('wps_ic_url_key') || !defined('WPS_IC_CRITICAL')) {
                return $table;
            }
            static $wpc_ev = null;
            if ($wpc_ev === null) {
                $wpc_ev = [];
                $k = (new wps_ic_url_key())->setup('');
                $f = $k ? rtrim(WPS_IC_CRITICAL, '/') . '/' . $k . '/font-metrics.json' : '';
                if ($f && @is_readable($f)) {
                    $j = json_decode((string) @file_get_contents($f), true);
                    // v7.10.593 — SECOND READER OF THE SAME ARTIFACT, and the one with no
                    // validation window: it merges the decoded object straight into the metrics
                    // table. Unwrapped, a stamped envelope would enter as families named v/uuid/
                    // tpl_key/generated_at plus one called "families". It also runs at priority 5,
                    // ahead of the reader at 10, so fixing only that one would have left this the
                    // live path. function_exists guard: the helper is defined in its own block.
                    if (is_array($j) && function_exists('wpc_unwrap_font_metrics_payload')) {
                        $j = wpc_unwrap_font_metrics_payload($j, (string) $k);
                    }
                    if (is_array($j)) {
                        $wpc_ev = $j;
                    }
                }
            }
            return array_merge($wpc_ev, $table);
        } catch (\Throwable $e) {
            return $table;
        }
    }
    add_filter('wpc_font_fallback_metrics', 'wpc_font_metrics_from_evidence', 5);
}


