            if (is_array($d)) { $ev[] = $d; }
        }
        if (empty($ev)) { // DB fallback (wpc_cache_first_log writes here when the file path refuses)
            $log = get_option('wpc_cache_first_log', []);
            if (is_array($log)) { $ev = array_slice($log, -22); }
        }
        // v7.10.614 — LANE SPLIT, surfaced explicitly. It fires at most once a day while the
        // cflog runs hundreds of entries an hour, so the last-22 tail below would essentially
        // never contain it. "no split found" and "the detector has not run" are completely
        // different answers and must never look alike, so both are printed.
        $wpc_lane_split = null;
        if ($clines) {
            foreach (array_reverse(array_slice($clines, -4000)) as $wpc_cflog_line) {
                if (strpos($wpc_cflog_line, 'lane-split') === false) { continue; }
                $wpc_cflog_row = json_decode($wpc_cflog_line, true);
                if (is_array($wpc_cflog_row) && ($wpc_cflog_row['event'] ?? '') === 'lane-split') { $wpc_lane_split = $wpc_cflog_row; break; }
            }
        }
        $wpc_lane_split_ran = function_exists('get_transient') ? (bool) get_transient('wpc_lane_split613') : false;
        if ($wpc_lane_split === null) {
            $o[] = "LANE SPLIT: none recorded — "
                 . ($wpc_lane_split_ran
                    ? "detector HAS run this period and found no split (good)"
                    : "detector has NOT run yet: it needs a WARM or CRON request, and runs once per day. Trigger a warm, then re-check.");
        } else {
            $wpc_lane_layers = is_array($wpc_lane_split['layers'] ?? null) ? $wpc_lane_split['layers'] : [];
            $wpc_lane_split_age = max(0, time() - (int) ($wpc_lane_split['t'] ?? 0));
            $o[] = "LANE SPLIT: quiet=" . (int) ($wpc_lane_layers['quiet'] ?? 0)
                 . " hard=" . (int) ($wpc_lane_layers['hard'] ?? 0)
                 . " | " . $wpc_lane_split_age . "s ago"
                 . " | url=" . substr((string) ($wpc_lane_split['url'] ?? '-'), 0, 48);
            if (!empty($wpc_lane_layers['q'])) { $o[] = "  QUIET (dependent delayed, its framework sync — handlers never attach): " . $wpc_lane_layers['q']; }
            if (!empty($wpc_lane_layers['h'])) { $o[] = "  HARD  (dependent sync, its dependency delayed — runs before what it needs): " . $wpc_lane_layers['h']; }
        }
        $o[] = "--- cflog (last " . count($ev) . " land events; src=" . ($clines ? 'file' : 'db') . ") ---";
        foreach ($ev as $e) {
            if (is_array($e)) {
                $o[] = "  " . gmdate('H:i:s', (int) ($e['t'] ?? 0)) . " " . ($e['event'] ?? '?')
                     // 70 chars truncated diagnostic payloads to uselessness — the .441
                     // no-stem-match fields (uri/inhtml/qw/imgs) sat past a 60-char stem and
                     // were never readable. A log you cannot read is not instrumentation.
                     . (empty($e['layers']) ? '' : ' ' . substr(json_encode($e['layers']), 0,
                         (int) apply_filters('wpc_cflog_payload_chars', 560)));
            }
        }
        // AGGRESSIVE-FLIP DIAGNOSIS: the exact reason a page does/doesn't go
        // interaction-only — reads the same inputs the render flip reads, so it
        // names the blocker without guessing (added .368 for the busy stall).
        $o[] = "--- FLIP DIAGNOSIS ---";
        $wpc_fd_moff = (int) get_option('wpc_delay_v3_manifest_off', 0);
        $wpc_fd_aoff = (int) get_option('wpc_delay_aggr_off', 0);
        $wpc_fd_dj   = $cd !== '' ? $cd . 'delay.json' : '';
        $wpc_fd_djok = $wpc_fd_dj !== '' && @is_readable($wpc_fd_dj);
        $wpc_fd_ceil = false; $wpc_fd_rc = 'n/a'; $wpc_fd_mt = 0; $wpc_fd_epoch = 'absent'; $wpc_fd_measured = false; $wpc_fd_j = null;
        if ($wpc_fd_djok) {
            $wpc_fd_mt = (int) @filemtime($wpc_fd_dj);
            $wpc_fd_j  = json_decode((string) @file_get_contents($wpc_fd_dj), true);
            $wpc_fd_ceil = is_array($wpc_fd_j) && isset($wpc_fd_j['ceiling']) && is_array($wpc_fd_j['ceiling']);
            if (is_array($wpc_fd_j) && isset($wpc_fd_j['schema_epoch'])) { $wpc_fd_epoch = (string) (int) $wpc_fd_j['schema_epoch']; }
            $wpc_fd_rc = 'absent';
            foreach ([$wpc_fd_j, $wpc_fd_j['mobile'] ?? null, $wpc_fd_j['desktop'] ?? null] as $wpc_fd_s) {
                if (is_array($wpc_fd_s) && isset($wpc_fd_s['render_critical']) && is_array($wpc_fd_s['render_critical'])) {
                    $wpc_fd_rc = 'present(' . count($wpc_fd_s['render_critical']) . ')'; break;
                }
            }
            $wpc_fd_measured = class_exists('wps_ic_js_delay_v3') && wps_ic_js_delay_v3::wpc_delay_measured_shape($wpc_fd_j);
        }
        // Evaluate for the TARGET $cd/$key directly — NOT the ambient admin-ajax
        // request context (wpc_aggr_live()/wpc_measured use the request url_key,
        // which is admin-ajax here → false negative; the 48 self-test caught it).
        $wpc_fd_uuid = @is_readable($cd . 'uuid.txt') ? trim((string) @file_get_contents($cd . 'uuid.txt')) : '-';
        $wpc_fd_luid = @is_readable($cd . 'land_uuid.txt') ? trim((string) @file_get_contents($cd . 'land_uuid.txt')) : '-';
        $wpc_fd_lpre = 'absent';
        if (@is_readable($cd . 'lcp.json')) {
            $wpc_fd_lj = json_decode((string) @file_get_contents($cd . 'lcp.json'), true);
            if (is_array($wpc_fd_lj) && !empty($wpc_fd_lj['hints']['lcp_preload'])) { $wpc_fd_lpre = 'PRESENT(' . count($wpc_fd_lj['hints']['lcp_preload']) . ')'; }
        }
        $o[] = "on-disk uuid: " . $wpc_fd_uuid . " | land_uuid: " . $wpc_fd_luid . " | lcp.json lcp_preload: " . $wpc_fd_lpre . "  <-- land_uuid is the OBS uuid; it holds steady by design while the CRIT uuid advances (template-cache split). Only STALE if lcp_preload is absent";
        $o[] = "delay.json on disk: " . ($wpc_fd_djok ? filesize($wpc_fd_dj) . 'B, mtime ' . max(0, time() - $wpc_fd_mt) . 's ago' : 'ABSENT');
        $o[] = "  schema_epoch: " . $wpc_fd_epoch . " | ceiling{}: " . ($wpc_fd_ceil ? 'PRESENT' : 'ABSENT') . " | render_critical key: " . $wpc_fd_rc . ($wpc_fd_djok && !$wpc_fd_measured ? '  <-- OLD-SCHEMA gen (no schema_epoch>=1 / no ceiling); amendment-refetch (meta-or-DERIVED uuid URL) supersedes on next repull' : '');
        // Live probe of what the amendment-refetch WILL pull (meta-or-derived from
        // the on-disk uuid) — proves whether the fix converges plugin-side or is
        // genuinely blocked service-side, without guessing.
        if ($wpc_fd_djok && !$wpc_fd_measured && function_exists('wpc_crit_artifact_url')) {
            $wpc_fd_amu = wpc_crit_artifact_url($cd, 'delay');
            if ($wpc_fd_amu !== '') {
                $wpc_fd_pr = wp_remote_get($wpc_fd_amu, ['headers' => ['user-agent' => defined('WPS_IC_API_USERAGENT') ? WPS_IC_API_USERAGENT : ''], 'timeout' => 4]);
                $wpc_fd_pc = !is_wp_error($wpc_fd_pr) ? (int) wp_remote_retrieve_response_code($wpc_fd_pr) : 0;
                $wpc_fd_pb = $wpc_fd_pc === 200 ? (string) wp_remote_retrieve_body($wpc_fd_pr) : '';
                $wpc_fd_pm = $wpc_fd_pb !== '' && class_exists('wps_ic_js_delay_v3')
                    && wps_ic_js_delay_v3::wpc_delay_measured_shape(json_decode($wpc_fd_pb, true));
                // v7.10.476 — DO NOT ATTRIBUTE ON AN OLD ARTIFACT. The probe fetches the copy for
                // the uuid ON DISK. If that gen predates the measured-shape feature, "old-schema"
                // says nothing about what the service emits TODAY — and the previous wording
                // ("SERVICE-side") sent the service team hunting a fault that was not theirs.
                // A stale artifact is un-attributable by construction; only a RECENT one accuses.
                $wpc_fd_age = ($wpc_fd_mt > 0) ? max(0, time() - $wpc_fd_mt) : -1;
                $wpc_fd_oldgen = ($wpc_fd_age < 0
                    || $wpc_fd_age > (int) apply_filters('wpc_amend_probe_attribution_max_age', 6 * HOUR_IN_SECONDS));
                $o[] = "  amendment probe: HTTP " . $wpc_fd_pc . " | " . strlen($wpc_fd_pb) . "B | measured-shape: "
                    . ($wpc_fd_pm
                        ? 'YES → amendment-refetch WILL land this on next repull ✓'
                        : ($wpc_fd_pc === 200
                            ? ($wpc_fd_oldgen
                                ? 'NO — but this artifact is ' . ($wpc_fd_age < 0 ? 'of unknown age' : human_time_diff($wpc_fd_mt, time()) . ' old')
                                  . ', so it PREDATES the measured-shape feature. NOT attributable: dispatch a fresh gen to find out.'
                                : 'NO on a RECENT gen (' . human_time_diff($wpc_fd_mt, time()) . ' old) → service-side')
                            : 'unreachable (retry/not-yet-landed)'))
                    . "\n    url: " . preg_replace('/[?&]t=\d+/', '', $wpc_fd_amu);
            }
        }
        $o[] = "manifest_off (promotion kill-switch): " . ($wpc_fd_moff > 0 ? 'SET ' . max(0, time() - $wpc_fd_moff) . 's ago' . ($wpc_fd_mt > $wpc_fd_moff ? ' (gen NEWER → .367 overrides ✓)' : ' (gen OLDER → blocks unless bg-heal ran)') : 'clear');
        $o[] = "aggr_off (watchdog demote): " . ($wpc_fd_aoff > 0 ? 'SET ' . max(0, time() - $wpc_fd_aoff) . 's ago (DEMOTED)' : 'clear');
        $wpc_fd_master = class_exists('wps_ic_js_delay_v3') && method_exists('wps_ic_js_delay_v3', 'wpc_delay_master_on')
            ? (wps_ic_js_delay_v3::wpc_delay_master_on($set) ? 'ON' : 'OFF') : '?';
        $wpc_fd_moffblk  = $wpc_fd_moff > 0 && $wpc_fd_mt <= $wpc_fd_moff;
        $wpc_fd_tele = apply_filters('wpc_delay_v3_telemetry', true) && apply_filters('wpc_delay_v3_io_when_measured', true);
        $o[] = "delay master: " . $wpc_fd_master . " | measured(this gen): " . ($wpc_fd_measured ? 'YES' : 'NO')
            . " | telemetry+io: " . ($wpc_fd_tele ? 'on' : 'OFF');
        $wpc_fd_flip = $wpc_fd_master === 'ON' && $wpc_fd_measured && !$wpc_fd_moffblk && $wpc_fd_aoff <= 0 && $wpc_fd_tele;
        // Ground truth from real HTML: served (what visitors/PSI get) + fresh
        // loopback (what a fresh render produces). If VERDICT=should-fire but
        // served shows 60 while fresh shows 0 → stale page-cache (purge). If
        // fresh ALSO shows 60 → the flip genuinely isn't firing (on-disk gen).
        $wpc_fd_cfg = function ($html) {
            return (is_string($html) && preg_match('/wpcDelayV3Cfg=\{"timeout":(\d+),"aggr":(\d+)/', $html, $m))
                ? 'timeout:' . $m[1] . ',aggr:' . $m[2] : 'n/a';
        };
        $o[] = "served flip config: " . $wpc_fd_cfg(isset($h) ? $h : '')
            . " | fresh-render: " . ($wpc_fd_cfg(isset($hf) ? $hf : '') === 'n/a' && (!isset($hf) || $hf === '') ? 'loopback-unavailable' : $wpc_fd_cfg(isset($hf) ? $hf : ''));
        $o[] = "VERDICT: " . ($wpc_fd_flip
            ? 'flip SHOULD fire (timeout:0,aggr:1) — if FRESH-render above shows 0 but the live page shows 60, it is stale page-cache: purge + reload'
            : 'flip WILL NOT fire — ' . (!$wpc_fd_djok ? 'no delay.json on disk' : (!$wpc_fd_measured ? 'on-disk gen is OLD-SCHEMA (no schema_epoch>=1, no ceiling{}) — amendment-refetch pulls the measured copy from the meta-or-DERIVED uuid URL on the next repull: measured YES above = the flip lands automatically; measured NO is only attributable when that artifact is RECENT (see its age above) — on an old gen it means no new gen has landed, not that the service is behind (uuid on-disk ' . $wpc_fd_uuid . ')' : ($wpc_fd_master === 'OFF' ? 'delay master off' : ($wpc_fd_moffblk ? 'manifest_off newer than gen' : ($wpc_fd_aoff > 0 ? 'watchdog-demoted' : 'telemetry/io off'))))));

        echo implode("\n", $o) . "\n";
        wp_die();
    }
    add_action('wp_ajax_wpc_perf_debug', 'wpc_perf_debug_report');
    add_action('wp_ajax_nopriv_wpc_perf_debug', 'wpc_perf_debug_report');
}

if (!function_exists('wpc_premint_upload_sizes')) {
    /**
     * Upload-hook pre-mint (service contract: the natural URL IS the pre-mint endpoint). When an
     * upload's sizes land, each emitted size's next-gen zone URL is requested once with its
     * origin-ext hint: the edge mints and caches, the first visitor lands on warm keys. Bounded:
     * full + WP sizes x2 formats, 12 URLs per image, 8 images per request, image mimes only,
     * standalone from compress-on-upload (runs with auto-optimize off). Kill filter
     * wpc_upload_premint.
     *
     * The hook makes no request, it records the attachment id. The requests run after the
     * response is released, one parallel batch per image, or in one cron event where the
     * response cannot be released.
     */
    function wpc_premint_upload_sizes($data, $attachment_id)
    {
        try {
            if (is_array($data) && wpc_premint_upload_zone() !== '') {
                wpc_premint_upload_record((int) $attachment_id);
            }
        } catch (\Throwable $e) {
        }
        return $data;
    }

    /** The zone host a pre-mint goes to, or '' when this site pre-mints nothing. */
    function wpc_premint_upload_zone()
    {
        if (!apply_filters('wpc_upload_premint', true) || !function_exists('wp_get_attachment_url')) {
            return '';
        }
        if (!class_exists('wps_rewriteLogic') && defined('WPS_IC_DIR') && is_readable(WPS_IC_DIR . 'addons/cdn/rewriteLogic.php')) {
            include_once WPS_IC_DIR . 'addons/cdn/rewriteLogic.php';
        }
        if (!class_exists('wps_rewriteLogic') || !method_exists('wps_rewriteLogic', 'src_hint_qs')) {
            return '';
        }
        if (function_exists('wpc_get_optimization_mode') && wpc_get_optimization_mode() === 'lazy_cdn') {
            return '';
        }
        $zone = trim((string) get_option('ic_cdn_zone_name', ''));
        if ($zone === '' || (function_exists('wpc_v2_zone_cdn_suppressed') && wpc_v2_zone_cdn_suppressed())) {
            return '';
        }
        return $zone;
    }

    /** Remembers an attachment for this request's pre-mint and arms its one shutdown handler. */
    function wpc_premint_upload_record($attachment_id)
    {
        if ($attachment_id <= 0) {
            return;
        }
        if (!isset($GLOBALS['wpc_premint_ids']) || !is_array($GLOBALS['wpc_premint_ids'])) {
            $GLOBALS['wpc_premint_ids'] = [];
        }
        if (count($GLOBALS['wpc_premint_ids']) < 8) {
            $GLOBALS['wpc_premint_ids'][$attachment_id] = $attachment_id;
        }
        if (empty($GLOBALS['wpc_premint_armed'])) {
            $GLOBALS['wpc_premint_armed'] = true;
            add_action('shutdown', 'wpc_premint_upload_shutdown', PHP_INT_MAX);
        }
    }

    /** Releases the response, then pre-mints; with no way to release it, one cron event does. */
    function wpc_premint_upload_shutdown()
    {
        try {
            $ids = isset($GLOBALS['wpc_premint_ids']) && is_array($GLOBALS['wpc_premint_ids']) ? array_values($GLOBALS['wpc_premint_ids']) : [];
            $GLOBALS['wpc_premint_ids'] = [];
            if (!$ids) {
                return;
            }
            if (!(function_exists('wpc_finish_request') && wpc_finish_request())) {
                if (function_exists('wp_schedule_single_event') && function_exists('wp_next_scheduled')
                    && !wp_next_scheduled('wpc_premint_upload_run', [$ids])) {
                    wp_schedule_single_event(time(), 'wpc_premint_upload_run', [$ids]);
                }
                return;
            }
            @ignore_user_abort(true);
            @set_time_limit(60);
            wpc_premint_upload_run($ids, 'shutdown');
        } catch (\Throwable $e) {
        }
    }

    /** The URLs one attachment pre-mints, from its saved sizes: [] when it is not a local image. */
    function wpc_premint_upload_urls($attachment_id, $zone)
    {
        $data  = wp_get_attachment_metadata($attachment_id);
        $url   = (string) wp_get_attachment_url($attachment_id);
        $clean = (string) preg_replace('/[?#].*$/', '', $url);
        $ext   = strtolower((string) pathinfo($clean, PATHINFO_EXTENSION));
        if (!in_array($ext, array('jpg', 'jpeg', 'png', 'webp'), true)) {
            return array();
        }
        $site = rtrim((string) site_url(), '/');
        if (strpos($clean, $site) !== 0) {
            return array();
        }
        $base = 'https://' . $zone . substr($clean, strlen($site));
        $hint = wps_rewriteLogic::src_hint_qs($ext);
        $dir  = substr($base, 0, strrpos($base, '/') + 1);
        $mk   = function ($fileBase) use ($hint, $ext) {
            $out = array();
            foreach (array('webp', 'avif') as $f) {
                $u = (string) preg_replace('/\.(?:jpe?g|png|webp)$/i', '.' . $f, $fileBase);
                if ($u === $fileBase && $f === $ext) { $out[] = $u; continue; }
                $out[] = $u . ($hint !== '' ? $hint : '');
            }
            return $out;
        };
        $urls = $mk($base);
        if (is_array($data) && isset($data['sizes']) && is_array($data['sizes'])) {
            foreach ($data['sizes'] as $sz) {
                if (count($urls) >= 12) { break; }
                if (empty($sz['file']) || !is_string($sz['file'])) { continue; }
                foreach ($mk($dir . $sz['file']) as $u) {
                    if (count($urls) >= 12) { break; }
                    $urls[] = $u;
                }
            }
        }
        return $urls;
    }

    /**
     * Requests every recorded image's pre-mint URLs, one parallel batch per image. Each request
     * carries the Accept header a current browser sends for an image, so the copy the zone mints
     * is stored under the Accept class browsers read.
     */
    function wpc_premint_upload_run($ids, $via = 'cron')
    {
        try {
            $accept = wpc_browser_accept('image');
            $zone = wpc_premint_upload_zone();
            $requests_class = '\WpOrg\Requests\Requests';
            if ($zone === '' || !class_exists($requests_class)) {
                return;
            }
            $started = microtime(true);
            foreach (array_slice(array_unique(array_map('intval', (array) $ids)), 0, 8) as $id) {
                if ($id <= 0 || microtime(true) - $started > 15) {
                    continue;
                }
                $urls = wpc_premint_upload_urls($id, $zone);
                $batch = array();
                foreach ($urls as $u) {
                    if (class_exists('WP_Http') && (new WP_Http())->block_request($u)) {
                        continue;
                    }
                    $batch[] = array('url' => $u, 'headers' => array('Accept' => $accept), 'data' => array(), 'type' => 'GET');
                }
                if (!$batch) {
                    continue;
                }
                $verify = apply_filters('https_ssl_verify', true, $batch[0]['url']);
                $bundle = defined('ABSPATH') && defined('WPINC') ? ABSPATH . WPINC . '/certificates/ca-bundle.crt' : '';
                $requests_class::request_multiple($batch, array(
                    'timeout'          => 3,
                    'connect_timeout'  => 2,
                    'follow_redirects' => false,
                    'verify'           => $verify ? ($bundle !== '' && is_readable($bundle) ? $bundle : true) : false,
                    'verifyname'       => (bool) $verify,
                    'useragent'        => apply_filters('http_headers_useragent', 'WordPress/' . get_bloginfo('version') . '; ' . get_bloginfo('url'), $batch[0]['url']),
                ));
                if (function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('upload-premint', '', '', array('n' => count($batch), 'id' => $id, 'via' => (string) $via, 'ms' => (int) round((microtime(true) - $started) * 1000)));
                }
            }
        } catch (\Throwable $e) {
        }
    }
    add_filter('wp_generate_attachment_metadata', 'wpc_premint_upload_sizes', PHP_INT_MAX - 1, 2);
    add_action('wpc_premint_upload_run', 'wpc_premint_upload_run');
}

if (!function_exists('wpc_rum_census_receiver')) {
    /** RUM census relay: the page beacon posts SAME-ORIGIN (no CSP connect-src walls, no
     *  third-party blocking, and the apikey never appears in page bytes — injected here).
     *  Always 204, allowlist-rebuilt payload (never relays arbitrary bytes), own-host URL
     *  only (no open relay), hourly forward cap mirroring the ingest bucket. */
    function wpc_rum_census_receiver()
    {
        while (ob_get_level()) { @ob_end_clean(); }
        status_header(204);
        if (!apply_filters('wpc_rum_beacon', true)) { exit; }
        // The page's census is a form whose field `d` holds the payload base64-encoded (gzip bytes
        // with enc=gz, else the JSON): a Plesk host's OWASP CRS refused the raw
        // application/octet-stream and text/plain bodies with rule 920420 and fail2ban banned the
        // visitors (ticket 12055). A copy cached before that change still posts the raw body, so
        // a request without the field is read as before. Both land as the same bytes, under the
        // same 32768-byte cap, so what is forwarded does not depend on how it arrived.
        if (isset($_POST['d']) && is_string($_POST['d'])) {
            $field = $_POST['d'];   // base64 carries no quote or backslash, so WP's slashing leaves it as sent
            // 43692 is the base64 length of 32768 bytes, the cap the decoded payload meets below.
            if ($field === '' || strlen($field) > 43692) { wpc_rum_count_drop('size'); exit; }
            $raw = base64_decode($field, true);
            if (!is_string($raw)) { wpc_rum_count_drop('shape'); exit; }
        } else {
            $raw = (string) @file_get_contents('php://input', false, null, 0, 33000);
        }
        wpc_rum_census_relay($raw, isset($_GET['enc']) && $_GET['enc'] === 'gz');
        exit;
    }

    /** One page beacon, checked, rebuilt and forwarded to crit: 'sent', or the reason it was dropped. */
    function wpc_rum_census_relay($raw, $gz)
    {
        $raw = (string) $raw;
        if ($raw === '' || strlen($raw) > 32768) { wpc_rum_count_drop('size'); return 'size'; }
        if ($gz || substr($raw, 0, 2) === "\x1f\x8b") {
            if (!function_exists('gzdecode')) { wpc_rum_count_drop('gzip'); return 'gzip'; }
            $raw = (string) @gzdecode($raw);
            if ($raw === '' || strlen($raw) > 524288) { wpc_rum_count_drop('gzip'); return 'gzip'; }
        }
        $beacon = json_decode($raw, true);
        $version = (int) (is_array($beacon) && isset($beacon['v']) ? $beacon['v'] : 0);
        if (!is_array($beacon) || ($version !== 1 && $version !== 2)
            || empty($beacon['url']) || !is_string($beacon['url'])) { wpc_rum_count_drop('shape'); return 'shape'; }
        $beacon_host = strtolower((string) parse_url((string) $beacon['url'], PHP_URL_HOST));
        $home_host = function_exists('home_url') ? strtolower((string) parse_url(home_url(), PHP_URL_HOST)) : '';
        $strip_www = function ($h) { return strpos($h, 'www.') === 0 ? substr($h, 4) : $h; };
        if ($beacon_host === '' || $home_host === '' || $strip_www($beacon_host) !== $strip_www($home_host)) { wpc_rum_count_drop('host'); return 'host'; }
        $options = (array) get_option(defined('WPS_IC_OPTIONS') ? WPS_IC_OPTIONS : 'wps_ic');
        if (empty($options['api_key'])) { wpc_rum_count_drop('apikey'); return 'apikey'; }
        $forward_count = (int) get_transient('wpc_rum_fw_ct');
        if ($forward_count >= (int) apply_filters('wpc_rum_forward_cap', 60)) { wpc_rum_count_drop('ratecap'); return 'ratecap'; }
        set_transient('wpc_rum_fw_ct', $forward_count + 1, HOUR_IN_SECONDS);
        $payload = wpc_shape_rum_census_payload($beacon, (string) $options['api_key']);
        $payload['visitor'] = function_exists('wpc_visitor_kind') ? wpc_visitor_kind() : 'human';
        if (isset($payload['cdn'])) {
            $country = wpc_rum_visitor_country();
            if ($country !== '') { $payload['country'] = $country; }
        }
        $endpoint = apply_filters('wpc_rum_census_endpoint',
            defined('WPS_IC_CRITICAL_API_URL') ? str_replace('/generate', '/rum-census', WPS_IC_CRITICAL_API_URL) : '');
        if (!is_string($endpoint) || strpos($endpoint, 'http') !== 0) { wpc_rum_count_drop('endpoint'); return 'endpoint'; }
        $body = wpc_rum_census_fit($payload, (int) apply_filters('wpc_rum_body_limit', 51200));
        if ($body === '') { wpc_rum_count_drop('size'); return 'size'; }
        $headers = ['Content-Type' => 'application/json'];
        if ($payload['v'] === 2 && function_exists('gzencode')) {
            $gzipped = gzencode($body, 6);
            while (is_string($gzipped) && strlen($gzipped) > 32768 && !empty($payload['atf_selectors'])) {
                $payload['atf_selectors'] = array_slice($payload['atf_selectors'], 0, (int) floor(count($payload['atf_selectors']) / 2));
                $payload['truncated'] = true;
                $body = (string) wp_json_encode($payload);
                $gzipped = gzencode($body, 6);
            }
            if (is_string($gzipped) && $gzipped !== '') {
                $body = $gzipped;
                $headers['Content-Encoding'] = 'gzip';
            }
        }
        wp_remote_post($endpoint, [
            'timeout' => 2,
            'blocking' => false,
            'headers' => $headers,
            'body' => $body,
        ]);
        return 'sent';
    }

    /**
     * The JSON body for $payload within $limit bytes before gzip, the measure crit's body limit
     * uses: the selector, id, font and image lists are halved in that order until it fits, or ''.
     */
    function wpc_rum_census_fit(array &$payload, $limit)
    {
        $body = (string) wp_json_encode($payload);
        foreach (['atf_selectors', 'atf_ids', 'fonts_used', 'atf_images'] as $field) {
            while (strlen($body) > $limit && !empty($payload[$field]) && is_array($payload[$field])) {
                $payload[$field] = array_slice($payload[$field], 0, (int) floor(count($payload[$field]) / 2));
                $payload['truncated'] = true;
                $body = (string) wp_json_encode($payload);
            }
        }
        return $body !== '' && strlen($body) <= $limit ? $body : '';
    }

    /** The visitor's country as two capital letters from Cloudflare's CF-IPCountry, or ''. Never the IP. */
    function wpc_rum_visitor_country()
    {
        $country = isset($_SERVER['HTTP_CF_IPCOUNTRY']) ? (string) $_SERVER['HTTP_CF_IPCOUNTRY'] : '';
        $country = strtoupper(trim((string) apply_filters('wpc_rum_visitor_country', $country)));
        return preg_match('/^[A-Z]{2}$/', $country) === 1 && $country !== 'XX' && $country !== 'T1' ? $country : '';
    }

    /** The cdn block rebuilt field by field: at most 10 zone files, paths without a query, 2 KB of JSON at most; null when unusable. */
    function wpc_shape_rum_cdn_block($c)
    {
        if (!is_array($c)) { return null; }
        $ms = function ($v) { return is_numeric($v) ? (int) max(0, min(60000, round((float) $v))) : 0; };
        $bytes = function ($v) { return is_numeric($v) ? (int) max(0, min(50000000, (float) $v)) : 0; };
        $out = [
            'lcp_ms' => $ms(isset($c['lcp_ms']) ? $c['lcp_ms'] : 0),
            'lcp_cdn' => isset($c['lcp_cdn']) && $c['lcp_cdn'] === true,
            'files' => [],
        ];
        if (isset($c['ect']) && in_array($c['ect'], ['slow-2g', '2g', '3g', '4g'], true)) { $out['ect'] = $c['ect']; }
        $files = isset($c['files']) && is_array($c['files']) ? array_values($c['files']) : [];
        foreach ($files as $f) {
            if (count($out['files']) >= 10) { break; }
            if (!is_array($f) || !isset($f['type'], $f['path']) || !is_string($f['path'])
                || !in_array($f['type'], ['img', 'css', 'js', 'font'], true)) { continue; }
            $path = (string) preg_replace('/[?#].*$/s', '', $f['path']);
            if ($path === '' || $path[0] !== '/' || preg_match('/[^\x21-\x7e]/', $path)) { continue; }
            $out['files'][] = [
                'type' => $f['type'],
                'path' => substr($path, 0, 200),
                'ttfb_ms' => $ms(isset($f['ttfb_ms']) ? $f['ttfb_ms'] : 0),
                'dl_ms' => $ms(isset($f['dl_ms']) ? $f['dl_ms'] : 0),
                'transfer' => $bytes(isset($f['transfer']) ? $f['transfer'] : 0),
                'body' => $bytes(isset($f['body']) ? $f['body'] : 0),
                'lcp' => isset($f['lcp']) && $f['lcp'] === true,
            ];
        }
        while (!empty($out['files']) && strlen((string) wp_json_encode($out)) > 2048) { array_pop($out['files']); }
        return !empty($out['files']) || $out['lcp_cdn'] ? $out : null;
    }

    function wpc_shape_rum_census_payload($j, $apikey)
    {
        $v = (int) (isset($j['v']) ? $j['v'] : 1) === 2 ? 2 : 1;
        $vp = (isset($j['viewport']) && is_array($j['viewport'])) ? $j['viewport'] : [];
        $out = [
            'v' => $v,
            'apikey' => (string) $apikey,
            'url' => substr((string) preg_replace('/[?#].*$/s', '', (string) $j['url']), 0, 500),
            'viewport' => [
                'w' => (int) (isset($vp['w']) ? $vp['w'] : 0),
                'h' => (int) (isset($vp['h']) ? $vp['h'] : 0),
                'dpr' => (float) (isset($vp['dpr']) ? $vp['dpr'] : 1),
            ],
            'lcp' => null,
            'atf_images' => [],
        ];
        if (isset($j['lcp']) && is_array($j['lcp'])) {
            $lr = (isset($j['lcp']['rect']) && is_array($j['lcp']['rect'])) ? $j['lcp']['rect'] : [];
            $out['lcp'] = [
                'selector' => substr((string) (isset($j['lcp']['selector']) ? $j['lcp']['selector'] : ''), 0, 120),
                'url' => (isset($j['lcp']['url']) && is_string($j['lcp']['url'])) ? substr($j['lcp']['url'], 0, 300) : null,
                'rect' => [
                    'w' => (int) (isset($lr['w']) ? $lr['w'] : 0),
                    'h' => (int) (isset($lr['h']) ? $lr['h'] : 0),
                    'x' => (int) (isset($lr['x']) ? $lr['x'] : 0),
                    'y' => (int) (isset($lr['y']) ? $lr['y'] : 0),
                ],
                't_ms' => (int) (isset($j['lcp']['t_ms']) ? $j['lcp']['t_ms'] : 0),
            ];
        }
        if (isset($j['atf_images']) && is_array($j['atf_images'])) {
            foreach (array_slice($j['atf_images'], 0, 20) as $im) {
                if (!is_array($im)) { continue; }
                $cl = [];
                if (isset($im['classes']) && is_array($im['classes'])) {
                    foreach (array_slice($im['classes'], 0, 2) as $c) {
                        if (is_string($c) && $c !== '') { $cl[] = substr($c, 0, 80); }
                    }
                }
                $out['atf_images'][] = [
                    'classes' => $cl,
                    'slot_w' => (int) (isset($im['slot_w']) ? $im['slot_w'] : 0),
                    'slot_h' => (int) (isset($im['slot_h']) ? $im['slot_h'] : 0),
                    'intrinsic_w' => (int) (isset($im['intrinsic_w']) ? $im['intrinsic_w'] : 0),
                    'current_src' => (isset($im['current_src']) && is_string($im['current_src'])) ? substr($im['current_src'], 0, 300) : '',
                    'loading' => substr((string) (isset($im['loading']) ? $im['loading'] : ''), 0, 10),
                ];
            }
        }
        $strs = function ($list, $max, $len) {
            $o = [];
            if (!is_array($list)) { return $o; }
            foreach ($list as $x) {
                if (!is_string($x) || $x === '' || preg_match('/[\x00-\x08\x0b\x0c\x0e-\x1f]/', $x)) { continue; }
                $x = substr($x, 0, $len);
                if (!in_array($x, $o, true)) { $o[] = $x; }
                if (count($o) >= $max) { break; }
            }
            return $o;
        };
        $out['fonts_used'] = $strs(isset($j['fonts_used']) ? $j['fonts_used'] : [], 64, 120);
        $sample_rate = isset($j['sr']) && is_numeric($j['sr']) ? (int) $j['sr'] : 0;
        if ($sample_rate >= 1 && $sample_rate <= 100000) {
            $out['sr'] = $sample_rate;
            $cdn = wpc_shape_rum_cdn_block(isset($j['cdn']) ? $j['cdn'] : null);
            if ($cdn !== null) { $out['cdn'] = $cdn; }
        }
        if ($v === 2) {
            $out['device'] = (isset($j['device']) && $j['device'] === 'mobile') ? 'mobile' : 'desktop';
            $out['atf_selectors'] = $strs(isset($j['atf_selectors']) ? $j['atf_selectors'] : [], 2000, 300);
            $out['atf_ids'] = $strs(isset($j['atf_ids']) ? $j['atf_ids'] : [], 200, 80);
            $out['truncated'] = !empty($j['truncated']);
            $out['device_ua'] = (isset($j['device_ua']) && $j['device_ua'] === 'm') ? 'm' : 'd';
            $out['gen_uuid'] = (isset($j['gen_uuid']) && is_string($j['gen_uuid']) && preg_match('/^[a-f0-9-]{8,64}$/i', $j['gen_uuid'])) ? $j['gen_uuid'] : '';
            $out['plugin_version'] = (isset($j['plugin_version']) && is_string($j['plugin_version'])) ? substr(preg_replace('/[^0-9.]/', '', $j['plugin_version']), 0, 16) : '';
            $out['phases'] = (isset($j['phases']) && is_string($j['phases'])) ? substr(preg_replace('/[^0-4]/', '', $j['phases']), 0, 5) : '';
            $sh = (isset($j['sheets']) && is_array($j['sheets'])) ? $j['sheets'] : [];
            $out['sheets'] = [
                'total' => (int) (isset($sh['total']) ? $sh['total'] : 0),
                'readable' => (int) (isset($sh['readable']) ? $sh['readable'] : 0),
                'cors_blocked' => (int) (isset($sh['cors_blocked']) ? $sh['cors_blocked'] : 0),
            ];
            $out['selector_source'] = (isset($j['selector_source']) && in_array($j['selector_source'], ['probe', 'cssRules', 'both', 'none'], true)) ? $j['selector_source'] : 'none';
            $out['bytes'] = (int) (isset($j['bytes']) ? $j['bytes'] : 0);
        }
        return $out;
    }

    /**
     * Counts a dropped RUM beacon by reason in option wpc_rum_drops (day-keyed); the previous
     * day's map is journaled as rum-drops when the day rolls over.
     */
    function wpc_rum_count_drop($why)
    {
        try {
            if (!function_exists('get_option')) { return; }
            $d = (array) get_option('wpc_rum_drops', []);
            $day = gmdate('Y-m-d');
            if (!isset($d['day']) || $d['day'] !== $day) {
                if (!empty($d['day']) && function_exists('wpc_cache_first_log')) {
                    wpc_cache_first_log('rum-drops', '', '', $d);
                }
                $d = ['day' => $day];
            }
            $d[$why] = (int) (isset($d[$why]) ? $d[$why] : 0) + 1;
            update_option('wpc_rum_drops', $d, false);
        } catch (\Throwable $e) {
        }
    }
    add_action('wp_ajax_wpc_rum_census', 'wpc_rum_census_receiver');
    add_action('wp_ajax_nopriv_wpc_rum_census', 'wpc_rum_census_receiver');
}

if (!function_exists('wpc_device_mix_receiver')) {
    /**
     * THE DEVICE MIX: a cache in front of the origin that stores one device's render and hands it
     * to the other. Every page carries the device it was rendered for, and the visitor's browser
     * tests its own agent against the same rule on every view (wps_cdn_rewrite::
     * wpc_device_check_pass); when the two differ it posts here, at most once a day. This relay
     * judges the report with the server's own rule (wpc_ua_is_mobile) on the report's request,
     * and a confirmed mix holds the site in fix B: the store verdict keeps every copy local,
     * served private with no Apache mirror, until 30 days pass without another confirmed report
     * (filter wpc_device_mix_hold_s). The first confirmation of a hold purges the page copies and
     * the caches in front of the origin. At most one report a day is recorded.
     *
     * Kill switches: wpc_device_mix_check (the browser check and this relay), wpc_device_mix_fix
     * (fix B; reports are still judged and logged).
     */
    function wpc_device_mix_receiver()
    {
        while (ob_get_level()) { @ob_end_clean(); }
        status_header(204);
        wpc_device_mix_judge(wp_unslash($_POST));
        exit;
    }

    /**
     * Judge one report (the check's form fields: host, path, page m|d) against this request's
     * agent. Returns what was decided: off, day (one already recorded today), shape, host, same
     * (the server's rule puts this agent in the page's own bucket), or mix (recorded).
     */
    function wpc_device_mix_judge($report)
    {
        if (!apply_filters('wpc_device_mix_check', true)) {
            return 'off';
        }
        $drop = function ($why) {
            if (function_exists('wpc_rum_count_drop')) { wpc_rum_count_drop('mix-' . $why); }
            return $why;
        };
        $state = wpc_device_mix_state();
        if (($state['day'] ?? '') === gmdate('Y-m-d')) {
            return $drop('day');
        }
        if (!is_array($report) || !isset($report['host'], $report['path'], $report['page'])
            || !is_string($report['host']) || !is_string($report['path'])
            || !in_array($report['page'], ['m', 'd'], true)) {
            return $drop('shape');
        }
        $bare = function ($host) { return strpos($host, 'www.') === 0 ? substr($host, 4) : $host; };
        $host = strtolower(trim($report['host']));
        $home = strtolower((string) parse_url((string) home_url(), PHP_URL_HOST));
        if ($host === '' || $home === '' || $bare($host) !== $bare($home)) {
            return $drop('host');
        }
        $visitor = wpc_ua_is_mobile() ? 'm' : 'd';
        if ($visitor === $report['page']) {
            return $drop('same');
        }
        wpc_device_mix_note($report['page'], $visitor, substr($host . $report['path'], 0, 300));
        return 'mix';
    }

    /** The recorded mix: since, last (unix seconds), day (Y-m-d of the last), n, page, visitor, url; or []. */
    function wpc_device_mix_state()
    {
        $state = get_option('wpc_device_mix', []);
        return is_array($state) ? $state : [];
    }

    /** Whether the site is held in fix B: a confirmed mix within the hold, and the fix switched on. */
    function wpc_device_mix_held()
    {
        if (!apply_filters('wpc_device_mix_fix', true)) {
            return false;
        }
        $last = (int) (wpc_device_mix_state()['last'] ?? 0);
        return $last > 0 && $last > time() - (int) apply_filters('wpc_device_mix_hold_s', 30 * DAY_IN_SECONDS);
    }

    /** Record a confirmed mix. The first one of a hold purges what the caches in front of the origin hold. */
    function wpc_device_mix_note($page, $visitor, $url)
    {
        $held = wpc_device_mix_held();
        $state = wpc_device_mix_state();
        $now = time();
        update_option('wpc_device_mix', [
            'since' => $held ? (int) ($state['since'] ?? $now) : $now,
            'last' => $now,
            'day' => gmdate('Y-m-d', $now),
            'n' => (int) ($state['n'] ?? 0) + 1,
            'page' => (string) $page,
            'visitor' => (string) $visitor,
            'url' => (string) $url,
        ], true);
        $fix = (bool) apply_filters('wpc_device_mix_fix', true);
        if (function_exists('wpc_cache_first_log')) {
            wpc_cache_first_log('device-mix', '', (string) $url, ['page' => (string) $page, 'visitor' => (string) $visitor,
                'n' => (int) ($state['n'] ?? 0) + 1, 'engaged' => ($fix && !$held) ? 1 : 0, 'fix' => $fix ? 1 : 0]);
        }
        if ($fix && !$held && class_exists('wps_ic_cache')) {
            wps_ic_cache::removeHtmlCacheFiles('all', '', '', 'soft');
            wps_ic_cache::cfPurgeAllHtml(true, true);
        }
    }

    add_action('wp_ajax_wpc_device_mix', 'wpc_device_mix_receiver');
    add_action('wp_ajax_nopriv_wpc_device_mix', 'wpc_device_mix_receiver');
}


if (!function_exists('wpc_font_inline_self_arm')) {
    function wpc_font_inline_self_arm()
    {
        try {
            if (!is_admin() || wp_doing_ajax() || (defined('DOING_CRON') && DOING_CRON)
                || !apply_filters('wpc_localize_inline_fonts', true)
                || wpc_is_admin_lane_held('wpc_font_selfarm_lock')) {
                return;
            }
            if (!class_exists('wps_ic_fonts') && defined('WPS_IC_DIR')) {
                @include_once WPS_IC_DIR . 'addons/fonts/fonts.class.php';
            }
            if (!class_exists('wps_ic_fonts')) {
                return;
            }
            $f = new wps_ic_fonts();
            if (method_exists($f, 'isActive') && $f->isActive() !== 'local') {
                return;
            }

            wpc_hold_admin_lane('wpc_font_selfarm_lock', 30 * MINUTE_IN_SECONDS); // ≤1/30min, own throttle
            register_shutdown_function(function () use ($f) {
                if ((function_exists('fastcgi_finish_request') || function_exists('litespeed_finish_request'))) { wpc_finish_request(); }
                if (function_exists('ignore_user_abort')) { @ignore_user_abort(true); }
                if (function_exists('set_time_limit')) { @set_time_limit(120); }
                try {
                    $n = method_exists($f, 'localizeInlineFonts') ? (int) $f->localizeInlineFonts('') : 0;
                    if ($n > 0) {
                        // Site-wide purge at most once/day: a recurring n>0 means the localize
                        // loop hasn't converged, and wiping the HTML cache each pass turns that
                        // into a permanent cold-cache storm (the FPM-stampede class).
                        if (!get_transient('wpc_font_purgeall_day')
                            && class_exists('wps_ic_cache') && method_exists('wps_ic_cache', 'removeHtmlCacheFiles')) {
                            set_transient('wpc_font_purgeall_day', 1, DAY_IN_SECONDS);
                            try { wps_ic_cache::removeHtmlCacheFiles('all', '', '', 'soft'); } catch (\Throwable $e) {}
                        }

                        delete_transient('wpc_font_inline_lock');
                        if (function_exists('wpc_cache_first_log')) {
                            wpc_cache_first_log('font-selfarm', '', '', ['n' => $n]);
                        }
                    }
                } catch (\Throwable $e) {
                }
            });
        } catch (\Throwable $e) {
        }
    }
    add_action('admin_init', 'wpc_font_inline_self_arm');
}


if (!function_exists('wpc_brand_name')) {
